      { 9.41, "Universal" }, { 10.24, "everywhere else." }, { 11.25, "Aim. See. Move." },
    }, linesEnd = 12.08 },
  remaster = { film = "remaster", drop = 4.10, calm = 3.5, breath = 0.6, greet = { 0.7, 3.0 }, start = 0, exit = 34.0,
    word = 31.45, stagger = 0.07, rise = 0.7, hub = 31.78, rule = 31.96, status = 32.14, hint = 32.44, finale = 31.45, greeting = true,
    lines = {
      { 7.67, "One hub." }, { 9.455, "Every game." }, { 11.24, "Engineered" }, { 13.025, "for the game" }, { 14.81, "you’re in." },
      { 16.595, "Universal" }, { 18.38, "everywhere else." }, { 20.165, "Aim. See. Move." }, { 21.95, "Every setting," }, { 23.735, "yours." },
    }, linesEnd = 25.52 },
}
local FILMS = { reel = "REEL", remaster = "REMASTER", exclusive = "EXCLUSIVE", hellsing = "HELLSING", invincible2 = "INVINCIBLE2", blackflag = "BLACKFLAG", omniman = "OMNIMAN", goldberg = "GOLDBERG", quwen = "QUWEN" }
local function specOf(plan)
  local key = plan and FILMS[plan.film]
  if key then return B[key] end
  return Film.spec
end
-- installed, at some size?
function Loader.has(mode)
  local plan = MODES[mode]
  if not plan then return Loader.others[mode] ~= nil end
  local spec = specOf(plan)
  return spec ~= nil and not Assets.lite and Film.pick(Config.get("app.filmQuality"), spec) ~= nil
end
function Loader.spec(mode) return MODES[mode] end

local BONE, SOFT = Color3.fromRGB(245, 244, 239), Color3.fromRGB(158, 157, 166)

local function label(parent, text, font, size, color, props)
  local item = Instance.new("TextLabel")
  item.BackgroundTransparency = 1
  item.BorderSizePixel = 0
  item.FontFace = B.F[font]
  item.TextSize = size
  item.Text = text
  item.TextColor3 = color or BONE
  item.AutomaticSize = Enum.AutomaticSize.XY
  item.TextXAlignment = Enum.TextXAlignment.Left
  if props then
    for key, value in pairs(props) do item[key] = value end
  end
  item.Parent = parent
  return item
end
-- A line of type that rises out of a mask and leaves through the top of it.
-- side: "left" or "right" (which edge `position` anchors)
local function maskLine(parent, text, font, size, color, side, position)
  local right = side == "right"
  local clip = Instance.new("Frame")
  clip.BackgroundTransparency = 1
  clip.ClipsDescendants = true
  clip.AnchorPoint = Vector2.new(right and 1 or 0, 1)
  clip.Position = position
  clip.Size = UDim2.fromOffset(10, 10)
  clip.Parent = parent
  local item = label(clip, text, font, size, color)
  local function fit()
    local bounds, unit = item.AbsoluteSize, Loader.unit or 1
    clip.Size = UDim2.fromOffset(bounds.X / unit + 14, bounds.Y / unit + 6)
  end
  item:GetPropertyChangedSignal("AbsoluteSize"):Connect(fit)
  fit()
  local api = { clip = clip, label = item }
  -- enter 0..1 rises in from below; leave 0..1 carries it out through the top
  function api.set(enter, leave)
    local height = clip.Size.Y.Offset
    item.Position = UDim2.fromOffset(4, height * (1 - enter) - height * (leave or 0))
    item.TextTransparency = math.clamp(1 - enter * 1.6 + (leave or 0), 0, 1)
  end
  api.set(0, 0)
  return api
end

-- the intros there are (src/09b: "signal"), and the one Shuffle picks from
Loader.others = {}
Loader.SHUFFLE = { "exclusive", "hellsing", "invincible2", "blackflag", "omniman", "goldberg", "quwen", "remaster", "reel", "cinematic", "signal" }
function Loader.run(done, override)
  -- getgenv().BASED_INTRO = "signal" | "cinematic" | "quick" | "shuffle" | "off" forces a mode for one launch (testing)
  local forced = B.genv.BASED_INTRO
  override = override or ((MODES[forced] or Loader.others[forced] or forced == "off" or forced == "shuffle") and forced or nil)
  local mode = override or Config.get("app.intro")
  if mode == "shuffle" then
    -- (a different one from last time, when there is a choice)
    local pool = {}
    for _, name in ipairs(Loader.SHUFFLE) do
      if (MODES[name] or Loader.others[name]) and name ~= Loader.lastShuffle then pool[#pool + 1] = name end
    end
    mode = pool[math.random(1, math.max(#pool, 1))] or "cinematic"
    Loader.lastShuffle = mode
  end
  if Loader.others[mode] then
    if Loader.active then return end
    Loader.active = true
    return Loader.others[mode](function()
      Loader.active = false
      done()
    end)
  end
  if mode == "off" or not MODES[mode] then
    done()
    return
  end
  if Loader.active then return end
  Loader.active = true
  -- (a film that is not installed: the next one along, or the wordmark alone)
  local NEXT = { hellsing = "exclusive", invincible2 = "exclusive", blackflag = "exclusive", omniman = "exclusive", goldberg = "exclusive", quwen = "exclusive", exclusive = "remaster", remaster = "reel", reel = "cinematic" }
  while MODES[mode] and not Loader.has(mode) and mode ~= "quick" do
    mode = NEXT[mode] or "quick"
  end
  local plan = MODES[mode]
  local spec = specOf(plan)
  local DROP = plan.drop or DROP
  local gui = B.screen(9500)
  local view = B.viewport()
  local k = math.clamp(view.Y / 1080, 0.55, 2)
  Loader.unit = k

  local root = UI.frame(gui, { Name = "Intro", Size = UDim2.fromScale(1, 1) })
  -- a modal button: frees the cursor, and swallows clicks so nothing reaches the game
  local veil = UI.new("TextButton", { Name = "Veil", Text = "", AutoButtonColor = false, Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(0, 0, 0),
    BackgroundTransparency = 1, BorderSizePixel = 0, Modal = true, Parent = root })
  Motion.to(veil, "BackgroundTransparency", 0, "smooth")
  local stage = UI.frame(root, { Name = "Stage", Size = UDim2.fromScale(1, 1), ZIndex = 2 })
  local filmHost = UI.frame(stage, { Name = "FilmHost", Size = UDim2.fromScale(1, 1), ZIndex = 1 })

  -- ---- the player
  local setName = (not Assets.lite) and spec and Film.pick(Config.get("app.filmQuality"), spec) or nil
  local volume = Config.get("app.introVolume") / 100
  local player
  if setName then
    local exitFrame = math.min(spec.count - 1, math.floor(plan.exit * spec.fps) + 12)
    player = Film.new(filmHost, { spec = spec, set = setName, slots = 10, audio = volume > 0, volume = 0, start = plan.start, to = exitFrame, warmTo = exitFrame, budget = 2 })
  end
  local cuts = spec and spec.cuts or {}

  -- ---- grade: vignette, grain, bars
  UI.image(stage, "vignette", { Name = "Vignette", Size = UDim2.fromScale(1, 1), ImageTransparency = 0.25, ZIndex = 3 })
  local grain = UI.image(stage, "grain", { Name = "Grain", Size = UDim2.new(1, 600, 1, 600), Position = UDim2.fromOffset(-300, -300), ScaleType = Enum.ScaleType.Tile,
    TileSize = UDim2.fromOffset(512, 512), ImageTransparency = 0.925, ZIndex = 4 })
  local dim = UI.frame(stage, { Name = "Dim", Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(0, 0, 0), BackgroundTransparency = 1, ZIndex = 5 })
  local barHeight = math.floor(view.Y * 0.085)
  local barTop = UI.frame(stage, { Name = "BarTop", Size = UDim2.new(1, 0, 0, barHeight), Position = UDim2.fromOffset(0, -barHeight), BackgroundColor3 = Color3.new(0, 0, 0),
    BackgroundTransparency = 0, ZIndex = 6 })
  local barBottom = UI.frame(stage, { Name = "BarBottom", Size = UDim2.new(1, 0, 0, barHeight), Position = UDim2.new(0, 0, 1, 0), BackgroundColor3 = Color3.new(0, 0, 0),
    BackgroundTransparency = 0, ZIndex = 6 })

  -- ---- type, laid out in 1080p units and scaled to the screen
  local typeLayer = UI.frame(stage, { Name = "Type", Size = UDim2.fromScale(1 / k, 1 / k), ZIndex = 8 })
  local typeScale = Instance.new("UIScale"); typeScale.Scale = k; typeScale.Parent = typeLayer
  local W, H = view.X / k, view.Y / k
  -- (the author's edit has its own monitor strips down both sides: the type keeps inside them)
  local margin = plan.margin and math.floor(W * plan.margin) or 56
  local shadowed = { TextStrokeColor3 = Color3.new(0, 0, 0), TextStrokeTransparency = 0.72 }
  local function small(text, font, color, props)
    local item = label(typeLayer, text, font, 11, color, props)
    for key, value in pairs(shadowed) do item[key] = value end
    item.TextTransparency = 1
    return item
  end
  local topLeft = small("BASED HUB", "wideBold", BONE, { Position = UDim2.fromOffset(margin, 34) })
  local timecode = small("", "mono400", SOFT, { Position = UDim2.new(1, -margin, 0, 34), AnchorPoint = Vector2.new(1, 0) })
  local registry = B.Registry and B.Registry.status() or { engineered = false }
  local gameLine = registry.engineered and ("ENGINEERED FOR  ·  " .. string.upper(registry.name or "THIS GAME")) or "NO SCRIPT ENGINEERED FOR THIS GAME YET  ·  UNIVERSAL LOADED"
  local bottomLeft = small("V" .. B.VERSION .. "  ·  " .. (registry.engineered and "ENGINEERED" or "UNIVERSAL"), "mono400", SOFT, { Position = UDim2.new(0, margin, 1, -44) })
  local skip = small("SPACE TO SKIP", "mono400", SOFT, { Position = UDim2.new(1, -margin, 1, -44), AnchorPoint = Vector2.new(1, 0) })
  local progress = UI.frame(typeLayer, { Name = "Progress", Size = UDim2.new(0, 0, 0, 1), Position = UDim2.new(0, 0, 1, -1), BackgroundColor3 = BONE, BackgroundTransparency = 0.35 })

  local baseline = -(barHeight / k) - 30
  local greeting1, greeting2
  if plan.greeting then
    greeting1 = maskLine(typeLayer, "Good to see you,", "serifItalic", 62, BONE, "left", UDim2.new(0, margin, 1, baseline - 70))
    greeting2 = maskLine(typeLayer, B.LP.DisplayName .. ".", "serifItalic", 62, BONE, "left", UDim2.new(0, margin, 1, baseline))
  end
  -- the per-cut lines alternate sides, so the eye is carried across the frame
  local lines = {}
  -- In a game that has a script of its own, the edit's two lines about Universal ("Universal",
  -- "everywhere else.") would be about somewhere else: they name the game instead, and the last
  -- line is the game's own if it has one.
  local words = {}
  for index, cue in ipairs(plan.lines or {}) do words[index] = cue[2] end
  local universal = table.find(words, "Universal")
  if registry.engineered and universal then
    words[universal], words[universal + 1] = registry.name or "This game", "is loaded."
    if words[universal + 2] then words[universal + 2] = registry.tagline or words[universal + 2] end
  end
  for index, cue in ipairs(plan.lines or {}) do
    local right = index % 2 == 0
    local line = maskLine(typeLayer, words[index], "serifItalic", 92, BONE, right and "right" or "left", UDim2.new(right and 1 or 0, right and -margin or margin, 1, baseline))
    line.clip.Visible = false
    line.label.TextStrokeColor3 = Color3.new(0, 0, 0)
    line.label.TextStrokeTransparency = 0.8
    lines[index] = { at = cue[1], untilTime = (plan.lines[index + 1] and plan.lines[index + 1][1]) or plan.linesEnd, line = line }
  end

  -- ---- wordmark: five glyph images that rise out of their own masks, then "hub"
  local mark = UI.frame(typeLayer, { Name = "Wordmark", AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.47) })
  local markScale = Instance.new("UIScale"); markScale.Parent = mark
  local wm = Assets.manifest.wordmark
  local letters = {}
  local hubImage
  local markWidth, capPx = 0, math.min(H * 0.16, W * 0.085)
  if wm and wm.glyphs and Assets.id(wm.glyphs[1].image) then
    local s = capPx / wm.cap
    local x = 0
    for index, glyph in ipairs(wm.glyphs) do
      local w, h = glyph.w * s, glyph.h * s
      local clip = UI.frame(mark, { Name = glyph.char, Size = UDim2.fromOffset(w, h), Position = UDim2.fromOffset(x - wm.pad * s, 0), ClipsDescendants = true })
      local image = UI.new("ImageLabel", { BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), Position = UDim2.fromScale(0, 1.05), Image = Assets.id(glyph.image) or "",
        ImageColor3 = BONE, Parent = clip })
      letters[index] = { image = image }
      x += glyph.advance * s * 0.972
    end
    local hub = wm.hub
    local hs = s * (wm.size / 560) * 0.98
    local hw, hh = hub.w * hs, hub.h * hs
    hubImage = UI.new("ImageLabel", { Name = "Hub", BackgroundTransparency = 1, Size = UDim2.fromOffset(hw, hh),
      Position = UDim2.fromOffset(x + 4 * s, (wm.pad + wm.cap) * s - hub.baseline * hs), Image = Assets.id(hub.image) or "", ImageColor3 = T.accent, ImageTransparency = 1, Parent = mark })
    markWidth = x + 4 * s + hw - hub.pad * hs * 2
    mark.Size = UDim2.fromOffset(markWidth, (wm.cap + wm.pad * 2) * s)
  else
    -- no art installed: set the wordmark in type
    local row = UI.frame(mark, { AutomaticSize = Enum.AutomaticSize.XY })
    UI.list(row, "x", 6, { v = "Bottom" })
    letters[1] = { text = label(row, "BASED", "wideBlack", 92, BONE, { LayoutOrder = 1, TextTransparency = 1 }) }
    hubImage = label(row, "hub", "serifItalic", 100, T.accent, { LayoutOrder = 2, TextTransparency = 1 })
    markWidth, capPx = 560, 70
    mark.Size = UDim2.fromOffset(markWidth, 110)
  end
  local glow = UI.image(typeLayer, "glow", { Name = "Glow", AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.47), Size = UDim2.fromOffset(markWidth * 1.7, capPx * 5.5),
    ImageColor3 = T.accent, ImageTransparency = 1, ZIndex = 0 })
  local below = UI.frame(typeLayer, { Name = "Below", AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0.47, capPx * 0.5 + 34), Size = UDim2.fromOffset(markWidth, 60) })
  local rule = UI.frame(below, { Name = "Rule", AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.fromScale(0.5, 0), Size = UDim2.new(0, 0, 0, 1), BackgroundColor3 = BONE, BackgroundTransparency = 0.45 })
  local statusLine = label(below, gameLine, "wideBold", 10.5, registry.engineered and BONE or SOFT, { AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0, 16),
    TextTransparency = 1, TextXAlignment = Enum.TextXAlignment.Center, TextStrokeColor3 = Color3.new(0, 0, 0), TextStrokeTransparency = 0.75 })
  local keyHint = string.upper(Config.keyLabel(Config.get("app.key.menu"))) .. "  ·  OPENS AND CLOSES THE HUB"
  local hintLine = label(below, keyHint, "mono400", 10.5, SOFT, { AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0, 38),
    TextTransparency = 1, TextXAlignment = Enum.TextXAlignment.Center, TextStrokeColor3 = Color3.new(0, 0, 0), TextStrokeTransparency = 0.75 })
  local flash = UI.frame(root, { Name = "Flash", Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(1, 1, 1), BackgroundTransparency = 1, ZIndex = 20 })
  -- (a film that fades out at its end: black over the whole stage, picture, type and all)
  local fader = UI.frame(stage, { Name = "Fader", Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(0, 0, 0), BackgroundTransparency = 1, ZIndex = 9 })

  -- ---- prelude: decode the opening frames, and say how far along that is
  local ring = UI.image(typeLayer, "ring", { Name = "Ring", AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromOffset(34, 34), ImageTransparency = 1 })
  local sweep = UI.gradient(ring, { Transparency = UI.alphaSeq(0, 0, 0.5, 0.2, 1, 1), Rotation = 0 })
  local percent = label(typeLayer, "00", "mono400", 11, SOFT, { AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0.5, 30), TextTransparency = 1,
    TextXAlignment = Enum.TextXAlignment.Center })
  local spinning = true
  local spin = Motion.every(function(dt)
    if spinning then sweep.Rotation = (sweep.Rotation + dt * 300) % 360 end
  end, nil, "loader.spin")
  -- only show the spinner if this takes long enough to be noticed
  local showSpinner = Motion.after(0.3, function()
    if spinning then ring.ImageTransparency = 0.2; percent.TextTransparency = 0.3 end
  end, "loader.spinner")
  local wordImages = {}
  for _, entry in ipairs(letters) do
    if entry.image then wordImages[#wordImages + 1] = entry.image end
  end
  task.spawn(function() pcall(function() S.ContentProvider:PreloadAsync(wordImages) end) end)
  if player then
    player:prepare(8, 5, function(p) percent.Text = string.format("%02d", math.floor(p * 99)) end)
    if player.missing then player:destroy(); player = nil end
  else
    task.wait(0.25)
  end
  if not player then
    -- no film installed: the wordmark alone, on the quick cut's timing, then the hub
    plan = MODES.quick
    DROP = plan.drop
    for _, entry in ipairs(lines) do entry.line.clip:Destroy() end
    table.clear(lines)
    if greeting1 then greeting1.clip:Destroy(); greeting2.clip:Destroy(); greeting1, greeting2 = nil, nil end
  end
  spinning = false
  showSpinner.cancel(); spin.cancel()
  ring:Destroy(); percent:Destroy()
  if not B.alive then return end

  -- ---- run
  local clockStart = os.clock()
  local finished, exiting = false, false
  local punch = Motion.spring(1, "bouncy", function(x) markScale.Scale = x[1] end, 0.0005)
  punch:snap({ 1 })
  local shake = Motion.spring(2, { 0.5, 0.55 }, function(x) stage.Position = UDim2.fromOffset(x[1], x[2]) end, 0.05)
  local lastCut = plan.start
  -- a cut that starts after the drop never plays it
  local dropped = plan.start >= DROP
  local finaled = false
  local shot = 0
  local grainAt = 0
  local job, inputConnection
  local total = (spec and spec.duration or plan.exit)

  local function cleanup()
    if job then job.cancel() end
    if inputConnection then inputConnection:Disconnect() end
    Loader.active = false
    Loader.unit = nil
  end
  local function exit(skipped)
    if exiting then return end
    exiting = true
    if not skipped and plan.fade then
      -- a film that has faded out ends in black: the hub comes up as the black clears
      local track = player and player.sound
      if track then player.sound = nil; track:Destroy() end
      Loader.last = { mode = mode, set = setName, skipped = false, quiet = true, stats = player and player.stats or nil, seconds = os.clock() - clockStart }
      if player then player:destroy() end
      stage:Destroy()
      cleanup()
      B.try("loader.done", done)
      veil.Modal = false
      Motion.tween(0.9, ease.outCubic, function(p) veil.BackgroundTransparency = p end, function() gui:Destroy() end)
      return
    end
    -- out on white: a flash covers the swap from film to hub
    Motion.tween(0.07, ease.linear, function(p) flash.BackgroundTransparency = 1 - p end, function()
      local track = player and player.sound
      if track then
        track.Parent = gui
        player.sound = nil
        local from = track.Volume
        Motion.tween(skipped and 0.9 or 1.6, ease.outSine, function(p) track.Volume = from * (1 - p) end, function() track:Destroy() end)
      end
      Loader.last = { mode = mode, set = setName, skipped = skipped, stats = player and player.stats or nil, seconds = os.clock() - clockStart }
      if player then player:destroy() end
      stage:Destroy()
      veil:Destroy()
      cleanup()
      B.try("loader.done", done)
      Motion.tween(0.6, ease.outCubic, function(p) flash.BackgroundTransparency = p end, function() gui:Destroy() end)
    end)
  end
  inputConnection = UIS.InputBegan:Connect(function(input)
    if input.KeyCode == Enum.KeyCode.Space or input.KeyCode == Enum.KeyCode.Return or input.KeyCode == Enum.KeyCode.Escape then
      if os.clock() - clockStart > 0.35 and not B.genv.BASED_NOSKIP then exit(true) end
    end
  end)
  B.own(inputConnection)

  if player then
    player:setAlpha(0)
    player:play()
  end
  local wordOut, wordBack = plan.wordOut, plan.wordBack
  job = Motion.every(function()
    local since = os.clock() - clockStart
    local t = player and player.time or (plan.start + since)
    -- picture and sound come up together
    local fadeIn = win(since, 0, 0.55, ease.outCubic)
    if player then
      player:setAlpha(fadeIn)
      if not exiting then player:setVolume(volume * fadeIn) end
      player.zoom.Scale = t < DROP and util.lerp(1.07, 1.0, win(t, plan.start, (plan.calm or 2.9) - plan.start + 0.01, ease.outCubic)) or util.lerp(1.05, 1.0, win(t, DROP, 0.7, ease.outExpo))
    end
    -- letterbox: in for the opening, thrown open by the drop
    local bars = win(since, 0.05, 0.7, ease.outQuint) * (1 - win(t, DROP - 0.02, 0.32, ease.outExpo))
    barTop.Position = UDim2.fromOffset(0, -barHeight * (1 - bars))
    barBottom.Position = UDim2.new(0, 0, 1, -barHeight * bars)
    local chrome = win(since, 0.3, 0.6, ease.outCubic)
    topLeft.TextTransparency = 1 - chrome
    timecode.TextTransparency = 1 - chrome * 0.8
    bottomLeft.TextTransparency = 1 - chrome * 0.75
    skip.TextTransparency = 1 - chrome * 0.6
    timecode.Text = string.format("%05.2f  /  %05.2f", t, total)
    progress.Size = UDim2.new(util.clamp01((t - plan.start) / (plan.exit - plan.start)), 0, 0, 1)

    -- opening greeting
    if greeting1 then
      local inAt, outAt = plan.greet and plan.greet[1] or 0.7, plan.greet and plan.greet[2] or 2.3
      greeting1.set(win(t, inAt, 0.85, ease.outExpo), win(t, outAt, 0.45, ease.inCubic))
      greeting2.set(win(t, inAt + 0.2, 0.85, ease.outExpo), win(t, outAt + 0.08, 0.45, ease.inCubic))
    end
    -- one line per cut: in on the cut, out just before the next
    for _, entry in ipairs(lines) do
      local on = t >= entry.at - 0.02 and t < entry.untilTime + 0.05
      if entry.line.clip.Visible ~= on then entry.line.clip.Visible = on end
      if on then
        entry.line.set(win(t, entry.at, 0.36, ease.outExpo), win(t, entry.untilTime - 0.16, 0.16, ease.inCubic))
      end
    end

    -- wordmark: in during the blackout, out on the flash, back for the finale
    local breath = plan.breath or 0.16
    local inhale = t < DROP and win(t, DROP - breath, breath - 0.02, ease.inCubic) or 0
    local leaving = wordOut and t >= wordOut and (not wordBack or t < wordBack)
    local returned = wordBack and t >= wordBack
    for index, entry in ipairs(letters) do
      local y, alpha
      if returned then
        local p = win(t, wordBack + (index - 1) * 0.06, 0.6, ease.outExpo)
        y, alpha = 1.05 * (1 - p), 1
      elseif leaving then
        local p = win(t, wordOut + (index - 1) * 0.035, 0.34, ease.inCubic)
        y, alpha = -1.05 * p, 1
      else
        local p = win(t, plan.word + (index - 1) * plan.stagger, plan.rise, ease.outExpo)
        y, alpha = 1.05 * (1 - p), p
      end
      if entry.image then
        entry.image.Position = UDim2.fromScale(0, y)
        entry.image.ImageTransparency = inhale * 0.7
      else
        entry.text.TextTransparency = 1 - alpha * (1 - inhale * 0.7) * ((leaving and 1 - win(t, wordOut, 0.3)) or 1)
      end
    end
    local hubP, ruleP, statusP
    if returned then
      hubP, ruleP, statusP = win(t, wordBack + 0.32, 0.6, ease.outExpo), win(t, wordBack + 0.5, 0.7, ease.outExpo), win(t, wordBack + 0.72, 0.6, ease.outCubic)
      if statusLine.Text ~= keyHint then statusLine.Text = keyHint; statusLine.TextColor3 = BONE end
    elseif leaving then
      local gone = 1 - win(t, wordOut, 0.3, ease.inCubic)
      hubP, ruleP, statusP = gone, gone, gone
    else
      hubP, ruleP, statusP = win(t, plan.hub, 0.8, ease.outExpo), win(t, plan.rule, 0.75, ease.outExpo), win(t, plan.status, 0.6, ease.outCubic)
    end
    if hubImage:IsA("ImageLabel") then hubImage.ImageTransparency = 1 - hubP * (1 - inhale * 0.7) else hubImage.TextTransparency = 1 - hubP * (1 - inhale * 0.7) end
    rule.Size = UDim2.new(ruleP, 0, 0, 1)
    statusLine.TextTransparency = 1 - statusP * (1 - inhale * 0.6)
    hintLine.TextTransparency = plan.hint and 1 - win(t, plan.hint, 0.6, ease.outCubic) * 0.85 or 1
    local glowBase = (leaving and 0) or (returned and win(t, wordBack, 0.8, ease.outCubic) * 0.2) or win(t, plan.word + 0.2, 1.4, ease.outCubic) * 0.2
    local burst = (t >= DROP and not leaving and 0.16 * (1 - win(t, DROP, 1.2, ease.outCubic)) or 0)
      + (plan.finale and t >= plan.finale and 0.3 * (1 - win(t, plan.finale, 1.6, ease.outCubic)) or 0)
    glow.ImageTransparency = 1 - math.min(1, glowBase + burst)
    dim.BackgroundTransparency = 1 - inhale * 0.5

    if not dropped then
      -- anticipation: the mark leans in before the hit
      if t < DROP and t > DROP - 0.75 then punch:snap({ 1 + 0.03 * win(t, DROP - 0.75, 0.75, ease.inCubic) }) end
      if t >= DROP then
        dropped = true
        punch:snap({ 1.11 }); punch:to({ 1 }, "bouncy")
        shake:impulse(1, 900 * k); shake:impulse(2, -520 * k)
        flash.BackgroundTransparency = 0.12
        Motion.tween(0.5, ease.outCubic, function(p) if not exiting then flash.BackgroundTransparency = 0.12 + 0.88 * p end end)
        lastCut = DROP
      end
    else
      -- every later cut of the edit gives the frame a small kick
      for _, cut in ipairs(cuts) do
        if cut > lastCut + 0.05 and cut <= t and cut < plan.exit - 0.05 then
          lastCut = cut
          punch:impulse(1, 0.9)
          shake:impulse(1, (math.random() - 0.5) * 420 * k); shake:impulse(2, (math.random() - 0.5) * 300 * k)
          if not exiting then
            flash.BackgroundTransparency = 0.88
            Motion.tween(0.28, ease.outCubic, function(p) if not exiting then flash.BackgroundTransparency = 0.88 + 0.12 * p end end)
          end
        end
      end
    end
    -- the finale: the wordmark lands on the film's last hit
    if plan.finale and not finaled and t >= plan.finale then
      finaled = true
      punch:snap({ 1.1 }); punch:to({ 1 }, "bouncy")
      shake:impulse(1, 700 * k); shake:impulse(2, -420 * k)
      if not exiting then
        flash.BackgroundTransparency = 0.3
        Motion.tween(0.55, ease.outCubic, function(p) if not exiting then flash.BackgroundTransparency = 0.3 + 0.7 * p end end)
      end
    end
    -- after it, each loud shot kicks the wordmark
    if plan.shots and plan.shots[shot + 1] and t >= plan.shots[shot + 1] then
      shot += 1
      punch:impulse(1, 1.4)
      shake:impulse(1, (math.random() - 0.5) * 520 * k); shake:impulse(2, (math.random() - 0.5) * 380 * k)
      if not exiting then
        flash.BackgroundTransparency = 0.9
        Motion.tween(0.16, ease.outCubic, function(p) if not exiting then flash.BackgroundTransparency = 0.9 + 0.1 * p end end)
      end
    end
    -- the end: a slow fade over the film's last words (a quarter sine, as its sound fades)
    if plan.fade then
      local out = util.clamp01((t - plan.fade[1]) / (plan.fade[2] - plan.fade[1]))
      fader.BackgroundTransparency = math.cos(out * math.pi / 2)
    end
    -- film grain drifts at film cadence, not at the display's
    if since - grainAt > 1 / 24 then
      grainAt = since
      grain.Position = UDim2.fromOffset(-300 + math.random(-250, 250), -300 + math.random(-250, 250))
    end
    if not finished and (t >= plan.exit or (player and player.ended)) then
      finished = true
      exit(false)
    end
  end, nil, "loader")
end
end
do -- 09b_signal.lua
-- ============================================================================
--  09b signal  the second intro: the live game in black and white, framed like
--              a broadcast monitor, cut to the track
--
--  The film intro (09 loader) plays an edit. This one plays nothing recorded:
--  for seven seconds the camera is taken and pointed at the player's own
--  avatar, wherever they stand, in whatever game, with the picture graded to
--  black and white. Shots of it (a close-up that pushes in, low from the
--  ground, backlit from behind, overhead and turning, a dutch tilt, the eyes)
--  cut faster and faster as the track builds; on the drop the wordmark is hit
--  onto the screen. Down both sides run two monitor strips, like the edit the
--  author sent as the look to beat: waveform traces, red level blocks and a
--  twisting ribbon, all driven by the loudness of the track as it plays.
--  Letterbox bars cover the game's own buttons and bars.
--
--  Cues are times in the hub's film track (film.json: the drop at 5.93, the
--  white flash at 9.22); it is played from 2.0. With no track installed the
--  same cues run on the clock, silent, the strips driven by a beat of their own.
-- ============================================================================
local S, util, Motion, Config, Assets = B.S, B.util, B.Motion, B.Config, B.Assets
local UIS, RunService = S.UserInputService, S.RunService
local ease, win = Motion.ease, Motion.window
local Intro = { active = false }
B.SignalIntro = Intro

local BONE = Color3.fromRGB(245, 244, 239)
local DIM = Color3.fromRGB(150, 150, 158)
local RED = Color3.fromRGB(236, 96, 98)
local VIOLET = Color3.fromRGB(132, 124, 255)
local CYAN = Color3.fromRGB(90, 230, 255)
local BLACK = Color3.new(0, 0, 0)

local START, DROP, LEAVE, OUT = 2.0, 5.9333, 8.3833, 9.2167
-- the cuts: faster and faster as the track builds, then the edit's own after the drop
local CUTS = { 2.0, 2.88, 3.62, 4.25, 4.75, 5.15, 5.45, 5.7, 5.9333, 6.8833, 7.6167, 8.3833 }
local ORDER = { "face", "low", "behind", "orbit", "dolly", "dutch", "crane", "eyes", "hero", "orbitWide", "low", "face" }
local LINES = { "SIGNAL ACQUIRED", "SUBJECT  //  %NAME%", "LOCATION  //  %GAME%", "THREAT LEVEL  //  MAXIMUM", "STATUS  //  ARMED",
  "ALL SYSTEMS  //  ONLINE", "LOCKING ON", "" }
Intro.CUTS, Intro.DROP, Intro.OUT, Intro.START = CUTS, DROP, OUT, START

local STRIP = 168            -- design px (the screen's height is 1080 of them) of each monitor strip
local BAR = 112              -- letterbox bars over the game's own top buttons and bottom bars
local TRACE_N, RIBBON_N, STRIPES = 30, 26, 13

-- ---------------------------------------------------------------- the shots
-- Each: from the avatar `s` (root, head, feet, forward, right, yaw) and how far through the shot it
-- is (0..1) -> where the camera is, what it looks at, and the field of view.
local SHOTS = {
  face = function(s, p) return s.head + s.forward * util.lerp(4.4, 2.7, p) + s.right * 0.45 - Vector3.yAxis * 0.35, s.head + Vector3.yAxis * 0.1, 38 end,
  low = function(s, p) return s.feet + s.forward * util.lerp(9.5, 7.2, p) + s.right * 1.6 + Vector3.yAxis * 0.5, s.head + Vector3.yAxis * 2.2, 64 end,
  behind = function(s, p) return s.root - s.forward * util.lerp(7.5, 5.6, p) - s.right * 1.3 - Vector3.yAxis * 1.1, s.head + s.forward * 7 + Vector3.yAxis * 3.2, 56 end,
  orbit = function(s, p)
    local a = s.yaw + p * 1.25
    return s.root + Vector3.new(math.cos(a) * 9, util.lerp(26, 19, p), math.sin(a) * 9), s.root, 50
  end,
  dolly = function(s, p) return s.root + s.right * 7.5 + s.forward * util.lerp(-3.2, 3.2, p) + Vector3.yAxis * 0.8, s.root + Vector3.yAxis * 0.9, 44 end,
  dutch = function(s, p) return s.head + s.forward * 5.2 - s.right * 2.3 + Vector3.yAxis * 0.6, s.head, 40, math.rad(util.lerp(-13, -19, p)) end,
  crane = function(s, p) return s.root + s.forward * 8 + s.right * -1 + Vector3.yAxis * util.lerp(-2, 6.5, p), s.root + Vector3.yAxis * util.lerp(0, 2.2, p), 50 end,
  eyes = function(s, p) return s.head + s.forward * util.lerp(2.5, 1.95, p) + Vector3.yAxis * 0.18, s.head + Vector3.yAxis * 0.18, 30 end,
  hero = function(s, p)
    local a = s.yaw + 0.55 + p * 0.55
    local out = util.lerp(9, 16, ease.outCubic(p))
    return s.root + Vector3.new(math.cos(a) * out, util.lerp(0.6, 4.2, p), math.sin(a) * out), s.root + Vector3.yAxis * 1.6, 72
  end,
  orbitWide = function(s, p)
    local a = s.yaw - 0.9 - p * 0.8
    return s.root + Vector3.new(math.cos(a) * 15, util.lerp(7, 10, p), math.sin(a) * 15), s.root + Vector3.yAxis * 1.2, 60
  end,
}

-- the avatar, or (no body yet) wherever the camera was looking
local function subject(camera, fallback)
  local character = B.LP.Character
  local root = character and character:FindFirstChild("HumanoidRootPart")
  local head = character and character:FindFirstChild("Head")
  if root and head then
    local look = Vector3.new(root.CFrame.LookVector.X, 0, root.CFrame.LookVector.Z)
    look = look.Magnitude > 1e-3 and look.Unit or Vector3.new(0, 0, -1)
    local right = look:Cross(Vector3.yAxis).Unit
    return { root = root.Position, head = head.Position, feet = root.Position - Vector3.yAxis * 3, forward = look, right = right,
      yaw = math.atan2(look.Z, look.X), body = character }
  end
  local at = fallback or (camera.Focus.Position)
  local look = Vector3.new(camera.CFrame.LookVector.X, 0, camera.CFrame.LookVector.Z)
  look = look.Magnitude > 1e-3 and -look.Unit or Vector3.new(0, 0, 1)
  return { root = at, head = at + Vector3.yAxis * 1.5, feet = at - Vector3.yAxis * 3, forward = look, right = look:Cross(Vector3.yAxis).Unit,
    yaw = math.atan2(look.Z, look.X) }
end

-- ---------------------------------------------------------------- pieces
local function frame(parent, props)
  local item = Instance.new("Frame")
  item.BorderSizePixel = 0
  item.BackgroundColor3 = BONE
  for key, value in pairs(props or {}) do item[key] = value end
  item.Parent = parent
  return item
end
local function label(parent, text, font, size, color, props)
  local item = Instance.new("TextLabel")
  item.BackgroundTransparency = 1
  item.BorderSizePixel = 0
  item.FontFace = B.F[font] or B.F.mono400
  item.TextSize = size
  item.Text = text
  item.TextColor3 = color or BONE
  item.AutomaticSize = Enum.AutomaticSize.XY
  item.TextXAlignment = Enum.TextXAlignment.Left
  for key, value in pairs(props or {}) do item[key] = value end
  item.Parent = parent
  return item
end
-- a straight piece of line from a to b (design px)
local function segment(item, a, b, thick)
  local d = b - a
  local length = d.Magnitude
  item.Position = UDim2.fromOffset((a.X + b.X) / 2, (a.Y + b.Y) / 2)
  item.Size = UDim2.fromOffset(length + 1, thick)
  item.Rotation = math.deg(math.atan2(d.Y, d.X))
end

-- One monitor strip: two waveform traces, three red level blocks, a twisting ribbon, ticks and
-- read-outs. `step(t, level, beat)` moves all of it.
local function strip(parent, right, height)
  local holder = frame(parent, { Name = right and "StripRight" or "StripLeft", BackgroundColor3 = BLACK, Size = UDim2.new(0, STRIP, 1, 0),
    AnchorPoint = Vector2.new(right and 1 or 0, 0), Position = UDim2.fromScale(right and 1 or 0, 0), ClipsDescendants = true, ZIndex = 10 })
  frame(holder, { Name = "Edge", Size = UDim2.new(0, 1, 1, 0), Position = UDim2.fromScale(right and 0 or 1, 0), AnchorPoint = Vector2.new(right and 0 or 1, 0),
    BackgroundColor3 = Color3.fromRGB(52, 52, 60), ZIndex = 11 })
  local traces = {}
  for index = 1, 2 do
    local list = {}
    for i = 1, TRACE_N do
      list[i] = frame(holder, { AnchorPoint = Vector2.new(0.5, 0.5), BackgroundTransparency = index == 1 and 0.02 or 0.5, ZIndex = 12 })
    end
    traces[index] = { segs = list, x = (index == 1) == right and STRIP * 0.72 or STRIP * 0.3, seed = math.random() * 1000, gain = index == 1 and 1 or 0.6 }
  end
  -- red level blocks: stacks of stripes, each stripe as wide as its band is loud
  local blocks = {}
  for index = 1, 3 do
    local top = height * (index == 1 and 0.12 or (index == 2 and 0.47 or 0.78))
    local list = {}
    for i = 1, STRIPES do
      list[i] = frame(holder, { AnchorPoint = Vector2.new(0.5, 0), BackgroundColor3 = RED, BackgroundTransparency = 0.12, ZIndex = 13,
        Position = UDim2.fromOffset(STRIP * (right and 0.4 or 0.6), top + (i - 1) * 6), Size = UDim2.fromOffset(4, 3) })
    end
    blocks[index] = { stripes = list, seed = math.random() * 1000, centre = STRIP * (right and 0.4 or 0.6) }
  end
  -- the ribbon: a twist seen from the side, each rung as wide as the twist is turned toward us
  local ribbon = {}
  for i = 1, RIBBON_N do
    ribbon[i] = frame(holder, { AnchorPoint = Vector2.new(0.5, 0.5), BackgroundTransparency = 0.18, ZIndex = 12, Size = UDim2.fromOffset(4, 2) })
  end
  local ribbonX = STRIP * (right and 0.22 or 0.8)
  -- ticks across it, and its read-outs
  local ticks = {}
  for i = 1, 6 do
    ticks[i] = frame(holder, { BackgroundColor3 = VIOLET, BackgroundTransparency = 0.25, ZIndex = 14, Size = UDim2.fromOffset(STRIP * 0.5, 1),
      AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromOffset(STRIP / 2, height * math.random()) })
  end
  local reads = {}
  for i = 1, 4 do
    reads[i] = label(holder, "", "mono400", 10, DIM, { ZIndex = 15, Position = UDim2.fromOffset(right and 10 or 12, i <= 2 and (14 + (i - 1) * 14) or (height - 44 + (i - 3) * 14)),
      TextTransparency = 0.15 })
  end
  local api = { holder = holder }
  function api.step(t, level, beat, readout)
    -- traces: noise along the strip, its reach the loudness, a kick on each beat
    for _, trace in ipairs(traces) do
      local prev
      local reach = (8 + 46 * level + 30 * beat) * trace.gain
      for i = 1, TRACE_N + 1 do
        local y = (i - 1) / TRACE_N * height
        local n = math.noise(trace.seed + i * 0.37, t * 7.5) + 0.45 * math.noise(trace.seed * 0.5 + i * 1.9, t * 17)
        local point = Vector2.new(trace.x + n * reach, y)
        if prev then segment(trace.segs[i - 1], prev, point, trace.gain == 1 and 2 or 1) end
        prev = point
      end
    end
    -- blocks: each stripe a band, wider with the level, flaring on the beat
    for _, block in ipairs(blocks) do
      for i, stripe in ipairs(block.stripes) do
        local band = 0.5 + 0.5 * math.noise(block.seed + i * 0.61, t * 9)
        local width = math.clamp((0.1 + 0.9 * level * band + 0.35 * beat) * STRIP * 0.78, 3, STRIP * 0.86)
        stripe.Size = UDim2.fromOffset(width, 3)
        stripe.BackgroundTransparency = 0.05 + 0.5 * (1 - band) * (1 - beat)
      end
    end
    -- the ribbon turns at the tempo of the track
    for i, rung in ipairs(ribbon) do
      local y = (i - 0.5) / RIBBON_N * height
      local turn = math.sin(i * 0.55 + t * (3.2 + 4 * level))
      rung.Position = UDim2.fromOffset(ribbonX, y)
      rung.Size = UDim2.fromOffset(math.max(math.abs(turn) * (22 + 26 * level), 2), turn > 0 and 2 or 1)
      rung.BackgroundTransparency = turn > 0 and 0.08 or 0.55
    end
    -- ticks hop about now and then
    for _, tick in ipairs(ticks) do
      if math.random() < 0.06 + 0.3 * beat then tick.Position = UDim2.fromOffset(STRIP / 2 + (math.random() - 0.5) * 30, height * math.random()) end
      tick.BackgroundTransparency = 0.2 + 0.6 * math.random() * (1 - beat)
    end
    for i, item in ipairs(reads) do item.Text = readout[i] or "" end
  end
  return api
end

-- ---------------------------------------------------------------- the run
function Intro.run(done)
  if Intro.active then return end
  Intro.active = true
  local camera = workspace.CurrentCamera
  local view = B.viewport()
  local k = math.clamp(view.Y / 1080, 0.5, 2.5)
  local W, H = view.X / k, view.Y / k
  local gui = B.screen(9500)
  local root = frame(gui, { Name = "Signal", Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1 })
  -- (a modal button frees the cursor and keeps clicks from the game)
  local veil = Instance.new("TextButton")
  veil.Text, veil.AutoButtonColor, veil.Modal, veil.BorderSizePixel = "", false, true, 0
  veil.Size, veil.BackgroundColor3, veil.BackgroundTransparency = UDim2.fromScale(1, 1), BLACK, 0
  veil.Parent = root
  local layer = frame(root, { Name = "Layer", BackgroundTransparency = 1, Size = UDim2.fromOffset(W, H), ZIndex = 2 })
  local scale = Instance.new("UIScale"); scale.Scale = k; scale.Parent = layer

  -- ---- the grade: black and white, hard, a little bloom on the highlights
  local grade = Instance.new("ColorCorrectionEffect")
  grade.Name = util.randomName()
  grade.Saturation, grade.Contrast, grade.Brightness, grade.TintColor = -1, 0.72, -0.07, Color3.fromRGB(238, 240, 248)
  grade.Enabled = false
  grade.Parent = S.Lighting
  local bloom = Instance.new("BloomEffect")
  bloom.Name = util.randomName()
  bloom.Intensity, bloom.Size, bloom.Threshold, bloom.Enabled = 0.55, 30, 0.86, false
  bloom.Parent = S.Lighting
  local blur = Instance.new("BlurEffect")
  blur.Name = util.randomName()
  blur.Size, blur.Enabled = 0, true
  blur.Parent = S.Lighting

  -- ---- the frame: strips, bars, grain
  local height = H
  local left, right = strip(layer, false, height), strip(layer, true, height)
  local barTop = frame(layer, { Name = "BarTop", BackgroundColor3 = BLACK, Size = UDim2.new(1, 0, 0, BAR), ZIndex = 8 })
  local barBottom = frame(layer, { Name = "BarBottom", BackgroundColor3 = BLACK, Size = UDim2.new(1, 0, 0, BAR), AnchorPoint = Vector2.new(0, 1), Position = UDim2.fromScale(0, 1), ZIndex = 8 })
  local grain = Instance.new("ImageLabel")
  grain.BackgroundTransparency, grain.Image, grain.ScaleType, grain.TileSize = 1, Assets.image("grain") or "", Enum.ScaleType.Tile, UDim2.fromOffset(384, 384)
  grain.Size, grain.Position, grain.ImageTransparency, grain.ZIndex = UDim2.new(1, 600, 1, 600), UDim2.fromOffset(-300, -300), 0.86, 30
  grain.Parent = layer
  local vignette = Instance.new("ImageLabel")
  vignette.BackgroundTransparency, vignette.Image, vignette.Size, vignette.ImageTransparency, vignette.ZIndex = 1, Assets.image("vignette") or "", UDim2.fromScale(1, 1), 0.2, 7
  vignette.Parent = layer
  local flash = frame(root, { Name = "Flash", BackgroundColor3 = Color3.new(1, 1, 1), BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), ZIndex = 50 })

  -- ---- type
  local inner = STRIP + 34
  local registry = B.Registry and B.Registry.status() or {}
  local gameName = string.upper(registry.name or "this game")
  local name = string.upper(B.LP.DisplayName)
  local head = label(layer, "BASED  //  SIGNAL", "wideBold", 13, BONE, { Position = UDim2.fromOffset(inner, BAR / 2), AnchorPoint = Vector2.new(0, 0.5), ZIndex = 20, TextTransparency = 1 })
  local rec = label(layer, "", "mono500", 12, BONE, { Position = UDim2.new(1, -inner, 0, BAR / 2), AnchorPoint = Vector2.new(1, 0.5), ZIndex = 20, TextTransparency = 1,
    TextXAlignment = Enum.TextXAlignment.Right })
  local dot = frame(layer, { BackgroundColor3 = RED, Size = UDim2.fromOffset(9, 9), AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -inner - 168, 0, BAR / 2), ZIndex = 20,
    BackgroundTransparency = 1 })
  local corner = Instance.new("UICorner"); corner.CornerRadius = UDim.new(1, 0); corner.Parent = dot
  local channel = label(layer, "CH 01  //  " .. gameName, "mono400", 12, DIM, { Position = UDim2.new(0, inner, 1, -BAR / 2), AnchorPoint = Vector2.new(0, 0.5), ZIndex = 20, TextTransparency = 1 })
  local skip = label(layer, "SPACE TO SKIP", "mono400", 12, DIM, { Position = UDim2.new(1, -inner, 1, -BAR / 2), AnchorPoint = Vector2.new(1, 0.5), ZIndex = 20, TextTransparency = 1,
    TextXAlignment = Enum.TextXAlignment.Right })
  local line = label(layer, "", "mono500", 17, BONE, { Position = UDim2.new(0, inner, 1, -BAR - 26), AnchorPoint = Vector2.new(0, 1), ZIndex = 20, TextStrokeTransparency = 0.55 })
  local lineBar = frame(layer, { BackgroundColor3 = RED, Size = UDim2.fromOffset(0, 3), Position = UDim2.new(0, inner, 1, -BAR - 18), ZIndex = 20 })
  -- the name, huge, letter by letter while the track builds
  local big = label(layer, "", "wideBlack", math.clamp(1200 / math.max(#name, 4), 70, 150), BONE, { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
    ZIndex = 21, TextStrokeTransparency = 0.5, TextTransparency = 0.05, TextXAlignment = Enum.TextXAlignment.Center })
  local bigScale = Instance.new("UIScale"); bigScale.Parent = big
  -- the wordmark, and its two coloured ghosts for the hit
  local wm = Assets.manifest.wordmark
  local function wordmark(color, z)
    local holder = frame(layer, { BackgroundTransparency = 1, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.46), ZIndex = z })
    local capPx = math.min(H * 0.17, W * 0.09)
    local width = 0
    if wm and wm.glyphs and Assets.id(wm.glyphs[1].image) then
      local s = capPx / wm.cap
      local x = 0
      for _, glyph in ipairs(wm.glyphs) do
        local image = Instance.new("ImageLabel")
        image.BackgroundTransparency, image.Image, image.ImageColor3, image.ZIndex = 1, Assets.id(glyph.image) or "", color, z
        image.Size, image.Position = UDim2.fromOffset(glyph.w * s, glyph.h * s), UDim2.fromOffset(x - wm.pad * s, 0)
        image.Parent = holder
        x += glyph.advance * s * 0.972
      end
      width = x
      holder.Size = UDim2.fromOffset(width, (wm.cap + wm.pad * 2) * s)
    else
      local text = label(holder, "BASED", "wideBlack", 150, color, { ZIndex = z, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5) })
      local _ = text
      holder.Size = UDim2.fromOffset(620, 170)
    end
    local sizer = Instance.new("UIScale"); sizer.Parent = holder
    holder.Visible = false
    return holder, sizer
  end
  local ghostR, ghostRScale = wordmark(RED, 22)
  local ghostC, ghostCScale = wordmark(CYAN, 22)
  local mark, markScale = wordmark(BONE, 23)
  local tag = label(layer, "ENGINEERED FOR  //  " .. gameName, "wideBold", 15, BONE, { AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0.46, math.min(H * 0.17, W * 0.09) * 0.75 + 18),
    ZIndex = 23, TextTransparency = 1, TextXAlignment = Enum.TextXAlignment.Center })
  local rule = frame(layer, { BackgroundColor3 = RED, AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0.46, math.min(H * 0.17, W * 0.09) * 0.75 + 48), Size = UDim2.fromOffset(0, 3), ZIndex = 23 })
  local keyName = Config.keyLabel(Config.get("app.key.menu"))
  local hint = label(layer, string.upper(keyName) .. "  //  OPENS THE HUB", "mono500", 14, BONE, { AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0.46, math.min(H * 0.17, W * 0.09) * 0.75 + 66),
    ZIndex = 23, TextTransparency = 1, TextXAlignment = Enum.TextXAlignment.Center })

  -- ---- the track
  local volume = (Config.get("app.introVolume") or 50) / 100
  local film = B.Film and B.Film.spec
  local trackId = film and film.audio and not Assets.lite and Assets.id(film.audio) or nil
  local sound
  if trackId and volume > 0 then
    sound = Instance.new("Sound")
    sound.SoundId, sound.Volume, sound.Looped = trackId, volume, false
    sound.Parent = gui
    local waited = 0
    while not sound.IsLoaded and waited < 1.5 do waited += task.wait() end
    if not sound.IsLoaded then sound:Destroy(); sound = nil end
  end

  -- ---- the camera
  local saved = { type = camera.CameraType, subject = camera.CameraSubject, fov = camera.FieldOfView }
  local params = RaycastParams.new()
  params.FilterType = Enum.RaycastFilterType.Exclude
  params.IgnoreWater = true
  local focusAt = camera.Focus.Position
  local shake = Motion.spring(3, { 0.42, 0.5 }, function() end, 0.02)
  local shot = { index = 0, turn = 0 }
  -- A shot is taken from the side of the avatar that is open: the one asked for, or that one
  -- turned a quarter, a half or three quarters round, whichever has the most room at both ends.
  local function room(from, look)
    local hit = workspace:Raycast(look, from - look, params)
    return hit and hit.Distance / math.max((from - look).Magnitude, 1e-3) or 1
  end
  local function turned(from, look, turn)
    if turn == 0 then return from end
    local offset = from - look
    return look + CFrame.Angles(0, turn, 0):VectorToWorldSpace(offset)
  end
  local function cutTo(index)
    shot.index = index
    local s = subject(camera, focusAt)
    if s.body then params.FilterDescendantsInstances = { s.body } end
    local kind = ORDER[(index - 1) % #ORDER + 1]
    local best, bestRoom = 0, -1
    for _, turn in ipairs({ 0, math.pi / 2, -math.pi / 2, math.pi }) do
      local a1, l1 = SHOTS[kind](s, 0)
      local a2, l2 = SHOTS[kind](s, 1)
      local open = math.min(room(turned(a1, l1, turn), l1), room(turned(a2, l2, turn), l2))
      if open > bestRoom + 0.05 then best, bestRoom = turn, open end
      if open >= 0.999 then break end
    end
    shot.turn = best
  end
  local clock = START
  local function aim()
    local s = subject(camera, focusAt)
    local index = math.max(shot.index, 1)
    local kind = ORDER[(index - 1) % #ORDER + 1]
    local a, b = CUTS[index], CUTS[index + 1] or OUT
    local p = util.clamp01((clock - a) / math.max(b - a, 0.05))
    local from, look, fov, roll = SHOTS[kind](s, p)
    from = turned(from, look, shot.turn)
    -- (still never inside a wall: the camera is brought in front of anything left in the way)
    if s.body then params.FilterDescendantsInstances = { s.body } end
    local origin = look
    local hit = workspace:Raycast(origin, from - origin, params)
    if hit then from = hit.Position + (origin - hit.Position).Unit * 0.6 end
    local x = shake.x
    local cframe = CFrame.lookAt(from, look) * CFrame.Angles(x[2] * 0.004, x[1] * 0.004, (roll or 0) + x[3] * 0.003)
    camera.CameraType = Enum.CameraType.Scriptable
    camera.CFrame = cframe
    camera.FieldOfView = fov
  end
  RunService:BindToRenderStep("BasedSignalCamera", Enum.RenderPriority.Camera.Value + 10, function()
    if Intro.active then pcall(aim) end
  end)

  -- ---- leaving
  local finished = false
  local inputConnection, job
  local function restore()
    pcall(function() RunService:UnbindFromRenderStep("BasedSignalCamera") end)
    pcall(function()
      camera.CameraType = saved.type
      camera.CameraSubject = saved.subject
      camera.FieldOfView = saved.fov
    end)
    for _, effect in ipairs({ grade, bloom, blur }) do pcall(function() effect:Destroy() end) end
  end
  local function finish(skipped)
    if finished then return end
    finished = true
    flash.BackgroundTransparency = 0
    if job then job.cancel() end
    if inputConnection then inputConnection:Disconnect() end
    restore()
    Intro.active = false
    Intro.last = { skipped = skipped, sound = sound ~= nil, seconds = clock - START }
    if sound then
      local from = sound.Volume
      Motion.tween(skipped and 0.8 or 1.4, ease.outSine, function(p) if sound.Parent then sound.Volume = from * (1 - p) end end, function() pcall(function() sound:Destroy() end) end)
    end
    layer:Destroy()
    veil:Destroy()
    B.try("signal.done", done)
    Motion.tween(0.55, ease.outCubic, function(p) flash.BackgroundTransparency = p end, function()
      if sound and sound.Parent then sound.Parent = nil end
      gui:Destroy()
    end)
  end
  B.onUnload:connect(function() if Intro.active then restore(); Intro.active = false end end)
  inputConnection = UIS.InputBegan:Connect(function(input)
    if input.KeyCode == Enum.KeyCode.Space or input.KeyCode == Enum.KeyCode.Return or input.KeyCode == Enum.KeyCode.Escape then
      if clock - START > 0.35 and not B.genv.BASED_NOSKIP then finish(true) end
    end
  end)

  -- ---- run
  grade.Enabled, bloom.Enabled = true, true
  local started = os.clock()
  if sound then
    sound.TimePosition = START
    sound:Play()
  end
  local level, lastCut, beat, grainAt, typedFor = 0, 0, 0, 0, 0
  local dropped = false
  local frames = 0
  job = Motion.every(function(dt)
    if finished then return end
    if not B.alive then finish(true); return end
    frames += 1
    clock = START + (os.clock() - started)
    -- (tests: getgenv().BASED_SIGNAL_FREEZE = a film time holds the picture there)
    local freeze = B.genv.BASED_SIGNAL_FREEZE
    if type(freeze) == "number" and clock >= freeze then
      started += clock - freeze
      clock = freeze
    end
    -- the level: the track's own loudness when it plays, a beat of its own when it does not
    local loud
    if sound and sound.IsPlaying then loud = util.clamp01(sound.PlaybackLoudness / 520)
    else loud = 0.35 + 0.35 * math.abs(math.sin(clock * math.pi * 2.9)) end
    level += (loud - level) * (loud > level and 0.55 or 0.12)
    beat = math.max(beat - dt * 3.2, 0)
    -- cuts
    for index = lastCut + 1, #CUTS do
      if clock >= CUTS[index] then
        lastCut = index
        cutTo(index)
        beat = 1
        shake:impulse(1, (math.random() - 0.5) * 260); shake:impulse(2, (math.random() - 0.5) * 200); shake:impulse(3, (math.random() - 0.5) * 140)
        -- a frame of white or black on the cut, like the edit's
        if index > 1 and index ~= 9 then
          flash.BackgroundColor3 = (index % 2 == 0) and Color3.new(1, 1, 1) or BLACK
          flash.BackgroundTransparency = (index % 2 == 0) and 0.55 or 0.25
          task.delay(1 / 30, function() if not finished then flash.BackgroundTransparency = 1 end end)
        end
        blur.Size = index < 9 and 10 or 16
        typedFor = clock
      else
        break
      end
    end
    blur.Size = math.max(blur.Size - dt * 90, 0)
    -- the drop: white, the hit, the wordmark
    if not dropped and clock >= DROP then
      dropped = true
      flash.BackgroundColor3, flash.BackgroundTransparency = Color3.new(1, 1, 1), 0
      Motion.tween(0.5, ease.outCubic, function(p) if not finished then flash.BackgroundTransparency = p end end)
      shake:impulse(1, 900); shake:impulse(2, -700); shake:impulse(3, 500)
      for _, holder in ipairs({ mark, ghostR, ghostC }) do holder.Visible = true end
    end
    -- chrome
    local chrome = win(clock, START + 0.1, 0.4, ease.outCubic)
    head.TextTransparency, channel.TextTransparency, skip.TextTransparency = 1 - chrome, 1 - chrome * 0.85, 1 - chrome * 0.7
    rec.TextTransparency = 1 - chrome
    local seconds = clock - START
    rec.Text = string.format("REC  %02d:%02d:%02d", math.floor(seconds / 60), math.floor(seconds % 60), math.floor((seconds % 1) * 30))
    dot.BackgroundTransparency = (math.floor(clock * 2.5) % 2 == 0) and 0.05 or 0.8
    veil.BackgroundTransparency = win(clock, START, 0.25, ease.outCubic)
    -- the line of the shot, typed out
    local text = LINES[lastCut] or ""
    text = string.gsub(text, "%%NAME%%", name)
    text = string.gsub(text, "%%GAME%%", gameName)
    local typed = math.floor((clock - typedFor) * 46)
    line.Text = string.sub(text, 1, math.max(typed, 0)) .. ((typed < #text and math.floor(clock * 12) % 2 == 0) and "_" or "")
    line.Visible = not dropped
    lineBar.Size = UDim2.fromOffset(dropped and 0 or math.min(typed, #text) * 10.2, 3)
    -- the name, letter by letter while the track builds, gone on the drop
    if clock >= 4.25 and not dropped then
      local count = math.clamp(math.floor((clock - 4.25) / 1.45 * #name) + 1, 1, #name)
      big.Text = string.sub(name, 1, count)
      bigScale.Scale = 1 + 0.06 * win(clock, 4.25, 1.68) + 0.03 * beat
      big.Position = UDim2.new(0.5, (math.random() - 0.5) * 6 * beat, 0.5, (math.random() - 0.5) * 6 * beat)
      big.TextTransparency = 0.05 + 0.4 * (1 - win(clock, 4.25, 0.3))
    else
      big.Text = ""
    end
    -- the wordmark: hit, held, broken up on the way out
    if dropped then
      local hit = win(clock, DROP, 0.55, ease.outExpo)
      markScale.Scale = util.lerp(1.28, 1, hit) * (1 + 0.025 * beat)
      local split = (1 - win(clock, DROP, 0.45, ease.outCubic)) * 16 + 5 * beat
      local leaving = win(clock, LEAVE + 0.15, 0.55, ease.inCubic)
      local jitter = leaving > 0 and (math.random() - 0.5) * 40 * leaving or 0
      mark.Position = UDim2.new(0.5, jitter, 0.46, 0)
      ghostR.Position = UDim2.new(0.5, -split + jitter * 1.6, 0.46, 0)
      ghostC.Position = UDim2.new(0.5, split - jitter * 1.3, 0.46, 0)
      ghostRScale.Scale, ghostCScale.Scale = markScale.Scale, markScale.Scale
      for _, holder in ipairs({ mark, ghostR, ghostC }) do
        local fade = holder == mark and leaving or math.max(leaving, 1 - (split / 21) * 1.3)
        for _, image in ipairs(holder:GetChildren()) do
          if image:IsA("ImageLabel") then image.ImageTransparency = fade + (holder == mark and 0 or 0.35) end
          if image:IsA("TextLabel") then image.TextTransparency = fade + (holder == mark and 0 or 0.35) end
        end
      end
      local under = win(clock, DROP + 0.25, 0.6, ease.outCubic) * (1 - leaving)
      tag.TextTransparency = 1 - under
      rule.Size = UDim2.fromOffset(util.lerp(0, 420, win(clock, DROP + 0.2, 0.7, ease.outExpo)) * (1 - leaving), 3)
      hint.TextTransparency = 1 - win(clock, LEAVE - 0.6, 0.4, ease.outCubic) * (1 - win(clock, OUT - 0.25, 0.25))
    end
    -- the strips
    local readout = {
      string.format("CH.%02d  %s", math.max(lastCut, 1), (math.floor(clock * 2) % 2 == 0) and "REC" or ""),
      string.format("LV %03d", math.floor(level * 999)),
      string.format("T %06.2f", clock),
      string.format("FPS %03d", math.floor(frames / math.max(os.clock() - started, 0.05))),
    }
    left.step(clock, level, beat, readout)
    right.step(clock + 3.7, level, beat, { string.format("SIG %s", string.rep("|", math.floor(level * 8))), string.format("%+05.1f dB", (level - 1) * 24),
      string.format("CUT %02d/%02d", lastCut, #CUTS), "BASED" })
    -- grain at film cadence
    if clock - grainAt > 1 / 24 then
      grainAt = clock
      grain.Position = UDim2.fromOffset(-300 + math.random(-240, 240), -300 + math.random(-240, 240))
      grain.ImageTransparency = 0.84 + 0.05 * math.random()
    end
    barTop.Size, barBottom.Size = UDim2.new(1, 0, 0, BAR), UDim2.new(1, 0, 0, BAR)
    if clock >= OUT then finish(false) end
  end, nil, "signal")
end
if B.Loader then B.Loader.others.signal = Intro.run end
end
do -- 10_registry.lua
-- ============================================================================
--  10 registry  the tree that holds the apples
--
--  A game module is one table handed to BASED.game{...}. When the hub starts it
--  looks the current game up by universe id, then by place id:
--
--    * a module with `tabs`   -> its tabs are built into the hub, under the
--                                game's own heading, above Universal
--    * a module with `script` -> that script is run (a function, a file inside
--                                BasedHub/, or a URL)
--    * no module              -> Universal, and the player is told that no
--                                script has been engineered for this game yet
--
--  Modules compiled into the build live in based/games/*.lua. A .lua file
--  dropped into the executor's BasedHub/games/ folder is picked up the same way
--  with no rebuild: it is called with the hub table and calls hub.game{...}.
-- ============================================================================
local S, fs, Window, Config = B.S, B.fs, B.Window, B.Config
local Registry = { games = {}, active = nil, gameName = nil }
B.Registry = Registry

-- spec: id, name, places = {..}, universes = {..}, icon, tabs = function(hub), script,
--       universal (default true; false = the Universal tabs and the systems behind them are never started;
--       a list such as { "visuals" } = only those of visuals / combat / movement / players / world are)
function B.game(spec)
  if type(spec) ~= "table" or type(spec.id) ~= "string" then error("BASED.game needs a table with an id", 2) end
  spec.name = spec.name or spec.id
  spec.places, spec.universes = spec.places or {}, spec.universes or {}
  Registry.games[#Registry.games + 1] = spec
  return spec
end

local function loadDropIns()
  for _, file in ipairs(fs.list(fs.path("games"))) do
    if string.match(file, "%.lua$") or string.match(file, "%.luau$") then
      local source = fs.read(file)
      local name = string.match(file, "([^/]+)$") or file
      if source then
        local chunk, problem = loadstring(source, "=" .. name)
        if chunk then B.try("game file " .. name, chunk, B) else B.fault("game file " .. name, problem) end
      end
    end
  end
end

local function match()
  local universe, place = game.GameId, game.PlaceId
  for _, spec in ipairs(Registry.games) do
    if table.find(spec.universes, universe) then return spec end
  end
  for _, spec in ipairs(Registry.games) do
    if table.find(spec.places, place) then return spec end
  end
  return nil
end

local function runScript(spec)
  local script = spec.script
  if type(script) == "function" then
    task.spawn(B.safe("game script " .. spec.id, script), B)
    return
  end
  if type(script) ~= "string" then return end
  task.spawn(B.safe("game script " .. spec.id, function()
    local source
    if string.match(script, "^https?://") then source = game:HttpGet(script) else source = fs.read(fs.path(script)) end
    if not source then error("script not found: " .. script) end
    local chunk, problem = loadstring(source, "=" .. spec.id)
    if not chunk then error(problem) end
    chunk(B)
  end))
end

-- The module for this game, looked up before any page is registered: a module that says
-- `universal = false` keeps the Universal systems from starting at all, not just out of sight.
function Registry.pick()
  if Registry.picked then return Registry.active end
  Registry.picked = true
  loadDropIns()
  Registry.active = match()
  return Registry.active
end
function Registry.universal()
  local spec = Registry.active
  return not (spec and (spec.universal == false or type(spec.universal) == "table"))
end
-- is this one of Universal's tabs loaded in this game?
function Registry.keeps(name)
  local spec = Registry.active
  if not spec or spec.universal == nil or spec.universal == true then return true end
  return type(spec.universal) == "table" and table.find(spec.universal, name) ~= nil
end

function Registry.resolve()
  local spec = Registry.pick()
  -- the game's public name, for the intro and the home card (a web call: never wait on it)
  task.spawn(function()
    local ok, info = pcall(function() return S.MarketplaceService:GetProductInfo(game.PlaceId) end)
    if ok and type(info) == "table" and type(info.Name) == "string" then
      Registry.gameName = info.Name
      if Registry.onName then B.try("registry.name", Registry.onName, info.Name) end
    end
  end)
  if not spec then return end
  if spec.tabs then
    local order = 100
    local hub = { game = spec, B = B, Config = Config, toast = Window.toast }
    -- hub:page{ id, title, icon, build = function(page) ... end }
    function hub:page(pageSpec)
      order += 1
      pageSpec.id = spec.id .. "." .. (pageSpec.id or tostring(order))
      -- in a game that has a script, its first tab is where the hub opens
      if order == 101 then Window.startPage = pageSpec.id end
      pageSpec.group = spec.name
      pageSpec.order = order
      pageSpec.eyebrow = pageSpec.eyebrow or spec.name
      return Window.page(pageSpec)
    end
    B.try("game tabs " .. spec.id, spec.tabs, hub)
  end
  if spec.universal == false then
    for _, page in ipairs(Window.order) do
      if page.group == "Universal" then page.hidden = true end
    end
  end
  if spec.script then runScript(spec) end
end

function Registry.status()
  local spec = Registry.active
  return { engineered = spec ~= nil, name = spec and spec.name or nil, tagline = spec and spec.tagline or nil, gameName = Registry.gameName, count = #Registry.games,
    mode = spec and (spec.tabs and "tabs" or "script") or "universal", universal = Registry.universal(),
    kept = spec and type(spec.universal) == "table" and spec.universal or nil }
end

function Registry.announce()
  if Config.get("app.toasts") == false then return end
  local spec = Registry.active
  if spec then
    Window.toast({ title = "Engineered for " .. spec.name, text = spec.tabs and (Registry.universal() and "Its tabs are in the sidebar." or (type(spec.universal) == "table" and "Its own tabs, and what it keeps of Universal." or "Its own tabs only: Universal is not loaded here.")) or "Its script is running.",
      icon = "badge-check", tone = "ok", time = 5 })
  else
    Window.toast({ title = "No script engineered for this game yet", text = "Universal is loaded and ready.", icon = "info", tone = "accent", time = 6 })
  end
end
end
do -- 11_hud.lua
-- ============================================================================
--  11 hud      the island: what is left on screen when the hub is hidden
-- ============================================================================
local S, util, Motion, Theme, T, UI, Config, Window = B.S, B.util, B.Motion, B.Theme, B.T, B.UI, B.Config, B.Window
local Hud = {}
B.Hud = Hud

function Hud.ping()
  local ok, value = pcall(function() return B.LP:GetNetworkPing() * 1000 end)
  if ok and value and value > 0 then return value end
  local ok2, item = pcall(function() return S.Stats.Network.ServerStatsItem["Data Ping"]:GetValue() end)
  return ok2 and item or 0
end
function Hud.fps() return 1 / math.max(Motion.smoothDt, 1 / 1000) end

function Hud.start()
  if Hud.island then return end
  local holder = UI.frame(Window.hud, { Name = "Island", AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0, 12), Size = UDim2.fromOffset(0, 34),
    AutomaticSize = Enum.AutomaticSize.X, Visible = false })
  local sizer = Instance.new("UIScale"); sizer.Scale = Window.scale; sizer.Parent = holder
  local glass = UI.glass(holder, { level = "popover", radius = 17, shadow = 22, shadowY = 8, grain = false,
    props = { Size = UDim2.fromScale(0, 1), AutomaticSize = Enum.AutomaticSize.X } })
  local body = UI.pressable(glass, { Name = "Body", Size = UDim2.fromScale(0, 1), AutomaticSize = Enum.AutomaticSize.X })
  UI.pad(body, 0, 14, 0, 14)
  UI.list(body, "x", 9, { v = "Center" })
  UI.text(body, "BASED", "brand", "ink", { TextSize = 11, LayoutOrder = 1 })
  local dot = UI.frame(body, { Size = UDim2.fromOffset(4, 4), LayoutOrder = 2, Theme = { BackgroundColor3 = "accent" }, BackgroundTransparency = 0 })
  UI.corner(dot, true)
  local stats = UI.text(body, "", "mono", "sub", { TextSize = 11, LayoutOrder = 3 })
  local key = UI.text(body, "", "mono", "faint", { TextSize = 11, LayoutOrder = 4 })
  Hud.island = holder
  local shown = false
  local function show(on)
    on = on and Config.get("app.island") ~= false and not (B.Unnamed and (B.Unnamed.active() or B.Unnamed.open))
    if on == shown then return end
    shown = on
    if on then
      holder.Visible = true
      holder.Position = UDim2.new(0.5, 0, 0, -44)
      Motion.to(holder, "Position", UDim2.new(0.5, 0, 0, 12), "bouncy")
    else
      Motion.to(holder, "Position", UDim2.new(0.5, 0, 0, -48), "quick", function() if not shown then holder.Visible = false end end)
    end
  end
  UI.wire(body, {
    hover = function(on) Motion.to(sizer, "Scale", Window.scale * (on and 1.05 or 1), "snappy") end,
    click = function() Window.show(true) end,
  })
  Window.onShow:connect(function(open) show(not open) end)
  Config.on("app.island", function() show(not Window.open) end)
  Config.on("app.gui", function() show(not Window.open) end)
  -- in flight the island reads the speed instead: it is the number worth watching then
  local tick = 0
  Motion.every(function()
    if not shown then return end
    tick += 1
    local flight = B.Flight
    if flight and flight.state == "flying" then
      local _, speed, mach = flight.status()
      stats.Text = util.comma(speed) .. " st/s" .. ((mach or 0) >= 1 and string.format("  ·  Mach %.1f", mach) or "")
    elseif tick % 4 == 0 or stats.Text == "" or string.find(stats.Text, "st/s", 1, true) then
      stats.Text = string.format("%d fps  ·  %d ms", math.floor(Hud.fps() + 0.5), math.floor(Hud.ping() + 0.5))
    end
    key.Text = Config.keyLabel(Config.get("app.key.menu"))
  end, 8, "hud.island")
  show(not Window.open)
end
end
do -- 12_board.lua
-- ============================================================================
--  12 board    the film on the Home tab: an ad board that opens when hovered
--
--  Docked, it is part of the Home card: the film runs silently and fades into
--  the card on its left. Rest the mouse on it and it comes forward over the hub,
--  opens to the whole picture and the sound comes in; move off it and it goes
--  back. Click it while it is open and it stays open until it is clicked again.
--
--  Two players share one clock, so they are always on the same frame. Measured
--  on the test machine with the Home tab up (126 fps with no board): the small
--  set played in the card costs nothing that can be measured (128, 129), the
--  1820x1024 set costs up to a tenth (114 to 126). So the card plays the small
--  set, which it shows at less than its own size anyway, and the big one runs
--  only once the mouse is on it. The hand-over happens with both on the same
--  picture in the same place, and the sound joins where the picture already is.
--
--  The film keeps its own rate (24000/1001 frames a second: every frame the
--  file has). Nothing is decoded while it cannot be seen: hub hidden, another
--  tab, the card scrolled away, or switched off in Settings.
-- ============================================================================
local S, util, Motion, T, UI, Config, Window, Assets, Film = B.S, B.util, B.Motion, B.T, B.UI, B.Config, B.Window, B.Assets, B.Film
local UIS = S.UserInputService
local Board = { spec = B.BOARD, p = 0, popped = false, opens = 0 }
B.Board = Board

local DWELL = 0.28        -- seconds the mouse rests on it before it opens: passing over it does nothing
local LINGER = 0.14       -- and how long it may be off it before it goes back
local RADIUS = 18         -- corner radius opened out, in screen pixels
local MARGIN = 28         -- kept clear of the screen edge
local FOCUS = 0.3         -- docked, the card shows a strip of the picture: this far down it
-- docked: clear on the left where the card's words are, the picture itself on the right
local RAMP = { { 0, 1 }, { 0.5, 0.42 }, { 1, 0.04 } }
local DOCK_ALPHA = 0.9
local UNSEEN = 0.001      -- drawn, so it is decoded, and not to be seen

local O
local holder, panel, screen, scrim, rim, shade, bar, fill, chip, still
local dock, big           -- the player in the card, and the one that comes forward
local spring
local origin = os.clock()
local function clock() return os.clock() - origin end
local wantPop, pinned, armed, overSince, offSince = false, false, false, nil, nil
local bigOnShow = false   -- which of the two players is the one being looked at
local handing = false     -- opening, and the big player has no picture yet: the card's keeps its own until it has
local dockShown = 0       -- how visible the card's player is right now

local function enabled() return Board.spec ~= nil and not Assets.lite and O ~= nil and O.on end
local function onHome() return Window.open and Window.current ~= nil and Window.current.id == "home" end
-- docked, the board is on screen only where the page shows through its scroll area
local function inView()
  if not holder or not holder.Parent or not Window.pageHost then return false end
  local top, bottom = holder.AbsolutePosition.Y, holder.AbsolutePosition.Y + holder.AbsoluteSize.Y
  local hostTop = Window.pageHost.AbsolutePosition.Y
  return bottom > hostTop + 12 and top < hostTop + Window.pageHost.AbsoluteSize.Y - 12
end

local function dockRect()
  local at, size = holder.AbsolutePosition - UI.overlay.AbsolutePosition, holder.AbsoluteSize
  return at.X, at.Y, size.X, size.Y
end
local function popRect()
  local view = B.viewport()
  local width = math.min(view.X * O.size / 100, (view.Y - MARGIN * 2) * 16 / 9, view.X - MARGIN * 2)
  local height = width * 9 / 16
  -- over the middle of the hub, and never off the screen
  local centre = Window.holder.AbsolutePosition + Window.holder.AbsoluteSize / 2 - UI.overlay.AbsolutePosition
  local x = math.clamp(centre.X - width / 2, MARGIN, math.max(MARGIN, view.X - width - MARGIN))
  local y = math.clamp(centre.Y - height / 2, MARGIN, math.max(MARGIN, view.Y - height - MARGIN))
  return x, y, width, height
end
local function dockLook()
  return { tl = 0, bl = 0, tr = T.rCard, br = T.rCard, fade = RAMP, focusX = 0.5, focusY = FOCUS }
end

-- Everything that depends on how far open it is: 0 docked, 1 open (a spring, so it may pass 1).
-- It only ever moves the big player: the one in the card stays where it is.
local function apply(p)
  Board.p = p
  if not big or big.dead or not holder.Parent then return end
  local q = util.clamp01(p)
  Board.popped = q > 0.5
  local dx, dy, dw, dh = dockRect()
  local px, py, pw, ph = popRect()
  panel.Position = UDim2.fromOffset(util.lerp(dx, px, p), util.lerp(dy, py, p))
  panel.Size = UDim2.fromOffset(math.max(8, util.lerp(dw, pw, p)), math.max(8, util.lerp(dh, ph, p)))
  -- out here nothing is scaled with the hub: the card's radius is carried over in screen pixels
  local card = T.rCard * UI.unit()
  local left, right = util.lerp(0, RADIUS, q), util.lerp(card, RADIUS, q)
  local fade = false
  if q < 0.995 then
    local keep = (1 - q) ^ 1.6
    fade = { { RAMP[1][1], RAMP[1][2] * keep }, { RAMP[2][1], RAMP[2][2] * keep }, { RAMP[3][1], RAMP[3][2] * keep } }
  end
  big:setLook({ tl = left, bl = left, tr = right, br = right, fade = fade, focusY = util.lerp(FOCUS, 0.5, q) })
  if wantPop or p > 0.002 then big:setAlpha(util.lerp(DOCK_ALPHA, 1, q)) end
  big:setVolume(O.volume / 100 * q * q)
  scrim.BackgroundTransparency = 1 - 0.46 * q
  scrim.Visible = q > 0.01
  rim.Corner.CornerRadius = UDim.new(0, math.floor(right + 0.5))
  rim.Stroke.Transparency = 1 - (pinned and 0.5 or 0.2) * q
  if shade then shade.Transparency = 1 - 0.6 * q end
  bar.Visible = q > 0.6
end

-- the big player, made the first time the mouse comes near
local function makeBig()
  if big and not big.dead then return true end
  local set = Film.pick(O.quality, Board.spec)
  if not set then return false end
  big = Film.new(screen, { spec = Board.spec, set = set, loop = true, audio = true, muted = true, volume = 0, window = true, backdrop = false,
    slots = 6, budget = 2, soundHost = UI.soundHost, clock = clock })
  Board.big = big
  return big ~= nil
end
-- The mouse is on the board: start the big player where the small one is, out of sight, so
-- that by the time the board opens it has a picture to open with.
local function arm()
  if armed or not makeBig() then return end
  armed = true
  panel.Visible = true
  apply(0)
  big:setAlpha(UNSEEN)
  big:play()
end
local function disarm()
  if not armed then return end
  armed = false
  if big and not big.dead then
    big:setMuted(true)
    big:pause()
  end
  panel.Visible, scrim.Visible = false, false
end
local function open(on)
  if not on then pinned = false end
  if wantPop == on then return end
  if on then
    arm()
    if not armed then return end
    wantPop = true
    Board.opens += 1
    big:setMuted(false)
    if chip then chip.Visible = false end
    -- the hand-over, in one go: the big player shows the picture from this frame on, exactly
    -- where the card's player was showing it, and that one stops
    bigOnShow = true
    apply(Board.p)
    handing = true
    spring:to({ 1 }, { 0.5, 0.16 })
  else
    wantPop, handing = false, false
    -- the card's player starts again now, unseen, to be on the right frame when this lands
    if dock and not dock.dead and not dock.playing then dock:play() end
    spring:to({ 0 }, "smooth")
  end
end
-- shut at once, with nothing left over the hub: for when the tab or the hub goes away under it
local function shut()
  wantPop, pinned, overSince, offSince = false, false, nil, nil
  if spring then spring:snap({ 0 }) end
  bigOnShow, handing = false, false
  disarm()
end
Board.open, Board.shut = open, shut
-- held open whatever the mouse does (a click on the open board does this)
function Board.pin(on)
  pinned = on == true
  if pinned then open(true) end
  if big and not big.dead and armed then apply(Board.p) end
end

local function makeDock()
  if dock and not dock.dead then return end
  if not holder or not holder.Parent then return end
  -- the small set is all the card can show; where only the big one is installed, that plays
  local set = Film.has("hd", Board.spec) and "hd" or Film.pick("ultra", Board.spec)
  if not set then return end
  dock = Film.new(holder, { spec = Board.spec, set = set, loop = true, window = true, backdrop = false, slots = 6, budget = 2, look = dockLook(), clock = clock })
  Board.film = dock
  if dock then
    dock:setAlpha(UNSEEN)
    dockShown = 0
  end
end
local function drop()
  shut()
  if big then big:destroy() end
  if dock then dock:destroy() end
  big, dock, Board.big, Board.film = nil, nil, nil, nil
  if still and still.Parent then still.Visible = true end
end

-- Whether the board's film is on this machine at all (it is not part of a public install).
function Board.installed() return Board.spec ~= nil and not Assets.lite and Film.pick("ultra", Board.spec) ~= nil end

-- Called by the Home tab with its card. Returns false when there is no board to show (not
-- installed, lite mode): the card then keeps its still.
function Board.mount(card, stillImage)
  if not Board.installed() then return false end
  Board.define()
  still = stillImage
  holder = UI.frame(card, { Name = "Board", Size = UDim2.new(0.62, 0, 1, 0), Position = UDim2.fromScale(1, 0), AnchorPoint = Vector2.new(1, 0), Visible = O.on })

  scrim = UI.new("TextButton", { Name = "BoardScrim", Text = "", AutoButtonColor = false, BorderSizePixel = 0, BackgroundColor3 = Color3.new(0, 0, 0),
    BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), ZIndex = 78, Visible = false, Parent = UI.overlay })
  scrim.Activated:Connect(B.safe("board.scrim", function() open(false) end))
  panel = UI.frame(UI.overlay, { Name = "BoardPanel", ZIndex = 80, Visible = false })
  if UI.fx.shadow then
    local host = UI.frame(panel, { Name = "Shadow", Size = UDim2.fromScale(1, 1) })
    UI.corner(host, RADIUS)
    shade = Instance.new("UIShadow")
    shade.BlurRadius = UDim.new(0, 64)
    shade.Offset = UDim2.fromOffset(0, 24)
    shade.Color = Color3.new(0, 0, 0)
    shade.Transparency = 1
    pcall(function() shade.ShowBehindParent = false end)
    shade.Parent = host
  end
  screen = UI.frame(panel, { Name = "Screen", Size = UDim2.fromScale(1, 1), ZIndex = 2 })
  local hit = UI.new("TextButton", { Name = "Hit", Text = "", AutoButtonColor = false, BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), ZIndex = 5, Parent = panel })
  hit.Activated:Connect(B.safe("board.pin", function()
    if not wantPop then return end
    if pinned then open(false) else Board.pin(true) end
  end))
  -- a hairline round the picture, and how far through it is
  rim = UI.frame(panel, { Name = "Rim", Size = UDim2.fromScale(1, 1), ZIndex = 3 })
  local corner = Instance.new("UICorner")
  corner.Name = "Corner"
  corner.Parent = rim
  local stroke = Instance.new("UIStroke")
  stroke.Name = "Stroke"
  stroke.Color = Color3.new(1, 1, 1)
  stroke.Thickness = 1
  stroke.Transparency = 1
  stroke.Parent = rim
  bar = UI.frame(panel, { Name = "Progress", Size = UDim2.new(1, -RADIUS * 2, 0, 2), Position = UDim2.new(0, RADIUS, 1, -10), BackgroundColor3 = Color3.new(1, 1, 1),
    BackgroundTransparency = 0.78, ZIndex = 4, Visible = false })
  UI.corner(bar, true)
  fill = UI.frame(bar, { Name = "Fill", Size = UDim2.fromScale(0, 1), BackgroundColor3 = Color3.new(1, 1, 1), BackgroundTransparency = 0.1 })
  UI.corner(fill, true)

  -- what the board is for, until it has been opened once
  chip = UI.frame(holder, { Name = "Hint", AnchorPoint = Vector2.new(1, 1), Position = UDim2.new(1, -12, 1, -12), Size = UDim2.fromOffset(0, 24),
    AutomaticSize = Enum.AutomaticSize.X, BackgroundColor3 = Color3.new(0, 0, 0), BackgroundTransparency = 0.45, ZIndex = 6, Visible = O.hover })
  UI.corner(chip, true)
  UI.pad(chip, 0, 10, 0, 9)
  UI.list(chip, "x", 6, { v = "Center" })
  local glyph = UI.icon(chip, "volume-x", 13, "ink", { LayoutOrder = 1 })
  glyph.ImageColor3 = Color3.new(1, 1, 1)
  local words = UI.text(chip, "Hover for sound", "caption", "ink", { LayoutOrder = 2, TextSize = 11 })
  words.TextColor3 = Color3.new(1, 1, 1)

  spring = Motion.spring(1, "smooth", function(x) apply(x[1]) end, 0.0008)

  -- Every frame the Home tab is up: the mouse, and which of the two players is the one on show.
  Motion.every(function(dt)
    if not holder.Parent then return end
    local live = dock ~= nil and not dock.dead and enabled() and onHome()
    if not live or UI.popoverOpen() or (not O.hover and not pinned) then
      if wantPop then open(false) elseif armed and Board.p <= 0.002 then disarm() end
      overSince = nil
    else
      local now = os.clock()
      local mouse = UI.mouse()
      local over
      if Board.p > 0.02 then
        over = UI.inside(panel, mouse)
      else
        over = UI.inside(holder, mouse) and UI.inside(Window.pageHost, mouse) and inView() and not UIS:IsMouseButtonPressed(Enum.UserInputType.MouseButton1)
      end
      if over then
        offSince = nil
        overSince = overSince or now
        arm()
        -- open once it has rested there AND the big player has a picture to open with
        if not wantPop and now - overSince >= DWELL and big and big.fresh > 0 then open(true) end
      else
        overSince = nil
        if wantPop and not pinned then
          offSince = offSince or now
          if now - offSince >= LINGER then open(false) end
        elseif armed and not wantPop and Board.p <= 0.002 then
          disarm()
        end
      end
    end
    -- The hand-over back. The big player keeps the picture all the way home, and then sits
    -- exactly where the card's player is until that one has a picture of its own again.
    if dock and not dock.dead then
      if handing and big and big.fresh > 0 then
        handing = false
        if dock.playing then dock:pause() end
        dockShown = 0
        dock:setAlpha(UNSEEN)
      end
      if bigOnShow then
        if not wantPop and Board.p <= 0.002 and dock.fresh > 0 and not handing then
          bigOnShow = false
          dockShown = 1
          dock:setAlpha(DOCK_ALPHA)
          disarm()
          if chip then chip.Visible = O.hover and Board.opens == 0 end
        end
      elseif dock.playing then
        -- on its own in the card: let it in gently when it has just (re)started
        local goal = dock.fresh > 0 and 1 or 0
        if dockShown ~= goal then
          dockShown = goal == 1 and math.min(1, dockShown + dt * 6) or 0
          dock:setAlpha(util.lerp(UNSEEN, DOCK_ALPHA, dockShown))
          if still and still.Parent then still.Visible = dockShown < 1 end
        end
      end
    end
    if big and bar.Visible then fill.Size = UDim2.fromScale(util.clamp01(big.time / big.length), 1) end
  end, nil, "board.mouse")

  -- play only while it can be seen
  Motion.every(function()
    if not holder.Parent then return end
    if not enabled() then
      if dock or big then drop() end
      return
    end
    local seen = onHome() and (Board.p > 0.02 or inView())
    if seen then
      makeDock()
      if dock and not dock.playing and not wantPop and Board.p <= 0.002 then dock:play() end
    else
      if Board.p > 0 or wantPop or armed then shut() end
      if dock and dock.playing then
        dock:pause()
        dockShown = 0
        dock:setAlpha(UNSEEN)
        if still and still.Parent then still.Visible = true end
      end
    end
  end, 8, "board.watch")

  Config.on("home.board", function(on)
    if holder.Parent then holder.Visible = on end
    if not on then drop() end
  end)
  Config.on("home.boardQuality", function()
    shut()
    if big then big:destroy() end
    big, Board.big = nil, nil
  end)
  Config.on("home.boardHover", function(on)
    if chip and chip.Parent then chip.Visible = on and Board.p <= 0.02 and Board.opens == 0 end
    if not on and wantPop then open(false) end
  end)
  Config.on("app.radius", function() if dock and not dock.dead then dock:setLook(dockLook()) end end)
  -- open and at rest, nothing is moving to pick a new volume or size up
  for _, id in ipairs({ "home.boardVolume", "home.boardSize" }) do
    Config.on(id, function() if armed and big and not big.dead then apply(Board.p) end end)
  end
  Window.onShow:connect(function(on) if not on then shut() end end)
  Window.onPage:connect(function() shut() end)
  B.own(function()
    if big then big:destroy() end
    if dock then dock:destroy() end
  end)
  return true
end

function Board.define()
  if O then return end
  Config.define("home.board", true)
  Config.define("home.boardHover", true)
  Config.define("home.boardVolume", 60)
  Config.define("home.boardSize", 56)
  Config.define("home.boardQuality", "ultra")
  O = Config.mirror({ on = "home.board", hover = "home.boardHover", volume = "home.boardVolume", size = "home.boardSize", quality = "home.boardQuality" })
  Board.options = O
end
end
do -- 20_home.lua
-- ============================================================================
--  20 home     what game this is, whether it has a script, session numbers
-- ============================================================================
local S, util, Motion, Theme, T, UI, Config, Window, Assets, Registry, Hud = B.S, B.util, B.Motion, B.Theme, B.T, B.UI, B.Config, B.Window, B.Assets, B.Registry, B.Hud
B.pages = B.pages or {}

local function visible() return Window.open and Window.current and Window.current.id == "home" end

local function hero(frame)
  local status = Registry.status()
  local card = UI.surface(frame, { Name = "Hero", Size = UDim2.new(1, 0, 0, 214), ClipsDescendants = true }, "rCard")
  UI.stroke(card, "ink", "strokeA")
  -- The board: a film that plays silently in the card and opens with its sound when the mouse
  -- rests on it. Where it is not installed (or switched off), a still from the intro stands in.
  local film = B.Film and B.Film.spec
  local picture
  if film and not Assets.lite then
    local still = Assets.frame(film.sets.hd.tiles[1].path, 378, film.sets.hd.digits)
    if still then
      picture = UI.new("ImageLabel", { Name = "Still", BackgroundTransparency = 1, Image = still, ScaleType = Enum.ScaleType.Crop, Size = UDim2.new(0.62, 0, 1, 0),
        Position = UDim2.fromScale(1, 0), AnchorPoint = Vector2.new(1, 0), ImageTransparency = 0.25, Parent = card })
      UI.corner(picture, "rCard")
      UI.gradient(picture, { Transparency = UI.alphaSeq(0, 1, 0.55, 0.35, 1, 0.1) })
    end
  end
  if B.Board then B.try("home.board", B.Board.mount, card, picture) end
  local text = UI.frame(card, { Name = "Text", Size = UDim2.new(0.66, 0, 1, 0) })
  UI.pad(text, 22, 0, 20, 24)
  UI.list(text, "y", 6, { v = "Bottom" })
  local eyebrow = UI.frame(text, { Size = UDim2.new(1, 0, 0, 20), LayoutOrder = 1 })
  UI.list(eyebrow, "x", 8, { v = "Center" })
  local pip = UI.frame(eyebrow, { Size = UDim2.fromOffset(7, 7), LayoutOrder = 1, Theme = { BackgroundColor3 = status.engineered and "ok" or "accent" }, BackgroundTransparency = 0 })
  UI.corner(pip, true)
  UI.text(eyebrow, status.engineered and "ENGINEERED FOR THIS GAME" or "NO SCRIPT ENGINEERED FOR THIS GAME YET", "eyebrow", status.engineered and "ok" or "sub", { LayoutOrder = 2 })
  local title = UI.text(text, status.engineered and status.name or "Universal", "display", "ink", { TextSize = 46, LayoutOrder = 2, TextTruncate = Enum.TextTruncate.AtEnd,
    AutomaticSize = Enum.AutomaticSize.Y, Size = UDim2.new(1, 0, 0, 0) })
  local function line()
    local name = Registry.gameName and ("“" .. Registry.gameName .. "”") or "this game"
    if status.engineered then
      if status.kept then return "Its own tabs are in the sidebar. Of Universal, only " .. table.concat(status.kept, ", ") .. " is loaded in this game." end
      if not status.universal then return "Its own tabs are in the sidebar. Universal is not loaded in this game." end
      return status.mode == "tabs" and "Its tabs are in the sidebar, above Universal." or "Its script is running. Universal is here too."
    end
    return "Nothing has been built for " .. name .. " yet, so BASED loaded Universal: aim, ESP, movement and the rest work in any game."
  end
  local sub = UI.text(text, line(), "body", "sub", { TextWrapped = true, AutomaticSize = Enum.AutomaticSize.Y, Size = UDim2.new(1, 0, 0, 0), LayoutOrder = 3, LineHeight = 1.25 })
  Registry.onName = function() if sub.Parent then sub.Text = line() end end
  local _ = title
  -- pulse on the status pip
  local ring = UI.frame(pip, { Size = UDim2.fromScale(1, 1), AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
    Theme = { BackgroundColor3 = status.engineered and "ok" or "accent" }, BackgroundTransparency = 0.5 })
  UI.corner(ring, true)
  local phase = 0
  Motion.every(function(dt)
    if not ring.Parent or not visible() then return end
    phase = (phase + dt / 1.8) % 1
    local p = Motion.ease.outCubic(phase)
    ring.Size = UDim2.fromScale(1 + p * 2.4, 1 + p * 2.4)
    ring.BackgroundTransparency = 0.5 + 0.5 * p
  end, 30, "home.pulse")
end

local function stats(frame)
  local row = UI.frame(frame, { Name = "Stats", Size = UDim2.new(1, 0, 0, 74) })
  local tiles = {}
  local specs = {
    { "gauge", "FPS", function() return tostring(math.floor(Hud.fps() + 0.5)) end },
    { "wifi", "PING", function() return math.floor(Hud.ping() + 0.5) .. " ms" end },
    { "users", "PLAYERS", function() return #S.Players:GetPlayers() .. " / " .. S.Players.MaxPlayers end },
    { "timer", "SESSION", function()
      local s = math.floor(os.clock() - B.bootClock)
      return string.format("%d:%02d", s // 60, s % 60)
    end },
  }
  for index, spec in ipairs(specs) do
    local tile = UI.surface(row, { Size = UDim2.new(0.25, -9, 1, 0), Position = UDim2.new((index - 1) * 0.25, (index - 1) * 3, 0, 0) }, "rCard")
    UI.stroke(tile, "ink", "strokeA")
    UI.icon(tile, spec[1], 15, "faint", { Position = UDim2.fromOffset(14, 14) })
    UI.text(tile, spec[2], "eyebrow", "faint", { Position = UDim2.fromOffset(36, 15), TextSize = 9 })
    tiles[index] = { label = UI.text(tile, spec[3](), "monoBold", "ink", { Position = UDim2.fromOffset(14, 40), TextSize = 19 }), read = spec[3] }
  end
  Motion.every(function()
    if not row.Parent or not visible() then return end
    for _, tile in ipairs(tiles) do tile.label.Text = tile.read() end
  end, 2, "home.stats")
end

local function library(page)
  local games = Registry.games
  local section = page:section({ title = "Library", icon = "layers", full = true,
    desc = #games == 0 and "Game scripts show up here as they are engineered." or (#games .. (#games == 1 and " game script installed." or " game scripts installed.")) })
  if #games == 0 then
    section:custom({ height = 148, build = function(frame)
      local box = UI.frame(frame, { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.48), Size = UDim2.fromOffset(470, 0), AutomaticSize = Enum.AutomaticSize.Y })
      UI.list(box, "y", 8, { h = "Center" })
      local orb = UI.frame(box, { Size = UDim2.fromOffset(46, 46), LayoutOrder = 1, Theme = { BackgroundColor3 = "ink", BackgroundTransparency = "fill2A" } })
      UI.corner(orb, true)
      UI.icon(orb, "sprout", 21, "accent", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5) })
      UI.text(box, "The tree is planted. No apples yet.", "heading", "ink", { LayoutOrder = 2 })
      UI.text(box, "When a script is engineered for a game, joining that game switches BASED to its tabs on its own. Everywhere else you get Universal.",
        "caption", "sub", { LayoutOrder = 3, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Center, Size = UDim2.new(1, 0, 0, 0),
          AutomaticSize = Enum.AutomaticSize.Y, LineHeight = 1.25 })
    end })
    return
  end
  for _, spec in ipairs(games) do
    local active = Registry.active == spec
    section:custom({ height = 46, build = function(frame)
      UI.icon(frame, spec.icon or "gamepad-2", 17, active and "accent" or "sub", { Position = UDim2.new(0, 14, 0.5, 0), AnchorPoint = Vector2.new(0, 0.5) })
      UI.text(frame, spec.name, "label", "ink", { Position = UDim2.new(0, 42, 0.5, 0), AnchorPoint = Vector2.new(0, 0.5) })
      if active then
        UI.badge(frame, "ACTIVE", "ok", { Position = UDim2.new(1, -14, 0.5, 0), AnchorPoint = Vector2.new(1, 0.5) })
      else
        UI.text(frame, spec.tabs and "tabs" or "script", "mono", "faint", { Position = UDim2.new(1, -14, 0.5, 0), AnchorPoint = Vector2.new(1, 0.5) })
      end
    end })
  end
end

B.pages[#B.pages + 1] = function()
  Window.page({ id = "home", title = "Home", icon = "house", group = "", order = 10, eyebrow = "Welcome back, " .. B.LP.DisplayName, build = function(page)
    page:custom(214, hero)
    page:custom(74, stats)
    library(page)
    local quick = page:section({ title = "Quick actions", icon = "zap" })
    quick:button({ id = "home.rejoin", label = "Rejoin this server", text = "Rejoin", run = function() if B.Server then B.Server.rejoin() end end })
    quick:button({ id = "home.hop", label = "Find another server", text = "Hop", run = function() if B.Server then B.Server.hop() end end })
    local tips = page:section({ title = "Good to know", icon = "lightbulb" })
    tips:note({ icon = "keyboard", text = "Right-click a toggle or a button to bind it to a key. Right-click anything to reset it." })
    tips:note({ icon = "search", text = "Ctrl K searches every setting in every tab." })
    tips:note({ icon = "eye-off", text = Config.keyLabel(Config.get("app.key.menu")) .. " hides the hub. The island at the top brings it back." })
  end })
  Window.startPage = Window.startPage or "home"
end
end
do -- 21_roster.lua
-- ============================================================================
--  21 roster   every other player, kept current by events
--
--  ESP, aim and the player list all read this one table. A character's parts are
--  looked up when it spawns and cached, so nothing walks the workspace per frame.
-- ============================================================================
local S, Config = B.S, B.Config
local Players = S.Players
local Roster = { list = {}, byPlayer = {}, changed = B.Signal.new(), friends = {}, targets = {}, hidden = {} }
B.Roster = Roster

local R15_JOINTS = { "Head", "UpperTorso", "LowerTorso", "LeftUpperArm", "LeftLowerArm", "LeftHand", "RightUpperArm", "RightLowerArm", "RightHand",
  "LeftUpperLeg", "LeftLowerLeg", "LeftFoot", "RightUpperLeg", "RightLowerLeg", "RightFoot" }
local R6_JOINTS = { "Head", "Torso", "Left Arm", "Right Arm", "Left Leg", "Right Leg" }
Roster.BONES_R15 = { { "Head", "UpperTorso" }, { "UpperTorso", "LowerTorso" }, { "UpperTorso", "LeftUpperArm" }, { "LeftUpperArm", "LeftLowerArm" },
  { "LeftLowerArm", "LeftHand" }, { "UpperTorso", "RightUpperArm" }, { "RightUpperArm", "RightLowerArm" }, { "RightLowerArm", "RightHand" },
  { "LowerTorso", "LeftUpperLeg" }, { "LeftUpperLeg", "LeftLowerLeg" }, { "LeftLowerLeg", "LeftFoot" }, { "LowerTorso", "RightUpperLeg" },
  { "RightUpperLeg", "RightLowerLeg" }, { "RightLowerLeg", "RightFoot" } }
Roster.BONES_R6 = { { "Head", "Torso" }, { "Torso", "Left Arm" }, { "Torso", "Right Arm" }, { "Torso", "Left Leg" }, { "Torso", "Right Leg" } }

local function scan(entry)
  local character = entry.character
  if not character then return end
  local humanoid = character:FindFirstChildOfClass("Humanoid")
  entry.humanoid = humanoid
  entry.root = character:FindFirstChild("HumanoidRootPart") or character.PrimaryPart
  entry.head = character:FindFirstChild("Head")
  local r6 = (humanoid and humanoid.RigType == Enum.HumanoidRigType.R6) or character:FindFirstChild("Torso") ~= nil
  entry.r6 = r6
  local joints = {}
  local complete = true
  for _, name in ipairs(r6 and R6_JOINTS or R15_JOINTS) do
    local part = character:FindFirstChild(name)
    if part and part:IsA("BasePart") then joints[name] = part else complete = false end
  end
  entry.joints, entry.complete = joints, complete and entry.root ~= nil and humanoid ~= nil
  entry.bones = r6 and Roster.BONES_R6 or Roster.BONES_R15
  if humanoid then
    entry.health, entry.maxHealth = humanoid.Health, math.max(humanoid.MaxHealth, 1)
    entry.alive = humanoid.Health > 0
    -- how far below the root the feet are: the box needs it
    entry.legs = r6 and 3 or (humanoid.HipHeight + (entry.root and entry.root.Size.Y * 0.5 or 1))
  else
    entry.alive = false
  end
  local tool = character:FindFirstChildOfClass("Tool")
  entry.tool = tool and tool.Name or nil
  -- spawn protection: the game's own shield, while it lasts
  entry.shielded = character:FindFirstChildOfClass("ForceField") ~= nil
end

local function watch(entry, character)
  for _, connection in ipairs(entry.links) do connection:Disconnect() end
  table.clear(entry.links)
  entry.character = character
  entry.humanoid, entry.root, entry.head, entry.joints, entry.complete, entry.alive = nil, nil, nil, {}, false, false
  entry.spawned = os.clock()
  if not character then Roster.changed:fire(entry); return end
  scan(entry)
  local links = entry.links
  local function rescan() scan(entry) end
  links[#links + 1] = character.ChildAdded:Connect(function(child)
    if child:IsA("Tool") then entry.tool = child.Name
    elseif child:IsA("ForceField") then entry.shielded = true
    elseif child:IsA("Humanoid") or child:IsA("BasePart") then task.defer(rescan) end
  end)
  links[#links + 1] = character.ChildRemoved:Connect(function(child)
    if child:IsA("Tool") then
      local other = character:FindFirstChildOfClass("Tool")
      entry.tool = other and other.Name or nil
    elseif child:IsA("ForceField") then
      entry.shielded = character:FindFirstChildOfClass("ForceField") ~= nil
    elseif child:IsA("BasePart") then task.defer(rescan) end
  end)
  local function hookHumanoid(humanoid)
    links[#links + 1] = humanoid.HealthChanged:Connect(function(health)
      entry.health, entry.maxHealth = health, math.max(humanoid.MaxHealth, 1)
      entry.alive = health > 0
    end)
    links[#links + 1] = humanoid.Died:Connect(function() entry.alive = false end)
  end
  if entry.humanoid then hookHumanoid(entry.humanoid) else
    task.spawn(function()
      local humanoid = character:WaitForChild("Humanoid", 8)
      if humanoid and entry.character == character and B.alive then scan(entry); hookHumanoid(humanoid) end
    end)
  end
  Roster.changed:fire(entry)
end

local function add(player)
  if player == B.LP or Roster.byPlayer[player] then return end
  local entry = { player = player, name = player.Name, display = player.DisplayName, userId = player.UserId, links = {}, playerLinks = {}, joints = {},
    alive = false, complete = false }
  Roster.byPlayer[player] = entry
  Roster.list[#Roster.list + 1] = entry
  entry.playerLinks[1] = player.CharacterAdded:Connect(function(character) watch(entry, character) end)
  entry.playerLinks[2] = player.CharacterRemoving:Connect(function() watch(entry, nil) end)
  watch(entry, player.Character)
end
local function remove(player)
  local entry = Roster.byPlayer[player]
  if not entry then return end
  Roster.byPlayer[player] = nil
  local at = table.find(Roster.list, entry)
  if at then table.remove(Roster.list, at) end
  for _, connection in ipairs(entry.links) do connection:Disconnect() end
  for _, connection in ipairs(entry.playerLinks) do connection:Disconnect() end
  entry.gone = true
  Roster.changed:fire(entry)
end

function Roster.start()
  if Roster.started then return end
  Roster.started = true
  for _, userId in ipairs(Config.define("players.friends", {})) do Roster.friends[userId] = true end
  for _, userId in ipairs(Config.define("players.targets", {})) do Roster.targets[userId] = true end
  for _, userId in ipairs(Config.define("players.hidden", {})) do Roster.hidden[userId] = true end
  for _, player in ipairs(Players:GetPlayers()) do add(player) end
  B.connect(Players.PlayerAdded, add, "roster.add")
  B.connect(Players.PlayerRemoving, remove, "roster.remove")
  -- characters assemble over several frames: fill in whatever was missing
  B.Motion.every(function()
    for _, entry in ipairs(Roster.list) do
      if entry.character and not entry.complete then scan(entry) end
    end
  end, 2, "roster.scan")
  B.own(function()
    for _, entry in ipairs(Roster.list) do
      for _, connection in ipairs(entry.links) do connection:Disconnect() end
      for _, connection in ipairs(entry.playerLinks) do connection:Disconnect() end
    end
  end)
end

-- the same part lookup for any model: the ESP preview runs it on a clone of your character
function Roster.describe(character)
  local entry = { character = character, joints = {} }
  scan(entry)
  return entry
end
-- Three marks a player can carry, each kept by user id so it outlasts the server:
--   friend   skipped by aim, own colour in ESP
--   target   aim goes for them first (or only for them, if set so)
--   hidden   left out of ESP and aim altogether
local function mark(set, id)
  return function(entry, on)
    set[entry.userId] = on and true or nil
    local list = {}
    for userId in pairs(set) do list[#list + 1] = userId end
    table.sort(list)
    Config.set(id, list)
    Roster.changed:fire(entry)
  end
end
function Roster.isFriend(entry) return Roster.friends[entry.userId] == true end
function Roster.isTarget(entry) return Roster.targets[entry.userId] == true end
function Roster.isHidden(entry) return Roster.hidden[entry.userId] == true end
Roster.setFriend = mark(Roster.friends, "players.friends")
Roster.setTarget = mark(Roster.targets, "players.targets")
Roster.setHidden = mark(Roster.hidden, "players.hidden")
function Roster.anyTargets() return next(Roster.targets) ~= nil end
-- empty one of the three sets
function Roster.clear(which)
  local set = Roster[which]
  if not set then return end
  table.clear(set)
  Config.set("players." .. which, {})
  for _, entry in ipairs(Roster.list) do Roster.changed:fire(entry) end
end
function Roster.teamName(entry)
  local team = entry.player and entry.player.Team
  return team and team.Name or nil
end
-- on the other side: a different team, or no teams in this game at all
function Roster.isEnemy(entry)
  local mine, theirs = B.LP.Team, entry.player.Team
  if mine == nil or theirs == nil then return true end
  return mine ~= theirs
end
function Roster.teamColor(entry)
  local team = entry.player.Team
  return team and team.TeamColor.Color or nil
end
end
do -- 22_esp.lua
-- ============================================================================
--  22 esp      player overlays, drawn with GUI objects
--
--  GUI rather than the Drawing API, on purpose: these sit in a ScreenGui below
--  the hub, so the hub draws over them instead of under them; they take custom
--  fonts and antialiased sprites; and the same renderer draws the live preview
--  in the Visuals tab. A box is ONE 9-slice image with its dark keyline baked
--  in, a line is one stretched sprite. Elements that are switched off are never
--  created, and a property is only written when its value changed.
--
--  Far away is where an overlay earns its keep, and where the first version
--  gave up: a body under 3 px tall was simply not drawn. Now a body is never
--  drawn smaller than a set size (a mark rather than a figure, with no bones or
--  head ring, which would be a smudge), the range runs to no limit at all, a
--  ray that asks whether someone is in view is cast in lengths the engine can
--  see along, and when there are more players than chams or a set cap allow,
--  the nearest get them.
-- ============================================================================
local S, util, Motion, Theme, T, UI, Config, Roster, Assets = B.S, B.util, B.Motion, B.Theme, B.T, B.UI, B.Config, B.Roster, B.Assets
local Esp = { objects = {} }
B.Esp = Esp

local ELEMENTS = { "box", "name", "health", "hp", "distance", "tool", "team", "skeleton", "head", "tracer", "look", "arrows", "chams",
  "armor", "ammo", "money", "flags" }
Esp.ELEMENTS = ELEMENTS
-- What only a game knows about a player. Its module fills in what it has; an element with no
-- reader is not offered in the tab and is never drawn:
--   armor(entry) -> share (0..1), figure     a second bar beside health, and its number
--   ammo(entry)  -> "3/5"                    after the name of what they hold
--   money(entry) -> "$12,400 · wanted 585"   a line of its own under the box
--   flags(entry) -> "KNOCKED\nRELOADING"     beside the box, one to a line
-- `sample` is the same four for the picture in the tab: sample.armor(clock) and so on.
Esp.extras = {}
Esp.EXTRA = { { "armor", "Armor bar", icon = "shield" }, { "ammo", "Ammo of the held gun", icon = "zap" }, { "money", "Cash and wanted", icon = "gem" },
  { "flags", "State flags", icon = "flag" } }
Esp.sections = {}         -- functions (page) a game's module adds: its own sections on the Visuals tab
local ARMOR_COLOR = Color3.fromRGB(88, 166, 255)
local FLAG_COLOR = Color3.fromRGB(255, 209, 102)
local FAR = 100000        -- the last stop of the Range slider: no limit
local EVERYONE = 100      -- and of the player cap
local FIGURE = 14         -- a body shorter than this on screen is a mark: no bones, head ring or look line
Esp.FAR, Esp.EVERYONE = FAR, EVERYONE
local O            -- live settings
local want = {}    -- element name -> bool

-- ---------------------------------------------------------------- one target
local Object = {}
Object.__index = Object
Esp.Object = Object

local function sprite(parent, name, z)
  local image = Instance.new("ImageLabel")
  image.BackgroundTransparency = 1
  image.BorderSizePixel = 0
  image.Image = Assets.image(name) or ""
  image.ZIndex = z or 1
  image.Visible = false
  image.Parent = parent
  return image
end
local function text(parent, size)
  local label = Instance.new("TextLabel")
  label.BackgroundTransparency = 1
  label.BorderSizePixel = 0
  label.FontFace = B.F.text600
  label.TextSize = size
  label.Text = ""
  label.TextStrokeColor3 = Color3.new(0, 0, 0)
  label.TextStrokeTransparency = 0.45
  label.Size = UDim2.fromOffset(220, size + 4)
  label.ZIndex = 4
  label.Visible = false
  label.Parent = parent
  return label
end
-- write a position/size only when it moved by a pixel
local function rect(gui, cache, x, y, w, h)
  x, y, w, h = math.floor(x + 0.5), math.floor(y + 0.5), math.floor(w + 0.5), math.floor(h + 0.5)
  if cache[1] ~= x or cache[2] ~= y then gui.Position = UDim2.fromOffset(x, y); cache[1], cache[2] = x, y end
  if cache[3] ~= w or cache[4] ~= h then gui.Size = UDim2.fromOffset(w, h); cache[3], cache[4] = w, h end
end
local function show(gui, on)
  if gui.Visible ~= on then gui.Visible = on end
end
local function line(image, x1, y1, x2, y2, thickness)
  local dx, dy = x2 - x1, y2 - y1
  local length = math.sqrt(dx * dx + dy * dy)
  image.Position = UDim2.fromOffset((x1 + x2) * 0.5, (y1 + y2) * 0.5)
  image.Size = UDim2.fromOffset(length, thickness + 2.6)
  image.Rotation = math.deg(math.atan2(dy, dx))
end

function Object.new(parent)
  local self = setmetatable({ parent = parent, cache = {}, bones = {}, shown = false }, Object)
  self.root = Instance.new("Frame")
  self.root.BackgroundTransparency = 1
  self.root.Size = UDim2.fromScale(1, 1)
  self.root.Visible = false
  self.root.Parent = parent
  return self
end
function Object:get(key, make)
  local item = self[key]
  if not item then
    item = make(self.root)
    self[key] = item
    self.cache[key] = {}
  end
  return item
end
function Object:hide()
  if self.shown then
    self.shown = false
    self.root.Visible = false
  end
  if self.highlight and self.highlight.Enabled then self.highlight.Enabled = false end
  if self.arrow and self.arrow.Visible then self.arrow.Visible = false end
  if self.arrowText and self.arrowText.Visible then self.arrowText.Visible = false end
end
function Object:destroy()
  self.root:Destroy()
  if self.highlight then self.highlight:Destroy() end
  if self.arrow then self.arrow:Destroy() end
  if self.arrowText then self.arrowText:Destroy() end
end

-- info: x, y, w, h (the box), name, distance, health (0..1), hp (a number), tool, team, color,
--       alpha (0..1), joints = { [name] = {x, y, front} }, bones, headX, headY, headR, lookX,
--       lookY, originX, originY
function Object:draw(info, o, on)
  if not self.shown then self.shown = true; self.root.Visible = true end
  local cache = self.cache
  local color, fade = info.color, 1 - info.alpha
  local x, y, w, h = info.x, info.y, info.w, info.h
  local cx = x + w * 0.5

  -- box: one 9-slice sprite, or four corner brackets
  local full, corners = on.box and o.box == "full", on.box and o.box ~= "full"
  if full then
    local box = self:get("box", function(p)
      local image = sprite(p, "esp_box", 2)
      image.ScaleType = Enum.ScaleType.Slice
      image.SliceCenter = Rect.new(8, 8, 16, 16)
      return image
    end)
    box.SliceScale = o.thickness * 0.5
    box.ImageColor3, box.ImageTransparency = color, fade
    rect(box, cache.box, x - 1, y - 1, w + 2, h + 2)
    show(box, true)
  elseif self.box then show(self.box, false) end
  if corners then
    local size = math.clamp(math.min(w, h) * 0.28, 5, 26)
    for index = 1, 4 do
      local key = "corner" .. index
      local corner = self:get(key, function(p)
        local image = sprite(p, "esp_corner", 2)
        image.ScaleType = Enum.ScaleType.Slice
        image.SliceCenter = Rect.new(5, 5, 15, 15)
        image.Rotation = (index - 1) * 90
        return image
      end)
      corner.SliceScale = o.thickness * 0.5
      corner.ImageColor3, corner.ImageTransparency = color, fade
      local px = (index == 1 or index == 4) and x - 1 or x + w + 1 - size
      local py = (index == 1 or index == 2) and y - 1 or y + h + 1 - size
      rect(corner, cache[key], px, py, size, size)
      show(corner, true)
    end
  elseif self.corner1 then
    for index = 1, 4 do show(self["corner" .. index], false) end
  end
  if on.box and o.fill then
    local fill = self:get("fill", function(p)
      local frame = Instance.new("Frame")
      frame.BorderSizePixel = 0
      frame.ZIndex = 1
      frame.Visible = false
      UI.gradient(frame, { Rotation = 90, Transparency = UI.alphaSeq(0, 0.97, 1, 0.72) })
      frame.Parent = p
      return frame
    end)
    fill.BackgroundColor3 = color
    fill.BackgroundTransparency = fade
    rect(fill, cache.fill, x, y, w, h)
    show(fill, true)
  elseif self.fill then show(self.fill, false) end

  -- health: a thin bar on the left that eases toward the real value
  if on.health and info.health then
    local back = self:get("healthBack", function(p)
      local frame = Instance.new("Frame")
      frame.BorderSizePixel = 0
      frame.BackgroundColor3 = Color3.new(0, 0, 0)
      frame.ZIndex = 2
      frame.Visible = false
      frame.Parent = p
      local bar = Instance.new("Frame")
      bar.Name = "Bar"
      bar.BorderSizePixel = 0
      bar.AnchorPoint = Vector2.new(0, 1)
      bar.Position = UDim2.new(0, 1, 1, -1)
      bar.Parent = frame
      return frame
    end)
    local shownHealth = self.healthShown or info.health
    shownHealth += (info.health - shownHealth) * math.min(1, Motion.dt * 10)
    self.healthShown = shownHealth
    local bar = back.Bar
    back.BackgroundTransparency = 0.45 + fade * 0.55
    bar.BackgroundColor3 = Color3.fromHSV(0.33 * util.clamp01(shownHealth), 0.78, 0.96)
    bar.BackgroundTransparency = fade
    rect(back, cache.healthBack, x - 7, y - 1, 4, h + 2)
    local inner = math.max(1, math.floor((h) * util.clamp01(shownHealth) + 0.5))
    if cache.healthBack[5] ~= inner then bar.Size = UDim2.new(1, -2, 0, inner); cache.healthBack[5] = inner end
    show(back, true)
  elseif self.healthBack then show(self.healthBack, false) end
  -- armor: the same bar in blue, outside the health bar when there is one
  if on.armor and info.armor then
    local back = self:get("armorBack", function(p)
      local frame = Instance.new("Frame")
      frame.BorderSizePixel = 0
      frame.BackgroundColor3 = Color3.new(0, 0, 0)
      frame.ZIndex = 2
      frame.Visible = false
      frame.Parent = p
      local bar = Instance.new("Frame")
      bar.Name = "Bar"
      bar.BorderSizePixel = 0
      bar.AnchorPoint = Vector2.new(0, 1)
      bar.Position = UDim2.new(0, 1, 1, -1)
      bar.BackgroundColor3 = ARMOR_COLOR
      bar.Parent = frame
      return frame
    end)
    local shownArmor = self.armorShown or info.armor
    shownArmor += (info.armor - shownArmor) * math.min(1, Motion.dt * 10)
    self.armorShown = shownArmor
    local bar = back.Bar
    back.BackgroundTransparency = 0.45 + fade * 0.55
    bar.BackgroundTransparency = fade
    rect(back, cache.armorBack, x - ((on.health and info.health) and 12 or 7), y - 1, 4, h + 2)
    local inner = math.floor(h * util.clamp01(shownArmor) + 0.5)
    if cache.armorBack[5] ~= inner then bar.Size = UDim2.new(1, -2, 0, inner); cache.armorBack[5] = inner end
    show(back, true)
  elseif self.armorBack then show(self.armorBack, false) end

  -- labels
  if on.name and info.name then
    local label = self:get("name", function(p)
      local item = text(p, o.textSize)
      item.AnchorPoint = Vector2.new(0.5, 1)
      return item
    end)
    if cache.name.text ~= info.name then label.Text = info.name; cache.name.text = info.name end
    if cache.name.size ~= o.textSize then label.TextSize = o.textSize; cache.name.size = o.textSize end
    label.TextColor3, label.TextTransparency = color, fade
    label.TextStrokeTransparency = 0.45 + fade * 0.55
    rect(label, cache.name, cx, y - 4, 220, o.textSize + 4)
    show(label, true)
  elseif self.name then show(self.name, false) end
  -- under the box: how far and how much health in figures, then what they hold and whose side they are on
  local small = math.max(9, o.textSize - 2)
  local below = y + h + 3
  local figures
  if on.distance and info.distance then figures = util.studs(info.distance) .. " st" end
  if on.hp and info.hp then
    figures = (figures and (figures .. "  ·  ") or "") .. math.floor(info.hp + 0.5) .. " hp"
    if on.armor and info.armorValue and info.armorValue > 0 then figures = figures .. " +" .. math.floor(info.armorValue + 0.5) end
  end
  if figures then
    local label = self:get("dist", function(p)
      local item = text(p, small)
      item.FontFace = B.F.mono500
      item.AnchorPoint = Vector2.new(0.5, 0)
      return item
    end)
    if cache.dist.value ~= figures then label.Text = figures; cache.dist.value = figures end
    if cache.dist.size ~= small then label.TextSize = small; cache.dist.size = small end
    label.TextColor3 = Color3.new(1, 1, 1)
    label.TextTransparency = 0.12 + fade * 0.88
    label.TextStrokeTransparency = 0.5 + fade * 0.5
    rect(label, cache.dist, cx, below, 220, small + 3)
    show(label, true)
    below += small + 2
  elseif self.dist then show(self.dist, false) end
  local words
  if on.tool and info.tool then words = info.tool end
  if on.ammo and info.ammo then words = (words and (words .. "  ") or "") .. info.ammo end
  if on.team and info.team then words = (words and (words .. "  ·  ") or "") .. info.team end
  if words then
    local label = self:get("tool", function(p)
      local item = text(p, small)
      item.FontFace = B.F.text500
      item.AnchorPoint = Vector2.new(0.5, 0)
      return item
    end)
    if cache.tool.text ~= words then label.Text = words; cache.tool.text = words end
    if cache.tool.size ~= small then label.TextSize = small; cache.tool.size = small end
    label.TextColor3 = Color3.new(1, 1, 1)
    label.TextTransparency = 0.3 + fade * 0.7
    rect(label, cache.tool, cx, below, 220, small + 3)
    show(label, true)
    below += small + 2
  elseif self.tool then show(self.tool, false) end
  -- what they have on them, on a line of its own
  if on.money and info.money then
    local label = self:get("money", function(p)
      local item = text(p, small)
      item.FontFace = B.F.mono500
      item.AnchorPoint = Vector2.new(0.5, 0)
      item.TextColor3 = Color3.fromRGB(126, 231, 135)
      return item
    end)
    if cache.money.text ~= info.money then label.Text = info.money; cache.money.text = info.money end
    if cache.money.size ~= small then label.TextSize = small; cache.money.size = small end
    label.TextTransparency = 0.15 + fade * 0.85
    label.TextStrokeTransparency = 0.5 + fade * 0.5
    rect(label, cache.money, cx, below, 220, small + 3)
    show(label, true)
  elseif self.money then show(self.money, false) end
  -- what they are doing, beside the box: one word to a line
  if on.flags and info.flags then
    local label = self:get("flags", function(p)
      local item = text(p, small)
      item.FontFace = B.F.text700
      item.TextXAlignment = Enum.TextXAlignment.Left
      item.TextYAlignment = Enum.TextYAlignment.Top
      item.TextColor3 = FLAG_COLOR
      return item
    end)
    if cache.flags.text ~= info.flags then label.Text = info.flags; cache.flags.text = info.flags end
    local tiny = math.max(8, small - 1)
    if cache.flags.size ~= tiny then label.TextSize = tiny; cache.flags.size = tiny end
    label.TextTransparency = fade
    label.TextStrokeTransparency = 0.45 + fade * 0.55
    rect(label, cache.flags, x + w + 5, y - 1, 160, (tiny + 2) * 5)
    show(label, true)
  elseif self.flags then show(self.flags, false) end

  -- skeleton
  local bones = self.bones
  if on.skeleton and info.joints and info.bones then
    local joints = info.joints
    for index, pair in ipairs(info.bones) do
      local a, b = joints[pair[1]], joints[pair[2]]
      local bone = bones[index]
      if a and b and a[3] and b[3] then
        if not bone then
          bone = sprite(self.root, "line", 3)
          bone.AnchorPoint = Vector2.new(0.5, 0.5)
          bones[index] = bone
        end
        line(bone, a[1], a[2], b[1], b[2], o.thickness * 0.8)
        bone.ImageColor3, bone.ImageTransparency = color, fade
        show(bone, true)
      elseif bone then show(bone, false) end
    end
    for index = #info.bones + 1, #bones do show(bones[index], false) end
  else
    for _, bone in ipairs(bones) do show(bone, false) end
  end
  -- head ring
  if on.head and info.headR then
    local ring = self:get("head", function(p)
      local image = sprite(p, "ring", 3)
      image.AnchorPoint = Vector2.new(0.5, 0.5)
      return image
    end)
    local d = math.max(6, info.headR * 2)
    ring.ImageColor3, ring.ImageTransparency = color, fade
    rect(ring, cache.head, info.headX, info.headY, d, d)
    show(ring, true)
  elseif self.head then show(self.head, false) end
  -- look direction
  if on.look and info.lookX then
    local ray = self:get("look", function(p)
      local image = sprite(p, "line", 3)
      image.AnchorPoint = Vector2.new(0.5, 0.5)
      return image
    end)
    line(ray, info.headX, info.headY, info.lookX, info.lookY, o.thickness * 0.8)
    ray.ImageColor3, ray.ImageTransparency = color, 0.25 + fade * 0.75
    show(ray, true)
  elseif self.look then show(self.look, false) end
  -- tracer
  if on.tracer and info.originX then
    local tracer = self:get("tracer", function(p)
      local image = sprite(p, "line", 1)
      image.AnchorPoint = Vector2.new(0.5, 0.5)
      return image
    end)
    line(tracer, info.originX, info.originY, cx, o.tracerFrom == "top" and y or y + h, o.thickness * 0.8)
    tracer.ImageColor3, tracer.ImageTransparency = color, 0.35 + fade * 0.65
    show(tracer, true)
  elseif self.tracer then show(self.tracer, false) end
end

-- ---------------------------------------------------------------- the live overlay
local gui, layer, arrowLayer, highlights
local info = { joints = {} }
local jointPool = {}
local rayParams
local chamsBudget = 0
local order = {}          -- the roster, nearest first, when that matters

local function colorFor(entry, o)
  if o.markTarget and B.Aim and B.Aim.target == entry then return o.targetColor end
  if Roster.isFriend(entry) then return o.friendColor end
  if o.seenTint and entry.seen then return o.seenColor end
  if o.colorMode == "team" then return Roster.teamColor(entry) or o.color end
  if o.colorMode == "health" then return Color3.fromHSV(0.33 * util.clamp01((entry.health or 100) / (entry.maxHealth or 100)), 0.75, 1) end
  return o.color
end
local function nearer(a, b) return a.far < b.far end
-- what the game's module can say about a player, read ten times a second at the most
local function extrasOf(entry, now)
  local kept = entry.extra
  if kept and now - kept.at < 0.1 then return kept end
  kept = kept or {}
  entry.extra = kept
  kept.at = now + (entry.userId % 5) * 0.004
  local extras = Esp.extras
  kept.armor, kept.armorValue, kept.ammo, kept.money, kept.flags = nil, nil, nil, nil, nil
  if want.armor and extras.armor then kept.armor, kept.armorValue = B.try("esp.armor", extras.armor, entry) end
  if want.ammo and extras.ammo then kept.ammo = B.try("esp.ammo", extras.ammo, entry) end
  if want.money and extras.money then kept.money = B.try("esp.money", extras.money, entry) end
  if want.flags and extras.flags then kept.flags = B.try("esp.flags", extras.flags, entry) end
  return kept
end

local function step()
  local camera = workspace.CurrentCamera
  if not camera then return end
  local o = O
  local camCF = camera.CFrame
  local camPos = camCF.Position
  local view = camera.ViewportSize
  local range = o.range >= FAR and math.huge or o.range
  local nameRange = o.nameRange >= FAR and math.huge or o.nameRange
  -- where the fade begins and ends: on the range, or over 20,000 studs when there is none
  local span = range == math.huge and 20000 or range
  local fadeFrom = span * o.fadeFrom / 100
  local now = os.clock()
  local mouse = S.UserInputService:GetMouseLocation()
  local tanHalf = math.tan(math.rad(camera.FieldOfView) * 0.5)
  local sight = o.dimHidden or o.hideHidden or o.seenTint
  chamsBudget = 28      -- the engine draws 31 highlights at most

  -- who is in play this frame, and how far off
  local list = Roster.list
  local count = 0
  for _, entry in ipairs(list) do
    local root = entry.root
    local live = entry.alive and root ~= nil and root.Parent ~= nil and (not o.teamCheck or Roster.isEnemy(entry)) and not Roster.isHidden(entry)
    if live then
      entry.far = (root.Position - camPos).Magnitude
      if entry.far > range then live = false end
    end
    if live then
      count += 1
      order[count] = entry
    else
      local object = Esp.objects[entry]
      if object then object:hide() end
    end
  end
  for index = count + 1, #order do order[index] = nil end
  -- Nearest first, but only when it changes anything: a cap on how many are drawn, or more
  -- players than there are highlights to go round.
  local cap = o.maxPlayers >= EVERYONE and math.huge or o.maxPlayers
  if cap < count or (want.chams and count > chamsBudget) then table.sort(order, nearer) end

  for index = 1, count do
    local entry = order[index]
    local object = Esp.objects[entry]
    local root = entry.root
    local distance = entry.far
    local visible = index <= cap
    if visible and sight then
      -- one ray per player, ten times a second, spread across frames
      if not entry.seenAt or now - entry.seenAt > 0.1 then
        entry.seenAt = now + (entry.userId % 7) * 0.004
        rayParams.FilterDescendantsInstances = { B.LP.Character, entry.character }
        entry.seen = util.ray(camPos, (entry.head or root).Position, rayParams) == nil
      end
      if o.hideHidden and not entry.seen then visible = false end
    end
    if not visible then
      if object then object:hide() end
    else
      if not object then
        object = Object.new(layer)
        Esp.objects[entry] = object
      end
      local color = colorFor(entry, o)
      local alpha = 1
      if o.fade then alpha = 1 - util.clamp01((distance - fadeFrom) / math.max(span - fadeFrom, 1)) * 0.75 end
      if o.dimHidden and sight and not entry.seen then alpha *= 0.42 end
      local rootPos = root.Position
      local head = entry.head
      local top = camera:WorldToViewportPoint((head and head.Position or rootPos + Vector3.new(0, 1.6, 0)) + Vector3.new(0, 0.85, 0))
      local bottom = camera:WorldToViewportPoint(rootPos - Vector3.new(0, entry.legs or 3, 0))
      local onScreen = false
      if top.Z > 0 and bottom.Z > 0 then
        -- never smaller than the size that is set: far off, a body is a mark where they are
        local real = math.abs(bottom.Y - top.Y)
        local height = math.max(real, o.minSize)
        local width = height * o.boxWidth / 100
        local cx = (top.X + bottom.X) * 0.5
        local y = (top.Y + bottom.Y) * 0.5 - height * 0.5
        if height >= 2 and cx + width > 0 and cx - width < view.X and y + height > 0 and y < view.Y then
          onScreen = true
          local figure = real >= FIGURE
          local named = distance <= nameRange
          info.x, info.y, info.w, info.h = cx - width * 0.5, y, width, height
          info.color, info.alpha = color, alpha
          info.name = named and (o.displayNames and entry.display or entry.name) or nil
          info.distance = distance
          info.health = entry.health and (entry.health / (entry.maxHealth or 100)) or nil
          info.hp = entry.health
          info.tool = named and entry.tool or nil
          info.team = named and Roster.teamName(entry) or nil
          if want.armor or want.ammo or want.money or want.flags then
            local extra = extrasOf(entry, now)
            info.armor, info.armorValue, info.flags = extra.armor, extra.armorValue, extra.flags
            info.ammo, info.money = named and extra.ammo or nil, named and extra.money or nil
          else
            info.armor, info.armorValue, info.flags, info.ammo, info.money = nil, nil, nil, nil, nil
          end
          info.joints, info.bones, info.headR, info.lookX, info.originX = nil, nil, nil, nil, nil
          if figure and (want.head or want.look) and head then
            local hp = camera:WorldToViewportPoint(head.Position)
            info.headX, info.headY = hp.X, hp.Y
            info.headR = math.max(3, (head.Size.Y * 0.62) / hp.Z * view.Y / (2 * tanHalf))
            if want.look then
              local lp = camera:WorldToViewportPoint(head.Position + head.CFrame.LookVector * 5)
              if lp.Z > 0 then info.lookX, info.lookY = lp.X, lp.Y end
            end
          end
          if figure and want.skeleton and distance < o.skeletonRange then
            local joints = jointPool
            for name, part in pairs(entry.joints) do
              local p = camera:WorldToViewportPoint(part.Position)
              local slot = joints[name]
              if not slot then slot = {}; joints[name] = slot end
              slot[1], slot[2], slot[3] = p.X, p.Y, p.Z > 0
            end
            info.joints, info.bones = joints, entry.bones
          end
          if want.tracer then
            if o.tracerFrom == "mouse" then info.originX, info.originY = mouse.X, mouse.Y
            elseif o.tracerFrom == "center" then info.originX, info.originY = view.X * 0.5, view.Y * 0.5
            elseif o.tracerFrom == "top" then info.originX, info.originY = view.X * 0.5, 0
            else info.originX, info.originY = view.X * 0.5, view.Y end
          end
          object:draw(info, o, want)
          if object.arrow then show(object.arrow, false) end
          if object.arrowText then show(object.arrowText, false) end
        end
      end
      if not onScreen then
        if object.shown then object.shown = false; object.root.Visible = false end
        -- off screen: an arrow on a ring round the centre, pointing at them
        if want.arrows then
          local arrow = object.arrow
          if not arrow then
            arrow = sprite(arrowLayer, "arrow", 2)
            arrow.AnchorPoint = Vector2.new(0.5, 0.5)
            object.arrow = arrow
          end
          local size = o.arrowSize
          if object.arrowSize ~= size then arrow.Size = UDim2.fromOffset(size, size); object.arrowSize = size end
          local rel = camCF:PointToObjectSpace(rootPos)
          local angle = math.atan2(rel.X, -rel.Z)
          local radius = math.min(view.X, view.Y) * o.arrowRadius / 100
          local ax, ay = view.X * 0.5 + math.sin(angle) * radius, view.Y * 0.5 - math.cos(angle) * radius
          arrow.Position = UDim2.fromOffset(ax, ay)
          arrow.Rotation = math.deg(angle)
          arrow.ImageColor3 = color
          arrow.ImageTransparency = 0.15 + (1 - alpha) * 0.85
          show(arrow, true)
          if o.arrowDistance then
            -- how far, just inside the arrow
            local label = object.arrowText
            if not label then
              label = text(arrowLayer, 10)
              label.FontFace = B.F.mono500
              label.AnchorPoint = Vector2.new(0.5, 0.5)
              label.Size = UDim2.fromOffset(80, 14)
              label.TextColor3 = Color3.new(1, 1, 1)
              object.arrowText = label
            end
            local figures = util.studs(distance)
            if object.arrowFigures ~= figures then label.Text = figures; object.arrowFigures = figures end
            local inward = radius - size * 0.5 - 12
            label.Position = UDim2.fromOffset(view.X * 0.5 + math.sin(angle) * inward, view.Y * 0.5 - math.cos(angle) * inward)
            label.TextTransparency = 0.2 + (1 - alpha) * 0.8
            show(label, true)
          elseif object.arrowText then show(object.arrowText, false) end
        else
          if object.arrow then show(object.arrow, false) end
          if object.arrowText then show(object.arrowText, false) end
        end
      end
      -- chams: the engine's own outline through walls
      if want.chams and chamsBudget > 0 and entry.character then
        chamsBudget -= 1
        local highlight = object.highlight
        if not highlight then
          highlight = Instance.new("Highlight")
          highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
          highlight.Parent = highlights
          object.highlight = highlight
        end
        if highlight.Adornee ~= entry.character then highlight.Adornee = entry.character end
        highlight.FillColor, highlight.OutlineColor = color, color
        highlight.FillTransparency = 1 - (1 - o.chamsFill / 100) * alpha
        highlight.OutlineTransparency = o.chamsOutline and (1 - alpha) or 1
        if not highlight.Enabled then highlight.Enabled = true end
      elseif object.highlight and object.highlight.Enabled then
        object.highlight.Enabled = false
      end
    end
  end
end

local bound = false
local function setRunning(on)
  if on == bound then return end
  bound = on
  if on then
    S.RunService:BindToRenderStep("BasedEsp", Enum.RenderPriority.Camera.Value + 3, function()
      local ok, err = pcall(step)
      if not ok then B.fault("esp", err); Config.set("esp.enabled", false) end
    end)
  else
    pcall(function() S.RunService:UnbindFromRenderStep("BasedEsp") end)
    for _, object in pairs(Esp.objects) do object:hide() end
  end
end

function Esp.define()
  Config.define("esp.enabled", false)
  Config.define("esp.elements", { "box", "name", "health", "distance" })
  Config.define("esp.box", "corners")
  Config.define("esp.fill", false)
  Config.define("esp.boxWidth", 56)
  Config.define("esp.minSize", 12)
  Config.define("esp.colorMode", "custom")
  Config.define("esp.color", util.hex("C9C2FF"))
  Config.define("esp.friendColor", util.hex("45DDA8"))
  Config.define("esp.seenTint", false)
  Config.define("esp.seenColor", util.hex("FFD166"))
  Config.define("esp.markTarget", true)
  Config.define("esp.targetColor", util.hex("FF6B6B"))
  Config.define("esp.range", 3000)
  Config.define("esp.nameRange", FAR)
  Config.define("esp.skeletonRange", 500)
  Config.define("esp.maxPlayers", EVERYONE)
  Config.define("esp.teamCheck", false)
  Config.define("esp.displayNames", true)
  Config.define("esp.textSize", 13)
  Config.define("esp.thickness", 2)
  Config.define("esp.tracerFrom", "bottom")
  Config.define("esp.arrowSize", 18)
  Config.define("esp.arrowRadius", 36)
  Config.define("esp.arrowDistance", true)
  Config.define("esp.fade", true)
  Config.define("esp.fadeFrom", 55)
  Config.define("esp.dimHidden", false)
  Config.define("esp.hideHidden", false)
  Config.define("esp.chamsFill", 75)
  Config.define("esp.chamsOutline", true)
end

function Esp.start()
  if Esp.started then return end
  Esp.started = true
  Esp.define()
  Roster.start()
  gui = B.screen(8000)
  layer = UI.frame(gui, { Name = "Esp", Size = UDim2.fromScale(1, 1) })
  arrowLayer = UI.frame(gui, { Name = "Arrows", Size = UDim2.fromScale(1, 1) })
  highlights = Instance.new("Folder")
  highlights.Name = util.randomName()
  highlights.Parent = gui
  rayParams = RaycastParams.new()
  rayParams.FilterType = Enum.RaycastFilterType.Exclude
  rayParams.IgnoreWater = true
  O = Config.mirror({ enabled = "esp.enabled", box = "esp.box", fill = "esp.fill", boxWidth = "esp.boxWidth", minSize = "esp.minSize", colorMode = "esp.colorMode",
    color = "esp.color", friendColor = "esp.friendColor", seenTint = "esp.seenTint", seenColor = "esp.seenColor", markTarget = "esp.markTarget",
    targetColor = "esp.targetColor", range = "esp.range", nameRange = "esp.nameRange", skeletonRange = "esp.skeletonRange", maxPlayers = "esp.maxPlayers",
    teamCheck = "esp.teamCheck", displayNames = "esp.displayNames", textSize = "esp.textSize", thickness = "esp.thickness", tracerFrom = "esp.tracerFrom",
    arrowSize = "esp.arrowSize", arrowRadius = "esp.arrowRadius", arrowDistance = "esp.arrowDistance", fade = "esp.fade", fadeFrom = "esp.fadeFrom",
    dimHidden = "esp.dimHidden", hideHidden = "esp.hideHidden", chamsFill = "esp.chamsFill", chamsOutline = "esp.chamsOutline" })
  Esp.options = O
  local function elements(list)
    table.clear(want)
    for _, name in ipairs(list) do want[name] = true end
  end
  elements(Config.get("esp.elements"))
  Config.on("esp.elements", elements)
  Esp.want = want
  Config.on("esp.enabled", setRunning, true)
  -- a player who left takes their overlay with them
  Roster.changed:connect(function(entry)
    if entry.gone then
      local object = Esp.objects[entry]
      if object then object:destroy(); Esp.objects[entry] = nil end
    end
  end)
  B.own(function() setRunning(false) end)
end
end
do -- 23_aim.lua
-- ============================================================================
--  23 aim      aim assist, FOV ring, triggerbot
--
--  Two ways to turn toward a target. "Mouse" feeds relative mouse movement to
--  the game, so the game's own camera does the turning (works with any camera
--  script, first or third person). "Camera" writes the camera's CFrame, for
--  games that leave the default camera alone. Both close the gap by a fraction
--  per frame derived from frame time, so the feel is the same at 60 and 240 fps,
--  and each axis can have its own.
--
--  Far targets need three things the first version did not have: a range with
--  no ceiling, a line of sight that is cast in lengths a ray can see along (one
--  ray finds nothing past 15,000 studs, which read as "in view"), and a lead
--  that knows a shot takes time to arrive and falls on the way.
-- ============================================================================
local S, util, Motion, Theme, T, UI, Config, Roster, Hud, Assets = B.S, B.util, B.Motion, B.Theme, B.T, B.UI, B.Config, B.Roster, B.Hud, B.Assets
local UIS = S.UserInputService
local Aim = { target = nil, active = false }
B.Aim = Aim
local FAR = 100000        -- the last stop of the Range slider: no limit
local WHOLE = 2500        -- the last stop of the circle: the whole screen
Aim.FAR, Aim.WHOLE = FAR, WHOLE
local O
local wantParts = {}
local rayParams
local ring, ringStroke, mark, markStroke, crossA, crossB, snap, note, gui
local toggled = false
local lostAt = -math.huge     -- when the last target was lost: a new one waits out the switch delay
local onSince, onWho = nil, nil
local canMouse = type(mousemoverel) == "function"
Aim.canMouse = canMouse
Aim.canClick = type(mouse1click) == "function" or (type(mouse1press) == "function" and type(mouse1release) == "function")

local function aimPoint(entry, camera, origin)
  -- returns the part to aim at, where it is on screen, and how far that is from the crosshair
  local best, bestScreen, bestDistance
  local function consider(part)
    if not part then return end
    local p = camera:WorldToViewportPoint(part.Position + Vector3.new(0, O.offset, 0))
    if p.Z <= 0 then return end
    local d = (Vector2.new(p.X, p.Y) - origin).Magnitude
    if not bestDistance or d < bestDistance then best, bestScreen, bestDistance = part, p, d end
  end
  local joints = entry.joints
  if wantParts.nearest then
    consider(entry.head); consider(joints.UpperTorso or joints.Torso); consider(entry.root); consider(joints.LowerTorso)
  else
    local part = (wantParts.head and entry.head) or (wantParts.torso and (joints.UpperTorso or joints.Torso)) or (wantParts.root and entry.root) or entry.head or entry.root
    consider(part)
  end
  return best, bestScreen, bestDistance
end

-- Is there a clear line from the camera to that point? With "see through glass" on, something
-- that can be seen through or walked through does not count as a wall.
local function visible(camera, entry, point)
  local from = camera.CFrame.Position
  local ignore = { B.LP.Character, entry.character }
  for _ = 1, O.wallClear and 6 or 1 do
    rayParams.FilterDescendantsInstances = ignore
    local hit = util.ray(from, point, rayParams)
    if not hit then return true end
    local part = hit.Instance
    if not (O.wallClear and part:IsA("BasePart") and (part.Transparency >= 0.8 or not part.CanCollide)) then return false end
    ignore[#ignore + 1] = part
  end
  return false
end

local function valid(entry, camPos)
  if not entry.alive or not entry.root or not entry.root.Parent then return false end
  if Roster.isHidden(entry) then return false end
  if O.teamCheck and not Roster.isEnemy(entry) then return false end
  if O.ignoreFriends and Roster.isFriend(entry) then return false end
  if O.skipShielded and entry.shielded then return false end
  if O.onlyMarked and Roster.anyTargets() and not Roster.isTarget(entry) then return false end
  return O.range >= FAR or (entry.root.Position - camPos).Magnitude <= O.range
end

-- what a candidate is ranked by: lower is better
local function rank(entry, pixels, camPos)
  if O.priority == "distance" then return (entry.root.Position - camPos).Magnitude end
  if O.priority == "health" then return (entry.health or 100) / (entry.maxHealth or 100) end
  return pixels
end
local function better(a, b)
  -- a marked target comes before anyone who is not
  if a[5] ~= b[5] then return a[5] end
  return a[4] < b[4]
end

local function pick(camera, origin, now)
  local camPos = camera.CFrame.Position
  local radius = O.fov >= WHOLE and math.huge or O.fov
  -- keep the current target while it stays valid and close to the crosshair
  local current = Aim.target
  if current then
    if valid(current, camPos) then
      if O.sticky then
        local part, screen, distance = aimPoint(current, camera, origin)
        if part and distance <= radius * 1.6 and (not O.wallCheck or visible(camera, current, part.Position)) then
          return current, part, screen
        end
      end
    else
      -- dead, gone or no longer allowed: the next one is not taken at once
      lostAt = now
    end
  end
  if now - lostAt < O.switchDelay / 1000 then return nil end
  local candidates = {}
  for _, entry in ipairs(Roster.list) do
    if valid(entry, camPos) then
      local part, screen, distance = aimPoint(entry, camera, origin)
      if part and distance <= radius then candidates[#candidates + 1] = { entry, part, screen, rank(entry, distance, camPos), Roster.isTarget(entry) } end
    end
  end
  table.sort(candidates, better)
  -- best first; at most three wall checks a frame
  for index = 1, math.min(#candidates, 3) do
    local c = candidates[index]
    if not O.wallCheck or visible(camera, c[1], c[2].Position) then return c[1], c[2], c[3] end
  end
  return nil
end

local function isActive()
  if not O.enabled then return false end
  if O.mode == "always" then return true end
  if O.mode == "toggle" then return toggled end
  return Config.keyDown(O.key)
end

local lastClick = 0
local function click()
  if type(mouse1click) == "function" then mouse1click()
  elseif type(mouse1press) == "function" then mouse1press(); task.delay(0.02, mouse1release) end
end

-- the ring, the mark on the target and the line to it all take one colour: the accent, or your own
local function paint()
  if not ring then return end
  local color = O.ownColor and O.color or T.accent
  local alpha = 1 - O.fovOpacity / 100
  ringStroke.Color, ringStroke.Thickness, ringStroke.Transparency = color, O.fovThickness, alpha
  ring.BackgroundColor3 = color
  ring.BackgroundTransparency = O.fovFill and 1 - 0.07 * O.fovOpacity / 100 or 1
  markStroke.Color, crossA.BackgroundColor3, crossB.BackgroundColor3, snap.ImageColor3 = color, color, color, color
  local style = O.markStyle
  local size = style == "ring" and 24 or 9
  mark.Size = UDim2.fromOffset(size, size)
  markStroke.Enabled = style ~= "cross"
  crossA.Visible, crossB.Visible = style == "cross", style == "cross"
end
local function hideMarks()
  if mark and mark.Visible then mark.Visible = false end
  if snap and snap.Visible then snap.Visible = false end
  if note and note.Visible then note.Visible = false end
end

local function step(dt)
  local camera = workspace.CurrentCamera
  if not camera then return end
  local now = os.clock()
  local mouse = UIS:GetMouseLocation()
  local locked = UIS.MouseBehavior == Enum.MouseBehavior.LockCenter
  local origin = locked and camera.ViewportSize * 0.5 or mouse
  if ring then
    local showRing = O.enabled and O.showFov and O.fov < WHOLE and not (B.Window.anyOpen() and UI.popoverOpen())
    if ring.Visible ~= showRing then ring.Visible = showRing end
    if showRing then
      ring.Position = UDim2.fromOffset(origin.X, origin.Y)
      local d = O.fov * 2
      if ring.Size.X.Offset ~= d then ring.Size = UDim2.fromOffset(d, d) end
    end
  end
  local active = isActive() and not (B.Window.anyOpen() and UIS:GetFocusedTextBox() ~= nil)
  Aim.active = active
  if active then
    local entry, part, screen = pick(camera, origin, now)
    Aim.target = entry
    if entry and part then
      local camPos = camera.CFrame.Position
      local goal = part.Position + Vector3.new(0, O.offset, 0)
      if O.predict then
        -- where they will be when it arrives: your ping, the extra asked for, and the shot's own
        -- flight if it has one, which also falls on the way
        local lead = O.lead / 1000 + (Hud and Hud.ping() or 0) / 1000
        if O.bulletSpeed > 0 then
          local flight = (goal - camPos).Magnitude / O.bulletSpeed
          lead += flight
          goal += Vector3.new(0, 0.5 * O.drop * flight * flight, 0)
        end
        goal += entry.root.AssemblyLinearVelocity * lead
        local p = camera:WorldToViewportPoint(goal)
        if p.Z > 0 then screen = p end
      end
      local offX, offY = screen.X - origin.X, screen.Y - origin.Y
      -- inside the dead zone it is close enough: no hunting about a point it is already on
      if offX * offX + offY * offY > O.deadzone * O.deadzone then
        -- fraction of the remaining gap to close this frame, each way
        local gainX = 1 - math.exp(-dt * util.lerp(46, 3.2, util.clamp01(O.smooth / 100)))
        local gainY = O.split and 1 - math.exp(-dt * util.lerp(46, 3.2, util.clamp01(O.smoothY / 100))) or gainX
        if O.method == "mouse" and canMouse then
          local dx, dy = offX * gainX * (O.sens / 100), offY * gainY * (O.sens / 100)
          if math.abs(dx) + math.abs(dy) > 0.05 then mousemoverel(dx, dy) end
        else
          -- turn and tilt separately, about the world's up: the camera never rolls
          local cf = camera.CFrame
          local look, to = cf.LookVector, (goal - cf.Position).Unit
          local yaw, pitch = math.atan2(-look.X, -look.Z), math.asin(math.clamp(look.Y, -1, 1))
          local turn = (math.atan2(-to.X, -to.Z) - yaw + math.pi) % (2 * math.pi) - math.pi
          local tilt = math.asin(math.clamp(to.Y, -1, 1)) - pitch
          camera.CFrame = CFrame.new(cf.Position) * CFrame.Angles(0, yaw + turn * gainX, 0) * CFrame.Angles(pitch + tilt * gainY, 0, 0)
        end
      end
      if mark then
        mark.Visible = O.showTarget
        mark.Position = UDim2.fromOffset(screen.X, screen.Y)
        local lineOn = O.snapline
        if snap.Visible ~= lineOn then snap.Visible = lineOn end
        if lineOn then
          local length = math.sqrt(offX * offX + offY * offY)
          snap.Position = UDim2.fromOffset((origin.X + screen.X) * 0.5, (origin.Y + screen.Y) * 0.5)
          snap.Size = UDim2.fromOffset(length, 3.6)
          snap.Rotation = math.deg(math.atan2(offY, offX))
        end
        local noteOn = O.targetInfo
        if note.Visible ~= noteOn then note.Visible = noteOn end
        if noteOn then
          note.Position = UDim2.fromOffset(screen.X, screen.Y + 16)
          local words = entry.display .. "  ·  " .. util.studs((entry.root.Position - camPos).Magnitude) .. " st"
          if entry.health then words ..= "  ·  " .. math.floor(entry.health + 0.5) .. " hp" end
          if note.Text ~= words then note.Text = words end
        end
      end
    else
      hideMarks()
    end
  else
    Aim.target = nil
    hideMarks()
  end

  -- triggerbot: fire when the crosshair rests on an enemy
  if O.trigger and Aim.canClick and not B.Window.anyOpen() and (O.triggerMode ~= "key" or Config.keyDown(O.key)) then
    local ray = camera:ViewportPointToRay(origin.X, origin.Y)
    rayParams.FilterDescendantsInstances = { B.LP.Character }
    local reach = O.range >= FAR and FAR or O.range
    local hit = util.ray(ray.Origin, ray.Origin + ray.Direction * reach, rayParams)
    local model = hit and hit.Instance and hit.Instance:FindFirstAncestorOfClass("Model")
    local player = model and S.Players:GetPlayerFromCharacter(model)
    local entry = player and Roster.byPlayer[player]
    if entry and valid(entry, camera.CFrame.Position) and (not O.triggerHead or hit.Instance.Name == "Head") then
      -- on someone: how long for, and is it time for another shot
      if onWho ~= entry then onWho, onSince = entry, now end
      if now - onSince >= O.triggerReact / 1000 and now - lastClick > math.max(0.03, O.triggerDelay / 1000) then
        lastClick = now
        click()
      end
    else
      onWho, onSince = nil, nil
    end
  else
    onWho, onSince = nil, nil
  end
end

function Aim.define()
  Config.define("aim.enabled", false)
  Config.define("aim.mode", "hold")
  Config.define("aim.key", "MouseButton2")
  Config.define("aim.method", canMouse and "mouse" or "camera")
  Config.define("aim.fov", 140)
  Config.define("aim.showFov", true)
  Config.define("aim.fovThickness", 1.5)
  Config.define("aim.fovOpacity", 65)
  Config.define("aim.fovFill", false)
  Config.define("aim.ownColor", false)
  Config.define("aim.color", util.hex("C9C2FF"))
  Config.define("aim.showTarget", true)
  Config.define("aim.markStyle", "dot")
  Config.define("aim.snapline", false)
  Config.define("aim.targetInfo", false)
  Config.define("aim.smooth", 45)
  Config.define("aim.split", false)
  Config.define("aim.smoothY", 45)
  Config.define("aim.sens", 100)
  Config.define("aim.deadzone", 0)
  Config.define("aim.offset", 0)
  Config.define("aim.parts", { "head" })
  Config.define("aim.priority", "crosshair")
  Config.define("aim.onlyMarked", false)
  Config.define("aim.switchDelay", 0)
  Config.define("aim.teamCheck", true)
  Config.define("aim.wallCheck", true)
  Config.define("aim.wallClear", false)
  Config.define("aim.ignoreFriends", true)
  Config.define("aim.skipShielded", true)
  Config.define("aim.range", 2000)
  Config.define("aim.sticky", true)
  Config.define("aim.predict", false)
  Config.define("aim.lead", 0)
  Config.define("aim.bulletSpeed", 0)
  Config.define("aim.drop", 0)
  Config.define("aim.trigger", false)
  Config.define("aim.triggerMode", "always")
  Config.define("aim.triggerDelay", 80)
  Config.define("aim.triggerReact", 0)
  Config.define("aim.triggerHead", false)
end

function Aim.start()
  if Aim.started then return end
  Aim.started = true
  Aim.define()
  Roster.start()
  rayParams = RaycastParams.new()
  rayParams.FilterType = Enum.RaycastFilterType.Exclude
  rayParams.IgnoreWater = true
  O = Config.mirror({ enabled = "aim.enabled", mode = "aim.mode", key = "aim.key", method = "aim.method", fov = "aim.fov", showFov = "aim.showFov",
    fovThickness = "aim.fovThickness", fovOpacity = "aim.fovOpacity", fovFill = "aim.fovFill", ownColor = "aim.ownColor", color = "aim.color",
    showTarget = "aim.showTarget", markStyle = "aim.markStyle", snapline = "aim.snapline", targetInfo = "aim.targetInfo", smooth = "aim.smooth",
    split = "aim.split", smoothY = "aim.smoothY", sens = "aim.sens", deadzone = "aim.deadzone", offset = "aim.offset", priority = "aim.priority",
    onlyMarked = "aim.onlyMarked", switchDelay = "aim.switchDelay", teamCheck = "aim.teamCheck", wallCheck = "aim.wallCheck", wallClear = "aim.wallClear",
    ignoreFriends = "aim.ignoreFriends", skipShielded = "aim.skipShielded", range = "aim.range", sticky = "aim.sticky", predict = "aim.predict",
    lead = "aim.lead", bulletSpeed = "aim.bulletSpeed", drop = "aim.drop", trigger = "aim.trigger", triggerMode = "aim.triggerMode",
    triggerDelay = "aim.triggerDelay", triggerReact = "aim.triggerReact", triggerHead = "aim.triggerHead" })
  Aim.options = O
  local function parts(list)
    table.clear(wantParts)
    for _, name in ipairs(list) do wantParts[name] = true end
  end
  parts(Config.get("aim.parts"))
  Config.on("aim.parts", parts)

  gui = B.screen(8500)
  ring = UI.frame(gui, { Name = "Fov", AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(280, 280), Visible = false })
  UI.corner(ring, true)
  ringStroke = Instance.new("UIStroke")
  ringStroke.Parent = ring
  -- the line from the crosshair to the target, under the mark
  snap = UI.new("ImageLabel", { Name = "Snap", BackgroundTransparency = 1, Image = Assets.image("line") or "", AnchorPoint = Vector2.new(0.5, 0.5), ImageTransparency = 0.35,
    Visible = false, Parent = gui })
  mark = UI.frame(gui, { Name = "Target", AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(9, 9), Visible = false, BackgroundTransparency = 1 })
  UI.corner(mark, true)
  markStroke = Instance.new("UIStroke")
  markStroke.Thickness = 1.5
  markStroke.Parent = mark
  crossA = UI.frame(mark, { Name = "CrossA", AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromOffset(15, 2), Rotation = 45,
    BackgroundTransparency = 0, Visible = false })
  crossB = UI.frame(mark, { Name = "CrossB", AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromOffset(15, 2), Rotation = -45,
    BackgroundTransparency = 0, Visible = false })
  note = UI.new("TextLabel", { Name = "Note", BackgroundTransparency = 1, AnchorPoint = Vector2.new(0.5, 0), Size = UDim2.fromOffset(320, 14), FontFace = B.F.mono500,
    TextSize = 11, Text = "", TextColor3 = Color3.new(1, 1, 1), TextStrokeColor3 = Color3.new(0, 0, 0), TextStrokeTransparency = 0.5, Visible = false, Parent = gui })
  paint()
  for _, id in ipairs({ "aim.fovThickness", "aim.fovOpacity", "aim.fovFill", "aim.ownColor", "aim.color", "aim.markStyle", "app.accent", "app.scheme" }) do
    Config.on(id, function() task.defer(paint) end)
  end

  B.connect(UIS.InputBegan, function(input, processed)
    if O.mode ~= "toggle" or not O.enabled or Config.capturing then return end
    if input.UserInputType == Enum.UserInputType.Keyboard and UIS:GetFocusedTextBox() then return end
    if input.UserInputType ~= Enum.UserInputType.Keyboard and processed then return end
    if Config.keyName(input) == O.key then toggled = not toggled end
  end, "aim.toggle")

  local running = false
  local function refresh()
    local need = O.enabled or O.trigger
    if need == running then return end
    running = need
    if need then
      S.RunService:BindToRenderStep("BasedAim", Enum.RenderPriority.Camera.Value + 1, function(dt)
        local ok, err = pcall(step, dt)
        if not ok then B.fault("aim", err); Config.set("aim.enabled", false); Config.set("aim.trigger", false) end
      end)
    else
      pcall(function() S.RunService:UnbindFromRenderStep("BasedAim") end)
      ring.Visible = false
      hideMarks()
      Aim.target, Aim.active = nil, false
    end
  end
  Config.on("aim.enabled", refresh)
  Config.on("aim.trigger", refresh)
  refresh()
  B.own(function() pcall(function() S.RunService:UnbindFromRenderStep("BasedAim") end) end)
end
end
do -- 24_move.lua
-- ============================================================================
--  24 move     speed, jump, noclip, click teleport, gravity
--
--  Everything here restores what it changed when it is switched off, and
--  re-applies itself after a respawn. Flight lives in 26_flight.
-- ============================================================================
local S, Config = B.S, B.Config
local UIS = S.UserInputService
local Move = {}
B.Move = Move
local O
local saved = {}          -- original humanoid values, per character

local function parts()
  local character = B.character()
  local humanoid = character and character:FindFirstChildOfClass("Humanoid")
  local root = character and (character:FindFirstChild("HumanoidRootPart") or character.PrimaryPart)
  return character, humanoid, root
end
local function remember(humanoid)
  if saved.humanoid ~= humanoid then
    saved = { humanoid = humanoid, WalkSpeed = humanoid.WalkSpeed, JumpPower = humanoid.JumpPower, JumpHeight = humanoid.JumpHeight, UseJumpPower = humanoid.UseJumpPower }
  end
end

-- ---------------------------------------------------------------- noclip
local noclip = { character = nil, list = {}, changed = {}, added = nil }
local function noclipStep()
  local character = B.character()
  if not character then return end
  if noclip.character ~= character then
    if noclip.added then noclip.added:Disconnect() end
    noclip.character, noclip.list, noclip.changed = character, {}, {}
    for _, part in ipairs(character:GetDescendants()) do
      if part:IsA("BasePart") then table.insert(noclip.list, part) end
    end
    noclip.added = character.DescendantAdded:Connect(function(part)
      if part:IsA("BasePart") then table.insert(noclip.list, part) end
    end)
  end
  for _, part in ipairs(noclip.list) do
    if part.CanCollide then
      part.CanCollide = false
      noclip.changed[part] = true
    end
  end
end
local function stopNoclip()
  if noclip.added then noclip.added:Disconnect() end
  for part in pairs(noclip.changed) do
    -- only the parts that normally collide get it back
    local name = part.Name
    if part.Parent and (name == "HumanoidRootPart" or name == "Torso" or name == "UpperTorso" or name == "LowerTorso" or name == "Head") then part.CanCollide = true end
  end
  noclip = { character = nil, list = {}, changed = {}, added = nil }
end

-- ---------------------------------------------------------------- per-step work
local function physics(dt)
  local _, humanoid, root = parts()
  if not humanoid or not root then return end
  if O.speed or O.jump then remember(humanoid) end
  if O.speed then
    if O.speedMode == "cframe" then
      local direction = humanoid.MoveDirection
      local flight = B.Flight and B.Flight.state
      if direction.Magnitude > 0.05 and flight ~= "flying" and flight ~= "landing" then
        root.CFrame += direction * math.max(0, O.speedValue - humanoid.WalkSpeed) * dt
      end
    elseif humanoid.WalkSpeed ~= O.speedValue then
      humanoid.WalkSpeed = O.speedValue
    end
  end
  if O.jump then
    if not humanoid.UseJumpPower then humanoid.UseJumpPower = true end
    if humanoid.JumpPower ~= O.jumpValue then humanoid.JumpPower = O.jumpValue end
  end
end
local function restore(what)
  local humanoid = saved.humanoid
  if not humanoid or not humanoid.Parent then return end
  if what == "speed" then humanoid.WalkSpeed = saved.WalkSpeed end
  if what == "jump" then
    humanoid.UseJumpPower = saved.UseJumpPower
    humanoid.JumpPower, humanoid.JumpHeight = saved.JumpPower, saved.JumpHeight
  end
end

function Move.teleport(position)
  local _, _, root = parts()
  if not root then return false end
  root.CFrame = CFrame.new(position) * root.CFrame.Rotation
  root.AssemblyLinearVelocity = Vector3.zero
  return true
end

function Move.define()
  Config.define("move.speed", false)
  Config.define("move.speedValue", 32)
  Config.define("move.speedMode", "humanoid")
  Config.define("move.jump", false)
  Config.define("move.jumpValue", 80)
  Config.define("move.infJump", false)
  Config.define("move.noclip", false)
  Config.define("move.clickTp", false)
  Config.define("move.gravity", false)
  Config.define("move.gravityValue", 80)
end

function Move.start()
  if Move.started then return end
  Move.started = true
  Move.define()
  O = Config.mirror({ speed = "move.speed", speedValue = "move.speedValue", speedMode = "move.speedMode",
    jump = "move.jump", jumpValue = "move.jumpValue", infJump = "move.infJump", noclip = "move.noclip", clickTp = "move.clickTp",
    gravity = "move.gravity", gravityValue = "move.gravityValue" })
  Move.options = O
  B.connect(S.RunService.Heartbeat, physics, "move.physics")
  B.connect(S.RunService.Stepped, function() if O.noclip then noclipStep() end end, "move.noclip")
  Config.on("move.noclip", function(on) if not on then stopNoclip() end end)
  Config.on("move.speed", function(on) if not on then restore("speed") end end)
  Config.on("move.speedMode", function() restore("speed") end)
  Config.on("move.jump", function(on) if not on then restore("jump") end end)
  local baseGravity = workspace.Gravity
  local function gravity()
    workspace.Gravity = O.gravity and O.gravityValue or baseGravity
  end
  Config.on("move.gravity", gravity)
  Config.on("move.gravityValue", gravity)
  if O.gravity then gravity() end
  B.connect(UIS.JumpRequest, function()
    if not O.infJump then return end
    local _, humanoid = parts()
    if humanoid and humanoid.Health > 0 then humanoid:ChangeState(Enum.HumanoidStateType.Jumping) end
  end, "move.infjump")
  B.connect(UIS.InputBegan, function(input, processed)
    if not O.clickTp or processed or input.UserInputType ~= Enum.UserInputType.MouseButton1 then return end
    if not UIS:IsKeyDown(Enum.KeyCode.LeftControl) then return end
    local camera = workspace.CurrentCamera
    local mouse = UIS:GetMouseLocation()
    local ray = camera:ViewportPointToRay(mouse.X, mouse.Y)
    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude
    params.FilterDescendantsInstances = { B.LP.Character }
    -- as far as there is anything to click on: cast in lengths a ray can see along
    local hit = B.util.ray(ray.Origin, ray.Origin + ray.Direction * 100000, params)
    if hit then Move.teleport(hit.Position + Vector3.new(0, 3.2, 0)) end
  end, "move.clicktp")
  B.own(function()
    stopNoclip(); restore("speed"); restore("jump")
    workspace.Gravity = baseGravity
  end)
end
end
do -- 25_world.lua
-- ============================================================================
--  25 world    lighting, camera, crosshair, server tools
-- ============================================================================
local S, util, Motion, Theme, UI, Config, Window = B.S, B.util, B.Motion, B.Theme, B.UI, B.Config, B.Window
local Lighting = S.Lighting
local World = {}
B.World = World
local Server = {}
B.Server = Server
local O

-- ---------------------------------------------------------------- lighting
local LIGHT = { "Brightness", "ClockTime", "FogEnd", "FogStart", "GlobalShadows", "Ambient", "OutdoorAmbient", "ExposureCompensation" }
local original = nil
local atmospheres = {}
local function capture()
  if original then return end
  original = {}
  for _, key in ipairs(LIGHT) do original[key] = Lighting[key] end
end
local function applyLighting()
  local bright, noFog, time = O.fullbright, O.noFog, O.time
  if not (bright or noFog or time) then return end
  capture()
  if bright then
    if Lighting.Brightness ~= O.brightValue then Lighting.Brightness = O.brightValue end
    if Lighting.GlobalShadows then Lighting.GlobalShadows = false end
    local white = Color3.fromRGB(178, 178, 178)
    if Lighting.Ambient ~= white then Lighting.Ambient = white end
    if Lighting.OutdoorAmbient ~= white then Lighting.OutdoorAmbient = white end
    if Lighting.ExposureCompensation ~= 0 then Lighting.ExposureCompensation = 0 end
  end
  if time or bright then
    local clock = time and O.timeValue or 14
    if math.abs(Lighting.ClockTime - clock) > 0.02 then Lighting.ClockTime = clock end
  end
  if noFog or bright then
    if Lighting.FogEnd < 9e5 then Lighting.FogEnd = 1e6 end
    for _, child in ipairs(Lighting:GetChildren()) do
      if child:IsA("Atmosphere") then
        if atmospheres[child] == nil then atmospheres[child] = child.Density end
        if child.Density ~= 0 then child.Density = 0 end
      end
    end
  end
end
local function restoreLighting()
  if not original then return end
  if not O.fullbright then
    for _, key in ipairs({ "Brightness", "GlobalShadows", "Ambient", "OutdoorAmbient", "ExposureCompensation" }) do Lighting[key] = original[key] end
  end
  if not O.time and not O.fullbright then Lighting.ClockTime = original.ClockTime end
  if not O.noFog and not O.fullbright then
    Lighting.FogEnd, Lighting.FogStart = original.FogEnd, original.FogStart
    for atmosphere, density in pairs(atmospheres) do
      if atmosphere.Parent then atmosphere.Density = density end
    end
    table.clear(atmospheres)
  end
  if not (O.fullbright or O.noFog or O.time) then original = nil end
end

-- ---------------------------------------------------------------- crosshair
local cross
-- four arms and a dot, each with a dark keyline; returns the pieces for World.styleCrosshair
function World.makeCrosshair(parent, props)
  local root = UI.frame(parent, { Name = "Crosshair", AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromOffset(2, 2) })
  if props then
    for key, value in pairs(props) do root[key] = value end
  end
  local function keyline(target)
    local stroke = Instance.new("UIStroke")
    stroke.Color = Color3.new(0, 0, 0)
    stroke.Transparency = 0.4
    stroke.Thickness = 1
    stroke.Parent = target
    return stroke
  end
  local arms = {}
  for index = 1, 4 do
    local arm = Instance.new("Frame")
    arm.BorderSizePixel = 0
    arm.AnchorPoint = Vector2.new(0.5, 0.5)
    arm.Parent = root
    arms[index] = { frame = arm, stroke = keyline(arm) }
  end
  local dot = Instance.new("Frame")
  dot.BorderSizePixel = 0
  dot.AnchorPoint = Vector2.new(0.5, 0.5)
  dot.Position = UDim2.fromScale(0.5, 0.5)
  UI.corner(dot, true)
  dot.Parent = root
  return { root = root, arms = arms, dot = dot, dotStroke = keyline(dot) }
end
local function buildCrosshair()
  if cross then return end
  cross = World.makeCrosshair(B.screen(8600), { Visible = false })
end
-- draws the crosshair into `cross` from the current settings; also used by the tab's preview
function World.styleCrosshair(target, o)
  local length, gap, thick = o.crossLength, o.crossGap, o.crossThickness
  local clear = 1 - o.crossOpacity / 100
  local offsets = { { 0, -(gap + length * 0.5) }, { 0, gap + length * 0.5 }, { -(gap + length * 0.5), 0 }, { gap + length * 0.5, 0 } }
  target.root.Rotation = o.crossRotation
  for index, arm in ipairs(target.arms) do
    local vertical = index <= 2
    arm.frame.Size = UDim2.fromOffset(vertical and thick or length, vertical and length or thick)
    arm.frame.Position = UDim2.new(0.5, offsets[index][1], 0.5, offsets[index][2])
    arm.frame.BackgroundColor3 = o.crossColor
    arm.frame.BackgroundTransparency = clear
    -- the first arm is the one above the centre: a T has none
    arm.frame.Visible = length > 0 and not (index == 1 and o.crossT)
    arm.stroke.Enabled = o.crossOutline
    arm.stroke.Transparency = 0.4 + 0.6 * clear
  end
  target.dot.Visible = o.crossDot
  target.dot.Size = UDim2.fromOffset(thick + 2, thick + 2)
  target.dot.BackgroundColor3 = o.crossColor
  target.dot.BackgroundTransparency = clear
  target.dotStroke.Enabled = o.crossOutline
  target.dotStroke.Transparency = 0.4 + 0.6 * clear
end
local function refreshCrosshair()
  if O.crosshair then
    buildCrosshair()
    World.styleCrosshair(cross, O)
    cross.root.Visible = true
  elseif cross then
    cross.root.Visible = false
  end
end

-- ---------------------------------------------------------------- server
function Server.rejoin()
  Window.toast({ title = "Rejoining", text = "Back in a moment.", icon = "refresh-cw" })
  task.delay(0.4, function()
    local ok, err = pcall(function()
      if #S.Players:GetPlayers() <= 1 then S.TeleportService:Teleport(game.PlaceId, B.LP)
      else S.TeleportService:TeleportToPlaceInstance(game.PlaceId, game.JobId, B.LP) end
    end)
    if not ok then Window.toast({ title = "Could not rejoin", text = tostring(err), icon = "triangle-alert", tone = "bad" }) end
  end)
end
function Server.hop()
  Window.toast({ title = "Looking for a server", icon = "shuffle" })
  task.spawn(B.safe("server.hop", function()
    local url = "https://games.roblox.com/v1/games/" .. game.PlaceId .. "/servers/Public?sortOrder=Desc&excludeFullGames=true&limit=100"
    local ok, body = pcall(function() return game:HttpGet(url) end)
    local data = ok and select(2, pcall(function() return S.HttpService:JSONDecode(body) end))
    local choices = {}
    if type(data) == "table" and type(data.data) == "table" then
      for _, server in ipairs(data.data) do
        if type(server) == "table" and server.id ~= game.JobId and (server.playing or 0) < (server.maxPlayers or 0) then choices[#choices + 1] = server end
      end
    end
    if #choices == 0 then
      Window.toast({ title = "No other server found", text = "This may be the only one open.", icon = "triangle-alert", tone = "warn" })
      return
    end
    -- any of them, or the one with the fewest people in it, or the most that still has room
    local mode = Config.get("world.hopMode")
    local pick = choices[math.random(1, #choices)]
    if mode == "empty" or mode == "full" then
      table.sort(choices, function(a, b)
        if mode == "empty" then return (a.playing or 0) < (b.playing or 0) end
        return (a.playing or 0) > (b.playing or 0)
      end)
      pick = choices[1]
    end
    Server.picked = pick
    S.TeleportService:TeleportToPlaceInstance(game.PlaceId, pick.id, B.LP)
  end))
end
function Server.copyJoin()
  local line = string.format('game:GetService("TeleportService"):TeleportToPlaceInstance(%d, "%s", game.Players.LocalPlayer)', game.PlaceId, game.JobId)
  local ok = B.clipboard(line)
  Window.toast(ok and { title = "Join script copied", text = "Run it to land in this exact server.", icon = "clipboard", tone = "ok" }
    or { title = "No clipboard access", icon = "triangle-alert", tone = "warn" })
end

World.CROSS = { "world.crossLength", "world.crossGap", "world.crossThickness", "world.crossColor", "world.crossDot", "world.crossOutline", "world.crossOpacity",
  "world.crossRotation", "world.crossT" }
function World.define()
  Config.define("world.fullbright", false)
  Config.define("world.brightValue", 2)
  Config.define("world.crossOpacity", 100)
  Config.define("world.crossRotation", 0)
  Config.define("world.crossT", false)
  Config.define("world.hopMode", "random")
  Config.define("world.noFog", false)
  Config.define("world.time", false)
  Config.define("world.timeValue", 14)
  Config.define("world.fov", false)
  Config.define("world.fovValue", 90)
  Config.define("world.zoom", false)
  Config.define("world.zoomValue", 400)
  Config.define("world.crosshair", false)
  Config.define("world.crossLength", 7)
  Config.define("world.crossGap", 4)
  Config.define("world.crossThickness", 2)
  Config.define("world.crossColor", Color3.new(1, 1, 1))
  Config.define("world.crossDot", true)
  Config.define("world.crossOutline", true)
  Config.define("world.antiAfk", true)
  Config.define("world.fpsCap", 0)
  Config.define("world.autoExec", false)
end

World.AFK_QUIET = 600       -- s with no input and no answer before one is given unasked: half of what the engine allows

function World.start()
  if World.started then return end
  World.started = true
  World.define()
  O = Config.mirror({ fullbright = "world.fullbright", noFog = "world.noFog", time = "world.time", timeValue = "world.timeValue", fov = "world.fov",
    fovValue = "world.fovValue", zoom = "world.zoom", zoomValue = "world.zoomValue", crosshair = "world.crosshair", crossLength = "world.crossLength",
    crossGap = "world.crossGap", crossThickness = "world.crossThickness", crossColor = "world.crossColor", crossDot = "world.crossDot",
    crossOutline = "world.crossOutline", crossOpacity = "world.crossOpacity", crossRotation = "world.crossRotation", crossT = "world.crossT",
    brightValue = "world.brightValue", antiAfk = "world.antiAfk", fpsCap = "world.fpsCap" })
  World.options = O
  -- games rewrite lighting on their own clock: hold ours at a low rate rather than every frame
  Motion.every(applyLighting, 4, "world.lighting")
  for _, id in ipairs({ "world.fullbright", "world.noFog", "world.time" }) do
    Config.on(id, function(on) if on then applyLighting() else restoreLighting() end end)
  end
  Config.on("world.timeValue", applyLighting)
  Config.on("world.brightValue", applyLighting)

  local baseFov
  Motion.every(function()
    local camera = workspace.CurrentCamera
    if not camera then return end
    if O.fov then
      if not baseFov then baseFov = camera.FieldOfView end
      if math.abs(camera.FieldOfView - O.fovValue) > 0.05 then camera.FieldOfView = O.fovValue end
    elseif baseFov then
      camera.FieldOfView = baseFov
      baseFov = nil
    end
  end, nil, "world.fov")
  local baseZoom
  local function zoom()
    if O.zoom then
      baseZoom = baseZoom or B.LP.CameraMaxZoomDistance
      B.LP.CameraMaxZoomDistance = O.zoomValue
    elseif baseZoom then
      B.LP.CameraMaxZoomDistance = baseZoom
      baseZoom = nil
    end
  end
  Config.on("world.zoom", zoom)
  Config.on("world.zoomValue", zoom)
  zoom()

  Config.on("world.crosshair", refreshCrosshair)
  for _, id in ipairs(World.CROSS) do
    Config.on(id, refreshCrosshair)
  end
  refreshCrosshair()

  -- Anti-AFK. The idle kick is the engine's: twenty minutes with no input and the client is
  -- dropped. The engine says when it has begun counting (Idled: two minutes in, and again after),
  -- and each time is answered the way a player touching the mouse would. Should it never say so,
  -- the same answer is given on a clock of our own: once AFK_QUIET has gone with no input and no
  -- answer, and then that often. What it has done is kept, to be shown.
  local afk = { answered = 0, last = nil, input = os.clock(), failed = 0 }
  World.afk = afk
  local function answer()
    local ok = pcall(function()
      local virtual = S.VirtualUser
      virtual:CaptureController()
      virtual:ClickButton2(Vector2.new())
    end)
    if ok then
      afk.answered += 1
      afk.last = os.clock()
    else
      afk.failed += 1
    end
    return ok
  end
  B.connect(B.LP.Idled, function()
    if O.antiAfk then answer() end
  end, "world.afk")
  B.connect(S.UserInputService.InputBegan, function() afk.input = os.clock() end, "world.afk.input")
  Motion.every(function()
    if not O.antiAfk then return end
    local now = os.clock()
    if now - math.max(afk.input, afk.last or 0, afk.tried or 0) >= World.AFK_QUIET then
      afk.tried = now
      answer()
    end
  end, 0.2, "world.afk.clock")

  local function cap()
    if type(setfpscap) ~= "function" then return end
    pcall(setfpscap, O.fpsCap > 0 and O.fpsCap or 9999)
  end
  Config.on("world.fpsCap", cap)
  if O.fpsCap > 0 then cap() end

  -- carry the hub across a teleport, once per session
  local function queue()
    if World.queued or not Config.get("world.autoExec") or type(queue_on_teleport) ~= "function" then return end
    World.queued = true
    pcall(queue_on_teleport, 'pcall(function() loadstring(readfile("BasedHub.lua"))() end)')
  end
  Config.on("world.autoExec", queue)
  queue()

  B.own(function()
    O.fullbright, O.noFog, O.time = false, false, false
    restoreLighting()
    if baseFov and workspace.CurrentCamera then workspace.CurrentCamera.FieldOfView = baseFov end
    if baseZoom then B.LP.CameraMaxZoomDistance = baseZoom end
  end)
end
end
do -- 26_flight.lua
-- ============================================================================
--  26 flight   animated flight: charge, launch, cruise, sonic boom, timed landing
--
--  Physics is the Zod project's proven arrangement: a LinearVelocity and an
--  AlignOrientation on our own root (which we own, so it replicates) with the
--  humanoid parked in a state that applies no forces of its own. The effects
--  and sounds are Zod's too (zod/src/fx.lua and its captured particle pack).
--
--  The animations are the eleven supplied clips. They are marketplace pack
--  animations, so they load in any game and replicate to everyone; they are
--  R15 only. Each was sampled on a live rig on 2026-10-07 and the numbers
--  below come from that, not from watching them:
--
--    clip        length  torso pitch         what it is
--    idle         6.33 s   +11..+17 deg      float, bobbing half a stud
--    idle2        3.48 s    +4..+7, yaw -41  side-on float
--    slow         1.08 s   -31..-35          forward-leaning glide
--    aggressive   1.85 s     0..-9           upright, arms driving
--    up           2.75 s    -4..+6           upright climb
--    upFast       0.50 s    -5..-7           rigid rocket pose
--    aimDown      1.67 s   -24               leaning in, looking down
--    sonic        0.50 s   -83               flat, head first
--    down         0.60 s   -122              head-first dive
--    charge       4.83 s   see CHARGE        crouch with a hand on the ground
--    land         2.87 s   see LAND          descend, crouch, stand, float again
--
--  The pitch already inside a clip decides how much the ROOT is tilted on top
--  of it (POSE): the flat sonic pose follows the flight path fully, the upright
--  climb not at all. Every clip is published as a loop, including the landing,
--  so the landing is played once by hand and its feet are timed to the ground.
-- ============================================================================
local S, util, Config, Assets, fs = B.S, B.util, B.Config, B.Assets, B.fs
local ease = B.Motion.ease
local UIS = S.UserInputService
local STATE = Enum.HumanoidStateType
local UP = Vector3.yAxis
local Flight = { state = "off", speed = 0, ramp = 0, charge = 0, booms = 0, landings = 0, launches = 0, boomLog = {} }
B.Flight = Flight
-- How the body is carried. "constraints": a LinearVelocity and an AlignOrientation on the root,
-- the humanoid parked in a state of its own (the Zod arrangement, everywhere by default).
-- "frame": nothing is added to the body and its state is left to the humanoid; the flight puts
-- the root where it should be every frame, along a path that is looked along first (nothing that
-- is put somewhere collides on its way), with its velocity held at zero. The same way the Da Hood
-- ragebot carries the body, which is what that game's module asks for (games/dahood.lua).
Flight.body = "constraints"
local function byFrame() return Flight.body == "frame" end
-- The switch that flies. A game module can give flight a switch of its own (Da Hood: "dahood.fly",
-- off until it is put on there), so a universal flight left on elsewhere does not arm itself in it.
Flight.flag = "move.fly"
local faked = false          -- lv and ao are the frame mode's stand-ins, not instances
local O

local ANIMS = { idle = 108435473734278, idle2 = 91122978632763, idle3 = 94269438718677, idle4 = 76290458763814, slow = 76516494715741,
  aggressive = 114663559035455, up = 115265121798442, upFast = 116738664195186, aimDown = 83572938141768, sonic = 132624199623293,
  down = 120193221019191, hoverDown = 102323315718330, land = 107349693471273, charge = 89111716130280 }
Flight.ANIMS = ANIMS
-- Three clips came later and were sampled the same way (2026-10-08):
--   idle3      3.48 s  the side-on float of idle2 with the arms folded, hips 0.85 above standing
--   idle4      7.10 s  arms folded, the torso turning between 11 and 53 degrees to look about
--   hoverDown  1.00 s  upright, arms held out wide, barely moving: the easy way down
-- Hovering wears whichever of the four idles the player picks. The descend key alone, at an easy
-- pace, wears hoverDown; the head-first `down` is kept for a real dive.
local IDLES = { a = "idle", b = "idle2", c = "idle3", d = "idle4" }
local IDLE_ORDER = { "a", "b", "c", "d" }
-- follow: share of the flight path's elevation the root takes on.  lean: pitch added at speed
-- (radians, negative is forward).  rocket: stands the body's own axis along a climbing path.
-- dive: the same for a dive steeper than the clip's own.  bank: share of the turn lean rolled.
local POSE = {
  idle = { follow = 0, lean = 0, bank = 0.3 }, idle2 = { follow = 0, lean = 0, bank = 0.3 },
  idle3 = { follow = 0, lean = 0, bank = 0.3 }, idle4 = { follow = 0, lean = 0, bank = 0.3 },
  hoverDown = { follow = 0, lean = 0, bank = 0.2 },
  slow = { follow = 0.35, lean = 0, bank = 0.5 }, aggressive = { follow = 0.6, lean = -0.45, bank = 0.7 },
  aimDown = { follow = 0.5, lean = 0, bank = 0.5 }, sonic = { follow = 1, lean = 0, bank = 1 },
  up = { follow = 0, lean = 0, bank = 0.3, rocket = 0.5 }, upFast = { follow = 0, lean = 0, bank = 0.3, rocket = 1 },
  -- measured live in a straight dive at 900 st/s: at 0.5 the hips-to-head line sat 54 degrees off
  -- the path (the clip arches the head back up), so the dive takes the whole difference
  down = { follow = 0, lean = 0, bank = 0.4, dive = 1 },
}
-- The land clip, in seconds (root space, standing feet at -2.99):
--   0.00  leaning back with the feet 0.38 above the ground: the last of the descent
--   0.47  the feet reach the ground          0.68  a hand comes down beside them
--   0.78  the crouch is at its deepest       1.63  starts to stand
--   2.07  upright, feet still down           2.20  lifts off into a float again (it is a loop)
-- So it starts `lead` seconds before the ground and plays at contact/lead until the feet are
-- down, is held there until `hold`, and is faded out across the moment it stands upright.
local LAND = { lead = 0.6, contact = 0.46, hold = 1.0, out = 1.95, fade = 0.2 }
Flight.LAND = LAND
-- The charge clip stands at 0, is crouched by 0.33 s and then only breathes, with the torso at
-- its lowest at 2.25 s and 4.25 s. Turning playback around at those two still points holds the
-- crouch for as long as Space is held, and playback speed replicates where TimePosition does not.
local CHARGE = { low = 2.25, high = 4.25 }
local CLIMB_BOOST = 1.0      -- seconds of Space on a straight climb before it starts to accelerate
-- At the top of the speed range one frame is tens of studs (20,000 st/s at 240 fps is 83), and a
-- slow frame is hundreds. Two rules keep the ground solid anyway:
local HITCH = 0.05           -- speed into the ground is held to what a frame this long could cover
local PIN_SPEED = 1500       -- a landing faster than this is held on its path frame by frame
local DWELL = 0.25           -- a clip that has only just started is not swapped for its neighbour
local HOVER_DOWN_MAX = 500   -- the easy descent is only easy up to here: faster is a dive, whatever cruise is set to
local BOOM_GAP = 0.6         -- seconds between booms when a hard acceleration runs through several tiers
local SHADE = Color3.fromRGB(22, 36, 66)      -- the dark every pale image on the screen is backed with, so it shows on a bright sky
local VAPOUR = Color3.fromRGB(74, 96, 132)    -- the same idea for rings in the air: the blue-grey of vapour in shadow, not smoke
local PACK = { "SBoost", "KBoost", "STakeoff", "KTakeoff", "KSonic", "KHaze", "KCrater", "SSlam", "SImpact", "SWindTrail" }

local char, hum, root, animator
local tracks, current, currentSince = {}, nil, 0
local lv, ao, attachment
local vel, facing, lean = Vector3.zero, Vector3.new(0, 0, -1), 0
local savedAutoRotate, jumpWasEnabled
local chargeStart, chargeFx = 0, false
local spaceSince, launchUntil, launchVel = nil, 0, Vector3.zero
local stage, boomed, lastSonic, lastImpact, impact, floor = 0, 0, 0, 0, 0, nil
local airborneSince, landing, hinted, warmed = nil, nil, false, false
local idleChoice, idleIndex = { "idle" }, 1
local chargeHold
local rayParams, ignore, ignoreAt = nil, {}, -1
local tweens = {}

-- ---------------------------------------------------------------- helpers
local function alpha(rate, dt) return 1 - math.exp(-rate * dt) end
local function flat(v)
  local f = Vector3.new(v.X, 0, v.Z)
  return f.Magnitude > 1e-3 and f.Unit or nil
end
-- signed angle in degrees from one flat direction to another: a turn to the right is negative
local function signedYaw(from, to)
  local d = math.deg(math.atan2(to.X, to.Z) - math.atan2(from.X, from.Z))
  return (d + 180) % 360 - 180
end
local function alive() return hum ~= nil and root ~= nil and hum.Health > 0 and root.Parent ~= nil end
local function down(keyName) return UIS:GetFocusedTextBox() == nil and Config.keyDown(keyName) end
local function onGround()
  local state = hum:GetState()
  return hum.FloorMaterial ~= Enum.Material.Air and state ~= STATE.Freefall and state ~= STATE.Jumping and state ~= STATE.Physics
end
-- how far below the root's centre the soles are: R15 carries its leg length in HipHeight, R6 has
-- a HipHeight of 0 and two-stud legs
local function feetBelowRoot()
  local legs = 0
  if hum.RigType == Enum.HumanoidRigType.R6 then
    local leg = char:FindFirstChild("Left Leg")
    legs = leg and leg.Size.Y or 2
  end
  return hum.HipHeight + root.Size.Y * 0.5 + legs
end
local function volume() return (O.sound and O.volume or 0) / 100 end
-- effects run on the real clock: the hub's own motion speed setting must not slow a shockwave
local function animate(seconds, curve, apply)
  tweens[#tweens + 1] = { t = 0, length = math.max(seconds, 1e-3), curve = curve, apply = apply }
  apply(curve(0))
end
local function stepTweens(dt)
  for index = #tweens, 1, -1 do
    local tween = tweens[index]
    tween.t += dt
    local p = math.min(tween.t / tween.length, 1)
    local ok = pcall(tween.apply, tween.curve(p))
    if p >= 1 or not ok then table.remove(tweens, index) end
  end
end
local function later(seconds, instance)
  task.delay(seconds, function() if instance.Parent then instance:Destroy() end end)
end

-- ---------------------------------------------------------------- effects (ported from zod/src/fx.lua)
local Fx = { shake = 0, shakeTime = 0, fovKick = 0, roll = 0, offset = CFrame.identity, baseFov = nil, windAcc = 0, trails = false, rings = {}, speed = 0,
  dress = 0, mach = 0, pulseAcc = 0, lineAlpha = 0, tunnelAlpha = 0, lineClock = 0, punch = 0, ripples = 0, previewUntil = 0, previewTier = 0 }
Flight.Fx = Fx
local pack, templates, folder, soundHost = nil, {}, nil, nil
local function fxFolder()
  if folder and folder.Parent then return folder end
  folder = Instance.new("Folder")
  folder.Name = util.randomName()
  folder.Parent = workspace
  B.own(folder)
  return folder
end
local function loadPack()
  if pack ~= nil then return pack end
  pack = false
  local file = Assets.manifest.fx and Assets.manifest.fx.flight
  local source = file and fs.read(fs.path(file))
  local chunk = source and loadstring(source, "=flight-pack")
  if chunk then
    local ok, result = pcall(chunk)
    if ok and type(result) == "table" then pack = result end
  end
  return pack
end
-- Potassium may write MeshPart.MeshId directly (measured); an executor that may not gets the
-- mesh the supported way, in the background, and the template simply has it from then on.
local function ensureMesh(part, id)
  if part.MeshId ~= "" then return end
  task.spawn(function()
    local ok, made = pcall(function() return S.AssetService:CreateMeshPartAsync(Content.fromUri(id)) end)
    if not ok then ok, made = pcall(function() return S.AssetService:CreateMeshPartAsync(id) end) end
    if ok and made then
      pcall(function() part:ApplyMesh(made) end)
      made:Destroy()
    end
  end)
end
-- node = { class, parentIndex, properties, attributes, references }
local function buildTemplate(nodes)
  local made = table.create(#nodes)
  for index, node in ipairs(nodes) do
    local instance = Instance.new(node[1])
    for name, value in pairs(node[3]) do pcall(function() instance[name] = value end) end
    if node[4] then
      for name, value in pairs(node[4]) do instance:SetAttribute(name, value) end
    end
    if node[1] == "MeshPart" and node[3].MeshId then ensureMesh(instance, node[3].MeshId) end
    made[index] = instance
  end
  local top
  for index, node in ipairs(nodes) do
    if node[5] then
      for property, target in pairs(node[5]) do pcall(function() made[index][property] = made[target] end) end
    end
    if node[2] == 0 then top = top or made[index] else made[index].Parent = made[node[2]] end
  end
  -- The captured pressure-wave mesh carries a red, always-on-top Highlight: on screen that is a
  -- red flash across the whole body at every boom. Nothing here wants a Highlight.
  for _, instance in ipairs(made) do
    if instance:IsA("Highlight") then instance:Destroy() end
  end
  return top
end
local function template(name)
  local cached = templates[name]
  if cached == nil then
    local data = loadPack()
    cached = data and data[name] and buildTemplate(data[name]) or false
    templates[name] = cached
  end
  return cached or nil
end
local function clone(name)
  local source = template(name)
  return source and source:Clone() or nil
end
Flight.template = template
-- Mach 1 is the sonic speed, and a tier is one doubling of it: tier 1 from Mach 1, tier 2 from
-- Mach 2, tier 3 from Mach 4, and so on. Tier 1 is the boom as it has always been. From tier 2
-- up, every tier makes the boom, and what follows the body afterwards, bigger.
local function tierOf(speed)
  local mach = speed / math.max(O.sonic, 1)
  if mach < 1 then return 0, mach end
  return math.floor(math.log(mach, 2) + 1e-6) + 1, mach
end
Flight.tierOf = tierOf
-- a child of a pack template, by path
local function piece(key, ...)
  local node = template(key)
  for _, name in ipairs({ ... }) do
    node = node and node:FindFirstChild(name)
  end
  return node
end
-- An emitter grown by `scale` and made more solid by `gain` (1 leaves it be). Each is built once
-- and handed out as copies: the tiers only ever ask for a handful of sizes.
local variants = {}
local function variant(name, emitter, scale, gain)
  local made = variants[name]
  if not made then
    made = emitter:Clone()
    local sizes = {}
    for index, point in ipairs(emitter.Size.Keypoints) do
      sizes[index] = NumberSequenceKeypoint.new(point.Time, point.Value * scale, point.Envelope * scale)
    end
    made.Size = NumberSequence.new(sizes)
    if gain ~= 1 then
      local alphas = {}
      for index, point in ipairs(emitter.Transparency.Keypoints) do
        alphas[index] = NumberSequenceKeypoint.new(point.Time, math.clamp(1 - (1 - point.Value) * gain, 0, 1))
      end
      made.Transparency = NumberSequence.new(alphas)
    end
    variants[name] = made
  end
  return made:Clone()
end
-- The pack's shock rings are additive, and measured, their textures have no alpha at all (a pale
-- ring on a black square): they light up a dark sky and cannot be seen against a bright one. So
-- each gets two twins that can: the pack's vapour ring, which does have alpha, moving exactly as
-- the shock ring does, drawn once dark a little outside it and once pale a little inside.
local function twin(name, like, scale, dark)
  local key = (dark and "shade:" or "mist:") .. name
  local made = variants[key]
  if not made then
    local ring = piece("SBoost", "Attachment", "Ring")
    if not ring then return nil end
    made = like:Clone()
    local sizes = {}
    for index, point in ipairs(like.Size.Keypoints) do
      sizes[index] = NumberSequenceKeypoint.new(point.Time, point.Value * scale, point.Envelope * scale)
    end
    made.Size = NumberSequence.new(sizes)
    made.Texture = ring.Texture
    made.LightEmission, made.LightInfluence, made.Brightness = 0, 0, 1
    made.Color = ColorSequence.new(dark and VAPOUR or Color3.new(1, 1, 1))
    made.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.18, 0.62),
      NumberSequenceKeypoint.new(0.6, 0.78), NumberSequenceKeypoint.new(1, 1) })
    made.ZOffset = dark and -0.6 or -0.3
    variants[key] = made
  end
  return made:Clone()
end
-- fire every emitter the way the source games do: after EmitDelay, for EmitDuration or EmitCount
local function emit(top, scale)
  scale = scale or 1
  for _, item in ipairs(top:IsA("ParticleEmitter") and { top } or top:GetDescendants()) do
    if item:IsA("ParticleEmitter") then
      local delay, duration = item:GetAttribute("EmitDelay") or 0, item:GetAttribute("EmitDuration") or 0
      local count = item:GetAttribute("EmitCount") or item.Rate
      local function go()
        if not item.Parent then return end
        if duration > 0 then
          item.Enabled = true
          task.delay(duration, function() if item.Parent then item.Enabled = false end end)
        else
          item:Emit(math.max(1, math.floor(count * scale + 0.5)))
        end
      end
      if delay > 0.01 then task.delay(delay, go) else go() end
    end
  end
end
local function place(model, cf)
  if model:IsA("BasePart") then
    model.CFrame = cf
    model.Anchored, model.CanCollide, model.CanQuery, model.CanTouch = true, false, false, false
  end
  model.Parent = fxFolder()
end
local function tweenSize(part, to, seconds, curve)
  local from = part.Size
  animate(seconds, curve or ease.outCubic, function(p) part.Size = from:Lerp(to, p) end)
end

-- the first four are the Zod project's own files; the ids are the ones it measured loading anywhere
local SOUNDS = {
  boom = { file = "fly_boom", fallback = 558073810 }, takeoff = { file = "fly_takeoff", fallback = 138149044086182 },
  slam = { file = "fly_land", fallback = 107674019694824 }, wind = { file = "fly_wind", fallback = 5813077875 },
  crack = { id = 92631715509459 }, thump = { id = 558073810 }, step = { id = 18782450650 },
}
local function soundId(name)
  local spec = SOUNDS[name]
  if spec.id then return "rbxassetid://" .. spec.id end
  return Assets.sound(spec.file) or ("rbxassetid://" .. spec.fallback)
end
local function sounds()
  if soundHost and soundHost.Parent then return soundHost end
  soundHost = Instance.new("Folder")
  soundHost.Name = util.randomName()
  soundHost.Parent = S.SoundService
  B.own(soundHost)
  return soundHost
end
local function play(name, scale, pitch)
  local level = volume() * (scale or 1)
  if level <= 0 then return nil end
  local sound = Instance.new("Sound")
  sound.SoundId = soundId(name)
  sound.Volume = math.min(level, 10)
  sound.PlaybackSpeed = pitch or 1
  sound.Parent = sounds()
  sound:Play()
  later(10, sound)
  Fx.lastSound = name
  return sound
end

function Fx.kick(shake, fov)
  if O.fxShake then Fx.shake = math.max(Fx.shake, shake) end
  if O.fxFov then Fx.fovKick = math.max(Fx.fovKick, fov) end
end
function Fx.takeoff(groundAt, strength)
  strength = math.clamp(strength, 0.3, 1.6)
  if O.fxTakeoff then
    for _, name in ipairs({ "KTakeoff", "STakeoff" }) do
      local burst = clone(name)
      if burst then
        place(burst, CFrame.new(groundAt))
        emit(burst, strength)
        later(6, burst)
      end
    end
  end
  play("takeoff", 1.1, 0.95 + 0.1 * strength)
  Fx.kick(0.35 * strength, 6 * strength)
end

-- Rings and bursts ride ahead of the body, square to the direction of travel. Zod could weld them
-- above the head because it laid the whole root flat; here the clip supplies the pose and the root
-- stays nearer upright, so they are re-aimed along the real path every frame instead.
local function heading()
  if Fx.previewUntil > os.clock() and Fx.previewDir then return Fx.previewDir end
  if Flight.state == "flying" and vel.Magnitude > 8 then return vel.Unit end
  return UP
end
local function frameAlong(direction, distance)
  local at = root.Position + direction * distance
  return CFrame.lookAt(at, at + direction, math.abs(direction.Y) < 0.95 and UP or Vector3.xAxis)
end
local function ride(distance)
  local att = Instance.new("Attachment")
  att.Parent = root
  att.WorldCFrame = frameAlong(heading(), distance)
  Fx.rings[att] = distance
  return att
end
function Fx.aim()
  local direction = heading()
  for att, distance in pairs(Fx.rings) do
    if att.Parent then att.WorldCFrame = frameAlong(direction, distance) else Fx.rings[att] = nil end
  end
end
local function ringAttachment(names, enabled, distance)
  local source = template("SBoost")
  local holder = source and source:FindFirstChild("Attachment")
  if not holder or not root then return nil end
  local att = ride(distance)
  for _, name in ipairs(names) do
    local emitter = holder:FindFirstChild(name)
    if emitter then
      local copy = emitter:Clone()
      copy.Enabled = enabled
      copy.Parent = att
    end
  end
  return att
end
local function retire(att, seconds)
  for _, item in ipairs(att:GetChildren()) do
    if item:IsA("ParticleEmitter") then item.Enabled = false end
  end
  later(seconds, att)
end
function Fx.startCharge()
  if Fx.chargeAtt or not O.fxBoost then return end
  Fx.chargeAtt = ringAttachment({ "Ring", "Ring1" }, true, 3.2)
end
function Fx.stopCharge()
  local att = Fx.chargeAtt
  Fx.chargeAtt = nil
  if att then retire(att, 1) end
end
function Fx.boostRing(on)
  if on then
    if not Fx.boostAtt and O.fxBoost then Fx.boostAtt = ringAttachment({ "Ring2" }, true, 3.5) end
  elseif Fx.boostAtt then
    retire(Fx.boostAtt, 2)
    Fx.boostAtt = nil
  end
end
-- a glass shell welded to the root that swells and collapses: the pressure wave
function Fx.haze()
  local mesh = O.fxHaze and root and clone("KHaze")
  if not mesh then return end
  mesh.Anchored, mesh.CanCollide, mesh.CanQuery, mesh.CanTouch, mesh.Massless = false, false, false, false, true
  mesh.Material = Enum.Material.Glass
  mesh.Transparency = 6          -- the source game passes 6 on purpose: refraction with no fill
  mesh.Size = Vector3.new(0.2, 0.2, 0.2)
  mesh.CFrame = root.CFrame
  local weld = Instance.new("Weld")
  weld.Part0, weld.Part1 = root, mesh
  weld.Parent = mesh
  mesh.Parent = fxFolder()
  tweenSize(mesh, Vector3.new(20, 20, 20), 0.12, ease.outSine)
  task.delay(0.12, function() if mesh.Parent then tweenSize(mesh, Vector3.zero, 0.36, ease.inCubic) end end)
  later(0.6, mesh)
end
function Fx.boostStage(level)
  if not root then return end
  if O.fxBoost then
    local source = template("KBoost")
    local part = source and source:FindFirstChild("Boost" .. level)
    local holder = part and part:FindFirstChild("Attachment")
    if holder then
      local att = ride(3)
      -- an emitter's Acceleration is in world space: as captured, these gusts all blew toward
      -- +Z whichever way the flight was going. They are turned to blow back along the path.
      local back = -heading()
      for _, item in ipairs(holder:GetChildren()) do
        if item:IsA("ParticleEmitter") then
          local copy = item:Clone()
          local push = copy.Acceleration.Magnitude
          if push > 0 then copy.Acceleration = back * push end
          copy.Parent = att
        end
      end
      emit(att)
      later(3, att)
    end
    Fx.boostRing(true)
  end
  if level >= 3 then Fx.haze() end
  play("takeoff", 0.55, 1.1 + level * 0.12)
  Fx.kick(0.25 + level * 0.12, 3 + level * 2.5)
end
function Fx.sonicBoom(velocity, tier)
  if not root then return end
  local direction = velocity.Magnitude > 1 and velocity.Unit or root.CFrame.LookVector
  local over = math.clamp((tier or 1) - 1, 0, 6)      -- how far past the plain boom this one is
  if O.fxSonic then
    local att = ringAttachment({ "BigRing" }, false, 3.5)
    if att then
      local big = att:FindFirstChild("BigRing")
      if big then big:Emit(big:GetAttribute("EmitCount") or 3) end
      local source = template("SBoost")
      local vapor = source and source.Attachment:FindFirstChild("VaporCone")
      if vapor then
        local cone = Instance.new("Attachment")
        cone.CFrame = CFrame.new(0, 0, 2.5)
        cone.Parent = att
        local copy = vapor:Clone()
        copy.Enabled = true
        copy.Parent = cone
        task.delay(1, function() if copy.Parent then copy.Enabled = false end end)
      end
      later(4, att)
    end
    -- the ring left hanging in the air where the barrier broke
    local ring = clone("KSonic")
    if ring then
      place(ring, CFrame.lookAt(root.Position, root.Position + direction, math.abs(direction.Y) < 0.95 and UP or Vector3.xAxis) * CFrame.Angles(math.pi / 2, 0, 0))
      emit(ring)
      later(4, ring)
    end
    if over > 0 then
      -- Past Mach 2, anything left hanging in the air is behind the camera within a frame. So
      -- what grows with the speed is what travels WITH the body: shock rings that open around
      -- it one after another, each wider than the last, and a gust of wind thrown back off it.
      local rings = ride(2.5)
      local big = 1 + 0.55 * over
      for index = 1, math.min(1 + over, 5) do
        task.delay((index - 1) * 0.07, function()
          if not rings.Parent then return end
          local grown = big * (0.7 + 0.3 * index)
          for _, name in ipairs({ "Shockwave1", "Shockwave2" }) do
            local from = piece("KBoost", "Boost3", "Attachment", name)
            if from then
              local wave = variant(name .. ":" .. over .. ":" .. index, from, grown, 1)
              wave.Name = "MachRing"
              wave.Parent = rings
              wave:Emit(1)
            end
          end
          local like = piece("KBoost", "Boost3", "Attachment", "Shockwave2")
          for _, dark in ipairs({ true, false }) do
            local ring = like and twin("ring:" .. over .. ":" .. index, like, grown * (dark and 1.04 or 0.93), dark)
            if ring then
              ring.Name = dark and "MachRingShade" or "MachRingMist"
              ring.Parent = rings
              ring:Emit(1)
            end
          end
        end)
      end
      local wind = piece("KBoost", "Boost3", "Attachment", "Wind3")
      if wind then
        -- Seen live at Mach 16: seventy-odd of these at 1.6 times their opacity were a white
        -- cloud with a silhouette in it. A dozen or two, as drawn, read as wind.
        local gust = variant("gust:" .. over, wind, 1 + 0.15 * over, 1)
        gust.Name = "MachGust"
        gust.Acceleration = -direction * wind.Acceleration.Magnitude
        gust.Parent = rings
        gust:Emit(10 + 6 * over)
      end
      later(2.5, rings)
    end
  end
  Fx.haze()
  -- louder and lower the higher the tier; from Mach 2 the boom comes as the pair of bangs a real
  -- one is, and from Mach 8 there is a roll of thunder under it
  local pitch = math.max(1 - 0.06 * over, 0.64)
  play("boom", math.min(1.5 + 0.2 * over, 2.8), pitch)
  play("crack", 0.55, pitch)
  if over >= 1 then
    task.delay(0.11, function() play("boom", 1.1 + 0.15 * over, pitch * 0.82) end)
    Fx.punch = 1
  end
  if over >= 1 then Fx.ripple(tier) end
  if over >= 3 then
    play("thump", 0.9, 0.6)
    play("slam", 0.9, 0.7)
  end
  Fx.kick(math.min(1.1 + 0.3 * over, 2.6), math.min(16 + 4 * over, 36))
end
function Fx.crater(at, normal, power)
  power = math.clamp(power, 0.2, 2)
  if O.fxCrater then
    local up = normal or UP
    local cf = CFrame.lookAt(at, at + up, math.abs(up.Y) < 0.95 and UP or Vector3.xAxis) * CFrame.Angles(-math.pi / 2, 0, 0)
    if power >= 0.45 then
      local mesh = clone("KCrater")
      if mesh then
        local full = mesh.Size
        mesh.Size = Vector3.new(full.X * 0.2, full.Y, full.Z * 0.2) * power
        place(mesh, cf + up * 0.05)
        tweenSize(mesh, full * power, 0.18, ease.outCubic)
        emit(mesh, power)
        task.delay(5, function()
          if not mesh.Parent then return end
          local skin = mesh:FindFirstChildOfClass("SurfaceAppearance")
          if skin then skin:Destroy() end      -- a SurfaceAppearance ignores the fade otherwise
          animate(1.2, ease.linear, function(p) mesh.Transparency = p end)
        end)
        later(7, mesh)
      end
    end
    -- dust for every landing; the full slam ring only for the heavy ones
    local dust = clone(power >= 0.9 and "SSlam" or "STakeoff")
    if dust then
      place(dust, power >= 0.9 and cf or CFrame.new(at))
      emit(dust, math.clamp(power, 0.35, 1.4))
      later(5, dust)
    end
  end
  if power >= 0.9 then
    play("slam", 1.4)
    play("thump", 0.7)
  else
    play("step", 0.5 + power * 0.6)
  end
  Fx.kick(0.4 + 0.6 * power, 7 * power)
end
function Fx.wall(at, normal)
  if O.fxCrater then
    local mark = clone("SImpact")
    if mark then
      local size = mark.Size
      mark.Size = Vector3.new(0.1, 0.1, 0.1)
      place(mark, CFrame.lookAt(at, at + normal, math.abs(normal.Y) < 0.95 and UP or Vector3.xAxis))
      tweenSize(mark, size, 0.2)
      for _, item in ipairs(mark:GetDescendants()) do
        if item:IsA("ParticleEmitter") then item:Emit(item.Rate) end
      end
      later(5, mark)
    end
  end
  play("slam", 1.1)
  Fx.kick(0.9, 10)
end
local LIMBS = { "RightHand", "LeftHand", "RightFoot", "LeftFoot" }
-- limb trails last longer and show more the higher the tier
local function styleTrail(trail)
  local over = math.clamp(Fx.dress - 1, 0, 5)
  trail.Lifetime = 0.13 * (1 + 0.6 * over)
  trail.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.2, 0.93 - 0.07 * over), NumberSequenceKeypoint.new(1, 1) })
end
function Fx.setTrails(on)
  on = on == true
  if on == Fx.trails or not char then return end
  Fx.trails = on
  local proto = on and template("SWindTrail")
  proto = proto and proto:FindFirstChildWhichIsA("Trail")
  for _, name in ipairs(LIMBS) do
    local limb = char:FindFirstChild(name)
    if limb then
      local a, b = limb:FindFirstChild("BasedTrailA"), limb:FindFirstChild("BasedTrailB")
      if on and not a and proto then
        a, b = Instance.new("Attachment"), Instance.new("Attachment")
        a.Name, b.Name = "BasedTrailA", "BasedTrailB"
        local half = limb.Size.X / 1.7 * 2
        a.CFrame, b.CFrame = CFrame.new(half, 0, 0), CFrame.new(-half, 0, 0)
        a.Parent, b.Parent = limb, limb
        local trail = proto:Clone()
        trail.Attachment0, trail.Attachment1 = a, b
        trail.Color = ColorSequence.new(O.trailColor)
        styleTrail(trail)
        trail.Enabled = true
        trail.Parent = a
      elseif not on and a then
        local trail = a:FindFirstChildWhichIsA("Trail")
        if trail then trail.Enabled = false end
        a.Name = "BasedTrailDone"
        if b then b.Name = "BasedTrailDone"; later(0.6, b) end
        later(0.6, a)
      end
    end
  end
end
-- Wind streaks: two points a hair apart with a trail between them, carried for a tenth of a
-- second and then let go, so each draws a line as long as that tenth of a second of flight. They
-- are pooled: the top tiers throw ninety a second, and making three instances for every one of
-- them is the kind of churn that shows up as a stutter.
local streaks, streakFree = {}, {}
Fx.streaks = streaks
local function windStreak()
  local terrain = workspace:FindFirstChildOfClass("Terrain")
  if not root or not terrain then return end
  local streak = table.remove(streakFree)
  if not streak then
    local proto = template("SWindTrail")
    proto = proto and proto:FindFirstChildWhichIsA("Trail")
    if not proto or #streaks >= 140 then return end
    local a, b = Instance.new("Attachment"), Instance.new("Attachment")
    local trail = proto:Clone()
    trail.Attachment0, trail.Attachment1 = a, b
    trail.Color = ColorSequence.new(Color3.new(1, 1, 1))
    trail.Parent = a
    streak = { a = a, b = b, trail = trail }
    streaks[#streaks + 1] = streak
  end
  local a, b, trail = streak.a, streak.b, streak.trail
  local over = math.clamp(Fx.dress - 1, 0, 4)
  local reach = 10 + 3 * over
  local offset = Vector3.new(math.random(-100, 100), math.random(-100, 100), math.random(-100, 100)) / 100 * reach
  trail.Enabled = false
  a.Parent, b.Parent = root, root
  a.Position, b.Position = offset, offset + Vector3.new(0.06 + 0.03 * over, 0, 0)
  trail.Lifetime = 0.13 * (1 + 0.5 * over)
  trail:Clear()
  trail.Enabled = true
  -- let go of it after a moment, so the streak stretches out behind us
  task.delay(0.1, function()
    if not a.Parent or not b.Parent then return end
    local at, bt = a.WorldPosition, b.WorldPosition
    a.Parent, b.Parent = terrain, terrain
    a.WorldPosition, b.WorldPosition = at, bt
  end)
  task.delay(0.25 + trail.Lifetime, function()
    if a.Parent and b.Parent then
      streakFree[#streakFree + 1] = streak
    else
      -- its points went with a body that was replaced: forget it
      local at = table.find(streaks, streak)
      if at then table.remove(streaks, at) end
    end
  end)
end
-- What follows the body while it stays fast, from Mach 2 up: a vapour cone at the nose sized to
-- the tier, a shock ring thrown off it at intervals from Mach 4, and a glow there from Mach 8.
-- All of it rides with the body, for the reason given at the boom.
local function dressTo(tier)
  if tier == Fx.dress then return end
  Fx.dress = tier
  if Fx.dressAtt then
    retire(Fx.dressAtt, 0.6)
    Fx.dressAtt, Fx.pulse, Fx.pulseTwins = nil, nil, nil
  end
  if tier >= 2 and O.fxSonic and root and root.Parent then
    local over = math.min(tier - 1, 6)
    -- Ahead of the body, and further ahead the bigger it is. Seen on screen at Mach 32 with the
    -- cone a stud and a half off the chest: its vapour drifts back, and from the chase camera
    -- there was a white cloud where the body should be. Out in front, the body is drawn over it.
    local att = ride(4 + 0.6 * over)
    local vapor = piece("SBoost", "Attachment", "VaporCone")
    if vapor then
      local cone = variant("cone:" .. over, vapor, 1 + 0.2 * over, 1)
      cone.Name = "MachCone"
      cone.Enabled = true
      cone.Parent = att
    end
    local shock = tier >= 3 and piece("KBoost", "Boost3", "Attachment", "Shockwave2")
    if shock then
      Fx.pulse = variant("pulse:" .. over, shock, 0.9 + 0.35 * over, 0.85)
      Fx.pulse.Name = "MachPulse"
      Fx.pulse.Parent = att
      Fx.pulseTwins = {}
      for _, dark in ipairs({ true, false }) do
        local ring = twin("pulse:" .. over, shock, (0.9 + 0.35 * over) * (dark and 1.04 or 0.93), dark)
        if ring then
          ring.Name = dark and "MachPulseShade" or "MachPulseMist"
          ring.Parent = att
          Fx.pulseTwins[#Fx.pulseTwins + 1] = ring
        end
      end
    end
    local glowId = tier >= 4 and Assets.image("glow")
    if glowId then
      -- Air piled up white-hot ahead of the body: a rim of light round the head and shoulders
      -- as seen from behind. Small and faint on purpose. The first version (eleven studs wide,
      -- four deep) was measured on screen as a fog that left only a silhouette.
      local glow = Instance.new("ParticleEmitter")
      glow.Name = "BowGlow"
      glow.Texture = glowId
      glow.Rate, glow.Lifetime, glow.Speed = 16, NumberRange.new(0.1, 0.14), NumberRange.new(0, 0)
      glow.Size = NumberSequence.new(2.6 + 0.35 * over)
      glow.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.3, 0.9), NumberSequenceKeypoint.new(1, 1) })
      glow.Color = ColorSequence.new(Color3.fromRGB(214, 230, 255))
      glow.LightEmission, glow.LightInfluence, glow.LockedToPart, glow.ZOffset = 1, 0, true, 1
      glow.Parent = att
    end
    Fx.dressAtt = att
  end
  if char then
    for _, name in ipairs(LIMBS) do
      local limb = char:FindFirstChild(name)
      local a = limb and limb:FindFirstChild("BasedTrailA")
      local trail = a and a:FindFirstChildWhichIsA("Trail")
      if trail then styleTrail(trail) end
    end
  end
end
-- What is drawn over the game past Mach 2. All of it is images, so it costs nothing in the world:
--   speed lines   streaks at the edge of the screen that point at its centre, redrawn at a new
--                 angle some twenty times a second, with a second set between them from Mach 8
--   the tunnel    the edges of the screen darken, deeper with every doubling
--   the ripple    at each boom, a shock ring opens across the screen from the body
-- Measured on a pale sky, white alone could hardly be seen. So everything pale has the same
-- image in dark blue under it, a hair larger or turned a fraction: one of the two always shows.
local overlays, lines, lineShade, lines2, tunnel
local function overlay(name, image, z, tint)
  if not overlays or not overlays.Parent then overlays = B.screen(7900) end
  local label = Instance.new("ImageLabel")
  label.Name = name
  label.BackgroundTransparency = 1
  label.Image = image
  label.ImageColor3 = tint or Color3.new(1, 1, 1)
  label.AnchorPoint, label.Position = Vector2.new(0.5, 0.5), UDim2.fromScale(0.5, 0.5)
  label.ImageTransparency = 1
  label.Visible = false
  label.ZIndex = z
  label.Parent = overlays
  return label
end
function Fx.ripple(tier)
  local id = O.fxLines and Assets.image("shock")
  local camera = workspace.CurrentCamera
  if not id or not camera or not root then return end
  Fx.ripples += 1
  local over = math.clamp(tier - 1, 1, 6)
  local at, seen = camera:WorldToViewportPoint(root.Position)
  local centre = seen and UDim2.fromOffset(at.X, at.Y) or UDim2.fromScale(0.5, 0.5)
  local reach = camera.ViewportSize.Magnitude * (1.5 + 0.12 * over)       -- how wide it ends, in pixels
  local strength = math.min(0.55 + 0.08 * over, 0.9)
  -- one ring at Mach 2, two from Mach 4, three from Mach 16
  for index = 1, over >= 4 and 3 or (over >= 2 and 2 or 1) do
    task.delay((index - 1) * 0.09, function()
      local dark, light = overlay("ScreenShockShade", id, 5, SHADE), overlay("ScreenShock", id, 6)
      dark.Position, light.Position = centre, centre
      dark.Visible, light.Visible = true, true
      animate(0.36 + 0.05 * over, ease.outCubic, function(p)
        local side = (0.05 + 0.95 * p) * reach
        light.Size = UDim2.fromOffset(side, side)
        dark.Size = UDim2.fromOffset(side * 1.03, side * 1.03)
        local left = (1 - p) ^ 1.4 * strength
        light.ImageTransparency = 1 - left
        dark.ImageTransparency = 1 - left * 0.85
      end)
      later(1.5, dark)
      later(1.5, light)
    end)
  end
end
local function speedLines(dt, mach, active)
  local want, dark = 0, 0
  if O.fxLines then
    if active then want = math.clamp((mach - 1.6) / 5, 0, 1) * 0.5 end
    if active then dark = math.clamp(math.log(math.max(mach, 1), 2) - 1, 0, 3) / 3 * 0.42 end
    Fx.punch = math.max(0, Fx.punch - dt * 2.5)
    want = math.min(want + Fx.punch * 0.35, 0.8)
    dark = math.min(dark + Fx.punch * 0.2, 0.6)
  else
    Fx.punch = 0
  end
  Fx.lineAlpha += (want - Fx.lineAlpha) * alpha(7, dt)
  Fx.tunnelAlpha += (dark - Fx.tunnelAlpha) * alpha(5, dt)
  if Fx.tunnelAlpha < 0.004 then
    if tunnel and tunnel.Visible then tunnel.Visible = false end
  else
    local id = not tunnel and Assets.image("vignette")
    if id then
      tunnel = overlay("MachTunnel", id, 1)
      tunnel.Size = UDim2.fromScale(1, 1)
    end
    if tunnel then
      tunnel.Visible = true
      tunnel.ImageTransparency = 1 - Fx.tunnelAlpha
    end
  end
  if Fx.lineAlpha < 0.004 then
    if lines and lines.Visible then lines.Visible, lineShade.Visible, lines2.Visible = false, false, false end
    return
  end
  if not lines then
    local id = Assets.image("speedlines")
    if not id then return end
    lineShade, lines2, lines = overlay("SpeedShade", id, 2, SHADE), overlay("SpeedLines2", id, 3), overlay("SpeedLines", id, 4)
    Fx.lines = lines
  end
  if not lines.Visible then
    -- a square that still covers the screen whichever way it is turned
    local side = math.ceil(workspace.CurrentCamera.ViewportSize.Magnitude * 1.08)
    lines.Size = UDim2.fromOffset(side, side)
    lineShade.Size, lines2.Size = lines.Size, lines.Size
    lines.Visible, lineShade.Visible, lines2.Visible = true, true, true
  end
  lines.ImageTransparency = 1 - Fx.lineAlpha
  lineShade.ImageTransparency = 1 - Fx.lineAlpha * 0.9
  lines2.ImageTransparency = 1 - Fx.lineAlpha * math.clamp((mach - 8) / 24, 0, 1) * 0.9
  Fx.lineClock += dt
  if Fx.lineClock >= 0.045 then
    Fx.lineClock = 0
    lines.Rotation = math.random(0, 359)
    lineShade.Rotation = lines.Rotation + 0.35      -- beside each line, not under it
    lines2.Rotation = math.random(0, 359)
  end
end
-- every frame: the dressing, trails, streaks and the wind loop all follow real speed
function Fx.update(dt, speed, flying, boosting)
  Fx.speed, Fx.flying, Fx.boosting = speed, flying, boosting
  local previewing = Fx.previewUntil > os.clock()
  local tier, mach = 0, 0
  if previewing then
    tier, mach = Fx.previewTier, 2 ^ (Fx.previewTier - 1) * 1.2
  elseif flying then
    tier, mach = tierOf(speed)
  end
  Fx.mach = mach
  -- up a tier the moment it is reached, down only once the speed is well under it
  if tier > Fx.dress then
    dressTo(tier)
  elseif Fx.dress > 0 and (previewing or not flying or speed < O.sonic * 2 ^ (Fx.dress - 1) * 0.85) then
    dressTo(tier)
  end
  if Fx.pulse and Fx.pulse.Parent then
    Fx.pulseAcc += dt
    if Fx.pulseAcc >= math.clamp(0.95 - 0.12 * Fx.dress, 0.3, 0.7) then
      Fx.pulseAcc = 0
      Fx.pulse:Emit(1)
      for _, ring in ipairs(Fx.pulseTwins or {}) do ring:Emit(1) end
    end
  end
  speedLines(dt, mach, flying or previewing)
  if not flying and not Fx.trails and not Fx.wind then return end
  local cruise = O.speed
  Fx.setTrails(flying and O.fxTrails and speed > math.max(60, cruise * 0.45))
  if flying and O.fxStreaks and speed > math.max(cruise * 1.1, 100) then
    Fx.windAcc += dt
    local every = math.clamp(0.05 - (speed - cruise) / 20000, Fx.dress >= 3 and 0.011 or 0.02, 0.05)
    while Fx.windAcc >= every do
      Fx.windAcc -= every
      windStreak()
    end
  else
    Fx.windAcc = 0
  end
  local wind = Fx.wind
  if wind and wind.Parent then
    local charging = Flight.state == "charging"
    local target = (flying and math.clamp(speed / 300, 0, 3) * 0.5 or (charging and 0.25 + 0.3 * Flight.charge or 0)) * volume()
    wind.Volume += (target - wind.Volume) * alpha(8, dt)
    local pitch = charging and (0.6 + 0.9 * Flight.charge) or math.clamp(speed / 165, 0.75, 2)
    wind.PlaybackSpeed += (pitch - wind.PlaybackSpeed) * alpha(8, dt)
    if target > 0.01 and not wind.IsPlaying then wind:Play()
    elseif target <= 0.01 and wind.Volume < 0.01 and wind.IsPlaying then wind:Stop() end
  end
end
local function cameraUndo()
  local camera = workspace.CurrentCamera
  if camera and Fx.offset ~= CFrame.identity then camera.CFrame = camera.CFrame * Fx.offset:Inverse() end
  Fx.offset = CFrame.identity
end
local function cameraApply(dt)
  local camera = workspace.CurrentCamera
  if not camera or not O then return end
  dt = math.min(dt, 0.1)
  Fx.shakeTime += dt
  Fx.shake = math.max(0, Fx.shake - dt * 1.6)
  Fx.fovKick = math.max(0, Fx.fovKick - dt * 22)
  -- the camera rolls a few degrees the way the body banks
  Fx.roll += ((Fx.flying and O.fxShake and math.clamp(lean * 0.12, -8, 8) or 0) - Fx.roll) * alpha(4, dt)
  local amp = 0
  if Fx.flying and O.fxShake and Fx.speed > 5 then
    amp = math.clamp(Fx.speed / 900, 0, 0.55) * (Fx.boosting and 1.2 or 1) + 0.07 * math.clamp(Fx.dress - 1, 0, 5)
  end
  amp += Fx.shake * 2
  if amp > 1e-4 or math.abs(Fx.roll) > 0.01 then
    local t = Fx.shakeTime * 4.4 * math.pi
    local offset = CFrame.Angles(math.sin(t) * amp * 0.004 + math.sin(t * 3.1) * Fx.shake * 0.01,
      math.sin(t * 0.7 + 1.3) * amp * 0.003 + math.cos(t * 2.7) * Fx.shake * 0.01, math.sin(t * 0.5 + 2.7) * amp * 0.002 + math.rad(Fx.roll))
    camera.CFrame = camera.CFrame * offset
    Fx.offset = offset
  end
  -- the field of view widens with speed, unless the player has locked it in Visuals
  if O.fxFov and not Config.get("world.fov") and (Fx.flying or Fx.fovKick > 0 or Fx.baseFov) then
    Fx.baseFov = Fx.baseFov or camera.FieldOfView
    local want = Fx.baseFov + (Fx.flying and math.clamp(Fx.speed * 15 / 450, 0, 32) or 0)
    want = math.min(want + Fx.fovKick, 115)
    camera.FieldOfView += (want - camera.FieldOfView) * alpha(4, dt)
    if not Fx.flying and Fx.fovKick <= 0 and math.abs(camera.FieldOfView - Fx.baseFov) < 0.05 then
      camera.FieldOfView = Fx.baseFov
      Fx.baseFov = nil
    end
  elseif Fx.baseFov then
    camera.FieldOfView = Fx.baseFov
    Fx.baseFov = nil
  end
end
-- build the templates a frame apart and fetch their textures and the sounds, so the first
-- boom is not a silent, untextured one
local function warm()
  if warmed then return end
  warmed = true
  task.spawn(function()
    local list = {}
    for _, name in ipairs(PACK) do
      local made = template(name)
      if made then list[#list + 1] = made end
      task.wait()
    end
    local wind = Instance.new("Sound")
    wind.SoundId = soundId("wind")
    wind.Looped = true
    wind.Volume = 0
    wind.Parent = sounds()
    Fx.wind = wind
    for name in pairs(SOUNDS) do
      if name ~= "wind" then
        local sound = Instance.new("Sound")
        sound.SoundId = soundId(name)
        sound.Parent = sounds()
        list[#list + 1] = sound
        later(20, sound)
      end
    end
    pcall(function() S.ContentProvider:PreloadAsync(list) end)
  end)
end
-- Fire the boom of a tier where the body stands, and wear that tier for a moment: what a setting
-- looks like, without having to fly it. The rings open along the way the body faces.
function Fx.preview(tier)
  if not root or not root.Parent then return false end
  warm()
  local look = root.CFrame.LookVector
  Fx.previewTier, Fx.previewUntil, Fx.previewDir = tier, os.clock() + 2.6, look
  Fx.sonicBoom(look * O.sonic * 2 ^ (tier - 1), tier)
  return true
end

-- ---------------------------------------------------------------- animation layer
local function loadTracks()
  table.clear(tracks)
  current, Flight.clip = nil, nil
  Flight.animated = false
  if not animator or not O.animations or hum.RigType ~= Enum.HumanoidRigType.R15 then return end
  local preload = {}
  for name, id in pairs(ANIMS) do
    local animation = Instance.new("Animation")
    animation.AnimationId = "rbxassetid://" .. id
    local ok, track = pcall(function() return animator:LoadAnimation(animation) end)
    if ok and track then
      -- three of the clips are published at Core priority and would lose to the game's own idle
      track.Priority = Enum.AnimationPriority.Action4
      tracks[name] = track
      preload[#preload + 1] = animation
      Flight.animated = true
    end
  end
  -- fetched before first use: a track played before its data arrives shows nothing to anyone
  task.spawn(function() pcall(function() S.ContentProvider:PreloadAsync(preload) end) end)
end
local function setAnim(name, fade, rate)
  Flight.clip = name
  local track = tracks[name]
  if not track then
    -- no clip for this (R6, or animations off): make sure nothing stale keeps playing
    if current and tracks[current] then tracks[current]:Stop(fade or 0.25) end
    current = nil
    return
  end
  if current == name then
    if rate and math.abs(track.Speed - rate) > 0.04 then track:AdjustSpeed(rate) end
    return
  end
  local previous = current and tracks[current]
  track:Play(fade or 0.3, 1, rate or 1)
  if previous then previous:Stop(fade or 0.3) end
  current, currentSince = name, os.clock()
end
local function stopAnims(fade)
  for _, track in pairs(tracks) do
    if track.IsPlaying then track:Stop(fade or 0.25) end
  end
  current, Flight.clip = nil, nil
end
-- the hover poses the player picked, in a fixed order, and the one whose turn it is
local function chooseIdles(list)
  table.clear(idleChoice)
  for _, key in ipairs(IDLE_ORDER) do
    if table.find(list, key) then idleChoice[#idleChoice + 1] = IDLES[key] end
  end
  if #idleChoice == 0 then idleChoice[1] = "idle" end
end
local function idleName() return idleChoice[(idleIndex - 1) % #idleChoice + 1] end
local function isIdle(name) return name == "idle" or name == "idle2" or name == "idle3" or name == "idle4" end
-- playback speed follows airspeed; stepped, because every change is sent to the other clients
local function paced(base, gain, fraction, low, high)
  return math.floor(math.clamp(base + gain * fraction, low, high) * 20 + 0.5) / 20
end

-- ---------------------------------------------------------------- physics
local function buildPhysics()
  if byFrame() then
    -- (stand-ins with the same fields: the flight below sets them, and the frame step carries them out)
    if not (faked and lv) then
      lv = { fake = true, Parent = true, VectorVelocity = vel }
      ao = { fake = true, Parent = true, CFrame = root.CFrame.Rotation, Responsiveness = 14 }
      attachment = nil
      faked = true
    end
    return
  end
  faked = false
  if lv and lv.Parent and ao and ao.Parent then return end
  for _, item in ipairs({ lv, ao, attachment }) do
    if item then pcall(function() item:Destroy() end) end
  end
  attachment = Instance.new("Attachment")
  attachment.Name = util.randomName()
  attachment.Parent = root
  lv = Instance.new("LinearVelocity")
  lv.Attachment0 = attachment
  lv.MaxForce = math.huge
  lv.RelativeTo = Enum.ActuatorRelativeTo.World
  lv.VelocityConstraintMode = Enum.VelocityConstraintMode.Vector
  lv.VectorVelocity = vel
  lv.Parent = root
  ao = Instance.new("AlignOrientation")
  ao.Mode = Enum.OrientationAlignmentMode.OneAttachment
  ao.Attachment0 = attachment
  ao.MaxTorque = math.huge
  ao.MaxAngularVelocity = math.huge
  ao.Responsiveness = 14
  ao.CFrame = root.CFrame.Rotation
  ao.Parent = root
end
local function teardownPhysics()
  for _, item in ipairs({ lv, ao, attachment }) do
    if item and typeof(item) == "Instance" then pcall(function() item:Destroy() end) end
  end
  lv, ao, attachment = nil, nil, nil
  faked = false
end
-- the speed the body really has: in frame mode its velocity is held at zero, so it is the flight's own
local function bodySpeed()
  if faked and lv then return lv.VectorVelocity.Magnitude end
  return root and root.Parent and root.AssemblyLinearVelocity.Magnitude or 0
end
-- Space charges a launch while flight is armed, so it must not also jump
local function blockJump(block)
  if not hum then return end
  if block then
    if jumpWasEnabled == nil then
      jumpWasEnabled = hum:GetStateEnabled(STATE.Jumping)
      hum:SetStateEnabled(STATE.Jumping, false)
    end
  elseif jumpWasEnabled ~= nil then
    pcall(function() hum:SetStateEnabled(STATE.Jumping, jumpWasEnabled) end)
    jumpWasEnabled = nil
  end
end
-- Physics: the humanoid applies no forces of its own. Freefall: Roblox's own character sounds,
-- which run on every client for every character, play a rushing-wind loop from the replicated
-- state, which makes the wind the one sound other players hear.
local function flightState() return O.windForOthers and STATE.Freefall or STATE.Physics end
local function setState(state)
  if byFrame() or not hum then return end
  if hum:GetState() ~= state then hum:ChangeState(state) end
end

local function startFlying(initial)
  if not alive() or Flight.state == "flying" then return end
  Flight.state = "flying"
  vel = initial or (byFrame() and Vector3.zero or root.AssemblyLinearVelocity)
  Flight.ramp, stage, lean, spaceSince, boomed, impact, floor = 0, 0, 0, nil, 0, 0, nil
  facing = flat(root.CFrame.LookVector) or facing
  buildPhysics()
  if savedAutoRotate == nil then savedAutoRotate = hum.AutoRotate end
  hum.AutoRotate = false
  setState(flightState())
  blockJump(true)
end
-- Where the body last stood on something, and a safe way down when the flight lets go of it in
-- the air (frame mode only: there the body has no momentum to carry it anywhere). Measured live
-- in Da Hood: let go at rest over the edge of the world, it fell past the height where the game
-- takes a body out and the player died. So: a short drop is fallen; a long one is put straight
-- onto the ground under it; with no ground under it at all, back where it last stood.
local stood                  -- CFrame where the body last had a floor under its feet
local LET_FALL = 60          -- studs of drop that are simply fallen
local function putDown()
  if not alive() then return end
  local params = RaycastParams.new()
  params.FilterType = Enum.RaycastFilterType.Exclude
  params.FilterDescendantsInstances = { char }
  params.IgnoreWater = false
  params.RespectCanCollide = true
  local from = root.Position
  local hit = util.ray(from, from - UP * 20000, params, 3)
  local feet = feetBelowRoot()
  root.AssemblyLinearVelocity, root.AssemblyAngularVelocity = Vector3.zero, Vector3.zero
  if hit and hit.Normal.Y > 0.3 then
    if from.Y - hit.Position.Y - feet > LET_FALL then
      root.CFrame = root.CFrame.Rotation + (hit.Position + UP * (feet + 0.2))
    end
  elseif stood then
    root.CFrame = stood + UP * 0.5
    if B.Window and B.Window.toast then
      B.Window.toast({ title = "No ground under you", text = "Put back where you last stood.", icon = "shield-check", time = 3 })
    end
  end
end
Flight.putDown = putDown
-- hand the body back to the humanoid; `toGround` when we are standing on something
local function leaveFlight(toGround)
  Fx.stopCharge()
  Fx.boostRing(false)
  Fx.setTrails(false)
  stage, Flight.ramp = 0, 0
  -- (carried by frames, the body is let go at rest: a body thrown at flight speed lands at it)
  local momentum = (not byFrame() and root and root.Parent) and root.AssemblyLinearVelocity or Vector3.zero
  teardownPhysics()
  if hum and savedAutoRotate ~= nil then
    pcall(function() hum.AutoRotate = savedAutoRotate end)
    savedAutoRotate = nil
  end
  if alive() then
    if toGround then
      setState(STATE.GettingUp)
    else
      -- keep the momentum and let the humanoid fall normally
      setState(STATE.Freefall)
      root.AssemblyLinearVelocity = momentum
      if byFrame() and not (Flight.blocked and Flight.blocked()) then putDown() end
    end
  end
end
local function stopEverything()
  local state = Flight.state
  if state == "flying" or (state == "landing" and lv ~= nil) then leaveFlight(false) end
  Fx.stopCharge()
  if chargeHold then
    pcall(function() chargeHold.plane:Destroy() end)
    pcall(function() chargeHold.att:Destroy() end)
    chargeHold = nil
  end
  stopAnims(0.25)
  blockJump(false)
  landing, airborneSince = nil, nil
  Flight.state, Flight.speed, Flight.ramp, Flight.charge = "off", 0, 0, 0
end

-- ---------------------------------------------------------------- the ground
local function exclusions()
  local now = os.clock()
  if now - ignoreAt > 0.5 then
    ignoreAt = now
    table.clear(ignore)
    if folder then ignore[#ignore + 1] = folder end
    -- never land on, or crash into, another player
    for _, player in ipairs(S.Players:GetPlayers()) do
      if player.Character then ignore[#ignore + 1] = player.Character end
    end
    rayParams.FilterDescendantsInstances = ignore
  end
  return rayParams
end
local function groundBelow(from, reach)
  local hit = workspace:Raycast(from, Vector3.new(0, -reach, 0), exclusions())
  if hit and hit.Normal.Y > 0.55 then return hit end
  return nil
end

-- ---------------------------------------------------------------- charge and launch
-- While charging the body is held where it stands: the crouch has a hand on the ground, and
-- walking slides it along (in the first minutes of real use the player held W through four
-- charges out of five). Sideways only; up and down are left to the ground.
local function holdStill(on)
  if chargeHold then
    pcall(function() chargeHold.plane:Destroy() end)
    pcall(function() chargeHold.att:Destroy() end)
    chargeHold = nil
  end
  if not on or not root or not root.Parent then return end
  if byFrame() then
    chargeHold = { fake = true, at = root.Position }
    return
  end
  local att = Instance.new("Attachment")
  att.Name = util.randomName()
  att.Parent = root
  local plane = Instance.new("LinearVelocity")
  plane.Attachment0 = att
  plane.MaxForce = math.huge
  plane.RelativeTo = Enum.ActuatorRelativeTo.World
  plane.VelocityConstraintMode = Enum.VelocityConstraintMode.Plane
  plane.PrimaryTangentAxis, plane.SecondaryTangentAxis = Vector3.xAxis, Vector3.zAxis
  plane.PlaneVelocity = Vector2.zero
  plane.Parent = root
  chargeHold = { att = att, plane = plane }
end
local function beginCharge()
  Flight.state, Flight.charge = "charging", 0
  chargeStart, chargeFx = os.clock(), false
  holdStill(true)
  setAnim("charge", 0.15, 1)
end
local function release()
  local held = os.clock() - chargeStart
  Fx.stopCharge()
  holdStill(false)
  local charge = math.clamp((held - 0.2) / math.max(O.chargeTime, 0.1), 0, 1)
  local quick = held < 0.2
  local strength = quick and 0.4 or (0.6 + charge)
  local up = quick and 46 or O.launch * (0.5 + 0.9 * charge)
  local forward = (flat(workspace.CurrentCamera.CFrame.LookVector) or Vector3.zero) * up * 0.12
  local hit = groundBelow(root.Position, 12)
  Fx.takeoff(hit and hit.Position + Vector3.new(0, 0.1, 0) or root.Position - Vector3.new(0, feetBelowRoot(), 0), strength)
  Flight.state, Flight.charge = "ground", 0
  Flight.launches += 1
  launchVel = UP * up + forward
  -- the launch carries for a moment whatever the keys say: it boosts up to the sky
  launchUntil = os.clock() + (quick and 0.25 or 0.45 + 0.75 * charge)
  startFlying(launchVel)
  setAnim(quick and "up" or "upFast", 0.12, 1)
end
local function stepCharge()
  local held = os.clock() - chargeStart
  if chargeHold and chargeHold.fake and root and root.Parent then
    -- sideways only, as the plane constraint does: up and down are the ground's
    local at, here = chargeHold.at, root.Position
    root.CFrame = root.CFrame.Rotation + Vector3.new(at.X, here.Y, at.Z)
    local v = root.AssemblyLinearVelocity
    root.AssemblyLinearVelocity = Vector3.new(0, math.min(v.Y, 0), 0)
  end
  Flight.charge = math.clamp((held - 0.2) / math.max(O.chargeTime, 0.1), 0, 1)
  if held > 0.2 then
    if not chargeFx then
      chargeFx = true
      Fx.startCharge()
    end
    Fx.kick(0.05 + 0.1 * Flight.charge, 0)
  end
  local track = tracks.charge
  if track and track.IsPlaying then
    local at = track.TimePosition
    if at >= CHARGE.high and track.Speed > 0 then track:AdjustSpeed(-1)
    elseif at <= CHARGE.low and track.Speed < 0 then track:AdjustSpeed(1) end
  end
  if not down("Space") then
    release()
  elseif not onGround() then
    -- knocked off the ground while charging: let go of the crouch, the armed state catches the fall
    Fx.stopCharge()
    holdStill(false)
    stopAnims(0.15)
    Flight.state, Flight.charge = "ground", 0
  end
end

-- ---------------------------------------------------------------- landing
local function beginLanding(hit, approach)
  local feet = feetBelowRoot()
  landing = { started = os.clock(), from = root.Position, to = hit.Position + UP * feet, ground = hit.Position, normal = hit.Normal,
    power = math.clamp(approach / 320, 0.25, 1.8), approach = approach, touched = false, released = false,
    look = flat(vel) or flat(root.CFrame.LookVector) or facing }
  Flight.state = "landing"
  Fx.boostRing(false)
  Fx.setTrails(false)
  stage, Flight.ramp, spaceSince = 0, 0, nil
  -- measured live: in Freefall the humanoid flickers into Landed over the last studs, at full
  -- descent speed, which is exactly what a game's fall damage listens for. Physics has no Landed.
  setState(STATE.Physics)
  -- slowed so that the clip's feet reach the ground on the frame the body does
  setAnim("land", 0.18, LAND.contact / LAND.lead)
end
-- The way down: sideways motion is shed along the way, the drop itself is not eased (the crouch
-- is what absorbs it). Returns where the root should be at `t` and how fast it is moving there.
local function landingPath(L, t)
  local p = math.clamp(t / LAND.lead, 0, 1)
  local span = L.to - L.from
  local across, rate = 1 - (1 - p) ^ 2, 2 * (1 - p) / LAND.lead
  return Vector3.new(L.from.X + span.X * across, L.from.Y + span.Y * p, L.from.Z + span.Z * across),
    Vector3.new(span.X * rate, span.Y / LAND.lead, span.Z * rate)
end
local function finishLanding(fade)
  local track = tracks.land
  if track and track.IsPlaying then track:Stop(fade) end
  if lv then leaveFlight(true) end
  current, Flight.clip = nil, nil
  landing = nil
  Flight.state = "ground"
end
local function touchDown(L)
  L.touched, L.touchedAt = true, os.clock()
  local feet = feetBelowRoot()
  -- Measured live: a landing from 5,665 st/s was abandoned because the body was more than six
  -- studs from its mark, which at that speed is a quarter of one frame. Only a body that stopped
  -- SHORT of the mark, by more than a tenth of a second of travel, met something on the way; one
  -- that is level with it or past it (a slow frame carries it on) simply belongs on the mark.
  local span = L.to - L.from
  local past = span.Magnitude > 1e-3 and (root.Position - L.to):Dot(span.Unit) or 0
  if past < 0 and (root.Position - L.to).Magnitude > math.max(6, L.approach * 0.12) then
    -- something stood in the way: put down here if there is ground here, otherwise carry on flying
    local below = groundBelow(root.Position, feet + 4)
    if not below then
      landing = nil
      Flight.state = "flying"
      vel = Vector3.zero
      return
    end
    L.to, L.ground, L.normal = below.Position + UP * feet, below.Position, below.Normal
  end
  vel = Vector3.zero
  if lv then lv.VectorVelocity = vel end
  root.AssemblyLinearVelocity, root.AssemblyAngularVelocity = vel, vel
  root.CFrame = CFrame.lookAt(L.to, L.to + L.look)
  if ao then
    ao.CFrame = CFrame.lookAt(Vector3.zero, L.look)
    ao.Responsiveness = 60
  end
  local track = tracks.land
  if track then track:AdjustSpeed(1) end
  Flight.landings += 1
  Fx.crater(L.ground, L.normal, L.power)
end
local function stepLanding(dt)
  local L = landing
  local now = os.clock()
  if not L.touched then
    local t = now - L.started
    -- the last frame of travel is taken by the touchdown itself: one more frame at this
    -- velocity would carry the body past the ground before anything could stop it
    if t + dt < LAND.lead and lv and lv.Parent then
      setState(STATE.Physics)
      -- The path's own velocity with a gentle pull back onto it. Chasing the position frame by
      -- frame was measured live to swing between 4 and 250 st/s on a 120 st/s descent (frames
      -- and physics steps do not line up); this is the same path, flown smoothly.
      local point, speed = landingPath(L, t)
      local off = point - root.Position
      if L.approach > PIN_SPEED and off.Magnitude > 1 then
        -- at thousands of studs a second that same mismatch is tens of studs: put the body on
        -- the path. A correction of less than one frame's travel cannot be told from the travel.
        root.CFrame = root.CFrame.Rotation + point
        off = Vector3.zero
      end
      vel = speed + off * 6
      lv.VectorVelocity = vel
      ao.CFrame = CFrame.lookAt(Vector3.zero, L.look)
      ao.Responsiveness = 30
      return
    end
    touchDown(L)
    if landing ~= L then return end
  end
  local clipTime = LAND.contact + (now - L.touchedAt)
  if not tracks.land then
    if now - L.touchedAt > 0.25 then finishLanding(0) end
    return
  end
  if not L.released and clipTime >= LAND.hold then
    -- the body was held still through the impact; from here the humanoid has it again
    L.released = true
    leaveFlight(true)
  end
  if clipTime >= LAND.out then
    finishLanding(LAND.fade)
  elseif L.released and (hum.MoveDirection.Magnitude > 0.1 or down("Space")) then
    finishLanding(0.3)
  end
end

-- ---------------------------------------------------------------- flying
local function direction(camera)
  local move = UIS:GetFocusedTextBox() and Vector3.zero or hum.MoveDirection
  local dir = Vector3.zero
  if move.Magnitude > 0.01 then
    -- the flat move direction becomes camera-relative in 3D: look up while pressing forward, fly up
    local basis = CFrame.lookAt(Vector3.zero, flat(camera.CFrame.LookVector) or Vector3.new(0, 0, -1))
    dir = camera.CFrame:VectorToWorldSpace(basis:VectorToObjectSpace(move))
  end
  local vertical = (down("Space") and 1 or 0) - (down(O.keyDown) and 1 or 0)
  local horizontal = dir.Magnitude > 0.01
  if vertical ~= 0 then dir += UP * vertical * (horizontal and 0.7 or 1) end
  return dir.Magnitude > 0.01 and dir.Unit or Vector3.zero, vertical, horizontal
end
-- which clip, and how fast it plays. Every threshold is wider on the way out than on the way
-- in, so a speed sitting on one does not flicker between two poses.
local function pickClip(speed, elevation, moving, vertical, horizontal, heldUp, launching)
  local cruise, was = O.speed, current
  if launching then return "upFast", 1 end
  if not moving then
    -- a long hover moves on to the next of the chosen poses
    if O.idleEvery > 0 and #idleChoice > 1 and isIdle(was) and os.clock() - currentSince > O.idleEvery then idleIndex += 1 end
    return idleName(), 1
  end
  local fraction = speed / math.max(cruise, 1)
  local climbing = was == "up" or was == "upFast"
  if (vertical > 0 and not horizontal) or elevation > (climbing and 0.8 or 0.95) then
    if heldUp > CLIMB_BOOST + 0.1 or speed > cruise * (was == "upFast" and 1.4 or 1.7) then return "upFast", 1 end
    return "up", paced(0.8, 0.5, fraction, 0.8, 1.5)
  end
  if (vertical < 0 and not horizontal) or elevation < ((was == "down" or was == "hoverDown") and -0.75 or -0.9) then
    -- hovering down is the descend key on its own at an easy pace; boosted, steered into or simply fast, it is the dive
    local easy = math.min(math.max(cruise * 1.35, 60), HOVER_DOWN_MAX) * (was == "hoverDown" and 1.2 or 1)
    if vertical < 0 and not horizontal and Flight.ramp < 0.05 and speed <= easy then return "hoverDown", 1 end
    return "down", 1
  end
  if speed >= O.sonic * (was == "sonic" and 0.6 or 0.72) then return "sonic", 1 end
  if Flight.ramp > 0.1 or speed > cruise * (was == "aggressive" and 1.25 or 1.5) then
    return "aggressive", paced(0.9, 0.5, speed / math.max(O.top, 1), 0.9, 1.5)
  end
  if elevation < (was == "aimDown" and -0.28 or -0.38) then return "aimDown", 1 end
  return "slow", paced(0.7, 0.6, fraction, 0.7, 1.4)
end
local function stepFly(dt)
  local camera = workspace.CurrentCamera
  setState(flightState())
  buildPhysics()
  local now = os.clock()
  local dir, vertical, horizontal = direction(camera)
  local moving = dir.Magnitude > 0
  local launching = launchUntil > now
  -- how long Space has been held: a long hold on a straight climb becomes the run at the boom
  if vertical > 0 then spaceSince = spaceSince or now else spaceSince = nil end
  local heldUp = spaceSince and now - spaceSince or 0

  local boosting = moving and (down(O.keyBoost) or (vertical > 0 and not horizontal and heldUp > CLIMB_BOOST))
  local ramp = Flight.ramp
  if boosting then ramp = math.min(1, ramp + dt / math.max(O.rampTime, 0.3)) else ramp = math.max(0, ramp - dt / 0.8) end
  Flight.ramp = ramp
  local wantStage = ramp >= 0.999 and 3 or (ramp >= 0.6 and 2 or (ramp >= 0.2 and 1 or 0))
  if wantStage > stage then
    stage = wantStage
    Fx.boostStage(stage)
  elseif wantStage < stage then
    stage = wantStage
    if stage == 0 then Fx.boostRing(false) end
  end

  local cruise = O.speed
  local top = math.max(O.top, cruise)
  local target = launching and launchVel or (moving and dir * (cruise + (top - cruise) * ramp ^ 1.5) or Vector3.zero)
  vel = vel:Lerp(target, alpha(launching and 10 or (moving and 4 + 2 * ramp or 5), dt))
  lv.VectorVelocity = vel
  local speed = vel.Magnitude
  Flight.speed = speed

  -- The boom, on the speed the body really has. Each tier booms once on the way up and is armed
  -- again when the speed is back under 80% of where it starts. A hard acceleration that runs
  -- through several tiers inside BOOM_GAP booms once more, for the highest one it has reached.
  local real = bodySpeed()
  local tier = tierOf(real)
  if tier > boomed and now - lastSonic > (boomed == 0 and 1.35 or BOOM_GAP) then
    boomed, lastSonic = tier, now
    Flight.booms += 1
    Flight.boomLog[#Flight.boomLog + 1] = tier
    if #Flight.boomLog > 40 then table.remove(Flight.boomLog, 1) end
    Fx.sonicBoom(vel, tier)
  else
    while boomed > 0 and real < O.sonic * 2 ^ (boomed - 1) * 0.8 do boomed -= 1 end
  end

  local elevation = speed > 4 and math.asin(math.clamp(vel.Y / speed, -1, 1)) or 0
  local name, rate = pickClip(speed, elevation, moving, vertical, horizontal, heldUp, launching)
  if current and POSE[current] and name ~= current and now - currentSince < DWELL then name, rate = current, nil end
  if isIdle(current) and not isIdle(name) then idleIndex += 1 end
  setAnim(name, (name == "sonic" or name == "upFast") and 0.2 or (isIdle(name) and (isIdle(current) and 0.6 or 0.4) or 0.3), rate)

  -- orientation: face along the path, tilt by what the clip does not already supply, bank into turns
  local planar = Vector3.new(vel.X, 0, vel.Z)
  local planarSpeed = planar.Magnitude
  if (moving or launching) and planarSpeed > math.max(6, speed * 0.2) then facing = planar.Unit end
  local wantLean = 0
  local dirFlat = flat(dir)
  if moving and dirFlat and planarSpeed > 20 then wantLean = math.clamp(signedYaw(planar.Unit, dirFlat) * 1.3, -70, 70) end
  lean += (wantLean - lean) * alpha(5, dt)
  local base = CFrame.lookAt(Vector3.zero, facing)
  local pitch, roll
  if not moving and not launching then
    -- hovering or braking: upright, tipped a little the way it is still drifting
    local drift = base:VectorToObjectSpace(vel)
    pitch, roll = math.clamp(drift.Z / 200, -0.25, 0.25), math.clamp(-drift.X / 200, -0.25, 0.25)
    ao.Responsiveness = 18
  else
    local blend = math.clamp(speed / math.max(cruise * 0.7, 30), 0, 1)
    local pose = tracks[name] and POSE[name]
    if pose then
      pitch = elevation * pose.follow + pose.lean
      if pose.rocket then pitch += (math.max(elevation, 0.6) - math.pi / 2) * pose.rocket end
      if pose.dive and elevation < -0.56 then pitch += (elevation + 0.56) * pose.dive end
    else
      -- no clip to wear (R6, animations off, or it failed to load): the body itself leads, head first
      pitch = elevation - math.pi / 2
    end
    pitch *= blend
    roll = math.rad(lean) * (pose and pose.bank or 1) * blend
    ao.Responsiveness = 14
  end
  -- rolled about the direction of travel first, then pitched: a bank stays a bank at any pitch
  ao.CFrame = base * CFrame.Angles(0, 0, roll) * CFrame.Angles(pitch, 0, 0)

  -- the ground: a landing is timed from the moment the path is sure to meet it. Measured: a ray
  -- finds nothing further than 15,000 studs however long it is asked to be, so this look-ahead
  -- (0.6 s of descent) sees the whole approach up to about 25,000 st/s straight down. Faster
  -- than that the landing starts when the ground comes into view and takes its 0.6 s from there.
  if O.autoLand and not launching then
    local descent = math.max(-vel.Y, 0)
    local slope = speed > 1 and vel.Y / speed or 0
    if vertical < 0 or (descent > 4 and (slope < -0.5 or (speed >= 320 and slope < -0.2))) then
      local feet = feetBelowRoot()
      local hit = groundBelow(root.Position, feet + descent * LAND.lead + 6)
      local clearance = hit and root.Position.Y - hit.Position.Y - feet
      -- Coming down at the ground is only a landing while it is still being flown there, or when
      -- it is too late to stop. With the keys let go the body brakes inside descent / 5 studs, and
      -- letting go high above the ground used to be taken for a landing anyway.
      local meant = vertical < 0 or (moving and dir.Y < -0.2) or (hit ~= nil and descent / 5 > clearance)
      if hit and meant and clearance <= descent * LAND.lead + (vertical < 0 and 4.5 or 0.5) then
        -- where the path meets the ground, not the spot straight below
        local carry = planar * LAND.lead * 0.5
        local there = carry.Magnitude > 1 and groundBelow(root.Position + carry + UP * 2, clearance + feet + 16) or hit
        if there and carry.Magnitude > 1 then
          local blocked = workspace:Raycast(root.Position, there.Position + UP * feet - root.Position, exclusions())
          if blocked and (blocked.Position - there.Position).Magnitude > 1.5 then there = hit end
        end
        if there then
          beginLanding(there, speed)
          return
        end
      end
    end
  end
  -- Something solid in the next frame's path. A wall at speed cracks and throws us back. Ground
  -- we are not landing on lets the feet come down onto it and no further: at these speeds a body
  -- covers several studs between physics steps and would otherwise pass clean through a floor,
  -- and at any speed it would sink to its waist. So a low pass skims the ground on its feet.
  local solid = not Config.get("move.noclip")
  if speed > 20 and solid then
    local heading = vel.Unit
    local feet = feetBelowRoot()
    local travel = math.max(speed * dt * 1.6, 4)
    local hit = workspace:Raycast(root.Position, heading * (math.max(speed * HITCH, travel) + feet * math.max(-heading.Y, 0)), exclusions())
    if hit and hit.Normal.Y > 0.55 then
      -- the speed into the ground is held to what one slow frame could cover, so the body
      -- flares onto its feet instead of arriving in a single step that might go through
      local gap = math.max((root.Position - hit.Position):Dot(hit.Normal) - feet, 0)
      local into = -vel:Dot(hit.Normal)
      if into > gap / HITCH then
        impact = math.max(impact, into)
        vel += hit.Normal * (into - gap / HITCH)
        lv.VectorVelocity = vel
        if gap < 2 and impact > 250 and now - lastImpact > 1 then
          lastImpact = now
          Fx.crater(hit.Position, hit.Normal, math.clamp(impact / 320, 0.6, 1.8))
          impact = 0
        end
      else
        impact = 0
      end
      floor = floor or {}
      floor.at, floor.normal, floor.seen = hit.Position, hit.Normal, now
    elseif hit and speed > 320 and hit.Distance <= travel + 2 then
      Fx.wall(hit.Position, hit.Normal)
      vel = hit.Normal * 25
      lv.VectorVelocity = vel
      Flight.ramp, stage = 0, 0
      Fx.boostRing(false)
    end
  end
  -- A frame longer than HITCH can still leave the body under the ground it was coming down on,
  -- where no ray ahead will ever find that ground again. If the surface last seen is now above
  -- the body, put the body back on it.
  if floor and solid and now - floor.seen < 0.5 then
    local feet = feetBelowRoot()
    local height = (root.Position - floor.at):Dot(floor.normal)
    if height < feet - 0.75 then
      local over = workspace:Raycast(root.Position + floor.normal * (feet - height + 2), -floor.normal * (feet - height + 2), exclusions())
      if over and over.Normal.Y > 0.55 then
        root.CFrame += over.Normal * (feet - (root.Position - over.Position):Dot(over.Normal))
        local into = -vel:Dot(over.Normal)
        if into > 0 then
          vel += over.Normal * into
          lv.VectorVelocity = vel
        end
        floor.at, floor.normal, floor.seen = over.Position, over.Normal, now
      end
    end
  end
end

-- ---------------------------------------------------------------- carried by frames
-- What the two constraints do, done by hand (Flight.body = "frame"): the root goes along the
-- velocity the flight asked for and turns toward the way it asked to face, at the rate it asked
-- for, and is never put through anything solid: the path is looked along first and the body is
-- stopped short of what is in it, sliding along it. Its velocity is held at zero, so the engine
-- adds nothing; what gravity does between two frames (hundredths of a stud) is not carried on.
local carried, written       -- where it is being carried, and the CFrame last put on it
local SKIN = 2.4             -- studs kept from anything solid in the way
local DEEPEST = 60           -- studs over the height at which the game takes a body to have fallen out of the world
local function carry(dt)
  if not (faked and lv and alive()) then carried, written = nil, nil; return end
  local at = root.Position
  -- (anything that put the body somewhere since the last frame, this flight's own landing for
  -- one, is where it now is: carried on from there)
  local from = carried
  if not from or not written or (at - written.Position).Magnitude > 0.75 then from = at end
  local v = lv.VectorVelocity
  local step = v * dt
  local to = from + step
  if step.Magnitude > 1e-3 and not Config.get("move.noclip") then
    local hit = workspace:Raycast(from, step.Unit * (step.Magnitude + SKIN), exclusions())
    if hit then
      to = from + step.Unit * math.max(hit.Distance - SKIN, 0)
      local into = v:Dot(hit.Normal)
      if into < 0 then
        v -= hit.Normal * into
        lv.VectorVelocity, vel = v, v
      end
    end
  end
  local lowest = workspace.FallenPartsDestroyHeight + DEEPEST
  if to.Y < lowest then
    to = Vector3.new(to.X, lowest, to.Z)
    if os.clock() - (Flight.floorSaid or -math.huge) > 12 and B.Window and B.Window.toast then
      Flight.floorSaid = os.clock()
      B.Window.toast({ title = "Held over the void", text = "No ground out here. Fly back toward the map.", icon = "shield-check", time = 3.5 })
    end
    if v.Y < 0 then
      v = Vector3.new(v.X, 0, v.Z)
      lv.VectorVelocity, vel = v, v
    end
  end
  local turn = root.CFrame.Rotation:Lerp(ao.CFrame.Rotation, alpha(ao.Responsiveness or 14, dt))
  local cframe = turn + to
  root.CFrame = cframe
  root.AssemblyLinearVelocity = Vector3.zero
  root.AssemblyAngularVelocity = Vector3.zero
  carried, written = to, cframe
end

local function step(dt)
  stepTweens(dt)
  if root and root.Parent and hum and hum.FloorMaterial ~= Enum.Material.Air and Flight.state ~= "flying" and Flight.state ~= "landing" then
    stood = root.CFrame
  end
  -- (Flight.blocked: something else has the body, a game's own mover for one)
  if not O.fly or not alive() or hum.SeatPart or (Flight.blocked and Flight.blocked()) then
    if Flight.state ~= "off" then stopEverything() end
    if Fx.previewUntil > os.clock() and alive() then Fx.aim() end
    Fx.update(dt, 0, false, false)
    return
  end
  dt = math.min(dt, 0.1)
  warm()
  local state = Flight.state
  if state == "off" then
    if onGround() then
      Flight.state = "ground"
      blockJump(true)
      if not hinted and B.Window and B.Window.toast then
        hinted = true
        B.Window.toast({ title = "Flight is armed", text = "Hold Space to charge, let go to launch.", icon = "plane", time = 4.5 })
      end
    else
      startFlying()
    end
  elseif state == "ground" then
    blockJump(true)
    if onGround() then
      airborneSince = nil
      if down("Space") then beginCharge() end
    else
      -- walked off an edge, or knocked into the air: catch it
      airborneSince = airborneSince or os.clock()
      if os.clock() - airborneSince > 0.25 then
        airborneSince = nil
        startFlying()
      end
    end
  elseif state == "charging" then
    stepCharge()
  elseif state == "flying" then
    stepFly(dt)
  elseif state == "landing" then
    stepLanding(dt)
  end
  carry(dt)
  Fx.aim()
  Fx.update(dt, bodySpeed(), Flight.state == "flying", stage > 0)
end

local function attach(character)
  pcall(stopEverything)
  teardownPhysics()
  table.clear(Fx.rings)
  table.clear(streaks)
  table.clear(streakFree)
  Fx.trails, Fx.chargeAtt, Fx.boostAtt, Fx.dressAtt, Fx.pulse, Fx.pulseTwins, Fx.dress, Fx.previewUntil = false, nil, nil, nil, nil, nil, 0, 0
  savedAutoRotate, jumpWasEnabled = nil, nil
  char, hum, root, animator = nil, nil, nil, nil
  table.clear(tracks)
  if not character then return end
  local humanoid = character:WaitForChild("Humanoid", 8)
  local rootPart = character:WaitForChild("HumanoidRootPart", 8)
  if not humanoid or not rootPart or B.LP.Character ~= character then return end
  char, hum, root = character, humanoid, rootPart
  animator = humanoid:FindFirstChildOfClass("Animator") or humanoid:WaitForChild("Animator", 4)
  loadTracks()
end

-- what the Movement tab shows while this is running
function Flight.status()
  local state = Flight.state
  if state == "flying" then
    local speed = (root and root.Parent) and bodySpeed() or Flight.speed
    local tier, mach = tierOf(speed)
    return (tier > 0 and string.format("Mach %.1f", mach) or (stage > 0 and "Boosting" or (speed < 8 and "Hovering" or "Flying"))), speed, mach
  elseif state == "charging" then
    return "Charging " .. math.floor(Flight.charge * 100 + 0.5) .. "%", 0
  elseif state == "landing" then
    return "Landing", 0
  elseif state == "ground" then
    return "Armed: hold Space", 0
  end
  return O.fly and "Waiting for your character" or "Off", 0
end

function Flight.define()
  Config.define("move.fly", false)
  if Flight.flag ~= "move.fly" then Config.define(Flight.flag, false) end
  Config.define("move.flySpeed", 120)
  Config.define("fly.top", 900)
  Config.define("fly.sonic", 650)
  Config.define("fly.rampTime", 3)
  Config.define("fly.launch", 320)
  Config.define("fly.chargeTime", 1.2)
  Config.define("fly.idles", { "a" })
  Config.define("fly.idleEvery", 0)
  -- one hover pose used to be a single choice ("a", "b" or "alternate"): carry it over, once
  local legacy = Config.define("fly.idle", "a")
  if legacy ~= "a" and Config.isDefault("fly.idles") then
    Config.set("fly.idles", legacy == "alternate" and { "a", "b" } or { legacy })
    Config.set("fly.idle", "a")
  end
  Config.define("fly.animations", true)
  Config.define("fly.autoLand", true)
  Config.define("fly.windForOthers", true)
  Config.define("fly.effects", { "sonic", "takeoff", "boost", "trails", "streaks", "haze", "crater", "shake", "fov", "lines" })
  Config.define("fly.trailColor", Color3.fromRGB(225, 230, 240))
  Config.define("fly.sound", true)
  Config.define("fly.volume", 85)
  Config.define("fly.key.boost", "LeftShift")
  Config.define("fly.key.down", "LeftControl")
end

function Flight.start()
  if Flight.started then return end
  Flight.started = true
  Flight.define()
  O = Config.mirror({ fly = Flight.flag, speed = "move.flySpeed", top = "fly.top", sonic = "fly.sonic", rampTime = "fly.rampTime", launch = "fly.launch",
    chargeTime = "fly.chargeTime", idleEvery = "fly.idleEvery", animations = "fly.animations", autoLand = "fly.autoLand", windForOthers = "fly.windForOthers",
    trailColor = "fly.trailColor", sound = "fly.sound", volume = "fly.volume", keyBoost = "fly.key.boost", keyDown = "fly.key.down" })
  Flight.options = O
  local function effects(list)
    for _, name in ipairs({ "Sonic", "Takeoff", "Boost", "Trails", "Streaks", "Haze", "Crater", "Shake", "Fov", "Lines" }) do
      O["fx" .. name] = table.find(list, string.lower(name)) ~= nil
    end
  end
  effects(Config.get("fly.effects"))
  Config.on("fly.effects", effects)
  chooseIdles(Config.get("fly.idles"))
  Config.on("fly.idles", chooseIdles)
  rayParams = RaycastParams.new()
  rayParams.FilterType = Enum.RaycastFilterType.Exclude
  rayParams.IgnoreWater = true
  rayParams.RespectCanCollide = true      -- invisible trigger volumes are not ground

  B.connect(B.LP.CharacterAdded, attach, "flight.character")
  if B.LP.Character then task.spawn(B.safe("flight.attach", attach), B.LP.Character) end
  Config.on("fly.animations", function()
    if not hum then return end
    stopAnims(0.2)
    loadTracks()
  end)
  Config.on("fly.trailColor", function(color)
    if not char then return end
    for _, item in ipairs(char:GetDescendants()) do
      if item:IsA("Trail") and item.Parent and item.Parent.Name == "BasedTrailA" then item.Color = ColorSequence.new(color) end
    end
  end)
  B.connect(S.RunService.Heartbeat, function(dt)
    local ok, err = pcall(step, dt)
    if not ok then
      -- a fault here must never leave the body stuck in the air
      B.fault("flight", err)
      pcall(stopEverything)
      pcall(teardownPhysics)
      Config.set(Flight.flag, false)
    end
  end, "flight.step")
  S.RunService:BindToRenderStep("BasedFlightUndo", Enum.RenderPriority.Camera.Value - 1, cameraUndo)
  S.RunService:BindToRenderStep("BasedFlightApply", Enum.RenderPriority.Camera.Value + 1, function(dt) pcall(cameraApply, dt) end)
  B.own(function()
    pcall(function() S.RunService:UnbindFromRenderStep("BasedFlightUndo") end)
    pcall(function() S.RunService:UnbindFromRenderStep("BasedFlightApply") end)
    pcall(stopEverything)
    pcall(teardownPhysics)
    local camera = workspace.CurrentCamera
    if camera then
      if Fx.offset ~= CFrame.identity then camera.CFrame = camera.CFrame * Fx.offset:Inverse() end
      if Fx.baseFov then camera.FieldOfView = Fx.baseFov end
    end
    for _, track in pairs(tracks) do pcall(function() track:Stop(0) end) end
    for _, streak in ipairs(streaks) do
      pcall(function() streak.a:Destroy() end)
      pcall(function() streak.b:Destroy() end)
    end
    if char then
      for _, item in ipairs(char:GetDescendants()) do
        if item.Name == "BasedTrailA" or item.Name == "BasedTrailB" or item.Name == "BasedTrailDone" then pcall(function() item:Destroy() end) end
      end
    end
    for att in pairs(Fx.rings) do pcall(function() att:Destroy() end) end
  end)
end
end
do -- 27_void.lua
-- ============================================================================
--  27 void     the void cannot kill, and a fall into it is brought back
--
--  Measured on the client with throwaway parts (2026-10-07, a place whose height
--  was -500): an unanchored body under workspace.FallenPartsDestroyHeight is
--  removed by this client within half a second, an anchored one is not. Writing
--  -math.huge or -1e9 reads back -50,000: the engine clamps it, and the void is
--  simply 50,000 studs down, which is under three seconds away at flight speeds.
--  NaN is kept as written, and then nothing is removed at any depth, down to 1e12.
--  So the height is set to NaN, set again if the game changes it, and given back
--  on switch-off and on unload.
--
--  That removes the engine's void. A game whose own server script kills below
--  some height is out of reach from here. What can be done about those is not to
--  arrive: a fall with nothing under it is put back where the body last stood,
--  before it gets that far. Flight is never interfered with.
-- ============================================================================
local S, Config = B.S, B.Config
local Void = { rescues = 0, spots = {} }
B.Void = Void
local O
local NAN = 0 / 0
local AIR = Enum.Material.Air
local STATE = Enum.HumanoidStateType
local SETTLE = 0.4        -- seconds stood on a spot before it is somewhere to go back to
local APART = 10          -- studs between the spots that are remembered
local KEEP = 8
local SEE = 15000         -- a ray finds nothing further away than this (measured for the flight)
local EVERY = 0.06        -- seconds between looks: a fall is slow next to a frame

local spots = Void.spots
local gameHeight          -- the game's own height: the last value seen there that was not ours
local params
local clock, stoodSince, fallTop = 0, nil, nil
local lastRescue, lastOver, lastToast, nowhere = -math.huge, -math.huge, -math.huge, -math.huge
local wasAlive, lastY, warned, stopped = false, 0, false, false

local function unset(value) return value ~= value end      -- NaN is the one number that is not itself
local function apply()
  if stopped then return end
  local height = workspace.FallenPartsDestroyHeight
  if O.noVoid then
    if not unset(height) then
      gameHeight = height
      workspace.FallenPartsDestroyHeight = NAN
    end
  elseif gameHeight ~= nil and unset(height) then
    workspace.FallenPartsDestroyHeight = gameHeight
  end
  Void.height = gameHeight
end

local function toast(title, text)
  local now = os.clock()
  if now - lastToast < 6 or not (B.Window and B.Window.toast) then return end
  lastToast = now
  B.Window.toast({ title = title, text = text, icon = "shield", time = 3.5 })
end
local function flying()
  local state = B.Flight and B.Flight.state
  return state == "flying" or state == "landing" or state == "charging"
end
local function below(from, reach, character)
  params.FilterDescendantsInstances = { character }
  return workspace:Raycast(from, Vector3.new(0, -reach, 0), params)
end
local function soles(character, humanoid, root)
  local legs = 0
  if humanoid.RigType == Enum.HumanoidRigType.R6 then
    local leg = character:FindFirstChild("Left Leg")
    legs = leg and leg.Size.Y or 2
  end
  return humanoid.HipHeight + root.Size.Y * 0.5 + legs
end

-- Somewhere to go back to: ground the body has stood on for a moment, that is part of the map
-- (anchored, or terrain) rather than something loose or carried along.
local function remember(character, humanoid, root, now)
  stoodSince = stoodSince or now
  if now - stoodSince < SETTLE then return end
  local hit = below(root.Position, soles(character, humanoid, root) + 4, character)
  local ground = hit and hit.Instance
  if not ground or not ground:IsA("BasePart") or not (ground:IsA("Terrain") or ground.Anchored) then return end
  local newest = spots[#spots]
  if newest and (newest.Position - root.Position).Magnitude < APART then
    spots[#spots] = root.CFrame
  else
    spots[#spots + 1] = root.CFrame
    if #spots > KEEP then table.remove(spots, 1) end
  end
end
local function rescue(character, root, now)
  -- back in the void this soon after the last time: that spot was no good, use the one before
  if now - lastRescue < 4 and #spots > 1 then table.remove(spots) end
  while #spots > 0 do
    local spot = spots[#spots]
    if below(spot.Position + Vector3.new(0, 2, 0), 14, character) then
      root.CFrame = spot + Vector3.new(0, 0.5, 0)
      root.AssemblyLinearVelocity, root.AssemblyAngularVelocity = Vector3.zero, Vector3.zero
      lastRescue, fallTop = now, nil
      Void.rescues += 1
      toast("Back from the void", "Put back where you last stood.")
      return true
    end
    table.remove(spots)      -- the ground there has gone
  end
  return false
end

local function look(now)
  local character = B.character()
  local humanoid = character and character:FindFirstChildOfClass("Humanoid")
  local root = character and character:FindFirstChild("HumanoidRootPart")
  local alive = humanoid ~= nil and root ~= nil and humanoid.Health > 0
  if not alive then
    -- It died with the void switched off, over nothing or under the game's height: the game has
    -- a rule of its own down there. Say so once, rather than leave it looking broken.
    if wasAlive and O.noVoid and not warned and (now - lastOver < 1.5 or (gameHeight ~= nil and lastY < gameHeight + 20)) then
      warned = true
      lastToast = -math.huge
      toast("This game has its own void", "Its scripts kill down there, which cannot be stopped from here. A shorter Catch me after gets you back before it.")
    end
    wasAlive, stoodSince, fallTop = false, nil, nil
    return
  end
  wasAlive, lastY = true, root.Position.Y
  if not O.noVoid then
    stoodSince, fallTop = nil, nil
    return
  end
  local state = humanoid:GetState()
  local airborne = humanoid.FloorMaterial == AIR
  if flying() or humanoid.SeatPart or state == STATE.Swimming or state == STATE.Climbing then
    stoodSince, fallTop = nil, nil
    return
  end
  if not airborne and state ~= STATE.Freefall then
    fallTop = nil
    remember(character, humanoid, root, now)
    return
  end
  stoodSince = nil
  local y = root.Position.Y
  fallTop = math.max(fallTop or y, y)              -- the highest point of this fall
  local caught = gameHeight ~= nil and y < gameHeight          -- where the game itself would have ended it
  if not caught and root.AssemblyLinearVelocity.Y < -4 and fallTop - y > 30 then
    -- falling, and some way into it: is there anything down there at all?
    if not below(root.Position, SEE, character) then
      lastOver = now
      caught = fallTop - y > O.voidDrop
    end
  end
  if caught and O.voidRescue and now >= nowhere and not rescue(character, root, now) then
    nowhere = now + 8
    toast("Nowhere to put you back", "No ground you stood on is left. The void still cannot kill you: fly out of it.")
  end
end

function Void.define()
  Config.define("move.noVoid", true)
  Config.define("move.voidRescue", true)
  Config.define("move.voidDrop", 150)
end

function Void.start()
  if Void.started then return end
  Void.started = true
  Void.define()
  O = Config.mirror({ noVoid = "move.noVoid", voidRescue = "move.voidRescue", voidDrop = "move.voidDrop" })
  Void.options = O
  params = RaycastParams.new()
  params.FilterType = Enum.RaycastFilterType.Exclude
  params.RespectCanCollide = true        -- something that cannot be stood on is not ground
  params.IgnoreWater = false             -- water is somewhere to land
  Config.on("move.noVoid", apply)
  -- the game setting its height again must not bring the void back
  B.connect(workspace:GetPropertyChangedSignal("FallenPartsDestroyHeight"), apply, "void.height")
  apply()
  B.connect(S.RunService.Heartbeat, function(dt)
    clock += dt
    if clock < EVERY then return end
    clock = 0
    look(os.clock())
  end, "void.look")
  B.own(function()
    -- stopped first: giving the height back fires the signal above, which would take it away again
    stopped = true
    if gameHeight ~= nil and unset(workspace.FallenPartsDestroyHeight) then workspace.FallenPartsDestroyHeight = gameHeight end
  end)
end
end
do -- 40_universal.lua
-- ============================================================================
--  40 universal  the tabs every game gets: Combat, Visuals, Movement, Players, World
-- ============================================================================
local S, util, Motion, Theme, T, UI, Config, Window, Controls = B.S, B.util, B.Motion, B.Theme, B.T, B.UI, B.Config, B.Window, B.Controls
local Roster, Esp, Aim, Move, World, Server, Hud = B.Roster, B.Esp, B.Aim, B.Move, B.World, B.Server, B.Hud
local UIS = S.UserInputService
B.pages = B.pages or {}
local GROUP = "Universal"
local firstPage = #B.pages + 1

local function onPage(id) return Window.open and Window.current ~= nil and Window.current.id == id end

-- ---------------------------------------------------------------- the 3D preview
-- Your own character on a turntable, with the real ESP renderer drawing over it.
-- Every switch in the tab changes this picture as you flip it.
local function dummy()
  local model = Instance.new("Model")
  local function block(name, size, position, color)
    local part = Instance.new("Part")
    part.Name = name
    part.Size = size
    part.CFrame = CFrame.new(position)
    part.Anchored = true
    part.Color = color
    part.Material = Enum.Material.SmoothPlastic
    part.TopSurface, part.BottomSurface = Enum.SurfaceType.Smooth, Enum.SurfaceType.Smooth
    part.Parent = model
    return part
  end
  local skin, shirt, trousers = Color3.fromRGB(226, 198, 170), Color3.fromRGB(96, 88, 150), Color3.fromRGB(44, 44, 54)
  block("Head", Vector3.new(1.2, 1.2, 1.2), Vector3.new(0, 4.6, 0), skin)
  local torso = block("Torso", Vector3.new(2, 2, 1), Vector3.new(0, 3, 0), shirt)
  block("Left Arm", Vector3.new(1, 2, 1), Vector3.new(-1.5, 3, 0), skin)
  block("Right Arm", Vector3.new(1, 2, 1), Vector3.new(1.5, 3, 0), skin)
  block("Left Leg", Vector3.new(1, 2, 1), Vector3.new(-0.5, 1, 0), trousers)
  block("Right Leg", Vector3.new(1, 2, 1), Vector3.new(0.5, 1, 0), trousers)
  local root = block("HumanoidRootPart", Vector3.new(2, 2, 1), Vector3.new(0, 3, 0), shirt)
  root.Transparency = 1
  model.PrimaryPart = torso
  return model
end
local function cloneCharacter()
  local character = B.character()
  if not character or not character:FindFirstChild("HumanoidRootPart") then return nil end
  local ok, clone = pcall(function()
    local archivable = character.Archivable
    character.Archivable = true
    local copy = character:Clone()
    character.Archivable = archivable
    return copy
  end)
  if not ok or not clone then return nil end
  for _, item in ipairs(clone:GetDescendants()) do
    if item:IsA("LuaSourceContainer") or item:IsA("Sound") or item:IsA("BillboardGui") or item:IsA("ForceField") or item:IsA("ParticleEmitter") or item:IsA("Tool") then
      item:Destroy()
    elseif item:IsA("BasePart") then
      item.Anchored = true
    end
  end
  local humanoid = clone:FindFirstChildOfClass("Humanoid")
  if humanoid then
    humanoid.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
    humanoid.HealthDisplayType = Enum.HumanoidHealthDisplayType.AlwaysOff
  end
  clone:PivotTo(CFrame.new(0, 3, 0))
  return clone
end

local function preview(frame)
  local stage = UI.frame(frame, { Name = "Stage", Size = UDim2.new(1, -24, 1, -24), Position = UDim2.fromOffset(12, 0), ClipsDescendants = true,
    Theme = { BackgroundColor3 = "ink" }, BackgroundTransparency = 0.965 })
  UI.corner(stage, "rControl")
  UI.gradient(stage, { Rotation = 90, Transparency = UI.alphaSeq(0, 1, 1, 0.9) })
  local viewport = UI.new("ViewportFrame", { Name = "Model", Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, LightColor = Color3.new(1, 1, 1),
    Ambient = Color3.fromRGB(150, 150, 160), LightDirection = Vector3.new(-0.6, -1, -0.8), Parent = stage })
  local world = Instance.new("WorldModel")
  world.Parent = viewport
  local model = cloneCharacter() or dummy()
  model.Parent = world
  local camera = Instance.new("Camera")
  camera.FieldOfView = 30
  camera.Parent = viewport
  viewport.CurrentCamera = camera
  local overlay = UI.frame(stage, { Name = "Overlay", Size = UDim2.fromScale(1, 1), ZIndex = 2 })
  local sample = Esp.Object.new(overlay)
  local arrow = UI.image(overlay, "arrow", { Size = UDim2.fromOffset(18, 18), AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(1, -26, 0, 30), Rotation = 55, Visible = false })
  local hint = UI.text(stage, "drag to turn", "mono", "faint", { TextSize = 10, AnchorPoint = Vector2.new(0.5, 1), Position = UDim2.new(0.5, 0, 1, -8), ZIndex = 3 })

  local entry = Roster.describe(model)
  local centre = (entry.root and entry.root.Position or Vector3.new(0, 3, 0)) + Vector3.new(0, 0.25, 0)
  local yaw, spin, idle = 0.5, 0, 0
  local dragging = false
  local grab = UI.new("TextButton", { Text = "", BackgroundTransparency = 1, AutoButtonColor = false, Size = UDim2.fromScale(1, 1), ZIndex = 5, Parent = stage })
  local lastX
  UI.drag(grab, function(point) dragging = true; lastX = point.X; hint.Visible = false end, function(point)
    local dx = point.X - lastX
    lastX = point.X
    yaw -= dx * 0.012
    spin = -dx * 0.012 / math.max(Motion.dt, 1 / 240)
  end, function() dragging = false; idle = 0 end)

  local info = { joints = {} }
  local joints = {}
  local clock = 0
  Motion.every(function(dt)
    if not stage.Parent or not onPage("visuals") then return end
    clock += dt
    if not dragging then
      -- a flick keeps turning and eases out; left alone, it drifts round slowly
      spin *= math.exp(-dt * 3.2)
      idle += dt
      yaw += spin * dt + (idle > 1.4 and 0.38 * dt or 0)
    end
    local size = stage.AbsoluteSize / UI.unit()
    if size.X < 10 then return end
    -- (a game whose module adds lines under the box gets a smaller figure, higher up: room for them)
    local more = Esp.extras.money ~= nil or Esp.extras.ammo ~= nil
    local distance = more and 18 or 15.5
    local cf = CFrame.new(centre - Vector3.new(0, more and 0.7 or 0, 0)) * CFrame.Angles(0, yaw, 0) * CFrame.new(0, 0, distance)
    camera.CFrame = cf
    local tanHalf = math.tan(math.rad(camera.FieldOfView) * 0.5)
    local aspect = size.X / size.Y
    local function project(point)
      local p = cf:PointToObjectSpace(point)
      local depth = -p.Z
      return (0.5 + p.X / (depth * tanHalf * aspect) * 0.5) * size.X, (0.5 - p.Y / (depth * tanHalf) * 0.5) * size.Y, depth
    end
    local o, on = Esp.options, Esp.want
    local head, root = entry.head, entry.root
    if not root then return end
    local _, topY = project((head and head.Position or root.Position + Vector3.new(0, 1.6, 0)) + Vector3.new(0, 0.85, 0))
    local cx, bottomY = project(root.Position - Vector3.new(0, entry.legs or 3, 0))
    local height = bottomY - topY
    local width = height * 0.56
    info.x, info.y, info.w, info.h = cx - width * 0.5, topY, width, height
    info.color = o.colorMode == "health" and Color3.fromHSV(0.33 * (0.55 + 0.45 * math.sin(clock * 0.9)), 0.75, 1) or o.color
    info.alpha = 1
    info.name = o.displayNames and B.LP.DisplayName or B.LP.Name
    info.distance = 128
    info.health = 0.55 + 0.45 * math.sin(clock * 0.9)
    info.hp = info.health * 100
    info.team = "Red team"
    info.tool = "Classic Sword"
    -- what the game's module adds, with figures of its own for the picture
    local extras = Esp.extras
    local demo = extras.sample or {}
    info.armor, info.armorValue, info.ammo, info.money, info.flags = nil, nil, nil, nil, nil
    if extras.armor then
      info.armor = 0.5 + 0.5 * math.sin(clock * 0.6 + 1.3)
      info.armorValue = info.armor * (demo.armorMax or 100)
    end
    if extras.ammo then info.ammo = demo.ammo or "12/30" end
    if extras.money then info.money = demo.money or "$12,500" end
    if extras.flags then info.flags = demo.flags or "RELOADING" end
    if demo.tool then info.tool = demo.tool end
    if demo.team ~= nil then info.team = demo.team or nil end
    info.joints, info.bones, info.headR, info.lookX, info.originX = nil, nil, nil, nil, nil
    if head then
      local hx, hy, depth = project(head.Position)
      info.headX, info.headY = hx, hy
      info.headR = (head.Size.Y * 0.62) / depth * size.Y / (2 * tanHalf)
      local lx, ly = project(head.Position + head.CFrame.LookVector * 2.2)
      info.lookX, info.lookY = lx, ly
    end
    for name, part in pairs(entry.joints) do
      local jx, jy, depth = project(part.Position)
      local slot = joints[name]
      if not slot then slot = {}; joints[name] = slot end
      slot[1], slot[2], slot[3] = jx, jy, depth > 0
    end
    info.joints, info.bones = joints, entry.bones
    info.originX, info.originY = size.X * 0.5, size.Y
    sample:draw(info, o, on)
    arrow.Visible = on.arrows == true
    arrow.ImageColor3 = info.color
    -- chams cannot draw inside a viewport: tint the model the way the fill would
    local fill = on.chams and (1 - o.chamsFill / 100) or 0
    viewport.ImageColor3 = Color3.new(1, 1, 1):Lerp(info.color, fill * 0.85)
  end, nil, "esp.preview")
end

-- ---------------------------------------------------------------- Visuals
-- the last stop of a distance slider reads as no limit rather than as a number
local function reach(limit)
  return function(v) return v >= limit and "No limit" or (util.comma(v) .. " st") end
end
B.pages[#B.pages + 1] = function()
  Esp.start(); World.start()
  Window.page({ id = "visuals", title = "Visuals", icon = "eye", group = GROUP, order = 220, build = function(page)
    local show = page:section({ title = "Preview", icon = "scan-eye", column = 1, weight = 8 })
    show:custom({ height = 348, build = preview })
    show:toggle({ id = "esp.enabled", label = "Player ESP", desc = "Draws the picture above on every player." })

    local what = page:section({ title = "What to draw", icon = "layers", column = 2, weight = 5 })
    local elements = {
      { "box", "Box", icon = "scan" }, { "name", "Name", icon = "tag" }, { "health", "Health bar", icon = "heart-pulse" }, { "hp", "Health number", icon = "hash" },
      { "distance", "Distance", icon = "ruler" }, { "tool", "Held tool", icon = "sword" }, { "team", "Team name", icon = "flag" }, { "skeleton", "Skeleton", icon = "bone" },
      { "head", "Head ring", icon = "circle" }, { "look", "Look direction", icon = "navigation" }, { "tracer", "Tracer", icon = "route" },
      { "arrows", "Off-screen arrows", icon = "arrow-up-right" }, { "chams", "Chams (through walls)", icon = "ghost" } }
    -- what only this game's module can read of a player: offered when it is there to be read
    for _, extra in ipairs(Esp.EXTRA) do
      if Esp.extras[extra[1]] then table.insert(elements, extra[1] == "armor" and 4 or #elements + 1, extra) end
    end
    what:multi({ id = "esp.elements", label = "Elements", empty = "Nothing", menuWidth = 226, options = elements })
    what:segmented({ id = "esp.box", label = "Box style", options = { { "corners", "Corners" }, { "full", "Full" } }, width = 160 })
    what:toggle({ id = "esp.fill", label = "Fill the box", bindable = false })
    what:slider({ id = "esp.boxWidth", label = "Box width", desc = "As a share of its height.", min = 30, max = 90, step = 1, suffix = "%" })
    what:segmented({ id = "esp.tracerFrom", label = "Tracers start at", options = { { "bottom", "Bottom" }, { "center", "Centre" }, { "top", "Top" }, { "mouse", "Mouse" } }, width = 232 })
    -- and whatever the game's module has to add to this tab, where it is seen
    for _, add in ipairs(Esp.sections) do B.try("visuals.extra", add, page) end

    local style = page:section({ title = "Colour & weight", icon = "palette", column = 2, weight = 5 })
    style:dropdown({ id = "esp.colorMode", label = "Colour by", options = { { "custom", "One colour" }, { "team", "Team colour" }, { "health", "Health" } } })
    style:color({ id = "esp.color", label = "Colour" })
    style:color({ id = "esp.friendColor", label = "Friends" })
    style:toggle({ id = "esp.seenTint", label = "Own colour when in view", desc = "Anyone you have a clear line to. One ray per player, ten times a second.", bindable = false,
      children = function(sub) sub:color({ id = "esp.seenColor", label = "In view" }) end })
    style:toggle({ id = "esp.markTarget", label = "Colour the aim target", desc = "Whoever aim assist is on.", bindable = false,
      children = function(sub) sub:color({ id = "esp.targetColor", label = "Target" }) end })
    style:slider({ id = "esp.thickness", label = "Line weight", min = 0.5, max = 6, step = 0.5, suffix = " px" })
    style:slider({ id = "esp.textSize", label = "Text size", min = 8, max = 32, step = 1, suffix = " px" })
    style:slider({ id = "esp.chamsFill", label = "Chams fill", desc = "0 is solid, 100 is outline only.", min = 0, max = 100, step = 5, suffix = "%" })
    style:toggle({ id = "esp.chamsOutline", label = "Chams outline", bindable = false })

    local who = page:section({ title = "Who and how far", icon = "filter", column = 1, weight = 4 })
    who:toggle({ id = "esp.teamCheck", label = "Hide teammates", bindable = false })
    who:toggle({ id = "esp.displayNames", label = "Show display names", bindable = false })
    who:slider({ id = "esp.range", label = "Range", desc = "All the way right is no limit.", min = 50, max = Esp.FAR, step = 50, curve = 3.2, valueWidth = 84, format = reach(Esp.FAR) })
    who:slider({ id = "esp.nameRange", label = "Names within", desc = "Further off, only the box and the distance: less to read on a full map.", min = 50, max = Esp.FAR, step = 50,
      curve = 3.2, valueWidth = 84, format = reach(Esp.FAR) })
    who:slider({ id = "esp.skeletonRange", label = "Skeleton range", desc = "Skeletons are the costliest element: keep them near.", min = 25, max = 10000, step = 25, curve = 3,
      valueWidth = 84, format = function(v) return util.comma(v) .. " st" end })
    who:slider({ id = "esp.minSize", label = "Smallest box", desc = "Far players are never drawn smaller than this, so they stay findable.", min = 0, max = 40, step = 1,
      format = function(v) return v <= 0 and "Off" or (util.format(v, 0) .. " px") end })
    who:slider({ id = "esp.maxPlayers", label = "Draw at most", desc = "The nearest first.", min = 1, max = Esp.EVERYONE, step = 1,
      format = function(v) return v >= Esp.EVERYONE and "Everyone" or (util.format(v, 0) .. (v == 1 and " player" or " players")) end, valueWidth = 84 })
    who:toggle({ id = "esp.fade", label = "Fade with distance", bindable = false, children = function(sub)
      sub:slider({ id = "esp.fadeFrom", label = "Starting at", desc = "How far along the range it begins.", min = 0, max = 95, step = 5, suffix = "%" })
    end })
    who:toggle({ id = "esp.dimHidden", label = "Dim players behind walls", desc = "One ray per player, ten times a second.", bindable = false })
    who:toggle({ id = "esp.hideHidden", label = "Only players in view", desc = "Leaves out anyone behind a wall.", bindable = false })

    local arrows = page:section({ title = "Off-screen arrows", icon = "arrow-up-right", column = 1, weight = 3 })
    arrows:slider({ id = "esp.arrowSize", label = "Size", min = 10, max = 48, step = 1, suffix = " px" })
    arrows:slider({ id = "esp.arrowRadius", label = "Distance from centre", min = 10, max = 48, step = 1, suffix = "%" })
    arrows:toggle({ id = "esp.arrowDistance", label = "Say how far", bindable = false })

    local light = page:section({ title = "World", icon = "sun", column = 1, weight = 4 })
    light:toggle({ id = "world.fullbright", label = "Fullbright", desc = "No shadows, flat daylight.", children = function(sub)
      sub:slider({ id = "world.brightValue", label = "Brightness", min = 1, max = 6, step = 0.25 })
    end })
    light:toggle({ id = "world.noFog", label = "No fog" })
    light:toggle({ id = "world.time", label = "Lock the time of day", children = function(sub)
      sub:slider({ id = "world.timeValue", label = "Hour", min = 0, max = 24, step = 0.25 })
    end })

    local cam = page:section({ title = "Camera", icon = "camera", column = 2, weight = 4 })
    cam:toggle({ id = "world.fov", label = "Field of view", children = function(sub)
      sub:slider({ id = "world.fovValue", label = "Degrees", desc = "Low is a scope, 120 is the widest the engine draws.", min = 5, max = 120, step = 1, suffix = "°" })
    end })
    cam:toggle({ id = "world.zoom", label = "Zoom out further", children = function(sub)
      sub:slider({ id = "world.zoomValue", label = "Max distance", min = 20, max = 20000, step = 10, curve = 3, valueWidth = 84, format = function(v) return util.comma(v) .. " st" end })
    end })

    local cross = page:section({ title = "Crosshair", icon = "crosshair", column = 2, weight = 5 })
    cross:custom({ height = 84, build = function(frame)
      local box = UI.frame(frame, { Size = UDim2.new(1, -24, 1, -8), Position = UDim2.fromOffset(12, 0), Theme = { BackgroundColor3 = "black" }, BackgroundTransparency = 0.55,
        ClipsDescendants = true })
      UI.corner(box, "rControl")
      local sample = World.makeCrosshair(box)
      local function paint() World.styleCrosshair(sample, World.options) end
