    aim:toggle({ id = "dahood.salvo", label = "Salvo", desc = "Each gun's next shot goes at someone else in reach.", default = true, children = function(sub)
      sub:slider({ id = "dahood.salvoWait", label = "Salvo hold time", desc = "How long a held shot may wait for one that stands.", min = 0, max = SALVO_WAIT, step = 0.05, default = SALVO_WAIT, suffix = " s" })
    end })
    aim:toggle({ id = "dahood.pipeline", label = "Chain knocks", desc = "Shoots another while a body is not ready to stomp.", default = true })
    aim:toggle({ id = "dahood.walls", label = "Wallbang hiders", desc = "Aims just outside a wall at one hiding in it.", default = true })
    extend("ragebot", page)

