    between:dropdown({ id = "dahood.wait", label = "Lurk in", desc = "Where you are between strikes.",
      options = { { "void", "The void" }, { "cloud", "A cloud round the target" }, { "cyclone", "A cyclone round the target" } }, default = "void" })
    between:slider({ id = "dahood.cloud", label = "Cloud & cyclone size", min = 40, max = 5000, step = 10, default = 150, curve = 3, suffix = " st" })

    local void = page:section({ title = "The void", icon = "cloud-fog", desc = "Far out and high up, where nobody can hit you." })
    void:toggle({ id = "dahood.hide", label = "Vanish into the void", desc = "Sends you to the void. Off: back where you stood.", default = false })
    void:toggle({ id = "dahood.voidRoam", label = "Roam the void", desc = "A new side of the map every frame, not one corner.", default = true })
    void:slider({ id = "dahood.voidFar", label = "Void distance", desc = "Held at a billion studs.", min = 5000, max = VOID_MAX, step = 1000, default = 40000, curve = 6, valueWidth = 110, format = studs })
    void:slider({ id = "dahood.voidJitter", label = "Void jumps", desc = "It never stays on one spot there.", min = 500, max = 10000000, step = 500, default = 6000, curve = 4, valueWidth = 110, format = studs })
    void:slider({ id = "dahood.voidHigh", label = "Void height", min = VOID_FLOOR, max = 1000000, step = 500, default = VOID_FLOOR, curve = 3, valueWidth = 110, format = studs })
    void:note({ icon = "info", text = "Nobody can hit you there. Knocked, you cannot go anywhere." })

    local spy = page:section({ title = "Ghost mode", icon = "ghost", desc = "A copy of you that only you see, while your body is away." })
    spy:toggle({ id = "dahood.ghost", label = "Ghost walk", desc = "It walks, runs and jumps as you do.", default = true })
    spy:slider({ id = "dahood.ghostSpeed", label = "Speed", desc = "The game walks at 16 and sprints at 22.", min = 16, max = 400, step = 1, default = 24, curve = 2.5, suffix = " st/s" })
    spy:toggle({ id = "dahood.ghostFly", label = "Ghost flight", desc = "Space up, Left Ctrl down, through walls.", default = false })
    spy:slider({ id = "dahood.ghostAlpha", label = "See-through", desc = "0: it looks like you.", min = 0, max = 95, step = 5, default = 0, suffix = "%" })
    spy:segmented({ id = "dahood.ghostReturn", label = "When off, return to", options = { { "ghost", "Where you walked" }, { "home", "Where it stood" } }, default = "ghost",
      width = 230 })

    local spam = page:section({ title = "Void spam", icon = "zap", desc = "Flick between the void and where you stood." })
    spam:toggle({ id = "dahood.spam", label = "Void spam", desc = "Flicks between the void and where you stood.", default = false })
    spam:slider({ id = "dahood.spamAt", label = "Time on the map", min = 0.02, max = 3, step = 0.01, default = 0.45, suffix = " s" })
    spam:slider({ id = "dahood.spamVoid", label = "Time in the void", min = 0.02, max = 3, step = 0.01, default = 0.15, suffix = " s" })
    spam:note({ icon = "info", text = "A stay under 0.12 s is never seen by the server." })
    extend("movement", page)
  end })
end

local function loadoutPage(hub)
  hub:page({ id = "loadout", title = "Arsenal", icon = "package", build = function(page)
    local buying = page:section({ title = "Auto restock", icon = "gem", desc = "Buys what you run out of." })
    buying:toggle({ id = "dahood.autoGuns", label = "Restock guns", desc = "Whenever one is missing.", default = true })
    buying:toggle({ id = "dahood.autoAmmo", label = "Restock ammo", desc = "When a gun is under one magazine in reserve.", default = true })
    buying:slider({ id = "dahood.mags", label = "Spare mags", min = 1, max = 50, step = 1, default = 3 })
    buying:slider({ id = "dahood.reloadBelow", label = "Reload when below", desc = "Reloads in the void below this. Never over a held shot.", min = 0, max = 100, step = 5, default = 100, suffix = "%" })
    buying:toggle({ id = "dahood.autoArmor", label = "Restock armor", desc = "High-Medium Armor (130).", default = true, children = function(sub)
      sub:slider({ id = "dahood.armorBelow", label = "When armor is under", min = 10, max = 130, step = 5, default = 100 })
    end })

    local owned = page:section({ title = "In hand", icon = "box" })
    local line = owned:note({ icon = "info", text = "" })
    Motion.every(function()
      if not (line.frame.Parent and Window.anyOpen()) then return end
      local DH = B.DaHood
      local parts = {}
      for _, gun in ipairs(GUNS) do
        if table.find(DH.options.guns, gun.name) then
          local tool = DH.tool(gun.name)
          local ammo, max = tool and tool:FindFirstChild("Ammo"), tool and tool:FindFirstChild("MaxAmmo")
          parts[#parts + 1] = gun.label .. ": " .. (tool and string.format("%s / %s, %d in reserve", ammo and tostring(ammo.Value) or "?", max and tostring(max.Value) or "?", DH.reserve(gun.name)) or "not owned")
        end
      end
      line.set((#parts > 0 and table.concat(parts, "\n") or "No gun chosen.") .. "\nCash: $" .. util.comma(DH.cash()))
    end, 2, "dahood.owned")
    extend("loadout", page)
  end })
end

local function playerPage(hub)
  hub:page({ id = "player", title = "Player", icon = "footprints", build = function(page)
    local DH = B.DaHood
    local about = page:section({ title = "Movement boosts", icon = "zap", desc = "For your own body, while the ragebot is off." })
    about:toggle({ id = "dahood.speed", label = "Speed boost", desc = "Added to where you stand. Walk speed is left alone: the game hangs if it is raised.", default = false, children = function(sub)
      sub:slider({ id = "dahood.speedValue", label = "Studs a second", desc = "The game gives 16 walking, 22 sprinting.", min = 20, max = 400, step = 1, default = 60, curve = 2, suffix = " st/s" })
      sub:toggle({ id = "dahood.speedWalls", label = "Stop at walls", desc = "Off: goes through them.", default = true })
    end })
    about:toggle({ id = "dahood.jump", label = "Super jump", desc = "The game gives 50. Not while the game says no jumping.", default = false, children = function(sub)
      sub:slider({ id = "dahood.jumpValue", label = "Jump power", desc = "The game caps upward speed at 80 with its Anti-fling on.", min = 50, max = 250, step = 1, default = 75 })
    end })
    about:toggle({ id = "dahood.airJump", label = "Air jump", desc = "Space jumps again in the air.", default = false })
    about:toggle({ id = "dahood.back", label = "Respawn where you fell", desc = "Your next body is put where the last one went down.", default = false })

    page:custom(nil, function(frame)
      local card = UI.surface(frame, { Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y })
      UI.stroke(card, "ink", "strokeA")
      local stack = UI.frame(card, { Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y })
      UI.list(stack, "y", 0)
      local top = UI.frame(stack, { Name = "Top", Size = UDim2.new(1, 0, 0, 52), LayoutOrder = 0 })
      local count = UI.text(top, "Players", "heading", "ink", { Position = UDim2.new(0, 16, 0.5, 0), AnchorPoint = Vector2.new(0, 0.5) })
      local own = Controls.pillButton(top, "Back to yourself", nil, function() DH.watch(nil) end)
      own.Name = "Own"
      own.AnchorPoint, own.Position = Vector2.new(1, 0.5), UDim2.new(1, -14, 0.5, 0)
      local list = UI.frame(stack, { Name = "List", Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 1 })
      UI.list(list, "y", 0)
      UI.pad(list, 0, 0, 6, 0)
      local rows = {}
      local function rebuild()
        for _, row in ipairs(rows) do row.frame:Destroy() end
        table.clear(rows)
        local players = S.Players:GetPlayers()
        table.sort(players, function(a, b) return string.lower(a.Name) < string.lower(b.Name) end)
        local watched = DH.watching()
        for index, player in ipairs(players) do
          if player ~= B.LP then
            local row = UI.frame(list, { Name = player.Name, Size = UDim2.new(1, 0, 0, 46), LayoutOrder = index })
            UI.frame(row, { Size = UDim2.new(1, -28, 0, 1), Position = UDim2.fromOffset(14, 0), Theme = { BackgroundColor3 = "ink", BackgroundTransparency = "strokeA" } })
            local face = UI.new("ImageLabel", { Size = UDim2.fromOffset(30, 30), Position = UDim2.new(0, 14, 0.5, 0), AnchorPoint = Vector2.new(0, 0.5), BackgroundTransparency = 0.9,
              Theme = { BackgroundColor3 = "ink" }, Image = "rbxthumb://type=AvatarHeadShot&id=" .. player.UserId .. "&w=150&h=150", Parent = row })
            UI.corner(face, true)
            UI.text(row, player.DisplayName, "label", "ink", { Position = UDim2.fromOffset(56, 6), Size = UDim2.new(1, -330, 0, 18), AutomaticSize = Enum.AutomaticSize.None,
              TextTruncate = Enum.TextTruncate.AtEnd })
            UI.text(row, "@" .. player.Name, "caption", "faint", { Position = UDim2.fromOffset(56, 24), Size = UDim2.new(1, -330, 0, 16), AutomaticSize = Enum.AutomaticSize.None,
              TextTruncate = Enum.TextTruncate.AtEnd, TextSize = 11.5 })
            local away = UI.text(row, "", "mono", "sub", { Name = "Away", AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -176, 0.5, 0) })
            local view = Controls.pillButton(row, watched == player and "Viewing" or "View", watched == player and "primary" or nil, function() DH.watch(player) end)
            view.Name = "Watch"
            view.AnchorPoint, view.Position = Vector2.new(1, 0.5), UDim2.new(1, -72, 0.5, 0)
            local go = Controls.pillButton(row, "Go", nil, function()
              local ok, why = DH.goTo(player)
              if not ok then Window.toast({ title = "Not moved", text = why, icon = "triangle-alert", tone = "warn" }) end
            end)
            go.Name = "GoTo"
            go.AnchorPoint, go.Position = Vector2.new(1, 0.5), UDim2.new(1, -14, 0.5, 0)
            rows[#rows + 1] = { frame = row, player = player, away = away }
          end
        end
        count.Text = #rows == 0 and "No one else is here" or (watched and ("Viewing " .. watched.DisplayName) or "Players")
        own.Visible = watched ~= nil
      end
      local waiting = false
      local function soon()
        if waiting then return end
        waiting = true
        task.delay(0.1, function()
          waiting = false
          if list.Parent then rebuild() end
        end)
      end
      DH.onTargets:connect(soon)
      DH.onWatch:connect(soon)
      rebuild()
      Motion.every(function()
        if not (list.Parent and Window.anyOpen()) then return end
        local mine = B.root()
        for _, row in ipairs(rows) do
          local character = row.player.Character
          local theirs = character and character:FindFirstChild("HumanoidRootPart")
          row.away.Text = (mine and theirs) and (util.comma(math.floor((theirs.Position - mine.Position).Magnitude + 0.5)) .. " st") or ""
        end
      end, 4, "dahood.players")
    end, unnamedPlayers)

    extend("player", page)

    local places = page:section({ title = "Teleports", icon = "map-pin", desc = "Shop pads, by what they sell." })
    local kinds = {}
    for _, item in ipairs(DH.places()) do kinds[#kinds + 1] = { item, item } end
    if #kinds == 0 then kinds[1] = { "", "The shop has not loaded" } end
    -- (a pad chosen before that this map does not have is not kept)
    local chosen = Config.get("dahood.place")
    local known = false
    for _, kind in ipairs(kinds) do known = known or kind[1] == chosen end
    if not known then Config.set("dahood.place", kinds[1][1], true) end
    places:dropdown({ id = "dahood.place", label = "Shop pad", options = kinds, default = "" })
    places:button({ id = "dahood.placeGo", label = "Teleport", text = "Go", run = function()
      local ok, why = DH.goToPlace(Config.get("dahood.place"))
      if not ok then Window.toast({ title = "Not moved", text = why, icon = "triangle-alert", tone = "warn" }) end
    end })

    local stay = page:section({ title = "Stay online", icon = "shield-check" })
    stay:toggle({ id = "world.antiAfk", label = "Anti-AFK", desc = "Stops the 20 minute idle kick. On by default.", bindable = false })
    local line = stay:note({ icon = "activity", text = "" })
    Motion.every(function()
      if not (line.frame.Parent and Window.anyOpen()) then return end
      local afk = B.World and B.World.afk
      if not afk then return end
      if not Config.get("world.antiAfk") then
        line.set("Off: left alone for twenty minutes, you will be dropped.")
      elseif afk.answered == 0 then
        line.set("On. Nothing to answer yet: you have not been idle.")
      else
        local gone = os.clock() - afk.last
        line.set(string.format("On. Answered %d time%s, the last %s ago.", afk.answered, afk.answered == 1 and "" or "s", gone < 90 and (math.floor(gone) .. " s") or (math.floor(gone / 60) .. " min")))
      end
    end, 1, "dahood.afk")
  end })
end

local function displayPage(hub)
  hub:page({ id = "display", title = "HUD", icon = "eye", build = function(page)
    local view = page:section({ title = "Camera", icon = "camera" })
    view:segmented({ id = "dahood.view", label = "Camera follows", desc = "Auto: the target while it is shot at, you the rest of the time.",
      options = { { "auto", "Auto" }, { "target", "Target" }, { "home", "Yourself" } }, default = "auto", width = 210 })
    view:toggle({ id = "dahood.hudStatus", label = "Status line", desc = "What it is doing, mid screen.", default = true })
    view:toggle({ id = "dahood.hudFeed", label = "Kill feed", desc = "Each kill, top left.", default = true })
    view:toggle({ id = "dahood.hudHits", label = "Hits in the feed", desc = "A line for every hit.", default = true })
    view:toggle({ id = "dahood.hudTargets", label = "Target list", desc = "Who it is on and who is next, under the status.", default = true })
    view:toggle({ id = "dahood.desync", label = "Show server body", desc = "A box where the others see your body.", default = false })

    local shots = page:section({ title = "Shot effects", icon = "zap" })
    shots:toggle({ id = "dahood.tracers", label = "Bullet tracers", default = true, children = function(sub)
      sub:color({ id = "dahood.tracerColor", label = "Colour", default = Color3.fromRGB(255, 45, 45) })
      sub:slider({ id = "dahood.tracerLife", label = "Stay for", min = 0.05, max = 5, step = 0.05, default = 0.35, suffix = " s" })
    end })
    shots:toggle({ id = "dahood.tint", label = "World tint", desc = "Only while it runs.", default = false, children = function(sub)
      sub:color({ id = "dahood.tintColor", label = "Colour", default = Color3.fromRGB(255, 120, 120) })
    end })
    extend("display", page)
  end })
end

B.game({
  id = "dahood",
  name = "Da Hood",
  tagline = "Hunt. Farm. Vanish.",
  universes = { 1008451066 },
  places = { 2788229376 },
  icon = "crosshair",
  universal = { "visuals" },          -- ESP and the rest of that tab; nothing else of Universal starts
  tabs = function(hub)
    start(hub)
    for _, part in ipairs(DH.parts) do
      if part.start then B.try("dahood." .. part.id, part.start, hub) end
    end
    ragebotPage(hub)
    movementPage(hub)
    playerPage(hub)
    loadoutPage(hub)
    extend("page", hub)
    displayPage(hub)
