})
end
do -- dahood_cash.lua
-- ============================================================================
--  Da Hood     the cash round
--
--  Breaks the cashiers and picks up what falls out of them. Run by hand, or by
--  the ragebot itself in the time it has to spare: all of it when it cannot pay
--  for a gun, and otherwise the seconds before a dead target can be hurt again.
--
--  Measured on the live server (2026-10-12, version 3267, two accounts):
--    * workspace.Cashiers holds 29 "CA$HIER" with a Humanoid of 100 health. A
--      gun hurts one: a Rifle shot took 99, one Double-Barrel shell 115.5. The
--      shooter has to be in range (refused from 1,147 studs). The vaults are left
--      alone: eleven shells at one were all taken and did nothing.
--    * Fists do too: a light punch 6.3 to 8.1, a punch held 1.6 s 70 (held 1.2 s
--      it is a light one). About 5 s a cashier.
--    * A broken one drops four "MoneyDrop" parts in the same frame, 3.8 to 4.7
--      studs from it ($225 to $500 each). A click on one counts from 14 studs
--      (20 was refused), not for the first 0.05 s after arriving, and only one
--      pick-up is taken every 0.52 s: clicks every 0.1 s took the four at 0.07,
--      0.69, 1.21 and 1.73 s after the break.
--    * A cashier is whole again 240.0 s after it broke.
--  So a round of all of them is about 70 s for some $43,000, every four minutes.
--
--  Fists are what it uses unless guns are asked for. On 2026-10-13 the second
--  account was kicked by the game (its message: "Stop.", error 267) 17 s into a
--  round with a shotgun, about a cashier every two seconds. With its fists, a
--  cashier every eight or nine seconds, it had done eight minutes of rounds that
--  day and was not. Which of the two it was (the gun, or how fast) was not found
--  out: that would have taken more kicks.
-- ============================================================================
local B = B or ...
local S, util, Motion, Config, Window = B.S, B.util, B.Motion, B.Config, B.Window
local DH = B.DaHood

local REACH = 11             -- studs from a drop a click on it is made from: 14 was taken, 20 refused
local CLICK_EVERY = 0.06     -- s between clicks on a drop: one that is refused costs nothing
local PICK_GAP = 0.52        -- s between two pick-ups the server takes
local RESPAWN = 240          -- s until a broken cashier is whole again
local STAND = 6              -- studs from a cashier it is shot from: its drops fall 3.8 to 4.7 studs from it
local FIST = 3.4             -- and punched from (3.6 was taken)
local CHARGE = 1.65          -- s a punch is held to be the heavy one
local RETRY = 0.07           -- s between two tries of a shot, at the least
local SETTLE = 0.16          -- s after arriving until the server is taken to have the body there (less, if the ragebot has timed it as less)
local LEAST = 2.6            -- s one cashier takes with a gun at the most: with less to spare none is begun
local LEAST_FIST = 7         -- and with fists
local GIVE_UP = 60           -- s a cashier that could not be broken is left alone
local OTHER_SIDE = 3         -- s before another side of one is tried, after a stay that took nothing off it
local NO_USE = 2.6           -- s of punching that takes nothing off a cashier before the stay is given up
local SIDES = {}
for index = 0, 7 do
  local turn = index * math.pi / 4
  SIDES[#SIDES + 1] = Vector3.new(math.cos(turn), 0, math.sin(turn))
end

local farm = { LEAST = LEAST, earned = 0, broken = 0, picked = 0, status = nil, PICK_GAP = PICK_GAP, RESPAWN = RESPAWN }
DH.farm = farm

local function start()
  local api = DH.api
  local LP = B.LP
  local O
  -- (kept for good: a table that forgets loses a cashier's time with nothing else holding it)
  local downAt = {}                                     -- per cashier: when it was seen broken
  local bad = {}                                        -- per cashier: until when it is left alone
  local skipped = {}                                    -- per drop: until when it is left alone
  local sides = {}                                      -- per cashier: the sides of it a stay took nothing from
  local worked = {}                                     -- per cashier: the side it was last broken from (it is the same one when it comes back)
  local noReload = {}                                   -- per gun: until when a reload that did nothing is not asked for again
  local shotAt = {}                                     -- per gun: when it last fired at a cashier
  local lastAt                                          -- where the last one worked on stands
  local began, beganCash                                -- when this run started, and with how much
  local params = RaycastParams.new()
  params.FilterType = Enum.RaycastFilterType.Exclude
  params.IgnoreWater = true

  local map = {}
  for id, default in pairs({ cash = false, cashAuto = true, cashGoal = 0, cashTool = "fists", cashLoose = true, cashAvoid = 40, cashWait = "void", cashGrab = false }) do
    Config.define("dahood." .. id, default)
    map[id] = "dahood." .. id
  end
  -- never armed by a saved setting: it moves the character the moment it is on
  if Config.get("dahood.cash") then Config.set("dahood.cash", false) end
  O = Config.mirror(map)
  farm.options = O

  local function running() return B.alive and (DH.on or O.cash) end
  -- waits, and says whether the round is still meant to be going
  local function rest(seconds)
    local untilAt = os.clock() + seconds
    repeat task.wait() until os.clock() >= untilAt or not running()
    return running()
  end
  local function say(text)
    farm.status = text
    api.setStatus(text)
  end

  -- ---------------------------------------------------------------- what is on the map
  local function cashiers()
    local out = {}
    local folder = workspace:FindFirstChild("Cashiers")
    for _, model in ipairs(folder and folder:GetChildren() or {}) do
      if model.Name == "CA$HIER" then
        local humanoid, head = model:FindFirstChildOfClass("Humanoid"), model:FindFirstChild("Head")
        if humanoid and head and head:IsA("BasePart") then
          local whole = humanoid.Health > 0
          if whole then downAt[model] = nil elseif not downAt[model] then downAt[model] = os.clock() end
          out[#out + 1] = { model = model, humanoid = humanoid, head = head, whole = whole }
        end
      end
    end
    return out
  end
  -- a drop that is gone is forgotten (they come and go by the hundred)
  local function forget()
    for drop in pairs(skipped) do
      if not drop.Parent then skipped[drop] = nil end
    end
  end
  local function drops()
    forget()
    local ignored = workspace:FindFirstChild("Ignored")
    local folder = ignored and ignored:FindFirstChild("Drop")
    local out = {}
    for _, item in ipairs(folder and folder:GetChildren() or {}) do
      if item.Name == "MoneyDrop" and item:IsA("BasePart") and item:FindFirstChildOfClass("ClickDetector") then out[#out + 1] = item end
    end
    return out
  end
  -- is anyone else standing within `reach` of there? (someone knocked or dead is nobody)
  local function crowded(position, reach)
    if reach <= 0 then return false end
    for _, player in ipairs(S.Players:GetPlayers()) do
      if player ~= LP then
        local state = DH.stateOf(player)
        local character = player.Character
        local root = character and character:FindFirstChild("HumanoidRootPart")
        if root and (state == "up" or state == "shield") and (root.Position - position).Magnitude <= reach then return true end
      end
    end
    return false
  end
  farm.cashiers, farm.drops, farm.crowded = cashiers, drops, crowded
  -- s until a broken one is whole again (at the most, for one that was broken before it was first seen)
  function farm.left(model, now)
    local at = downAt[model]
    return at and math.max(0, at + RESPAWN - (now or os.clock())) or nil
  end
  -- how many are whole, how many there are, and how long until the next one is
  function farm.count()
    local whole, soonest = 0, nil
    local list = cashiers()
    local now = os.clock()
    for _, cashier in ipairs(list) do
      if cashier.whole then whole += 1 else
        local left = math.max(0, (downAt[cashier.model] or now) + RESPAWN - now)
        if not soonest or left < soonest then soonest = left end
      end
    end
    return whole, #list, soonest
  end

  -- ---------------------------------------------------------------- what to break one with
  -- every gun that is on us with a round in it, the hardest shot first
  local function loaded(me)
    local out = {}
    if O.cashTool == "fists" then return out end
    for _, kind in ipairs(DH.GUNS) do
      local tool = api.myTool(kind.name)
      if tool and tool:FindFirstChild("Handle") and api.numberOf(tool, "Ammo", 0) > 0 then
        out[#out + 1] = { name = kind.name, tool = tool, hits = kind.hits or 1, cooldown = api.numberOf(tool, "ShootingCooldown", kind.cooldown),
          shot = api.numberOf(tool, "Damage", kind.damage) * (kind.hits or 1) }
      end
    end
    table.sort(out, function(a, b) return a.shot > b.shot end)
    local _ = me
    return out
  end
  local function fists() return (api.myTool("Combat")) end
  -- "gun", "fist" or nil
  local function weapon(me)
    if #loaded(me) > 0 then return "gun" end
    return fists() and "fist" or nil
  end
  farm.weapon = function() local me = B.character(); return me and weapon(me) or nil end

  -- Where to stand for a cashier: on a floor beside it with nothing between the body and its Head,
  -- the side nearest its own height first (its drops fall beside it, and have to be in reach).
  local function standFor(cashier, distance)
    local me = B.character()
    local centre = cashier.model:GetBoundingBox().Position
    local best
    local tried = sides[cashier.model]
    local known = worked[cashier.model]
    for index, side in ipairs(SIDES) do
      local at = centre + side * distance
      params.FilterDescendantsInstances = { me, cashier.model, api.folder }
      local floor = workspace:Raycast(at + Vector3.new(0, 3, 0), Vector3.new(0, -14, 0), params)
      if floor then
        local feet = Vector3.new(at.X, floor.Position.Y + 3, at.Z)
        local eye = feet + Vector3.new(0, 1.5, 0)
        params.FilterDescendantsInstances = { me, api.folder }
        local hit = workspace:Raycast(eye, cashier.head.Position - eye, params)
        if hit and hit.Instance:IsDescendantOf(cashier.model) and not (tried and tried[index]) then
          -- (the side it was broken from before, before any other)
          local score = math.abs(feet.Y - centre.Y) - (index == known and 1000 or 0)
          if not best or score < best.score then best = { at = feet, score = score, centre = centre, side = index } end
        end
      end
    end
    return best, centre
  end

  -- With a gun: the hardest loaded shot, sent again every RETRY until the round count answers,
  -- then the next gun (or the same one when its cooldown is over) until the cashier is broken.
  -- The first try goes out when the server is taken to have the body there, not before (sent on
  -- arriving and every 0.07 s after, the tries at 0, 0.07, 0.13 and 0.20 s were refused and the one
  -- at 0.24 taken). A try that is taken is answered a trip there and back later: the next waits
  -- for that, or a second shell goes into a cashier the first has already broken (a shotgun's
  -- second shot is held by the server and fired a cooldown later).
  local function shootDown(cashier, deadline)
    local me, pack = B.character(), LP:FindFirstChildOfClass("Backpack")
    local lastGun, lastFire, misses, useless = nil, -math.huge, 0, 0
    if not rest(math.min(DH.lag or SETTLE, SETTLE) + 0.02) then return false end
    while cashier.humanoid.Health > 0 and os.clock() < deadline and running() do
      local root = B.root()
      if not (root and me.Parent) then return false end
      local now = os.clock()
      local pick
      for _, gun in ipairs(loaded(me)) do
        local ready = (shotAt[gun.name] or -math.huge) + gun.cooldown + DH.rate.margin
        if lastGun and lastGun ~= gun.name then ready = math.max(ready, lastFire + DH.gap(lastGun, gun.name)) end
        if ready <= now then pick = gun; break end
      end
      if not pick then
        if #loaded(me) == 0 then return false end
        task.wait()
      else
        -- the first tool in the hand has to be a gun, or the server takes no shot at all
        if pack then
          for _, item in ipairs(me:GetChildren()) do
            if item:IsA("Tool") and not api.GUN[item.Name] then item.Parent = pack end
          end
        end
        if pick.tool.Parent ~= me then pick.tool.Parent = me end
        local before, was = api.numberOf(pick.tool, "Ammo", 0), cashier.humanoid.Health
        api.send(pick, root.Position + Vector3.new(0, 1.5, 0), cashier.head.Position, cashier.head)
        local sent = os.clock()
        local gap = math.max(RETRY, (DH.answer or (api.ping() * 2 + 0.05)) + 0.04)
        repeat task.wait() until api.numberOf(pick.tool, "Ammo", 0) < before or cashier.humanoid.Health <= 0 or os.clock() - sent >= gap
        if api.numberOf(pick.tool, "Ammo", 0) < before then
          local at = os.clock()
          shotAt[pick.name], lastGun, lastFire, misses = at, pick.name, at, 0
          -- (on the ragebot's own books too: it plans its next strike by when each gun last fired)
          api.fired[pick.name] = { at = at, shots = 1, step = pick.cooldown + DH.rate.margin }
          api.estimate[pick.name] = nil
          -- A shot the server took shows on the cashier with it. Two that took nothing off it:
          -- something is in the way, and every one more is a round thrown away.
          local seen = os.clock()
          while cashier.humanoid.Health >= was - 0.5 and os.clock() - seen < 0.25 and running() do task.wait() end
          if cashier.humanoid.Health >= was - 0.5 then
            useless += 1
            if useless >= 2 then return false end
          end
        else
          misses += 1
          if misses > 14 then return false end
        end
      end
    end
    return cashier.humanoid.Health <= 0
  end
  -- Nothing loaded, and a gun with rounds in reserve: it is reloaded. Only on its own: with the
  -- ragebot on the ragebot reloads, in the void and never over a shot the server is holding.
  local function reload(me)
    if O.cashTool == "fists" or #loaded(me) > 0 then return false end
    local remote, pack = api.mainEvent(), LP:FindFirstChildOfClass("Backpack")
    if not remote then return false end
    local now = os.clock()
    local pick, hardest
    for _, kind in ipairs(DH.GUNS) do
      local tool = api.myTool(kind.name)
      if tool and tool:FindFirstChild("Handle") and api.numberOf(tool, "MaxAmmo", 0) > 0 and api.reserve(kind.name) > 0 and not (noReload[kind.name] and noReload[kind.name] > now) then
        local shot = api.numberOf(tool, "Damage", kind.damage) * (kind.hits or 1)
        if not hardest or shot > hardest then pick, hardest = tool, shot end
      end
    end
    if not pick then return false end
    say("cash: reloading")
    -- (it is reloaded in the hand, and a gun has to be the first thing there)
    if pack then
      for _, item in ipairs(me:GetChildren()) do
        if item:IsA("Tool") and not api.GUN[item.Name] then item.Parent = pack end
      end
    end
    if pick.Parent ~= me then pick.Parent = me end
    local before, began, seen = api.numberOf(pick, "Ammo", 0), os.clock(), false
    remote:FireServer("Reload", pick)
    while os.clock() - began < 5 and running() do
      task.wait()
      local busy = api.flagOf(api.effectsOf(B.character()), "Reload")
      seen = seen or busy
      if not busy and (api.numberOf(pick, "Ammo", 0) > before or (not seen and os.clock() - began > 0.7)) then break end
    end
    if api.numberOf(pick, "Ammo", 0) <= before then noReload[pick.Name] = os.clock() + 20 end
    api.estimate[pick.Name] = nil
    farm.reloads = (farm.reloads or 0) + 1
    return true
  end
  -- With fists: one heavy punch, then light ones as fast as they go.
  local function punchDown(cashier, deadline)
    local me, humanoid = B.character(), B.humanoid()
    local combat = fists()
    if not (me and humanoid and combat) then return false end
    local effects = api.effectsOf(me)
    humanoid:EquipTool(combat)
    if not rest(0.35) then return false end
    if cashier.humanoid.Health > 30 then
      combat:Activate()
      local ok = rest(CHARGE)
      combat:Deactivate()
      if not (ok and rest(0.45)) then return false end
    end
    -- (a punch that lands shows on the cashier at once: NO_USE of punching with nothing to show is given up)
    local least, since = cashier.humanoid.Health, os.clock()
    while cashier.humanoid.Health > 0 and os.clock() < deadline and running() do
      if cashier.humanoid.Health < least - 0.5 then least, since = cashier.humanoid.Health, os.clock() end
      if os.clock() - since > NO_USE then break end
      if not api.flagOf(effects, "Attacking") then
        combat:Activate()
        task.wait(0.03)
        combat:Deactivate()
      end
      task.wait()
    end
    humanoid:UnequipTools()
    return cashier.humanoid.Health <= 0
  end

  -- Every drop within `radius` of `around`, the nearest to the body first: a click every
  -- CLICK_EVERY until it is gone (the server takes one pick-up in half a second).
  local function collect(around, radius, deadline)
    local took = 0
    while os.clock() < deadline and running() do
      local root = B.root()
      if not root then break end
      local now = os.clock()
      local best, bestAway
      for _, drop in ipairs(drops()) do
        if (drop.Position - around).Magnitude <= radius and not (skipped[drop] and skipped[drop] > now) then
          local away = (drop.Position - root.Position).Magnitude
          if not bestAway or away < bestAway then best, bestAway = drop, away end
        end
      end
      if not best then break end
      if bestAway > REACH then
        -- over it: a move of a few studs is the same place to the server
        api.pin("spot", best.Position + Vector3.new(0, 3.2, 0))
        if bestAway > REACH + 9 and not rest(math.max(api.lag(), 0.16)) then break end
      end
      local detector = best:FindFirstChildOfClass("ClickDetector")
      local tried = os.clock()
      while best.Parent and detector and os.clock() < deadline and os.clock() - tried < 2.2 and running() do
        fireclickdetector(detector)
        if not rest(CLICK_EVERY) then break end
      end
      if best.Parent then skipped[best] = os.clock() + 20 else
        took += 1
        farm.picked += 1
      end
    end
    return took
  end
  farm.collect = collect

  -- the nearest whole cashier nobody is standing at
  local function nextCashier(from)
    local now = os.clock()
    local best, bestAway
    for _, cashier in ipairs(cashiers()) do
      if cashier.whole and not (bad[cashier.model] and bad[cashier.model] > now) and not crowded(cashier.head.Position, O.cashAvoid) then
        local away = (cashier.head.Position - from).Magnitude
        if not bestAway or away < bestAway then best, bestAway = cashier, away end
      end
    end
    return best
  end
  -- loose cash that nobody is standing at, the nearest first
  local function strayDrop(from)
    local now = os.clock()
    local best, bestAway
    for _, drop in ipairs(drops()) do
      if not (skipped[drop] and skipped[drop] > now) and not crowded(drop.Position, O.cashAvoid) then
        local away = (drop.Position - from).Magnitude
        if not bestAway or away < bestAway then best, bestAway = drop, away end
      end
    end
    return best
  end

  function farm.wanted()
    if type(fireclickdetector) ~= "function" then return false end
    return O.cash or (O.cashAuto and DH.broke ~= nil)
  end
  -- One cashier, or one lot of loose cash, inside `spare` seconds. True when something was done.
  function farm.visit(spare)
    local me, root = B.character(), B.root()
    if not (me and root) then return false end
    local from = lastAt or (api.home() and api.home().Position) or root.Position
    local kind = weapon(me)
    local need = kind == "gun" and LEAST or LEAST_FIST
    local cashier = kind and spare >= need and nextCashier(from) or nil
    local before = api.cash()
    local started = os.clock()
    if cashier then
      local stand, centre = standFor(cashier, kind == "gun" and STAND or FIST)
      if not stand then
        bad[cashier.model] = started + GIVE_UP
        return true
      end
      local deadline = started + math.min(spare, kind == "gun" and 6 or 12) - 0.25
      local healthWas = cashier.humanoid.Health
      say("cash: breaking a cashier" .. (kind == "fist" and " (fists)" or ""))
      lastAt = centre
      api.focus.CFrame = CFrame.new(centre)
      api.pin("spot", stand.at, Vector3.new(centre.X, stand.at.Y, centre.Z))
      local broke
      if kind == "gun" then broke = shootDown(cashier, deadline) else
        broke = rest(math.max(api.lag(), 0.2)) and punchDown(cashier, deadline)
      end
      if broke then
        farm.broken += 1
        downAt[cashier.model] = os.clock()
        say("cash: picking up")
        -- (what falls out is on this client a frame or two after the cashier is seen to break:
        -- seen live, the first one of a round was left with all four lying there)
        local seen = os.clock()
        local function fallen()
          for _, drop in ipairs(drops()) do
            if (drop.Position - centre).Magnitude <= 16 then return true end
          end
          return false
        end
        while not fallen() and os.clock() - seen < 0.6 and running() do task.wait() end
        sides[cashier.model] = nil
        worked[cashier.model] = stand.side
        collect(centre, 16, math.max(deadline, os.clock() + math.min(2.4, math.max(spare - (os.clock() - started) - 0.2, 0))))
      elseif cashier.humanoid.Health > 0 and running() and cashier.humanoid.Health >= healthWas - 0.5 then
        -- Nothing taken off it in the whole stay: that side of it is no good (seen live: fists at
        -- one cashier for two minutes and more with not a point off it). Another side next time;
        -- and when no side is left, it is left alone for as long as a broken one takes to come back.
        local tried = sides[cashier.model]
        if not tried then tried = {}; sides[cashier.model] = tried end
        tried[stand.side] = true
        local left = 0
        for index = 1, #SIDES do
          if not tried[index] then left += 1 end
        end
        bad[cashier.model] = os.clock() + (left > 0 and OTHER_SIDE or RESPAWN)
        if left == 0 then sides[cashier.model] = nil end
        farm.gaveUp = (farm.gaveUp or 0) + 1
      elseif cashier.humanoid.Health > 0 and os.clock() >= deadline - 0.05 and kind == "gun" then
        bad[cashier.model] = os.clock() + GIVE_UP        -- shot at for the whole stay and still standing: something is in the way
      end
    elseif O.cashLoose and spare >= 1.2 then
      local drop = strayDrop(from)
      if not drop then return false end
      say("cash: picking up loose cash")
      lastAt = drop.Position
      api.focus.CFrame = CFrame.new(drop.Position)
      api.pin("spot", drop.Position + Vector3.new(0, 3.2, 0))
      if rest(math.max(api.lag(), 0.16)) then collect(drop.Position, 14, started + math.min(spare, 6) - 0.2) end
    else
      return false
    end
    farm.earned += math.max(0, api.cash() - before)
    if DH.on then api.pin("void") end
    return true
  end

  -- On its own (the ragebot off): cashier after cashier, and somewhere out of the way in between.
  function farm.step()
    local me, root, humanoid = B.character(), B.root(), B.humanoid()
    local effects = api.effectsOf(me)
    if not (me and root and humanoid and effects) or humanoid.Health <= 0 or api.flagOf(effects, "Dead") or not me:FindFirstChild("FULLY_LOADED_CHAR") then
      api.pin(nil)
      say("cash: respawning")
      return
    end
    if api.flagOf(effects, "K.O") then
      api.pin(nil)
      say("cash: knocked")
      return
    end
    if humanoid:GetStateEnabled(Enum.HumanoidStateType.Seated) then humanoid:SetStateEnabled(Enum.HumanoidStateType.Seated, false) end
    if O.cashGoal > 0 and api.cash() >= O.cashGoal then
      Window.toast({ title = "Cash round done", text = "$" .. util.comma(api.cash()) .. " in hand.", icon = "gem", tone = "ok" })
      Config.set("dahood.cash", false)
      return
    end
    local home = api.home()
    -- (a reload takes a second or two: out of the way for it)
    if #loaded(me) == 0 and O.cashTool ~= "fists" then
      local dry = false
      for _, kind in ipairs(DH.GUNS) do
        local tool = api.myTool(kind.name)
        if tool and api.reserve(kind.name) > 0 and not (noReload[kind.name] and noReload[kind.name] > os.clock()) then dry = true end
      end
      if dry then
        if O.cashWait == "void" or not home then api.pin("void") else api.pin("spot", home.Position) end
        if reload(me) then return end
      end
    end
    if farm.visit(30) then return end
    local whole, total, soonest = farm.count()
    if O.cashWait == "void" or not home then api.pin("void") else api.pin("spot", home.Position) end
    if not weapon(me) then say("cash: no loaded gun and no fists")
    elseif whole > 0 then say("cash: " .. whole .. " of " .. total .. " up, someone is at each")
    else say(string.format("cash: next cashier in %d s", math.ceil(soonest or RESPAWN))) end
  end

  local function switch(on)
    if on then
      if not (api.mainEvent() and api.arm()) then
        Window.toast({ title = "The cash round needs a spawned character", icon = "triangle-alert", tone = "warn" })
        task.defer(function() Config.set("dahood.cash", false) end)
        return
      end
      began, beganCash = os.clock(), api.cash()
      farm.began = began
      lastAt = nil
      DH.farming = true
      api.camera()
    elseif DH.farming then
      DH.farming = false
      farm.status = nil
      local humanoid = B.humanoid()
      if humanoid then pcall(function() humanoid:UnequipTools() end) end
      if not DH.on and not DH.hiding then
        api.pin(nil)
        api.release()
      end
    end
  end
  Config.on("dahood.cash", switch)
  B.onUnload:connect(function() DH.farming = false end)
  local _ = beganCash

  -- Cash near the player's own feet, while nothing here is moving the body: one drop in reach is
  -- clicked every CLICK_EVERY (the server takes one in half a second anyway).
  task.spawn(function()
    while B.alive do
      if O.cashGrab and not api.moving() and type(fireclickdetector) == "function" then
        local root = B.root()
        if root then
          local best, bestAway
          for _, drop in ipairs(drops()) do
            local away = (drop.Position - root.Position).Magnitude
            if away <= REACH and (not bestAway or away < bestAway) then best, bestAway = drop, away end
          end
          local detector = best and best:FindFirstChildOfClass("ClickDetector")
          if detector then
            local before = api.cash()
            B.try("dahood.grab", fireclickdetector, detector)
            task.wait(CLICK_EVERY)
            if api.cash() > before then
              farm.earned += api.cash() - before
              farm.picked += 1
            end
          end
        end
      end
      task.wait(O.cashGrab and CLICK_EVERY or 0.5)
    end
  end)
end

local function page(hub)
  hub:page({ id = "cash", title = "Cash", icon = "gem", build = function(page)
    local round = page:section({ title = "Cash farm", icon = "gem", desc = "Breaks cashiers and picks up what falls." })
    round:toggle({ id = "dahood.cash", label = "Start the farm", desc = "With the ragebot on, it goes between kills. Never on at launch." })
    round:toggle({ id = "dahood.cashAuto", label = "Farm when broke", desc = "The ragebot does a round by itself when it cannot pay.", default = true })
    round:slider({ id = "dahood.cashGoal", label = "Stop at", desc = "The farm stops at this much cash.", min = 0, max = 2000000, step = 5000, default = 0, curve = 2.4, valueWidth = 96,
      format = function(v) return v <= 0 and "Never" or ("$" .. util.comma(v)) end })
    local line = round:note({ icon = "activity", text = "" })

    local how = page:section({ title = "Farm style", icon = "wrench" })
    how:segmented({ id = "dahood.cashTool", label = "Break ATMs with", desc = "Guns are faster. A test account was kicked 17 s into a round with one.", options = { { "fists", "Fists" }, { "auto", "Guns" } }, default = "fists", width = 150 })
    how:toggle({ id = "dahood.cashLoose", label = "Grab loose cash", desc = "Picks up cash lying about the map.", default = true })
    how:slider({ id = "dahood.cashAvoid", label = "Avoid players within", desc = "Skips a cashier with someone this near. 0: never.", min = 0, max = 300, step = 5, default = 40, suffix = " st" })
    how:segmented({ id = "dahood.cashWait", label = "Wait in", desc = "While every cashier is broken.", options = { { "void", "The void" }, { "home", "Home" } }, default = "void", width = 150 })
    how:note({ icon = "info", text = "Fists: about 8 s a cashier. Each comes back after 4 minutes." })

    local own = page:section({ title = "On foot", icon = "footprints" })
    own:toggle({ id = "dahood.cashGrab", label = "Cash magnet", desc = "Picks up any cash within reach as you walk.", default = false })

    Motion.every(function()
      if not (line.frame.Parent and Window.anyOpen()) then return end
      local farm = B.DaHood.farm
      local whole, total, soonest = farm.count()
      local text = string.format("Cash $%s    earned $%s    %d broken    %d picked up", util.comma(B.DaHood.cash()), util.comma(farm.earned), farm.broken, farm.picked)
      if farm.began and farm.earned > 0 and B.DaHood.farming then
        local hours = math.max(os.clock() - farm.began, 1) / 3600
        text = text .. string.format("    $%s an hour", util.comma(farm.earned / hours))
      end
      text = text .. string.format("\nCashiers up: %d of %d%s", whole, total, (soonest and whole < total) and string.format(", the next in %d s", math.ceil(soonest)) or "")
      if B.DaHood.broke then text = text .. "\nShort of $" .. util.comma(B.DaHood.broke) .. " for what the ragebot needs." end
      line.set(text)
    end, 2, "dahood.cash")
  end })
end

DH.parts[#DH.parts + 1] = { id = "cash", start = start, page = page }
end
do -- dahood_esp.lua
-- ============================================================================
--  Da Hood     what ESP can read here, and marks on the map
--
--  Everything below is replicated to every client by the game itself (read on
--  2026-10-12, version 3267, one account looking at the other):
--    BodyEffects.Armor (130 with High-Medium Armor on) and FireArmor, the flags
--    K.O / Dead / Reload / Attacking / Grabbed / Cuff, a "Block" child while
--    blocking, a GRABBING_CONSTRAINT on a body that is being carried, the Ammo
--    and MaxAmmo of the tool in a hand, DataFolder.Currency and
--    leaderstats.Wanted.
--  And on the map: the cashiers (whole or broken, and since when) and cash
--  lying on the ground with what it is worth.
-- ============================================================================
local B = B or ...
local S, util, UI, Config = B.S, B.util, B.UI, B.Config
local DH = B.DaHood
local Esp = B.Esp

local ARMOR_FULL = 130       -- High-Medium Armor
local MARKS = 60             -- cashiers and drops marked at once, at the most (the nearest)
local AIM_NEAR = 6           -- studs from this body that someone's mouse point has to be, for them to be aiming at it

local function money(amount)
  if amount >= 999500 then return string.format("$%.1fM", amount / 1e6) end
  if amount >= 9950 then return string.format("$%.0fk", amount / 1000) end
  return "$" .. util.comma(amount)
end

local function start()
  local api = DH.api
  local LP = B.LP
  local O
  local map = {}
  for id, default in pairs({ espCashiers = false, espDrops = false, espWorldRange = 600, espCashierColor = Color3.fromRGB(126, 231, 135), espDropColor = Color3.fromRGB(255, 209, 102) }) do
    Config.define("dahood." .. id, default)
    map[id] = "dahood." .. id
  end
  O = Config.mirror(map)
  -- Once: the armor bar, the ammo and the flags join whatever was already drawn here, so they are
  -- seen without being looked for. After that the list is the player's own again.
  Config.define("dahood.espAdded", false)
  if not Config.get("dahood.espAdded") and type(Config.get("esp.elements")) == "table" then
    local list = table.clone(Config.get("esp.elements"))
    for _, name in ipairs({ "armor", "ammo", "flags" }) do
      if not table.find(list, name) then list[#list + 1] = name end
    end
    Config.set("esp.elements", list)
    Config.set("dahood.espAdded", true)
  end

  -- ---------------------------------------------------------------- what ESP reads of a player
  local extras = Esp.extras
  function extras.armor(entry)
    local character = entry.character
    if not character then return nil end
    local effects = api.effectsOf(character)
    local fire = effects and effects:FindFirstChild("FireArmor")
    local value = api.armorOf(character) + (fire and tonumber(fire.Value) or 0)
    return math.clamp(value / ARMOR_FULL, 0, 1), value
  end
  function extras.ammo(entry)
    local character = entry.character
    local tool = character and character:FindFirstChildOfClass("Tool")
    local ammo = tool and tool:FindFirstChild("Ammo")
    if not ammo then return nil end
    local max = tool:FindFirstChild("MaxAmmo")
    return tostring(ammo.Value) .. "/" .. tostring(max and max.Value or "?")
  end
  function extras.money(entry)
    local player = entry.player
    if not player then return nil end
    local data = player:FindFirstChild("DataFolder")
    local cash = data and data:FindFirstChild("Currency")
    local stats = player:FindFirstChild("leaderstats")
    local wanted = stats and stats:FindFirstChild("Wanted")
    local text = cash and money(tonumber(cash.Value) or 0) or nil
    local level = wanted and tonumber(wanted.Value) or 0
    if level > 0 then text = (text and (text .. "  ·  ") or "") .. "wanted " .. util.comma(level) end
    return text
  end
  function extras.flags(entry)
    local character = entry.character
    if not character then return nil end
    local effects = api.effectsOf(character)
    local out = {}
    -- Their mouse is on this body, with a gun out. (BodyEffects.MousePos is where each player's
    -- mouse points, sent to every client: read on 2026-10-14.)
    local mouse = effects and effects:FindFirstChild("MousePos")
    local tool = character:FindFirstChildOfClass("Tool")
    local mine = not api.moving() and B.root()
    if mine and mouse and tool and tool:FindFirstChild("Ammo") and typeof(mouse.Value) == "Vector3" and (mouse.Value - mine.Position).Magnitude <= AIM_NEAR then out[#out + 1] = "AIMING AT YOU" end
    if api.flagOf(effects, "K.O") then out[#out + 1] = "KNOCKED" end
    if character:FindFirstChild("GRABBING_CONSTRAINT") then out[#out + 1] = "CARRIED" end
    if character:FindFirstChildOfClass("ForceField") then out[#out + 1] = "SHIELD" end
    if effects then
      local grabbed = effects:FindFirstChild("Grabbed")
      if grabbed and grabbed.Value ~= nil then out[#out + 1] = "CARRYING" end
      if effects:FindFirstChild("Block") then out[#out + 1] = "BLOCKING" end
      if api.flagOf(effects, "Reload") then out[#out + 1] = "RELOADING" end
      if api.flagOf(effects, "Attacking") then out[#out + 1] = "SWINGING" end
      if api.flagOf(effects, "Cuff") then out[#out + 1] = "CUFFED" end
    end
    if entry.player and DH.isMarked(entry.player) then out[#out + 1] = "MARKED" end
    if #out == 0 then return nil end
    return table.concat(out, "\n", 1, math.min(#out, 4))
  end
  extras.sample = { armorMax = ARMOR_FULL, ammo = "2/2", money = "$12.4k  ·  wanted 585", flags = "RELOADING\nMARKED", tool = "[Double-Barrel SG]", team = false }

  -- ---------------------------------------------------------------- marks on the map
  local gui = B.screen(7990)
  local layer = UI.frame(gui, { Name = "World", Size = UDim2.fromScale(1, 1) })
  local pool, used = {}, 0
  local function label()
    used += 1
    local item = pool[used]
    if not item then
      item = UI.new("TextLabel", { BackgroundTransparency = 1, AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(180, 14), FontFace = B.F.mono500, TextSize = 11,
        TextStrokeColor3 = Color3.new(0, 0, 0), TextStrokeTransparency = 0.45, Text = "", Visible = false, Parent = layer })
      pool[used] = item
    end
    return item
  end
  local found = {}
  local function nearer(a, b) return a.away < b.away end
  local function step()
    used = 0
    local camera = workspace.CurrentCamera
    if camera and (O.espCashiers or O.espDrops) then
      local from = camera.CFrame.Position
      local now = os.clock()
      table.clear(found)
      if O.espCashiers and DH.farm and DH.farm.cashiers then
        for _, cashier in ipairs(DH.farm.cashiers()) do
          local away = (cashier.head.Position - from).Magnitude
          if away <= O.espWorldRange then found[#found + 1] = { at = cashier.head.Position, away = away, cashier = cashier } end
        end
      end
      if O.espDrops and DH.farm and DH.farm.drops then
        for _, drop in ipairs(DH.farm.drops()) do
          local away = (drop.Position - from).Magnitude
          if away <= O.espWorldRange then found[#found + 1] = { at = drop.Position, away = away, drop = drop } end
        end
      end
      if #found > MARKS then table.sort(found, nearer) end
      for index = 1, math.min(#found, MARKS) do
        local thing = found[index]
        local point = camera:WorldToViewportPoint(thing.at)
        if point.Z > 0 then
          local item = label()
          local text, color, alpha
          if thing.cashier then
            if thing.cashier.whole then
              text, color, alpha = string.format("ATM  %s st", util.studs(thing.away)), O.espCashierColor, 0.05
            else
              local left = DH.farm.left and DH.farm.left(thing.cashier.model, now)
              text, color, alpha = left and string.format("ATM  back in %d s", math.ceil(left)) or "ATM  broken", O.espCashierColor, 0.55
            end
          else
            local tag = thing.drop:FindFirstChildWhichIsA("TextLabel", true)
            text, color, alpha = string.format("%s  %s st", tag and tag.Text or "cash", util.studs(thing.away)), O.espDropColor, 0.05
          end
          if item.Text ~= text then item.Text = text end
          item.TextColor3 = color
          item.TextTransparency = alpha
          item.Position = UDim2.fromOffset(point.X, point.Y)
          if not item.Visible then item.Visible = true end
        end
      end
    end
    for index = used + 1, #pool do
      if pool[index].Visible then pool[index].Visible = false end
    end
  end
  B.connect(S.RunService.RenderStepped, step, "dahood.world")
  local _ = LP
end

-- its own section on the Visuals tab
Esp.sections[#Esp.sections + 1] = function(page)
  if not (B.Registry and B.Registry.active and B.Registry.active.id == "dahood") then return end
  local world = page:section({ title = "Da Hood ESP", icon = "map-pin", column = 2, weight = 4, desc = "Marks on the map. Armor, ammo, cash and flags are under Elements." })
  world:toggle({ id = "dahood.espCashiers", label = "ATM finder", desc = "Every ATM: whole, or how long until it is.", default = false, children = function(sub)
    sub:color({ id = "dahood.espCashierColor", label = "Colour", default = Color3.fromRGB(126, 231, 135) })
  end })
  world:toggle({ id = "dahood.espDrops", label = "Cash drops", desc = "Each drop and what it is worth.", default = false, children = function(sub)
    sub:color({ id = "dahood.espDropColor", label = "Colour", default = Color3.fromRGB(255, 209, 102) })
  end })
  world:slider({ id = "dahood.espWorldRange", label = "Within", min = 50, max = 3000, step = 50, default = 600, curve = 2, suffix = " st" })
end

DH.parts[#DH.parts + 1] = { id = "esp", start = start }
end
do -- dahood_fly.lua
-- ============================================================================
--  Da Hood     flight: the universal flight's clips, booms, trails and sounds,
--              carried the way this game takes it
--
--  The universal flight (src/26_flight.lua) carries the body with a LinearVelocity and
--  an AlignOrientation and parks the humanoid in a state of its own. Here it does none of
--  that (Flight.body = "frame"): the body is put where it should be every frame, the way
--  the ragebot has carried it in this game every day, with its velocity held at zero. Its
--  path is looked along first, so no speed carries it through a wall or the floor; it is
--  never lower than 60 studs over the height at which the game takes a body to have fallen
--  out of the world; walk speed and jump power are not touched. The same fourteen clips,
--  the same booms at every Mach tier, the launch, the trails, the wind and the timed
--  landing. It stands aside while the ragebot, the void or the cash round has the body.
-- ============================================================================
local B = B or ...
local Config, Motion, util = B.Config, B.Motion, B.util
local DH = B.DaHood

local function start()
  local Flight = B.Flight
  if not Flight then return end
  Flight.body = "frame"
  Flight.flag = "dahood.fly"
  Flight.blocked = function() return DH.on or DH.hiding or DH.farming == true end
  Flight.start()
end

local function studs(v) return util.comma(math.floor(v + 0.5)) .. " st/s" end

local function player(page)
  local Flight = B.Flight
  if not (Flight and Flight.started) then return end
  local fly = page:section({ title = "Flight", icon = "plane", desc = "Fly with the universal flight's moves, built for Da Hood." })
  local live = fly:note({ icon = "gauge", text = "" })
  Motion.every(function()
    if not (live.frame and live.frame.Parent) then return end
    if not (B.Window.anyOpen and B.Window.anyOpen()) then return end
    local label, speed, mach = Flight.status()
    local text = label
    if Flight.state == "flying" then text = string.format("%s  ·  %s%s", label, studs(speed or 0), (mach or 0) >= 1 and string.format("  ·  Mach %.1f", mach) or "") end
    if (DH.on or DH.hiding or DH.farming == true) and Config.get("dahood.fly") then text = "Waiting: the ragebot has your body" end
    live.set(text)
  end, 6, "dahood.fly.live")
  fly:toggle({ id = "dahood.fly", label = "Take flight", desc = "Hold Space on the ground to charge, let go to launch." })
  fly:slider({ id = "move.flySpeed", label = "Cruise speed", min = 10, max = 5000, step = 5, curve = 3.5, valueWidth = 88, format = studs })
  fly:slider({ id = "fly.top", label = "Top speed", desc = "What a held boost builds up to.", min = 100, max = 100000, step = 25, curve = 4, valueWidth = 96, format = studs })
  fly:multi({ id = "fly.idles", label = "Hover poses", desc = "Pick one, or several to take turns.", empty = "Float", menuWidth = 210, options = {
    { "a", "Float", icon = "feather" }, { "b", "Menace", icon = "swords" }, { "c", "Arms crossed", icon = "shield" }, { "d", "On watch", icon = "binoculars" } } })
  fly:toggle({ id = "fly.autoLand", label = "Land on the way down", desc = "Fly down at the ground to land, feet first.", bindable = false })
  fly:note({ icon = "info", text = "WASD steers, Space climbs, Left Ctrl comes down, Left Shift boosts. Nothing is added to your body: walls and the floor stop you at any speed." })

  local boom = page:section({ title = "Launch & sonic boom", icon = "rocket" })
  boom:slider({ id = "fly.chargeTime", label = "Full charge", desc = "How long Space is held for the strongest launch.", min = 0.2, max = 10, step = 0.1, curve = 2, suffix = " s" })
  boom:slider({ id = "fly.launch", label = "Launch power", min = 100, max = 20000, step = 10, curve = 3.5, valueWidth = 88, format = studs })
  boom:slider({ id = "fly.rampTime", label = "Time to top speed", min = 0.5, max = 60, step = 0.25, curve = 2, suffix = " s" })
  boom:slider({ id = "fly.sonic", label = "Sonic boom at", desc = "Mach 1. Every doubling past it booms again, bigger.", min = 150, max = 100000, step = 25, curve = 4,
    valueWidth = 96, format = studs })

  local look = page:section({ title = "Flight effects & sound", icon = "sparkles" })
  look:multi({ id = "fly.effects", label = "Effects", empty = "None", menuWidth = 244, options = {
    { "sonic", "Sonic booms", icon = "zap" }, { "lines", "Mach 2+ screen effects", icon = "scan-line" }, { "takeoff", "Launch burst", icon = "rocket" },
    { "boost", "Charge and boost rings", icon = "circle-dot" }, { "trails", "Limb trails", icon = "spline" }, { "streaks", "Wind streaks", icon = "wind" },
    { "haze", "Pressure wave", icon = "droplets" }, { "crater", "Landing crater", icon = "mountain" }, { "shake", "Camera shake and bank", icon = "vibrate" },
    { "fov", "Speed field of view", icon = "aperture" } } })
  look:color({ id = "fly.trailColor", label = "Trail colour" })
  look:toggle({ id = "fly.sound", label = "Flight sounds", bindable = false, children = function(sub)
    sub:slider({ id = "fly.volume", label = "Volume", min = 0, max = 150, step = 5, suffix = "%" })
  end })
  look:toggle({ id = "fly.animations", label = "Flight animations", desc = "R15 only. Off, or on R6, the body simply leads head first.", bindable = false })
  look:keybind({ id = "fly.key.boost", label = "Boost key", default = "LeftShift" })
  look:keybind({ id = "fly.key.down", label = "Descend key", default = "LeftControl" })
end

DH.parts[#DH.parts + 1] = { id = "fly", start = start, player = player }
end
do -- dahood_fx.lua
-- ============================================================================
--  Da Hood     what a hit looks and sounds like
--
--  The server tells this client of every hit it counted ("HitMarker", and
--  whether it was the head), whoever fired it: the ragebot or the player. On
--  each one: a sound from the pack, a mark where the body is (or mid screen),
--  and the damage as a figure, read off the health and armor the body lost.
--  A knock gets a sound and a mark of its own. All of it is this client's own:
--  nobody else hears or sees any of it.
--
--  The sounds are made by based/tools/hitsounds.py from sines, sweeps and
--  noise: nobody's recording.
-- ============================================================================
local B = B or ...
local S, util, Motion, UI, Config, Window, Assets = B.S, B.util, B.Motion, B.UI, B.Config, B.Window, B.Assets
local DH = B.DaHood

local HIT_SOUNDS = { { "off", "None" }, { "tick", "Tick" }, { "pop", "Pop" }, { "blip", "Blip" }, { "clack", "Clack" }, { "snap", "Snap" }, { "chirp", "Chirp" },
  { "thud", "Thud" }, { "punch", "Punch" }, { "bell", "Bell" }, { "ding", "Ding" }, { "glass", "Glass" }, { "coin", "Coin" }, { "zap", "Zap" } }
local KNOCK_SOUNDS = { { "off", "None" }, { "kill_chime", "Chime" }, { "kill_bass", "Bass drop" }, { "kill_coins", "Coins" }, { "kill_gong", "Gong" }, { "kill_sweep", "Sweep" },
  { "bell", "Bell" }, { "glass", "Glass" }, { "punch", "Punch" } }
local STYLES = { { "cross", "Cross" }, { "plus", "Plus" }, { "ring", "Ring" }, { "burst", "Burst" }, { "square", "Square" } }
local VOICES = 3             -- copies of a sound: quick hits overlap instead of cutting each other off
local STREAK = 1.2           -- s between hits that still count as one run: the pitch climbs along it
local SEEN = 0.4             -- s either side of the server's word in which a body's loss is taken to be that hit
local MARKS = 28             -- marks and figures on screen at once, at the most

local fx = { hits = 0, knocks = 0, HIT_SOUNDS = HIT_SOUNDS, KNOCK_SOUNDS = KNOCK_SOUNDS, STYLES = STYLES }
DH.fx = fx

local function start()
  local api = DH.api
  local LP = B.LP
  local O
  -- The player's own sounds: any .mp3, .ogg or .wav put in BasedHub/hitsounds is offered beside
  -- the pack, under its file name. (They stay on this machine: nothing here sends them anywhere.)
  fx.own = 0
  local has = {}
  for _, file in ipairs(B.fs.list(B.fs.path("hitsounds"))) do
    local base, kind = string.match(file, "([^/]+)%.(%w+)$")
    kind = kind and string.lower(kind)
    if base and (kind == "mp3" or kind == "ogg" or kind == "wav") then
      local label = string.gsub(string.gsub(base, "^Nebula_", ""), "_", " ")
      local key = "file:" .. base .. "." .. kind
      HIT_SOUNDS[#HIT_SOUNDS + 1] = { key, label }
      KNOCK_SOUNDS[#KNOCK_SOUNDS + 1] = { key, label }
      has[key] = true
      fx.own += 1
    end
  end
  local map = {}
  for id, default in pairs({ hitSound = "tick", headSound = has["file:Nebula_RustHeadshot.mp3"] and "file:Nebula_RustHeadshot.mp3" or "glass", knockSound = "kill_chime",
    hitVolume = 60, hitPitch = true, marker = true, markerStyle = "cross",
    markerSize = 16, markerTime = 0.4, markerWorld = true, markerColor = Color3.fromRGB(255, 255, 255), markerHead = Color3.fromRGB(255, 209, 102),
    markerKnock = Color3.fromRGB(255, 84, 84), damage = true, card = true, shotSound = "off", shotVolume = 50, muteGuns = "auto", muteAll = false, muteHit = true }) do
    Config.define("dahood." .. id, default)
    map[id] = "dahood." .. id
  end
  O = Config.mirror(map)
  fx.options = O
  -- (a sound that was chosen and is not there any more: its file was taken away)
  for _, id in ipairs({ "hitSound", "headSound", "knockSound", "shotSound" }) do
    local chosen = O[id]
    if type(chosen) == "string" and string.sub(chosen, 1, 5) == "file:" and not has[chosen] then Config.set("dahood." .. id, id == "shotSound" and "off" or "tick", true) end
  end

  -- ---------------------------------------------------------------- sound
  local host
  local voices = {}
  local function play(name, volume, speed)
    if not name or name == "off" or volume <= 0 then return false end
    local id
    if string.sub(name, 1, 5) == "file:" then id = Assets.id("hitsounds/" .. string.sub(name, 6)) else id = Assets.sound("hit_" .. name) end
    if not id then return false end
    if not (host and host.Parent) then
      host = Instance.new("Folder")
      host.Name = util.randomName()
      host.Parent = S.SoundService
      B.own(host)
      table.clear(voices)
    end
    local set = voices[name]
    if not set then set = { at = 0 }; voices[name] = set end
    set.at = set.at % VOICES + 1
    local sound = set[set.at]
    if not sound then
      sound = Instance.new("Sound")
      sound.SoundId = id
      sound.Parent = host
      set[set.at] = sound
    end
    sound.Volume = volume
    sound.PlaybackSpeed = speed or 1
    sound:Play()
    return true
  end
  fx.play = function(name) return play(name, O.hitVolume / 100, 1) end

  -- ---------------------------------------------------------------- marks
  local layer = UI.frame(api.gui, { Name = "Hits", Size = UDim2.fromScale(1, 1) })
  local live = {}              -- marks and figures being drawn: { frame, world, dx, dy, rise }
  local function bar(parent, color, angle)
    local frame = Instance.new("Frame")
    frame.BorderSizePixel = 0
    frame.AnchorPoint = Vector2.new(0.5, 0.5)
    frame.BackgroundColor3 = color
    frame.Rotation = angle
    local edge = Instance.new("UIStroke")
    edge.Color = Color3.new(0, 0, 0)
    edge.Transparency = 0.55
    edge.Thickness = 1
    edge.Parent = frame
    frame.Parent = parent
    return frame, edge
  end
  -- One mark: its pieces spread and fade over `life`. `world` keeps it on a place in the game
  -- as the view moves; without one it sits where it was put on screen.
  local function mark(style, color, size, life, x, y, world)
    while #live >= MARKS do
      local old = table.remove(live, 1)
      old.dead = true
      old.frame:Destroy()
    end
    local holder = UI.frame(layer, { Name = "Mark", Size = UDim2.fromOffset(0, 0), Position = UDim2.fromOffset(x, y) })
    local entry = { frame = holder, world = world }
    live[#live + 1] = entry
    local pieces = {}
    local ring, ringEdge
    if style == "ring" then
      ring = Instance.new("Frame")
      ring.BackgroundTransparency = 1
      ring.AnchorPoint = Vector2.new(0.5, 0.5)
      ring.Position = UDim2.fromOffset(0, 0)
      UI.corner(ring, true)
      ringEdge = Instance.new("UIStroke")
      ringEdge.Color = color
      ringEdge.Thickness = math.max(1.5, size * 0.13)
      ringEdge.Parent = ring
      ring.Parent = holder
    else
      local count = style == "burst" and 8 or 4
      local turn = (style == "cross" or style == "square") and 45 or (style == "burst" and 22.5 or 0)
      for index = 1, count do
        local angle = turn + (index - 1) * (360 / count)
        local piece, edge = bar(holder, color, style == "square" and angle + 90 or angle)
        pieces[index] = { piece, edge, math.rad(angle) }
      end
    end
    local thick = math.max(2, math.floor(size * 0.16 + 0.5))
    Motion.tween(math.max(life, 0.08), Motion.ease.outCubic, function(p)
      if entry.dead then return end
      local fade = p * p
      if ring then
        local across = size * (0.7 + 1.5 * p)
        ring.Size = UDim2.fromOffset(across, across)
        ringEdge.Transparency = fade
      else
        local out = size * (style == "burst" and (0.5 + 1.1 * p) or (0.42 + 0.5 * p))
        local long = size * (style == "burst" and 0.42 or (style == "square" and 0.9 or 0.62)) * (1 - 0.35 * p)
        for _, item in ipairs(pieces) do
          local piece, edge, angle = item[1], item[2], item[3]
          piece.Size = UDim2.fromOffset(long, thick)
          piece.Position = UDim2.fromOffset(math.cos(angle) * out, math.sin(angle) * out)
          piece.BackgroundTransparency = fade
          edge.Transparency = 0.55 + 0.45 * fade
        end
      end
    end, function()
      entry.dead = true
      local at = table.find(live, entry)
      if at then table.remove(live, at) end
      holder:Destroy()
    end)
    return entry
  end
  -- a figure that rises from where it was put and fades
  local function figure(text, color, x, y, world, size)
    while #live >= MARKS do
      local old = table.remove(live, 1)
      old.dead = true
      old.frame:Destroy()
    end
    local label = UI.new("TextLabel", { Name = "Figure", BackgroundTransparency = 1, AnchorPoint = Vector2.new(0.5, 1), Size = UDim2.fromOffset(160, 22),
      Position = UDim2.fromOffset(x, y), FontFace = B.F.text700, TextSize = size or 15, Text = text, TextColor3 = color, TextStrokeColor3 = Color3.new(0, 0, 0),
      TextStrokeTransparency = 0.4, Parent = layer })
    local entry = { frame = label, world = world, rise = 0, side = (math.random() * 2 - 1) * 14 }
    live[#live + 1] = entry
    Motion.tween(0.85, Motion.ease.outCubic, function(p)
      if entry.dead then return end
      entry.rise = 34 * p
      label.TextTransparency = p * p
      label.TextStrokeTransparency = 0.4 + 0.6 * p * p
    end, function()
      entry.dead = true
      local at = table.find(live, entry)
      if at then table.remove(live, at) end
      label:Destroy()
    end)
    return entry
  end
  -- marks that belong to a place in the game follow it as the view moves
  B.connect(S.RunService.RenderStepped, function()
    if #live == 0 then return end
    local camera = workspace.CurrentCamera
    if not camera then return end
    for _, entry in ipairs(live) do
      if entry.world and not entry.dead then
        local point = camera:WorldToViewportPoint(entry.world)
        local shown = point.Z > 0
        if entry.frame.Visible ~= shown then entry.frame.Visible = shown end
        if shown then entry.frame.Position = UDim2.fromOffset(point.X + (entry.side or 0), point.Y - (entry.rise or 0)) end
      elseif entry.rise and not entry.dead then
        entry.frame.Position = UDim2.fromOffset(entry.x + (entry.side or 0), entry.y - entry.rise)
      end
    end
  end, "dahood.marks")

  -- ---------------------------------------------------------------- whom, and how much
  -- What every body near has just lost: health and armor together, by the frame. The server's
  -- word that a hit counted comes within a few frames of the loss being seen, before or after.
  local totals = {}                                    -- per character: { total, losses = { { at, amount } }, knocked } (a body that is gone is taken out below)
  local function vitalsOf(character)
    local humanoid = character:FindFirstChildOfClass("Humanoid")
    if not humanoid then return nil end
    return humanoid.Health + api.armorOf(character)
  end
  -- The loss that goes with a hit told at `at`: the one nearest to it in time that no other hit has
  -- been given, inside SEEN before it and up to now. One hit, one loss: a gun that fires every
  -- 0.05 s has the next hit's loss on the body before this one's line is written.
  local function lossFor(record, at, upTo)
    local best, bestGap
    for _, loss in ipairs(record.losses) do
      if not loss[3] and loss[1] >= at - SEEN and loss[1] <= upTo then
        local gap = math.abs(loss[1] - at)
        if not bestGap or gap < bestGap then best, bestGap = loss, gap end
      end
    end
    return best, bestGap
  end
  local lastHit = { at = -math.huge, run = 0 }
  local recent = {}                                    -- per player: when a hit of ours was last put down to them
  local card = { player = nil, at = -math.huge }

  local function placeOf(player, head)
    local character = player and player.Parent and player.Character
    if not (character and character.Parent) then return nil end
    local part = head and character:FindFirstChild("Head") or api.torsoOf(character)
    return part and part.Position or nil
  end
  local function screenOf(world)
    local camera = workspace.CurrentCamera
    local view = B.viewport()
    if world and camera and O.markerWorld then
      local point = camera:WorldToViewportPoint(world)
      if point.Z > 0 and point.X > -40 and point.X < view.X + 40 and point.Y > -40 and point.Y < view.Y + 40 then return point.X, point.Y, world end
    end
    return view.X * 0.5, view.Y * 0.5, nil
  end

  -- a hit the server counted: `known` is who the ragebot was shooting at, when it was the one shooting
  local function onHit(head, known)
    local now = os.clock()
    fx.hits += 1
    -- (a shell is five pellets and the server says so five times in one frame: that is one hit to hear and to see)
    if now - lastHit.at < 0.04 then return end
    lastHit.run = (now - lastHit.at <= STREAK) and math.min(lastHit.run + 1, 12) or 0
    lastHit.at = now
    local pitch = 1
    if O.hitPitch then pitch = 1 + lastHit.run * 0.035 end
    local name = head and O.headSound ~= "off" and O.headSound or O.hitSound
    play(name, O.hitVolume / 100, pitch)
    -- who it was: the ragebot's target, or whoever is seen to lose health about now (a few frames
    -- are given for that to show)
    task.delay(0.09, function()
      if not B.alive then return end
      local stamp = os.clock()
      local victim, amount = known, 0
      local mine
      if known and known.Character and totals[known.Character] then
        mine = lossFor(totals[known.Character], now, stamp)
      else
        -- (nobody was being shot at by the ragebot: whoever lost health nearest to that moment)
        local nearest
        for _, player in ipairs(S.Players:GetPlayers()) do
          local record = player ~= LP and player.Character and totals[player.Character]
          local loss, gap = nil, nil
          if record then loss, gap = lossFor(record, now, stamp) end
          if loss and (not nearest or gap < nearest) then victim, mine, nearest = player, loss, gap end
        end
      end
      if mine then
        mine[3] = true
        amount = mine[2]
      end
      if victim then
        recent[victim] = stamp
        card.player, card.at = victim, stamp
      end
      local world = placeOf(victim, head)
      local x, y, anchor = screenOf(world)
      if api.O.hudHits then
        local who = victim and victim.Name or "someone"
        local where = head and "Head" or "Body"
        api.feed(amount >= 0.5 and string.format("Hit %s for %d in the %s", who, math.floor(amount + 0.5), where) or string.format("Hit %s in the %s", who, where), "Hit")
      end
      if O.marker then mark(O.markerStyle, head and O.markerHead or O.markerColor, O.markerSize, O.markerTime, x, y, anchor) end
      if O.damage and amount >= 0.5 then
        local entry = figure(string.format("-%d", math.floor(amount + 0.5)), head and O.markerHead or O.markerColor, x, y - O.markerSize, anchor and (anchor + Vector3.new(0, 1.6, 0)) or nil)
        entry.x, entry.y = x, y - O.markerSize
      end
    end)
  end
  DH.onHit:connect(onHit)
  fx.onHit = onHit

  -- a knock: one of ours if a hit was put down to that body a moment before
  local function onKnock(player, character)
    local now = os.clock()
    local ours = (recent[player] and now - recent[player] < 1.2) or (DH.on and DH.target == player)
    if not ours then return end
    fx.knocks += 1
    play(O.knockSound, O.hitVolume / 100, 1)
    local torso = api.torsoOf(character)
    local x, y, anchor = screenOf(torso and torso.Position or nil)
    if O.marker then mark(O.markerStyle == "ring" and "burst" or "ring", O.markerKnock, O.markerSize * 1.5, O.markerTime * 1.6, x, y, anchor) end
  end
  B.connect(S.Players.PlayerRemoving, function(player) recent[player] = nil end, "dahood.vitals.left")
  B.connect(S.RunService.Heartbeat, function()
    local now = os.clock()
    for character in pairs(totals) do
      if not character.Parent then totals[character] = nil end
    end
    for _, player in ipairs(S.Players:GetPlayers()) do
      local character = player ~= LP and player.Character
      if character and character.Parent then
        local total = vitalsOf(character)
        if total then
          local record = totals[character]
          if not record then
            record = { total = total, losses = {}, knocked = false }
            totals[character] = record
          end
          if total < record.total - 0.4 then
            local losses = record.losses
            losses[#losses + 1] = { now, record.total - total }
            while #losses > 0 and now - losses[1][1] > 2 do table.remove(losses, 1) end
          end
          record.total = total
          local down = api.flagOf(api.effectsOf(character), "K.O")
          if down and not record.knocked then
            -- (the flag follows the last hit by a few frames: the hit's own bookkeeping goes first)
            task.delay(0.12, function() if B.alive then B.try("dahood.knock", onKnock, player, character) end end)
          end
          record.knocked = down
        end
      end
    end
  end, "dahood.vitals")

  -- ---------------------------------------------------------------- shots
  -- A sound on every shot. The ragebot's are told by the engine as the server takes them: when the
  -- first of a turn fired, and how many it holds behind it, each a cooldown later. A shot the
  -- player fires by hand is told by the gun's own sound being played (the game plays it for those).
  local function shot()
    if O.shotSound ~= "off" then play(O.shotSound, O.shotVolume / 100, 0.97 + math.random() * 0.06) end
    fx.shots = (fx.shots or 0) + 1
  end
  fx.shot = shot
  DH.onShot:connect(function(gun, shots, first)
    local kind = api.GUN[gun]
    local step = (kind and kind.cooldown or 0.1) + DH.rate.margin
    local now = os.clock()
    for index = 0, math.max(shots, 1) - 1 do
      local due = (first or now) + index * step - now
      if due <= 0.02 then shot() else task.delay(due, function() if B.alive then shot() end end) end
    end
  end)
  -- The game's own gun sounds: each gun's Handle has a ShootSound (and the game plays copies of it
  -- called MG and DefaultShoot) and a NoAmmo. Hushed here, on this client only, by setting their
  -- volume to nothing and putting it back after.
  local GUN_SOUNDS = { ShootSound = true, MG = true, DefaultShoot = true, NoAmmo = true }
  -- (what the game sets them to: a sound found at nothing with no record of what it was is given this back)
  local GAME_VOLUME = { ShootSound = 0.5, MG = 0.5, DefaultShoot = 0.5, NoAmmo = 0.4 }
  -- Kept for good, not in a table that forgets: seen live, the record of a hushed sound was
  -- collected while the sound lived on, and it stayed silent after the ragebot stopped.
  local hushed = {}                                      -- sound -> the volume it had
  local wired = {}                                       -- a gun's ShootSound -> its Played link
  local function mineOf(sound)
    local me, pack = B.character(), LP:FindFirstChildOfClass("Backpack")
    return (me ~= nil and sound:IsDescendantOf(me)) or (pack ~= nil and sound:IsDescendantOf(pack))
  end
  local function quiet() return O.muteGuns == "always" or (O.muteGuns == "auto" and (DH.on or DH.farming == true)) end
  local function hush(sound)
    if hushed[sound] == nil then hushed[sound] = sound.Volume > 0 and sound.Volume or (GAME_VOLUME[sound.Name] or 0.5) end
    if sound.Volume ~= 0 then sound.Volume = 0 end
  end
  local function unhush()
    for sound, volume in pairs(hushed) do
      if sound.Parent then sound.Volume = volume end
    end
    table.clear(hushed)
  end
  local function tend(sound)
    if not (sound:IsA("Sound") and GUN_SOUNDS[sound.Name]) then return end
    local mine = mineOf(sound)
    if sound.Name == "ShootSound" and mine and not wired[sound] then
      wired[sound] = sound.Played:Connect(B.safe("dahood.shot", function() if not DH.on then shot() end end))
    end
    if quiet() and (mine or O.muteAll) then hush(sound) end
  end
  local function sweep()
    local on = quiet()
    if not on then unhush() end
    -- (a sound that is gone, with its gun or its body: forgotten, and its link let go)
    for sound in pairs(hushed) do
      if not sound.Parent then hushed[sound] = nil end
    end
    for sound, link in pairs(wired) do
      if not sound.Parent then link:Disconnect(); wired[sound] = nil end
    end
    local roots = { B.character(), LP:FindFirstChildOfClass("Backpack") }
    if on and O.muteAll then
      for _, player in ipairs(S.Players:GetPlayers()) do
        if player ~= LP and player.Character then roots[#roots + 1] = player.Character end
      end
    end
    for _, root in pairs(roots) do
      for _, item in ipairs(root:GetDescendants()) do tend(item) end
    end
    -- the game's own hit sound, when one from here is played in its place
    local gui = LP:FindFirstChildOfClass("PlayerGui")
    local theirs = gui and gui:FindFirstChild("HitSound", true)
    if theirs and theirs:IsA("Sound") then
      if O.muteHit and O.hitSound ~= "off" then
        if fx.theirHit == nil then fx.theirHit = theirs.Volume end
        if theirs.Volume ~= 0 then theirs.Volume = 0 end
      elseif fx.theirHit ~= nil then
        theirs.Volume = fx.theirHit
        fx.theirHit = nil
      end
    end
  end
  fx.sweep = sweep
  Motion.every(sweep, 3, "dahood.hush")
  -- (and the moment it is switched, not a third of a second later)
  for _, id in ipairs({ "dahood.on", "dahood.cash", "dahood.muteGuns", "dahood.muteAll", "dahood.muteHit", "dahood.hitSound" }) do
    Config.on(id, function() task.defer(function() if B.alive then B.try("dahood.hush", sweep) end end) end)
  end
  -- (a copy the game makes for one shot is hushed the frame it appears)
  B.connect(workspace.DescendantAdded, function(item)
    if item:IsA("Sound") and GUN_SOUNDS[item.Name] then tend(item) end
  end, "dahood.hush.added")
  B.onUnload:connect(function()
    unhush()
    for _, link in pairs(wired) do link:Disconnect() end
    local gui = LP:FindFirstChildOfClass("PlayerGui")
    local theirs = gui and gui:FindFirstChild("HitSound", true)
    if theirs and fx.theirHit ~= nil then theirs.Volume = fx.theirHit end
  end)

  -- ---------------------------------------------------------------- the target card
  -- Who is being shot at (or was last hit): face, name, health and armor as bars, what they hold.
  local cardFrame = UI.frame(api.gui, { Name = "Target", AnchorPoint = Vector2.new(0.5, 1), Position = UDim2.new(0.5, 0, 1, -118), Size = UDim2.fromOffset(250, 62),
    BackgroundColor3 = Color3.fromRGB(12, 12, 16), BackgroundTransparency = 0.28, Visible = false })
  UI.corner(cardFrame, 10)
  local rim = Instance.new("UIStroke")
  rim.Color = Color3.new(1, 1, 1)
  rim.Transparency = 0.86
  rim.Parent = cardFrame
  local face = UI.new("ImageLabel", { Name = "Face", Size = UDim2.fromOffset(42, 42), Position = UDim2.fromOffset(10, 10), BackgroundColor3 = Color3.new(1, 1, 1),
    BackgroundTransparency = 0.9, Parent = cardFrame })
  UI.corner(face, true)
  local nameLabel = UI.new("TextLabel", { Name = "Name", BackgroundTransparency = 1, Position = UDim2.fromOffset(62, 7), Size = UDim2.new(1, -150, 0, 16), FontFace = B.F.text600,
    TextSize = 13, TextColor3 = Color3.new(1, 1, 1), TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd, Text = "", Parent = cardFrame })
  local stateLabel = UI.new("TextLabel", { Name = "State", BackgroundTransparency = 1, AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -10, 0, 8), Size = UDim2.fromOffset(84, 14),
    FontFace = B.F.mono500, TextSize = 10, TextColor3 = Color3.fromRGB(255, 209, 102), TextXAlignment = Enum.TextXAlignment.Right, Text = "", Parent = cardFrame })
  local function meter(y, color)
    local back = UI.frame(cardFrame, { Position = UDim2.fromOffset(62, y), Size = UDim2.new(1, -72, 0, 6), BackgroundColor3 = Color3.new(1, 1, 1), BackgroundTransparency = 0.88 })
    UI.corner(back, true)
    local fill = UI.frame(back, { Size = UDim2.fromScale(1, 1), BackgroundColor3 = color, BackgroundTransparency = 0 })
    UI.corner(fill, true)
    return fill
  end
  local healthFill = meter(27, Color3.fromRGB(110, 231, 135))
  local armorFill = meter(37, Color3.fromRGB(88, 166, 255))
  local holdLabel = UI.new("TextLabel", { Name = "Holds", BackgroundTransparency = 1, Position = UDim2.fromOffset(62, 45), Size = UDim2.new(1, -72, 0, 13), FontFace = B.F.mono500,
    TextSize = 10, TextColor3 = Color3.new(1, 1, 1), TextTransparency = 0.25, TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd, Text = "", Parent = cardFrame })
  local shownFor, shownHealth, shownArmor
  -- (nothing is written for a knocked one: its empty health bar says it. The owner asked for the word gone.)
  local WORDS = { up = "", down = "", shield = "SHIELD", dead = "DEAD", loading = "LOADING", none = "NO BODY", gone = "LEFT" }
  Motion.every(function(dt)
    local now = os.clock()
    local player = DH.on and (DH.target) or nil
    if not player and now - card.at < 4 then player = card.player end
    if not (O.card and player and player.Parent) then
      if cardFrame.Visible then cardFrame.Visible = false end
      shownFor = nil
      return
    end
    if not cardFrame.Visible then cardFrame.Visible = true end
    if shownFor ~= player then
      shownFor, shownHealth, shownArmor = player, nil, nil
      face.Image = "rbxthumb://type=AvatarHeadShot&id=" .. player.UserId .. "&w=150&h=150"
      nameLabel.Text = player.DisplayName
    end
    local state = DH.stateOf(player)
    local character = player.Character
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    local health = (humanoid and state ~= "dead") and math.clamp(humanoid.Health / math.max(humanoid.MaxHealth, 1), 0, 1) or 0
    local armor = character and math.clamp(api.armorOf(character) / 130, 0, 1) or 0
    shownHealth = shownHealth and (shownHealth + (health - shownHealth) * math.min(1, dt * 12)) or health
    shownArmor = shownArmor and (shownArmor + (armor - shownArmor) * math.min(1, dt * 12)) or armor
    healthFill.Size = UDim2.fromScale(shownHealth, 1)
    armorFill.Size = UDim2.fromScale(shownArmor, 1)
    stateLabel.Text = WORDS[state] or ""
    local tool = character and character:FindFirstChildOfClass("Tool")
    local ammo, max = tool and tool:FindFirstChild("Ammo"), tool and tool:FindFirstChild("MaxAmmo")
    local words = tool and (tool.Name .. (ammo and (" " .. tostring(ammo.Value) .. "/" .. tostring(max and max.Value or "?")) or "")) or "nothing in hand"
    holdLabel.Text = string.format("%d hp +%d   %s", humanoid and math.floor(humanoid.Health + 0.5) or 0, character and math.floor(api.armorOf(character) + 0.5) or 0, words)
  end, 30, "dahood.card")
end

local function display(page)
  local DHfx = B.DaHood.fx
  local sound = page:section({ title = "Hit sounds", icon = "volume-2", desc = "Only you hear them. Your own files go in BasedHub/hitsounds." })
  sound:dropdown({ id = "dahood.hitSound", label = "Body hit", options = DHfx.HIT_SOUNDS, default = "tick" })
  sound:dropdown({ id = "dahood.headSound", label = "Head hit", desc = "None: the body sound.", options = DHfx.HIT_SOUNDS, default = "glass" })
  sound:dropdown({ id = "dahood.knockSound", label = "Knock", options = DHfx.KNOCK_SOUNDS, default = "kill_chime" })
  sound:slider({ id = "dahood.hitVolume", label = "Volume", min = 0, max = 100, step = 5, default = 60, suffix = "%" })
  sound:toggle({ id = "dahood.hitPitch", label = "Rising pitch", desc = "Each hit in a run sounds a little higher.", default = true })
  sound:toggle({ id = "dahood.muteHit", label = "Replace game sound", desc = "Hushes the game's own hit sound.", default = true })
  for _, id in ipairs({ "dahood.hitSound", "dahood.headSound", "dahood.knockSound", "dahood.shotSound" }) do
    -- picking one plays it
    Config.on(id, function(name) if Window.anyOpen() and DHfx.play then DHfx.play(name) end end)
  end

  local guns = page:section({ title = "Gun sounds", icon = "music", desc = "What a shot sounds like, to you." })
  guns:dropdown({ id = "dahood.shotSound", label = "Shot sound", desc = "Played as each shot is fired.", options = DHfx.HIT_SOUNDS, default = "off" })
  guns:slider({ id = "dahood.shotVolume", label = "Volume", min = 0, max = 100, step = 5, default = 50, suffix = "%" })
  guns:segmented({ id = "dahood.muteGuns", label = "Silence game guns", desc = "Auto: while the ragebot or cash round runs.",
    options = { { "off", "Off" }, { "auto", "Auto" }, { "always", "Always" } }, default = "auto", width = 190 })
  guns:toggle({ id = "dahood.muteAll", label = "Silence everyone's", default = false })

  local marks = page:section({ title = "Hitmarkers", icon = "target", desc = "Only you see them." })
  marks:toggle({ id = "dahood.marker", label = "Hitmarkers", default = true, children = function(sub)
    sub:dropdown({ id = "dahood.markerStyle", label = "Shape", options = DHfx.STYLES, default = "cross" })
    sub:toggle({ id = "dahood.markerWorld", label = "On the body", desc = "Off: in the middle of the screen.", default = true })
    sub:slider({ id = "dahood.markerSize", label = "Size", min = 8, max = 40, step = 1, default = 16, suffix = " px" })
    sub:slider({ id = "dahood.markerTime", label = "Stays for", min = 0.1, max = 1.5, step = 0.05, default = 0.4, suffix = " s" })
    sub:color({ id = "dahood.markerColor", label = "Body hit", default = Color3.fromRGB(255, 255, 255) })
    sub:color({ id = "dahood.markerHead", label = "Head hit", default = Color3.fromRGB(255, 209, 102) })
    sub:color({ id = "dahood.markerKnock", label = "Knock", default = Color3.fromRGB(255, 84, 84) })
  end })
  marks:toggle({ id = "dahood.damage", label = "Damage numbers", desc = "What each hit took, rising off the body.", default = true })
  marks:button({ id = "dahood.markerTry", label = "Test it", text = "Show", bindable = false, run = function()
    if DHfx.onHit then
      DHfx.onHit(false, nil)
      task.delay(0.35, function() if B.alive then DHfx.onHit(true, nil) end end)
    end
  end })
  marks:toggle({ id = "dahood.card", label = "Target card", desc = "Health, armor and gun of who you are hitting.", default = true })
end

DH.parts[#DH.parts + 1] = { id = "fx", start = start, display = display }
end
do -- dahood_guard.lua
-- ============================================================================
--  Da Hood     the guard: auto block, and two things for when you are down
--
--  Measured on the live server (2026-10-12, version 3267, two accounts three
--  studs apart, one punching and one watching its own health):
--    * Fists go straight through armor. A light punch took 12.6 to 16.2 health
--      with 130 armor on (the armor was not touched); a punch held 1.7 s took
--      77.2. One heavy punch and two light ones is a knock.
--    * "Block", true: BodyEffects.Block is there 0.08 to 0.12 s later. Blocked,
--      a light punch took 2.5 to 3.2 and a heavy one 28. BodyEffects.Defense
--      (100) falls 5 to 8 a light punch and 24 a heavy one, and comes back about
--      a quarter of a point a second. A block 0.26 s old and one 1.97 s old took
--      the same: there is no parry in this game, only the block.
--    * The puncher's BodyEffects.Attacking goes true 0.05 to 0.06 s before a
--      light punch lands, and about 1.9 s before a heavy one. So a block raised
--      on seeing it stops the heavy punch and is too late for the light one
--      (three of three landed in full). To stop those the block has to be up
--      before the swing: whenever someone is close with no gun out.
--    * While it blocks the game's own client will not fire a gun, and walks at 5.
-- ============================================================================
local B = B or ...
local S, Config, Window = B.S, B.Config, B.Window
local DH = B.DaHood

local CLOSE = 9              -- studs: someone this near with fists out can land a punch before a block is up (a punch reaches 3.6)
local LOWER = 0.35           -- s the block stays up after the last sign of a punch
local AGAIN = 0.6            -- s before a block the server does not show is asked for again
local STOMP_EVERY = 0.6      -- a stomp that misses costs about 0.55 s before another counts
local STOMP_SIDE = 2         -- studs to the side, and
local STOMP_LOW, STOMP_HIGH = 1.5, 9.5   -- studs above the torso, that a stomp counted from (measured over a body lying still)

local guard = { up = false, blocks = 0, why = nil, resets = 0, stomps = 0 }
DH.guard = guard

local function start()
  local api = DH.api
  local LP = B.LP
  local UIS = S.UserInputService
  local O
  local map = {}
  for id, default in pairs({ guard = "off", guardRange = 12, guardGun = true, unknock = true, autoStomp = false }) do
    Config.define("dahood." .. id, default)
    map[id] = "dahood." .. id
  end
  O = Config.mirror(map)
  guard.options = O

  local lastThreat, askedAt, lastStomp, resetAt = -math.huge, -math.huge, -math.huge, -math.huge
  local function friend(player)
    local roster = B.Roster
    local entry = roster and roster.byPlayer and roster.byPlayer[player]
    return entry ~= nil and roster.isFriend(entry)
  end
  -- who is about to hit, and how it shows: a swing under way, or fists out within reach
  local function threat(root)
    local nearest, kind, nearestAway
    for _, player in ipairs(S.Players:GetPlayers()) do
      if player ~= LP and not friend(player) and DH.stateOf(player) == "up" then
        local character = player.Character
        local theirs = character:FindFirstChild("HumanoidRootPart")
        local away = theirs and (theirs.Position - root.Position).Magnitude or math.huge
        if away <= O.guardRange then
          local found
          if api.flagOf(api.effectsOf(character), "Attacking") then
            found = "swing"
          elseif O.guard == "close" and away <= math.min(O.guardRange, CLOSE) then
            local tool = character:FindFirstChildOfClass("Tool")
            local unarmed = not (tool and tool:FindFirstChild("Ammo"))
            local toward = (root.Position - theirs.Position)
            local facing = toward.Magnitude < 0.5 or toward.Unit:Dot(theirs.CFrame.LookVector) > 0.25
            if unarmed and facing then found = "close" end
          end
          if found and (not nearestAway or away < nearestAway or (found == "swing" and kind ~= "swing")) then
            nearest, kind, nearestAway = player, found, away
          end
        end
      end
    end
    return nearest, kind
  end
  guard.threat = threat
  local function set(on, why)
    local remote = api.mainEvent()
    if not remote then return end
    if on == guard.up then
      -- up already: asked for again only when the server does not show it (the game's own key let it go)
      if not on or os.clock() - askedAt < AGAIN then return end
      local effects = api.effectsOf(B.character())
      if effects and effects:FindFirstChild("Block") then return end
    end
    if on and not guard.up then
      guard.blocks += 1
      guard.why = why
    end
    guard.up = on
    askedAt = os.clock()
    remote:FireServer("Block", on)
  end
  -- a gun in the hand and the trigger held: the block comes down, the game will not fire through it
  local function firing(me)
    if not O.guardGun then return false end
    local tool = me:FindFirstChildOfClass("Tool")
    if not (tool and tool:FindFirstChild("Ammo")) then return false end
    return UIS:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) and not Window.anyOpen()
  end

  local function step()
    local now = os.clock()
    local me, root, humanoid = B.character(), B.root(), B.humanoid()
    local effects = api.effectsOf(me)
    local able = me and root and humanoid and effects and humanoid.Health > 0 and not api.flagOf(effects, "Dead")
    local knocked = able and api.flagOf(effects, "K.O")
    -- the block: only for a body that is standing where others can reach it
    if O.guard ~= "off" and able and not knocked and not api.moving() then
      local who, kind = threat(root)
      if who and not firing(me) then
        lastThreat = now
        set(true, (kind == "swing" and "a swing from " or "fists out: ") .. who.Name)
      elseif guard.up and (now - lastThreat > LOWER or firing(me)) then
        set(false)
      end
    elseif guard.up then
      set(false)
    end
    -- Knocked: gone before the stomp, if that is asked for. The game's own reset is asked for once
    -- (measured: it does nothing to a knocked body inside 0.3 s). What works is the body's health
    -- put to nothing by its own client, and that is written every frame until it holds. Measured
    -- on 2026-10-13: written once, the instant the flag showed, the server put the health back
    -- and the body lay there for the 1.5 s until the next try (which held: dead 0.05 s after it);
    -- the day before, one written 0.3 s after the knock held at once.
    if O.unknock and knocked then
      if now - resetAt > 3 then
        resetAt = now
        guard.resets += 1
        local remote = api.mainEvent()
        if remote then remote:FireServer("ResetNew") end
      end
      humanoid.Health = 0
    end
    -- standing on a knocked body: stomp it
    if O.autoStomp and able and not knocked and not api.moving() and now - lastStomp >= STOMP_EVERY then
      for _, player in ipairs(S.Players:GetPlayers()) do
        if player ~= LP and not friend(player) and DH.stateOf(player) == "down" then
          local torso = api.torsoOf(player.Character)
          local off = torso and (root.Position - torso.Position)
          if off and off.Y >= STOMP_LOW and off.Y <= STOMP_HIGH and Vector3.new(off.X, 0, off.Z).Magnitude <= STOMP_SIDE then
            local remote = api.mainEvent()
            if remote then
              lastStomp = now
              guard.stomps += 1
              remote:FireServer("Stomp")
            end
            break
          end
        end
      end
    end
  end
  B.connect(S.RunService.Heartbeat, step, "dahood.guard")
  Config.on("dahood.guard", function(mode) if mode == "off" and guard.up then set(false) end end)
  B.onUnload:connect(function()
    if guard.up then
      local remote = api.mainEvent()
      if remote then pcall(function() remote:FireServer("Block", false) end) end
      guard.up = false
    end
  end)
end

local function player(page)
  local Motion = B.Motion
  local defence = page:section({ title = "Survival", icon = "shield", desc = "For your own body, while the ragebot is off." })
  defence:segmented({ id = "dahood.guard", label = "Auto block", desc = "Blocks before a punch lands.",
    options = { { "off", "Off" }, { "swings", "Swings" }, { "close", "Close" } }, default = "off", width = 190 })
  defence:slider({ id = "dahood.guardRange", label = "Within", desc = "How near someone has to be.", min = 5, max = 30, step = 1, default = 12, suffix = " st" })
  defence:toggle({ id = "dahood.guardGun", label = "Drop block to shoot", desc = "Drops the block while you fire a gun.", default = true })
  local HOW = "Swings: on a wind-up. Close: also fists out near you. A block takes four fifths off; the game has no parry."
  local line = defence:note({ icon = "info", text = HOW })
  defence:toggle({ id = "dahood.unknock", label = "Anti-stomp reset", desc = "Respawns before anyone can stomp you, and you keep your guns.", default = true })
  defence:toggle({ id = "dahood.autoStomp", label = "Auto stomp", desc = "Stomps any knocked player you stand on.", default = false })
  Motion.every(function()
    if not (line.frame.Parent and Window.anyOpen()) then return end
    local g = B.DaHood.guard
    if g.blocks == 0 then line.set(HOW)
    else line.set(string.format("%s    Blocked %d time%s%s.", g.up and "Blocking." or "Down.", g.blocks, g.blocks == 1 and "" or "s", g.why and (", the last for " .. g.why) or "")) end
  end, 2, "dahood.guard.line")
end

DH.parts[#DH.parts + 1] = { id = "guard", start = start, player = player }
end
do -- dahood_social.lua
-- ============================================================================
--  Da Hood     chat that can be read, and emotes kept by their ids
--
--  Read on the live game (2026-10-12, version 3267): chat here is Roblox's
--  TextChatService with its window switched off (ChatWindowConfiguration.Enabled
--  is false; the bar to type in is left on). So nothing anyone says is listed
--  anywhere. Two ways to read it, both this client's own: the window switched
--  back on, and a log of every message this client is sent, on screen and in
--  the tab. A whisper between two other players is never sent to a third
--  client: no script can show those.
--
--  An emote is an animation played on the player's own character, which the
--  game sends on to everyone like any other. One bought in the catalogue is an
--  asset that holds the animation; its id is turned into the animation's.
-- ============================================================================
local B = B or ...
local S, util, Motion, UI, Config, Window, Controls = B.S, B.util, B.Motion, B.UI, B.Config, B.Window, B.Controls
local DH = B.DaHood

local KEPT = 120             -- messages kept for the tab
local SHOWN = 8              -- lines of the log on screen at once
local SLOTS = 8              -- emotes that have a button (and so can have a key)

local social = { messages = {}, heard = 0, emotes = {}, playing = nil, SLOTS = SLOTS }
DH.social = social

local function start()
  local api = DH.api
  local LP = B.LP
  local O
  local map = {}
  for id, default in pairs({ chatWindow = false, chatLog = false, chatStay = 12, emoteLoop = true, emoteStop = true, emoteSpeed = 100 }) do
    Config.define("dahood." .. id, default)
    map[id] = "dahood." .. id
  end
  Config.define("dahood.emotes", {})
  O = Config.mirror(map)
  social.options = O

  -- ---------------------------------------------------------------- chat
  local onMessage = B.Signal.new()
  social.onMessage = onMessage
  local logFrame = UI.frame(api.gui, { Name = "ChatLog", AnchorPoint = Vector2.new(0, 1), Position = UDim2.new(0, 14, 1, -150), Size = UDim2.fromOffset(460, 0),
    AutomaticSize = Enum.AutomaticSize.Y, Visible = false })
  UI.list(logFrame, "y", 2)
  local order = 0
  local function line(who, text, tint)
    if not O.chatLog then return end
    order += 1
    local row = UI.frame(logFrame, { Name = "Said", Size = UDim2.fromOffset(0, 18), AutomaticSize = Enum.AutomaticSize.X, LayoutOrder = order,
      BackgroundColor3 = Color3.new(0, 0, 0), BackgroundTransparency = 0.5 })
    local label = UI.new("TextLabel", { Name = "Text", BackgroundTransparency = 1, Position = UDim2.fromOffset(7, 0), Size = UDim2.fromOffset(0, 18), AutomaticSize = Enum.AutomaticSize.X,
      FontFace = B.F.text500, TextSize = 12, RichText = false, Text = who .. ":  " .. text .. "   ", TextColor3 = tint or Color3.new(1, 1, 1),
      TextXAlignment = Enum.TextXAlignment.Left, Parent = row })
    local rows = {}
    for _, child in ipairs(logFrame:GetChildren()) do
      if child:IsA("Frame") then rows[#rows + 1] = child end
    end
    table.sort(rows, function(a, b) return a.LayoutOrder < b.LayoutOrder end)
    for index = 1, #rows - SHOWN do rows[index]:Destroy() end
    task.delay(math.max(O.chatStay, 2), function()
      if not (B.alive and row.Parent) then return end
      Motion.tween(0.5, Motion.ease.linear, function(p)
        if row.Parent then row.BackgroundTransparency = 0.5 + 0.5 * p; label.TextTransparency = p end
      end, function() if row.Parent then row:Destroy() end end)
    end)
  end
  local function heard(who, text, userId)
    if type(text) ~= "string" or text == "" then return end
    social.heard += 1
    local messages = social.messages
    messages[#messages + 1] = { who = who, text = text, at = os.clock(), userId = userId }
    if #messages > KEPT then table.remove(messages, 1) end
    line(who, text, userId == LP.UserId and Color3.fromRGB(170, 200, 255) or nil)
    onMessage:fire()
  end
  social.heardFrom = heard
  local chat = S.TextChatService
  local ok = pcall(function()
    B.connect(chat.MessageReceived, function(message)
      -- (the same message is told twice when it is one's own: once as it is sent, once as the server has it)
      if message.Status ~= Enum.TextChatMessageStatus.Success and message.Status ~= Enum.TextChatMessageStatus.Unknown then return end
      local source = message.TextSource
      local who = "System"
      local userId
      if source then
        userId = source.UserId
        local player = S.Players:GetPlayerByUserId(userId)
        who = player and player.DisplayName or source.Name
      end
      heard(who, message.Text, userId)
    end, "dahood.chat")
  end)
  social.listening = ok
  -- the window itself: the game switches it off, and this switches it back on for as long as it is asked for
  local windowWas
  local function windowConfig() return chat:FindFirstChildOfClass("ChatWindowConfiguration") end
  local function tendWindow()
    local config = windowConfig()
    if not config then return end
    if O.chatWindow then
      if windowWas == nil then windowWas = config.Enabled end
      if not config.Enabled then config.Enabled = true end
    elseif windowWas ~= nil then
      config.Enabled = windowWas
      windowWas = nil
    end
  end
  Motion.every(tendWindow, 1, "dahood.chatwindow")
  Config.on("dahood.chatWindow", function() task.defer(tendWindow) end)
  Config.on("dahood.chatLog", function(on) logFrame.Visible = on == true end, true)
  B.onUnload:connect(function()
    local config = windowConfig()
    if config and windowWas ~= nil then config.Enabled = windowWas end
  end)

  -- ---------------------------------------------------------------- emotes
  local resolved = {}
  -- the id of the animation an id stands for: its own, or the one inside a catalogue emote
  local function animationOf(id)
    id = tostring(id)
    if resolved[id] then return resolved[id] end
    local found
    if type(game.GetObjects) == "function" then
      local got, objects = pcall(function() return game:GetObjects("rbxassetid://" .. id) end)
      if got and type(objects) == "table" then
        for _, object in ipairs(objects) do
          local animation = object:IsA("Animation") and object or object:FindFirstChildWhichIsA("Animation", true)
          if animation and animation.AnimationId ~= "" then found = animation.AnimationId; break end
        end
      end
    end
    resolved[id] = found or ("rbxassetid://" .. id)
    return resolved[id]
  end
  local function stop()
    local playing = social.playing
    social.playing = nil
    if playing then
      pcall(function() playing.track:Stop(0.2) end)
      pcall(function() playing.track:Destroy() end)
    end
  end
  social.stop = stop
  -- play one by its place in the list, or by its id
  function social.play(which)
    local saved = Config.get("dahood.emotes")
    -- (a small whole number is a place in the list; anything else is an id. An empty place is
    -- nothing to play: found by the spec, it was taken for the id 5 and asked of the game.)
    local emote
    if type(which) == "number" and which >= 1 and which <= 64 and which % 1 == 0 then
      emote = saved[which]
    else
      emote = { id = which, name = tostring(which) }
    end
    if not emote then return false, "Nothing is saved there." end
    local id = string.match(tostring(emote.id), "%d+")
    if not id then return false, "That is not an id." end
    local humanoid = B.humanoid()
    local animator = humanoid and humanoid:FindFirstChildOfClass("Animator")
    if not animator or humanoid.Health <= 0 then return false, "You have no body just now." end
    -- the same one again stops it
    if social.playing and social.playing.id == id then stop(); return true end
    stop()
    local animation = Instance.new("Animation")
    animation.AnimationId = animationOf(id)
    local made, track = pcall(function() return animator:LoadAnimation(animation) end)
    if not made or not track then return false, "The game would not load that animation." end
    track.Priority = Enum.AnimationPriority.Action
    track.Looped = O.emoteLoop
    track:Play(0.15, 1, math.clamp(O.emoteSpeed / 100, 0.1, 4))
    social.playing = { id = id, track = track, name = emote.name, at = os.clock() }
    return true
  end
  -- walking off ends it, if that is asked for; so does a new body
  B.connect(S.RunService.Heartbeat, function()
    local playing = social.playing
    if not playing then return end
    local humanoid = B.humanoid()
    if not humanoid or humanoid.Health <= 0 then stop(); return end
    if O.emoteStop and os.clock() - playing.at > 0.25 and humanoid.MoveDirection.Magnitude > 0.1 then stop(); return end
    if not O.emoteLoop and not playing.track.IsPlaying and os.clock() - playing.at > 0.4 then stop() end
  end, "dahood.emote")
  function social.save(name, id)
    id = string.match(tostring(id or ""), "%d+")
    if not id then return false, "Type the number of an emote or an animation." end
    name = string.gsub(tostring(name or ""), "^%s+", "")
    name = string.gsub(name, "%s+$", "")
    if name == "" then name = "Emote " .. id end
    local saved = table.clone(Config.get("dahood.emotes"))
    for _, emote in ipairs(saved) do
      if tostring(emote.id) == id then emote.name = name; Config.set("dahood.emotes", saved); return true end
    end
    saved[#saved + 1] = { name = string.sub(name, 1, 24), id = id }
    Config.set("dahood.emotes", saved)
    return true
  end
  function social.remove(index)
    local saved = table.clone(Config.get("dahood.emotes"))
    if not saved[index] then return end
    table.remove(saved, index)
    Config.set("dahood.emotes", saved)
  end
  B.onUnload:connect(stop)
end

local function page(hub)
  hub:page({ id = "social", title = "Social", icon = "message-circle", build = function(page)
    local social = B.DaHood.social
    local chat = page:section({ title = "Chat", icon = "message-circle", desc = "The game hides the chat window. These bring it back." })
    chat:toggle({ id = "dahood.chatWindow", label = "Chat window", desc = "Roblox's own window, switched back on.", default = false })
    chat:toggle({ id = "dahood.chatLog", label = "Chat log", desc = "Every message you are sent, bottom left.", default = false, children = function(sub)
      sub:slider({ id = "dahood.chatStay", label = "A line stays for", min = 3, max = 60, step = 1, default = 12, suffix = " s" })
    end })
    local last = chat:note({ icon = "info", text = "Whispers between other players never reach you: nothing can show those." })
    Motion.every(function()
      if not (last.frame.Parent and Window.anyOpen()) then return end
      local messages = social.messages
      if #messages == 0 then return end
      local lines = {}
      for index = math.max(1, #messages - 5), #messages do lines[#lines + 1] = messages[index].who .. ": " .. string.sub(messages[index].text, 1, 70) end
      last.set(table.concat(lines, "\n"))
    end, 2, "dahood.chat.last")

    local moves = page:section({ title = "Emotes", icon = "music", desc = "Save an emote or animation by its id, then play it." })
    local nameBox = moves:input({ label = "Name", placeholder = "Griddy", width = 170 })
    local idBox = moves:input({ label = "Emote or animation id", placeholder = "3360689775", width = 170 })
    moves:button({ label = "Save it", text = "Save", bindable = false, run = function()
      local ok, why = social.save(nameBox.box.Text, idBox.box.Text)
      if ok then
        nameBox.box.Text, idBox.box.Text = "", ""
        Window.toast({ title = "Emote saved", icon = "circle-check", tone = "ok", time = 2 })
      else
        Window.toast({ title = "Not saved", text = why, icon = "triangle-alert", tone = "warn" })
      end
    end })
    moves:toggle({ id = "dahood.emoteLoop", label = "Loop emote", desc = "Off: once through.", default = true })
    moves:toggle({ id = "dahood.emoteStop", label = "Stop on walk", default = true })
    moves:slider({ id = "dahood.emoteSpeed", label = "Speed", min = 10, max = 300, step = 5, default = 100, suffix = "%" })
    moves:button({ id = "dahood.emoteStopNow", label = "Stop emote", text = "Stop", run = function() social.stop() end })

    -- one button for each of the first few saved: a button can have a key
    local slots = page:section({ title = "Your emotes", icon = "star", desc = "Right-click one to give it a key." })
    local buttons = {}
    for index = 1, social.SLOTS do
      buttons[index] = slots:button({ id = "dahood.emote" .. index, label = "Empty", text = "Play", run = function()
        local ok, why = social.play(index)
        if not ok then Window.toast({ title = "Not played", text = why, icon = "triangle-alert", tone = "warn" }) end
      end })
    end
    slots:custom({ name = "Saved", build = function(frame)
      local list = UI.frame(frame, { Name = "List", Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y })
      UI.list(list, "y", 0)
      local function rebuild()
        for _, child in ipairs(list:GetChildren()) do
          if child:IsA("Frame") then child:Destroy() end
        end
        local saved = Config.get("dahood.emotes")
        for index, button in ipairs(buttons) do
          local emote = saved[index]
          local label = button.row and button.row.label
          if label then label.Text = emote and (index .. "  ·  " .. emote.name) or (index .. "  ·  empty") end
          -- (and what the list of keys calls it)
          local bindable = Controls.bindables["dahood.emote" .. index]
          if bindable then bindable.label = emote and ("Emote: " .. emote.name) or ("Emote " .. index) end
        end
        for index, emote in ipairs(saved) do
          local row = UI.frame(list, { Name = "Emote", Size = UDim2.new(1, 0, 0, 34), LayoutOrder = index })
          UI.text(row, emote.name, "label", "ink", { Position = UDim2.new(0, 14, 0.5, 0), AnchorPoint = Vector2.new(0, 0.5), TextSize = 13 })
          UI.text(row, tostring(emote.id), "mono", "faint", { Position = UDim2.new(1, -164, 0.5, 0), AnchorPoint = Vector2.new(1, 0.5), TextSize = 11 })
          local play = Controls.pillButton(row, "Play", nil, function() social.play(index) end)
          play.AnchorPoint, play.Position = Vector2.new(1, 0.5), UDim2.new(1, -96, 0.5, 0)
          local remove = Controls.pillButton(row, "Remove", nil, function() social.remove(index) end)
          remove.Name = "Remove"
          remove.AnchorPoint, remove.Position = Vector2.new(1, 0.5), UDim2.new(1, -14, 0.5, 0)
        end
      end
      Config.on("dahood.emotes", function() if list.Parent then rebuild() end end)
      rebuild()
    end })
  end })
end

DH.parts[#DH.parts + 1] = { id = "social", start = start, page = page }
end
do -- dahood_who.lua
-- ============================================================================
--  Da Hood     who the ragebot hunts, besides the marked
--
--  Everyone (but the players you spare), anyone who comes near where you
--  stood, and whoever hurts you. The game names that one itself. Measured on
--  2026-10-14 with two accounts: a shot from one at the other set the victim's
--  BodyEffects.LastDamager to the shooter's character 26 ms after the victim's
--  health dropped (the victim's own client sees it). Every player's
--  LastGunShotAt (the server's own time of their last shot) and LastFiredGun
--  attributes reach every client 0.04 s after the shot, and BodyEffects.MousePos
--  is where each player's mouse points. Health comes back by itself, about one
--  a second.
--
--  Fight back by itself: hurt with the ragebot off, it switches the ragebot on,
--  kills whoever did it, and switches it off again (the body goes back where it
--  stood). It only ever switches off what it switched on.
--
--  Whoever aims at you (2026-10-14 evening): a gun out and the mouse held on this
--  body is taken as a hit, before there is one: hunted, and fought back.
-- ============================================================================
local B = B or ...
local S, Config, Window, Motion = B.S, B.Config, B.Window, B.Motion
local DH = B.DaHood

local LOOK_FOR = 0.4         -- s after a loss of health in which the game's word on who did it is waited for
local GIVE_UP = 90           -- s a fight it started by itself is kept up without a kill before it stops
local FLOOR = 1.5            -- health at or under which a body is taken to be knocked (the game drops it to 1)
local AIM_NEAR = 6           -- studs from this body that someone's mouse point has to be (as the ESP's AIMING AT YOU)
local AIM_HOLD = 0.3         -- s it has to stay there: a mouse swept across the body is not aiming at it

local who = { grudges = {}, hurtBy = 0, fought = 0, aimedBy = 0, auto = nil }
DH.who = who

local function start()
  local api = DH.api
  local LP = B.LP
  local Players = S.Players
  local map = {}
  for id, default in pairs({ everyone = false, zone = 0, revenge = false, revengeFor = 120, bodyguard = false, bodyguardKills = 1, aimed = false }) do
    Config.define("dahood." .. id, default)
    map[id] = "dahood." .. id
  end
  local O = Config.mirror(map)
  who.options = O

  local function friend(player)
    local roster = B.Roster
    local entry = roster and roster.byPlayer[player]
    return entry ~= nil and roster.isFriend(entry)
  end
  local function grudge(player, now)
    local untilAt = who.grudges[player.UserId]
    return untilAt ~= nil and now < untilAt
  end
  -- within the zone round where the body stood when the ragebot was switched on
  local function near(player)
    if O.zone <= 0 then return false end
    local home = api.home()
    local character = player.Character
    local torso = character and api.torsoOf(character)
    return home ~= nil and torso ~= nil and (torso.Position - home.Position).Magnitude <= O.zone
  end
  table.insert(DH.spares, friend)
  table.insert(DH.wants, function(player, now) return O.everyone or grudge(player, now) or near(player) end)
  -- (whoever has hurt this body lately goes before anyone else that can be shot as quickly)
  table.insert(DH.weighs, function(player, _, now) return grudge(player, now) and 1.5 or 0 end)
  DH.huntingAlso = DH.huntingAlso or {}
  table.insert(DH.huntingAlso, function() return O.everyone or O.zone > 0 or next(who.grudges) ~= nil end)

  -- ---------------------------------------------------------------- fighting back
  local auto                      -- the fight this started by itself: { at, players = { [userId] = kills it wants } , kills = {} }
  local function stopAuto(why)
    if not auto then return end
    auto = nil
    who.auto = nil
    if DH.on then Config.set("dahood.on", false, true) end
    if why then Window.toast({ title = "Fight over", text = why, icon = "swords", time = 3 }) end
  end
  local function fightBack(player, now)
    if auto then
      auto.players[player.UserId] = auto.players[player.UserId] or 0
      return
    end
    if not O.bodyguard or DH.on or DH.hiding or DH.farming then return end
    -- (knocked or dead: there is no body to fight with yet; it starts once there is. A knocked body's
    -- health is at the floor before the flag that says so comes: 0.04 to 0.10 s, measured)
    local me, humanoid = B.character(), B.humanoid()
    local effects = api.effectsOf(me)
    if not (me and humanoid and humanoid.Health > FLOOR and effects and me:FindFirstChild("FULLY_LOADED_CHAR")) or api.flagOf(effects, "K.O") or api.flagOf(effects, "Dead") then
      who.waiting = player
      return
    end
    auto = { at = now, players = { [player.UserId] = 0 } }
    Config.set("dahood.on", true, true)
    if not DH.on then
      -- (no body to hunt with yet: it is tried again once there is one)
      auto, who.waiting = nil, player
      return
    end
    who.auto = auto
    who.fought += 1
    Window.toast({ title = "Fighting back", text = player.DisplayName .. " hurt you.", icon = "swords", tone = "warn", time = 3 })
  end
  local function hurtBy(player, now)
    if not player or player == LP or friend(player) then return end
    local fresh = not grudge(player, now)
    who.grudges[player.UserId] = now + O.revengeFor
    who.last, who.lastAt = player, now
    if fresh then
      who.hurtBy += 1
      DH.onTargets:fire()
    end
    fightBack(player, now)
  end
  local function attackerOf(model)
    if typeof(model) ~= "Instance" then return nil end
    local player = Players:GetPlayerFromCharacter(model)
    -- (a body its player has since left behind: by its name)
    if not player then
      local named = Players:FindFirstChild(model.Name)
      if named and named:IsA("Player") then player = named end
    end
    if player == LP then return nil end
    return player
  end
  local lastLife, lossAt
  local aiming = setmetatable({}, { __mode = "k" })   -- per player: since when its mouse has been on this body
  B.connect(S.RunService.Heartbeat, function()
    local now = os.clock()
    -- someone holding a gun with the mouse on this body: (not while the body is away: in the void
    -- nobody aims at it, and where it strikes, it is already there to kill)
    if O.aimed and not api.moving() then
      local root = B.root()
      for _, player in ipairs(Players:GetPlayers()) do
        local character = player ~= LP and root and player.Character
        local effects = character and api.effectsOf(character)
        local mouse = effects and effects:FindFirstChild("MousePos")
        local tool = character and character:FindFirstChildOfClass("Tool")
        -- (up: a knocked or dead body keeps its gun and its mouse point where they were)
        if mouse and tool and tool:FindFirstChild("Ammo") and typeof(mouse.Value) == "Vector3" and (mouse.Value - root.Position).Magnitude <= AIM_NEAR
          and not friend(player) and DH.stateOf(player) == "up" then
          aiming[player] = aiming[player] or now
          if now - aiming[player] >= AIM_HOLD then
            aiming[player] = now
            if not grudge(player, now) then who.aimedBy += 1 end
            hurtBy(player, now)
          end
        else
          aiming[player] = nil
        end
      end
    end
    for id, untilAt in pairs(who.grudges) do
      if now >= untilAt then who.grudges[id] = nil end
    end
    -- the fight it started: over once every one of them has died as often as asked, or has gone
    if auto then
      local done = true
      for userId, kills in pairs(auto.players) do
        local player = Players:GetPlayerByUserId(userId)
        if player and kills < O.bodyguardKills then done = false end
      end
      if done then stopAuto("Everyone who hurt you is dead.")
      elseif now - (auto.lastKill or auto.at) > GIVE_UP then stopAuto("Nobody to hit for a minute and a half.") end
    end
    if who.waiting then
      local me, humanoid = B.character(), B.humanoid()
      local effects = api.effectsOf(me)
      if me and humanoid and humanoid.Health > FLOOR and me:FindFirstChild("FULLY_LOADED_CHAR") and not api.flagOf(effects, "K.O") and not api.flagOf(effects, "Dead") then
        local player = who.waiting
        who.waiting = nil
        if player.Parent then fightBack(player, now) end
      end
    end
    -- (health is followed all the time, so a hit the moment either is switched on is not missed)
    local me = B.character()
    local humanoid = me and me:FindFirstChildOfClass("Humanoid")
    local effects = api.effectsOf(me)
    if not (humanoid and effects) then lastLife, lossAt = nil, nil; return end
    local life = math.max(humanoid.Health, 0) + api.armorOf(me)
    if lastLife and life < lastLife - 0.5 then lossAt = now end
    lastLife = life
    if not (O.revenge or O.bodyguard) then lossAt = nil; return end
    if lossAt then
      local named = effects:FindFirstChild("LastDamager")
      local attacker = named and attackerOf(named.Value)
      if attacker then
        hurtBy(attacker, now)
        lossAt = nil
      elseif now - lossAt > LOOK_FOR then
        lossAt = nil
      end
    end
  end, "dahood.who")
  -- its kills of those it is fighting (with Stomp off, its knocks: there will be no kill to count)
  DH.onKill:connect(function(player)
    if auto and player and auto.players[player.UserId] and api.O.stomp then
      auto.players[player.UserId] += 1
      auto.lastKill = os.clock()
    end
  end)
  DH.onKnocked:connect(function(player)
    if auto and player and auto.players[player.UserId] and not api.O.stomp then
      auto.players[player.UserId] += 1
      auto.lastKill = os.clock()
    end
  end)
  -- switched off by hand: whatever it was doing by itself is over, and stays over
  Config.on("dahood.on", function(on) if not on and auto then auto, who.auto = nil, nil end end)
  Config.on("dahood.bodyguard", function(on) if not on then stopAuto(nil) end end)
  B.connect(Players.PlayerRemoving, function(player) who.grudges[player.UserId] = nil end, "dahood.who.left")
end

local function ragebot(page)
  local hunt = page:section({ title = "Hit list", icon = "users", desc = "The marked always. These add more; Spare keeps a player out." })
  hunt:toggle({ id = "dahood.everyone", label = "Kill everyone", desc = "Every player but the ones you spare.", default = false })
  hunt:slider({ id = "dahood.zone", label = "Kill zone", desc = "Within this of where you stood. 0: off.", min = 0, max = 5000, step = 10, default = 0, curve = 2, suffix = " st" })
  hunt:toggle({ id = "dahood.revenge", label = "Revenge", desc = "The game says who it was.", default = false, children = function(sub)
    sub:slider({ id = "dahood.revengeFor", label = "Revenge lasts", desc = "From their last hit.", min = 30, max = 3600, step = 10, default = 120, curve = 2, suffix = " s" })
  end })
  hunt:toggle({ id = "dahood.aimed", label = "Punish aimers", desc = "Gun out, mouse on you: taken as a hit, before there is one.", default = false })
  hunt:toggle({ id = "dahood.bodyguard", label = "Auto fight back", desc = "Hit while the ragebot is off: it starts, kills them, and stops.", default = false, children = function(sub)
    sub:slider({ id = "dahood.bodyguardKills", label = "Kills per grudge", desc = "Knocks, with Stomp them out off.", min = 1, max = 10, step = 1, default = 1 })
  end })
  local line = hunt:note({ icon = "activity", text = "" })
  B.Motion.every(function()
    if not (line.frame.Parent and Window.anyOpen()) then return end
    local w = B.DaHood.who
    local now, held = os.clock(), {}
    for userId, untilAt in pairs(w.grudges) do
      local player = S.Players:GetPlayerByUserId(userId)
      if player and untilAt > now then held[#held + 1] = player.DisplayName .. string.format(" (%ds)", math.ceil(untilAt - now)) end
    end
    if #held == 0 and w.hurtBy == 0 then line.set("Nobody has hurt you yet.")
    else line.set((#held > 0 and ("Hunting for hurting you: " .. table.concat(held, ", ") .. ".") or "Nobody is held to account now.")
      .. string.format("    Fought back %d time%s.", w.fought, w.fought == 1 and "" or "s")) end
  end, 2, "dahood.who.line")
  local _ = Motion
end

DH.parts[#DH.parts + 1] = { id = "who", start = start, ragebot = ragebot }
end
do -- 90_boot.lua
-- ============================================================================
--  90 boot     order of operations
-- ============================================================================
local S, util, Motion, Theme, T, UI, Config, Window, Assets = B.S, B.util, B.Motion, B.Theme, B.T, B.UI, B.Config, B.Window, B.Assets
local UIS = S.UserInputService

local function boot()
  if not game:IsLoaded() then game.Loaded:Wait() end
  Config.init()
  Assets.init()
  if B.Prefs then B.Prefs.define() end
  if B.Prefs then B.Prefs.apply() end
  if B.Unnamed then B.Unnamed.start() end
  Window.build()
  -- the game is looked up first: its module can ask for Universal not to be loaded at all
  if B.Registry then B.try("registry.pick", B.Registry.pick) end
  for _, register in ipairs(B.pages or {}) do
    local name = B.universalPages and B.universalPages[register]
    if not name or not B.Registry or B.Registry.keeps(name) then B.try("pages", register) end
  end
  if B.Registry then B.try("registry", B.Registry.resolve) end
  Window.rebuildNav()
  Config.listen()

  -- the menu key, the palette, and the panic key
  B.connect(UIS.InputBegan, function(input)
    if Config.capturing then return end
    if input.UserInputType ~= Enum.UserInputType.Keyboard then return end
    local name = input.KeyCode.Name
    if UIS:GetFocusedTextBox() then return end
    if name == Config.get("app.key.menu") then
      if B.Loader and B.Loader.active then return end
      if B.Unnamed then B.Unnamed.toggleActive() else Window.toggle() end
    elseif name == Config.get("app.key.panic") then
      B.unload()
    elseif input.KeyCode == Enum.KeyCode.K and (UIS:IsKeyDown(Enum.KeyCode.LeftControl) or UIS:IsKeyDown(Enum.KeyCode.RightControl)) and Window.open then
      Window.palette()
    end
  end, "boot.keys")

  local function reveal()
    if B.Unnamed and B.Unnamed.active() then B.Unnamed.show(true) else Window.show(true) end
    if B.Hud then B.try("hud", B.Hud.start) end
    if B.Unnamed then B.try("unnamed.watermark", B.Unnamed.watermark) end
    if B.Keys then B.try("keys.hud", B.Keys.hud) end
    if B.Registry then B.try("registry.announce", B.Registry.announce) end
  end
  -- the other tabs are assembled a card per frame in the background: under the intro when there
  -- is one, so the hub is complete the moment it appears
  task.delay(0.7, function() if B.alive then Window.prebuild() end end)
  if B.Loader then B.Loader.run(reveal) else reveal() end
  B.bootMs = math.floor((os.clock() - B.bootClock) * 1000)
end

task.spawn(function()
  local ok, err = xpcall(boot, function(e) return tostring(e) .. "\n" .. debug.traceback("", 2) end)
  if not ok then
    B.fault("boot", err)
    pcall(function()
      S.StarterGui:SetCore("SendNotification", { Title = "BASED Hub", Text = "Failed to start: " .. string.sub(tostring(err), 1, 120), Duration = 8 })
    end)
  end
end)
end
return B
